// The race type the last UI_QRModeSelect pick set -- this port's stand-in for
// the game's 0x83AAB4. Written on A over a mode item; UI_QRTrackSelect's ring
// is filtered by it (trackdb.c, reproducing SPEED2.EXE:0x4987C0), which is the
// same thing the real screen's populate pass at 0x4CDED0 reads it for. The
// mode-options page that also consumes it is still unported (TASKS.md #115).
static int g_qrRaceType = -1;

// The track the last UI_QRTrackSelect pick set. SPEED2.EXE:0x4CE0F0 writes the
// selected row's trackId into 0x83AAB4's companion slot via 0x502910 for
// frontend context 2, or into 0x8500B8/0x8500BC for LAN/Online; this is the
// context-2 half of that. Nothing downstream consumes it yet -- the mode
// options and car-select layers are the next two -- so like g_qrRaceType before
// this session it is written and logged rather than acted on.
static int g_qrTrackId = -1;

// The options page the last UI_OptionsMain pick set -- this port's OptionsSettings
// +0 (0x83AA04), which UI_Options' Setup switches on (OptPage).
static int g_optionsPage = -1;

// The garage's two category globals. ChooseCustomizeCategory's rows carry the
// value their IconOption holds at +0x58, which React writes to
// CarCustomizeManager+0x1c for CalcNextScreenFromChooseCustomizeCategory to
// resolve (0x8016092C); ChoosePerfCategory's carry the ePerfPackageTypes
// AddCategory was given (DAT_803d84e8, which UI_ChoosePerformancePackage and
// UI_BuyPerformanceParts read). The port takes its own next screen from
// MenuItem::target; both are set on A exactly where retail sets them.
static int g_customizeCategory = -1;
static int g_perfPackageType = -1;

// The engine's one race-settings object, SPEED2.EXE's 0x83AAB4. It is BSS over
// there, so its contents are not bytes in the exe at all -- they come from the
// initialiser at 0x515800, which modeopts.c transcribes. Everything the mode
// options screen shows and everything LEFT/RIGHT changes lives in here, and it
// outlives the screen exactly as the real one does (walk back to the track
// list and forward again and your picks are still set).
static RaceSettings g_raceSettings;
static bool g_raceSettingsReady = false;

static RaceSettings* raceSettings(void) {
	if (!g_raceSettingsReady) {
		raceset_init(&g_raceSettings);
		g_raceSettingsReady = true;
	}
	return &g_raceSettings;
}

// The registry that binds a loaded .fng to its item table.
//
// `titleHash` is the screen-title override the builder installs before adding
// any items, emitted as `push <hash>; call 0x4FFA80; push eax; push 0x42ADB44C;
// push <screen>; call 0x537B80` -- i.e. "resolve this language string and make
// it the text of the widget whose OP name hash is 0x42ADB44C". Scanning the
// whole .text for that exact instruction pattern finds it three times
// (0x4AF12E "Career", 0x4EB740 "Profile Manager", 0x4EB7E0 "Profile"), plus the
// same shape open-coded in UI_QRModeSelect's ctor 0x4E2A50, which picks the
// string from the frontend-context global 0x850078 (2 -> 0x05416105 "Quick Race
// Mode Select", 4 -> 0xEF9F780D "Split-Screen Mode Select", 8 and 0x200 ->
// 0x47B276EF "Race Mode Select"). Every other entry here carries 0 and keeps
// whatever text the .fng itself authors -- UI_OptionsMain needs no override
// either, its authored SH already resolves to "Options", and all four Quick
// Race screens happen to author the context-2 text already, so the override on
// UI_QRModeSelect is written down for fidelity rather than to fix a wrong title.
typedef struct {
	const char* fngName;       // matched case-insensitively against the loaded screen
	u32 titleHash;             // 0 = keep the screen's own authored title
	const char* fallbackTitle;
	const MenuItem* items;
	int itemCount;
	// Screens with no item table of their own can still sit on a flow-object
	// edge: the Quick Race chain's middle screens are plain screens whose A
	// button runs their flow node's forward function (see MENU_ITEMS_QRMODE).
	// This is that function's destination, or NULL for screens where A does
	// nothing. Only forward edges need it -- every back edge in the real flow
	// is a plain pop, which menuStack already does.
	const char* flowNext;
} MenuScreenDef;

// CarCustomizeManager's customize context (0x804BE800) read back as the one
// condition the port's own tables need from it: ChooseCustomizeCategory's Car
// Lot row. Retail sets that context to 0x100 on the car lot's own way into the
// garage; this port only ever gets there from the crib, so it stays false.
// MenuItem::customizeFromCarLot is what reads it.
static const bool g_customizeFromCarLot = false;

// CustomizationScreenManager's entry point (DAT_803D84E0): 1 when the crib's
// CHANGE PARTS opened the garage, 0 when the player walked into a shop from
// free roam (LaunchFrontendShopFromGame, Speed.elf 0x8012721C). The garage's
// screens branch on it all through: the unlock filter (GetPartUnlockFilter,
// 0x8017107C -- CAREER alone from the crib, CAREER|ONLINE in a shop), the
// performance category's Dyno row and its B (ChoosePerfCategory::Setup and
// NotificationMessage, 0x80171F20 / 0x80171938), and the package screen's
// package rows and their prices (ChoosePerformancePackages, 0x80173154 /
// 0x80172854).
#define CUSTOMIZE_ENTRY_SHOP 0
#define CUSTOMIZE_ENTRY_CRIB 1
// The main menu's CUSTOMIZE (TASKS.md #379): UIQRCarSelect's A in frontend
// context 0x20 calls BeginCarCustomize(3, ...) (GC 0x8015DDA0, PC 0x552CC0).
// No prices, nothing bought, QuickRaceUnlocker's parts, and the edits go to a
// tuned car (FEPlayerCarDB's TUNED_CAR_<n>) rather than a career one.
#define CUSTOMIZE_ENTRY_CUSTOMIZE 3
static int g_customizeEntry = CUSTOMIZE_ENTRY_CRIB;

// The frontend context, [0x850078] (GC DAT_803CE800): MMCarSelect::React
// (0x80303D28 / PC 0x4AED30) writes 0x20 for CUSTOMIZE, Quick Race's way in 2.
// UI_QRCarSelect is shared between the two and tells them apart by it
// (cardb.h CARDB_CTX_*). The career's own value (1) is g_worldFromCareer's
// business, so only these two are kept here.
static int g_feCtx = CARDB_CTX_QUICKRACE;
// ClearHasBeenModified / the flag byte [0x838540]: a Customize session changed
// a tuned car, so ExitToMain asks for the memory card save (EnterMemcard 0x42).
static bool g_custModified = false;
// The tuned slot BeginCarCustomize(3) is editing (PROFILE_WORK_SLOT holds the
// copy), whether AddNewTunedCar made it this time (isNew), and the career slot
// the profile pointed at before, put back when the garage hands the car back.
static int  g_custTuned = -1;
static bool g_custIsNew = false;
static int  g_custPrevSlot = -1;
// The view filter, UIQRCarSelect::CurrentViewFilter (PC static [0x7F444C]),
// one for Customize and Quick Race alike: All Cars (3), My Cars (2), Stock
// Cars (1), and in Quick Race also Career (4) and Sponsor Cars (8) (#390).
// Kept between visits; Customize's ctor drops Career / Sponsor to All Cars.
static int  g_custFilter = 3;
// The career-array slot a Quick Race drives (#390): a Career row's career
// slot, or PROFILE_WORK_SLOT holding a My Cars row's tuned car; -1 for a
// stock car. Set at car select's A, read by playerCareerSlot().
static int  g_qrRideSlot = -1;
// #526: the world's car is a preset ride -- BuildRideForPlayer's
// DDAY_PLAYER_CAR, Rachel's 350Z -- built into PROFILE_WORK_SLOT by
// FillWithPreset (presetInstallPerf()), so playerCareerSlot() drives that
// build and not the stock record. Set and cleared on the way into the world.
static bool g_worldPresetRide = false;
// The car the panel reselects when it is built again: SetSelectedCar's handle,
// a tuned slot, or with none the stock car's type.
static int  g_custSelTuned = -1;
static int  g_custSelType = -1;
// A Career row's slot (Quick Race, #390), the same way.
static int  g_custSelCareer = -1;
// A Sponsor row's index into kSponsorPresets (Quick Race, #445), the same way.
static int  g_custSelSponsor = -1;

// #403: the frontend's mode, 0x850078 on the PC -- career (1) from
// StartCareerHelper (0x495A30) on, back out of it (2) when MainFNGObject's
// ctor (0x4DF140) builds the main menu. Only career mode puts the career car
// on the turntable: the main menu shows player 1's car-select car instead.
// The port enters it as UI_CareerCrib loads, the screen StartCareerHelper's
// free-roam arm and every career frontend path go through.
static bool g_feCareerMode = false;
// That car: the ctor's FUN_00515d00 on profileData+0xE8, the handle the car
// select keeps on the car under the cursor (SetSelectedCar, 0x502A40, in
// Quick Race and Customize alike). src is a CAR_SRC_ value (-1 none yet).
static struct { int src, slot; char dir[32]; u32 nameHash, paint; } g_menuCar = { -1, -1, "", 0, 0 };
// #443 (PORT, the user's exception to retail): back on the main menu FROM the
// career (free roam or the career's own screens), the main menu keeps the
// career car rather than the car-select car. Off at boot, so the first main
// menu is retail's (the car-select car, a random stock one before any car
// select this boot -- resolveMenuCar()); on whenever career mode starts; off
// again once Quick Race's car select picks a car (SetSelectedCar's pick).
static bool g_menuCareerCar = false;

static bool customizeFromMenu(void) {
	return g_customizeEntry == CUSTOMIZE_ENTRY_CUSTOMIZE;
}
// MenuItem::customizeGate: ChooseCustomizeCategory::Setup's entry-point tests.
static bool customizeGateOpen(u8 gate) {
	switch (gate) {
	case CUSTGATE_NOT_CRIB: return g_customizeEntry != CUSTOMIZE_ENTRY_CRIB;
	case CUSTGATE_DYNO:     return customizeFromMenu() && g_feCtx != CARDB_CTX_LAN;
	default:                return true;
	}
}
// The shop that walk-in is in: PlayerCareerState +0x7DF8, valid while +0x7DF0
// is set -- NotifyEnterShopFromFreeRoam (0x80126DB0) writes both. A copy, since
// the shop table it comes from is the world's and goes with it.
static ShopRec g_shopIn;
static bool g_shopInValid = false;

static bool customizeInShop(void) {
	return g_customizeEntry == CUSTOMIZE_ENTRY_SHOP && g_shopInValid;
}

// The walk-in over: StartCareerFreeRoam's UnTakeControl (ExitToRoamHelper,
// 0x8015DD24) hands the garage back, and the next way in is the crib's again.
static void customizeLeaveShop(void) {
	g_customizeEntry = CUSTOMIZE_ENTRY_CRIB;
	g_shopInValid = false;
}

