#define OLCARSEL_MSG_YES         0x43A743ABu
#define OLCARSEL_MSG_NO          0x1190B317u
static bool isCarSelFng(const char* s) {
	return s && (strcasecmp(s, "UI_QRCarSelect.fng") == 0 || strcasecmp(s, OLCARSEL_FNG) == 0);
}
