// Line height of the UI font (g_uiFont) at C2D scale 1.0, measured once at startup.
// The fallback unit for text whose .ffn the game files do not supply (see
// menuTextScaleRaw()), and the unit the port's own screen-pixel text sizes
// (MENU_MIN_TEXT_PX, the bank strip, the chyron) are given in.
static float g_fontUnitPx = 24.0f;

// The UI font's citro2d textScale (30 / cell height; see c2dtext.h).
static float g_uiTextScale = 1.0f;

// The game's own fonts (ffn.h): GLOBALA.BUN carries ConduitMdITC_TT21i, the
// language file the rest. Each is calibrated against g_uiFont -- the .bcfnt
// the port draws every string with -- by the one thing both agree on, how
// wide a run of text is: the citro2d scale at which the .bcfnt's advances sum
// to the retail font's is the scale that draws one retail font unit as one
// pixel. Retail lays text out in those units (FEngFont::RenderString, Speed.elf
// 0x8014c1f0: glyph quads in font units, the String's SA size and its groups
// on top through the object matrix), so a String's citro2d scale is this
// times its size times the screen's layoutScale. TT21i's atlas is the UI
// font's face (Helvetica 67 Condensed Medium Oblique, TASKS.md #425), so
// matching widths matches height too. (With the Conduit fallback the .otf's
// baseline landed 26.1 units down a line at that scale, the retail TT21i's
// 26 -- its space glyph's y offset.)
static void loadRetailFonts(const Config* cfg) {
	if (g_uiFont) {
		const FINF_s* fi = C2D_FontGetInfo(g_uiFont);
		const float ts = fontmip_text_scale(g_uiFont);
		if (ts > 0.0f)
			g_uiTextScale = ts;
		else if (fi && fi->tglp && fi->tglp->cellHeight)
			g_uiTextScale = 30.0f / (float)fi->tglp->cellHeight;
	}
	if (!cfg || !g_uiFont) {
		dlog("retail fonts: no config or no UI font -- point-size text layout");
		return;
	}
	char path[300];
	if (buildGamePath(cfg, "GLOBAL/GLOBALA.BUN", path, sizeof(path)))
		ffn_load_file(path);
	if (buildGamePath(cfg, "LANGUAGES/English.bin", path, sizeof(path)))
		ffn_load_file(path);
	C2D_TextBuf probeBuf = C2D_TextBufNew(128);
	if (!probeBuf)
		return;
	// Every printable ASCII character once: the average over the whole set
	// irons out the per-glyph rounding both rasterisations carry (+-2%).
	char cal[96];
	int n = 0;
	for (int c = 0x20; c < 0x7f; c++)
		cal[n++] = (char)c;
	cal[n] = '\0';
	C2D_Text probe;
	C2D_TextFontParse(&probe, g_uiFont, probeBuf, cal);
	float pw = 0.0f, ph = 0.0f;
	textDims(&probe, 1.0f, 1.0f, &pw, &ph);
	for (int i = 0; i < ffn_count(); i++) {
		const FfnFont* f = ffn_at(i);
		// Advances only: citro2d does not kern, so neither does this sum.
		int units = 0;
		for (int c = 0x20; c < 0x7f; c++)
			units += ffn_char_width(f, (u32)c, -1);
		if (units > 0 && pw > 1.0f)
			ffn_set_c2d_scale(f, (float)units / pw);
		char b[128];
		snprintf(b, sizeof(b), "retail font %s: line %d, %d units over the ASCII set, "
			"c2d scale %.4f per unit", ffn_name(f), ffn_line_height(f), units,
			ffn_c2d_scale(f));
		dlog(b);
	}
	if (ffn_count() == 0)
		dlog("retail fonts: none in GLOBALA.BUN / English.bin -- point-size text layout");
	C2D_TextBufDelete(probeBuf);
}

// What a String is laid out in: its game font, calibrated, or -- when the file
// that font lives in is not on the card -- a stand-in built from the .ffn's
// point size, which is how this port sized text before it read the fonts: the
// point size is taken as the line height, and characters as wide as
// the UI font draws them at that size.
typedef struct {
	const FfnFont* f;  // NULL for the point-size stand-in
	float c2dScale;    // citro2d scale that draws one font unit as one pixel
	float lineH;       // font units
} MenuFont;

static bool menuFontOf(const FngWidget* w, MenuFont* out) {
	if (!w->hasFontRef)
		return false;
	const FfnFont* f = ffn_find(w->fontNameHash);
	if (f && ffn_c2d_scale(f) > 0.0f) {
		out->f = f;
		out->c2dScale = ffn_c2d_scale(f);
		out->lineH = (float)ffn_line_height(f);
		return true;
	}
	if (w->fontPointSize == 0)
		return false;
	out->f = NULL;
	out->c2dScale = (float)w->fontPointSize / g_fontUnitPx;
	out->lineH = (float)w->fontPointSize;
	return true;
}

// One character's width in font units, as GetLineWidth adds it up.
static float menuFontCharUnits(const MenuFont* mf, u32 code, int prev) {
	if (mf->f)
		return (float)ffn_char_width(mf->f, code, prev);
	fontGlyphPos_s gp;
	C2D_FontCalcGlyphPos(g_uiFont, &gp,
		C2D_FontGlyphIndexFromCodePoint(g_uiFont, code), 0, 1.0f, 1.0f);
	return gp.xAdvance * g_uiTextScale / mf->c2dScale;
}

