static FngSource fngSourceFor(const char* screenName, bool fromGlobalBun) {
	for (int i = 0; i < (int)(sizeof(FNG_SOURCES) / sizeof(FNG_SOURCES[0])); i++) {
		if (strcasecmp(screenName, FNG_SOURCES[i].fngName) == 0)
			return FNG_SOURCES[i].src;
	}
	return fromGlobalBun ? FNG_SRC_GLOBALB : FNG_SRC_FRONTEND;
}

// Where each package a scan has passed lives, so the next screen out of the
// same container is a seek and one read rather than another pass (TASKS.md
// #270 P4). Every package a scan walks over is noted, not only the one it was
// sent for, so a later screen earlier in the file is found here too. A scan
// that reaches the end of a container without a match marks it `full`: every
// package in it is then listed, and a name that is not is not there.
//
// The cost this removes is the loading screen's. Loading.fng sits 7.84 MB into
// the 8 MB GLOBALB.BUN, so finding it was a pass over the whole file: 1.84 s on
// Azahar, every race start and every return to free roam.
typedef struct {
	u8   src;
	bool jdlz;       // `len` is then the compressed block's length
	char name[40];
	long at;         // the package's FEn magic, or its JDLZ header
	u32  len;
} FngLoc;
#define FNG_LOC_MAX 96
static FngLoc g_fngLoc[FNG_LOC_MAX];
static int    g_fngLocCount = 0;
static bool   g_fngLocFull[FNG_SRC_COUNT];

static const FngLoc* fngLocFind(FngSource src, const char* name) {
	for (int i = 0; i < g_fngLocCount; i++)
		if (g_fngLoc[i].src == (u8)src && strcmp(g_fngLoc[i].name, name) == 0)
			return &g_fngLoc[i];
	return NULL;
}

static void fngLocNote(FngSource src, const char* name, size_t nameMax, long at, u32 len,
	bool jdlz)
{
	if (src >= FNG_SRC_COUNT || g_fngLocCount >= FNG_LOC_MAX)
		return;
	char n[40];
	size_t k = 0;
	while (k < nameMax && k < sizeof(n) - 1 && name[k] && name[k] >= 0x20 && name[k] < 0x7f) {
		n[k] = name[k];
		k++;
	}
	// A name that does not end inside the record is not a name.
	if (k == 0 || k >= nameMax || k >= sizeof(n) - 1 || name[k] != '\0')
		return;
	n[k] = '\0';
	if (fngLocFind(src, n))
		return;   // the first in file order is the one a scan returns
	FngLoc* l = &g_fngLoc[g_fngLocCount++];
	l->src = (u8)src;
	l->jdlz = jdlz;
	memcpy(l->name, n, k + 1);
	l->at = at;
	l->len = len;
}

// The stretches of a container a scan has to read. Its top-level chunks are
// walked first, and a texture pack (0xB3300000) is left out: no screen is
// stored inside one, and in GLOBALB.BUN the two of them are 7.07 MB of the
// 8 MB. The walk reads the headers through `buf` a few KB at a time, so the
// run of small chunks at the head of a file costs one read, not one each.
// Where the walk loses sync -- InGameCommon.bun has a zero header partway --
// the rest of the file is one span, scanned as before.
#define FNG_TEXPACK_CHUNK 0xB3300000u
#define FNG_MAX_SPANS     8
#define FNG_WALK_READ     (16u * 1024u)
typedef struct { long start, end; } FngSpan;

static int fngScanSpans(FILE* f, long fsize, u8* buf, FngSpan* sp) {
	int n = 0;
	long off = 0, spanStart = 0, bufAt = -1, bufLen = 0;
	while (off + 8 <= fsize && n < FNG_MAX_SPANS - 1) {
		if (bufAt < 0 || off < bufAt || off + 8 > bufAt + bufLen) {
			if (fseek(f, off, SEEK_SET) != 0)
				break;
			bufLen = (long)fread(buf, 1, FNG_WALK_READ, f);
			bufAt = off;
			if (bufLen < 8)
				break;
		}
		u32 type, size;
		memcpy(&type, buf + (off - bufAt), 4);
		memcpy(&size, buf + (off - bufAt) + 4, 4);
		if ((type == 0 && size == 0) || (long)size > fsize - (off + 8))
			break;
		if (type == FNG_TEXPACK_CHUNK) {
			if (off > spanStart) {
				sp[n].start = spanStart;
				sp[n].end = off;
				n++;
			}
			spanStart = off + 8 + (long)size;
		}
		off += 8 + (long)size;
	}
	if (spanStart < fsize) {
		sp[n].start = spanStart;
		sp[n].end = fsize;
		n++;
	}
	return n;
}

// Reads a package fngLocNote() recorded.
static bool fngLocRead(FILE* f, long fsize, const FngLoc* l, u8** outBuf, u32* outLen) {
	if (l->at < 0 || (long)l->len <= 0 || l->at + (long)l->len > fsize)
		return false;
	u8* b = (u8*)malloc(l->len);
	if (!b)
		return false;
	if (fseek(f, l->at, SEEK_SET) != 0 || fread(b, 1, l->len, f) != l->len) {
		free(b);
		return false;
	}
	if (!l->jdlz) {
		*outBuf = b;
		*outLen = l->len;
		return true;
	}
	u8* full = NULL;
	u32 fullLen = 0, consumed = 0;
	bool ok = jdlz_decompress(b, l->len, 0, &full, &fullLen, &consumed);
	free(b);
	if (!ok)
		return false;
	*outBuf = full;
	*outLen = fullLen;
	return true;
}

// One streaming pass over a .bun container, matching a package stored EITHER
// raw or as its own JDLZ sub-block. Supersedes the old raw-only file scan, which
// only ever saw the raw half and therefore could not reach the two dozen
// compressed packages sitting in the same files.
//
// Two traps this has to get right, both established empirically against the
// shipped containers rather than assumed:
//
//  1. A raw FEn hit is a FALSE POSITIVE when the four bytes at offset-18 are
//     "JDLZ". A JDLZ block is a 16-byte header, two flag bytes, then the
//     payload, and the first four output bytes of an .fng are provably
//     literals (a back-reference needs at least three bytes of prior output
//     and 'F','E','n' cannot be produced from 'F' alone), so every compressed
//     package leaves its own magic lying in the file 18 bytes past its header.
//     GLOBALB.BUN has 13 of these decoys and InGameCommon.bun has 24; taking
//     one would hand fng_parse() a package whose body is still compressed.
//
//  2. That same fact is the cheap POSITIVE filter for the compressed half:
//     only a JDLZ block with the magic at +18 can be an .fng at all, so
//     nothing else is ever decompressed. Candidates that pass it are decoded
//     128 bytes deep (jdlz_decompress_prefix) to read the Name at payload
//     offset 40, and only an actual name match is decoded in full.
//
// Only the spans fngScanSpans() leaves in are read (#270 P4), and every
// package passed on the way is noted in g_fngLoc.
static bool findFngInContainerFile(FILE* f, long fsize, FngSource src, const char* wantName,
	u8** outBuf, u32* outLen)
{
	const size_t nameLen = strlen(wantName);
	const size_t need = 40 + nameLen + 1;
	// Also needs 22 readable bytes past a 'J' for the +18 magic test; every
	// real screen name is long enough that `need` already covers that.
	if (need < 22 || need > FNG_SCAN_OVERLAP || fsize <= 0)
		return false;

	const FngLoc* known = fngLocFind(src, wantName);
	if (known)
		return fngLocRead(f, fsize, known, outBuf, outLen);
	if (src < FNG_SRC_COUNT && g_fngLocFull[src])
		return false;

	u8* win = (u8*)malloc(FNG_SCAN_WINDOW);
	if (!win)
		return false;

	FngSpan spans[FNG_MAX_SPANS];
	const int nSpans = fngScanSpans(f, fsize, win, spans);

	bool found = false, failed = false;
	for (int s = 0; s < nSpans && !found && !failed; s++) {
		const long spanStart = spans[s].start, spanEnd = spans[s].end;
		long base = spanStart;
		while (base < spanEnd && !found) {
			if (fseek(f, base, SEEK_SET) != 0) {
				failed = true;
				break;
			}
			long want = spanEnd - base;
			if (want > (long)FNG_SCAN_WINDOW)
				want = (long)FNG_SCAN_WINDOW;
			size_t got = fread(win, 1, (size_t)want, f);
			if (got < need)
				break;

			const size_t limit = got - need + 1;
			for (size_t i = 0; i < limit && !found; i++) {
				if (win[i] == 'F' && memcmp(win + i, "FEn\xE7", 4) == 0) {
					// Trap 1. A hit in the first 18 bytes of a window that is
					// not its span's first was already seen -- with its
					// predecessor bytes -- in the previous window's overlap, so
					// skipping it here loses nothing and saves a seek back. A
					// span starts at a chunk header, which no JDLZ block
					// straddles.
					if (i < 18) {
						if (base != spanStart)
							continue;
					} else if (memcmp(win + i - 18, "JDLZ", 4) == 0) {
						continue;
					}
					u32 payloadLen;
					memcpy(&payloadLen, win + i + 4, 4);
					const size_t total = 8 + (size_t)payloadLen;
					const long at = base + (long)i;
					if ((long)total <= 0 || at + (long)total > fsize)
						continue;
					fngLocNote(src, (const char*)win + i + 40, got - i - 40, at,
						(u32)total, false);
					if (strncmp((const char*)win + i + 40, wantName, nameLen + 1) != 0)
						continue;

					u8* copy = (u8*)malloc(total);
					if (!copy) {
						failed = true;
						break;
					}
					if (fseek(f, at, SEEK_SET) != 0 || fread(copy, 1, total, f) != total) {
						free(copy);
						failed = true;
						break;
					}
					*outBuf = copy;
					*outLen = (u32)total;
					found = true;
					break;
				}

				if (win[i] != 'J' || memcmp(win + i, "JDLZ", 4) != 0)
					continue;
				if (win[i + 4] != 0x02)
					continue;
				// Trap 2, the positive half.
				if (memcmp(win + i + 18, "FEn\xE7", 4) != 0)
					continue;

				u32 uLen, cLen;
				memcpy(&uLen, win + i + 8, 4);
				memcpy(&cLen, win + i + 12, 4);
				const long at = base + (long)i;
				if (cLen < 16 || uLen < 44 || at + (long)cLen > fsize)
					continue;
				// The largest shipped package is UI_PC_Customize_Options.fng at
				// 377,952 bytes; this cap is a sanity bound on a corrupt
				// header, not a policy about screen size.
				if (uLen > 4u * 1024u * 1024u)
					continue;

				// A block wholly inside the window is named from there, with
				// no read of its own -- which is what lets a scan note the
				// compressed packages it passes as well as the raw ones.
				u8 head[128];
				u32 headLen = 0;
				u8* comp = NULL;
				if (i + (size_t)cLen <= got) {
					headLen = jdlz_decompress_prefix(win + i, cLen, 0, head, sizeof(head));
					if (headLen >= 44)
						fngLocNote(src, (const char*)head + 40, headLen - 40, at, cLen, true);
					if (headLen < need ||
						strncmp((const char*)head + 40, wantName, nameLen + 1) != 0)
						continue;
				} else {
					comp = (u8*)malloc(cLen);
					if (!comp) {
						failed = true;
						break;
					}
					if (fseek(f, at, SEEK_SET) != 0 || fread(comp, 1, cLen, f) != cLen) {
						free(comp);
						failed = true;
						break;
					}
					headLen = jdlz_decompress_prefix(comp, cLen, 0, head, sizeof(head));
					if (headLen >= 44)
						fngLocNote(src, (const char*)head + 40, headLen - 40, at, cLen, true);
					if (headLen < need ||
						strncmp((const char*)head + 40, wantName, nameLen + 1) != 0) {
						free(comp);
						continue;
					}
				}

				u8* full = NULL;
				u32 fullLen = 0, consumed = 0;
				bool ok = comp
					? jdlz_decompress(comp, cLen, 0, &full, &fullLen, &consumed)
					: jdlz_decompress(win + i, cLen, 0, &full, &fullLen, &consumed);
				free(comp);
				if (!ok)
					continue;
				*outBuf = full;
				*outLen = fullLen;
				found = true;
				break;
			}

			if (failed || got < (size_t)want || base + (long)got >= spanEnd)
				break;
			base += (long)(FNG_SCAN_WINDOW - FNG_SCAN_OVERLAP);
		}
	}
	// Every span read to its end with no match: the container is listed.
	if (!found && !failed && src < FNG_SRC_COUNT)
		g_fngLocFull[src] = true;

	free(win);
	return found;
}

// Opens `src`'s container and pulls `screenName` out of it. FrontB.lzc is the
// odd one out and is not handled here: it is a single outer JDLZ block that has
// to be decompressed whole anyway (the frontend texture packs live in the same
// block, and loadFngScreen keeps that buffer alive to warm them), so it keeps
// its own path inside loadFngScreen below.
static bool loadFngFromBun(const Config* cfg, FngSource src, const char* screenName,
	u8** outBuf, u32* outLen)
{
	char path[600];
	buildGamePath(cfg, FNG_SOURCE_PATH[src], path, sizeof(path));
	FILE* f = fopen(path, "rb");
	if (!f) {
		char b[640];
		snprintf(b, sizeof(b), "fng screen %s: failed to open %s", screenName, path);
		dlog(b);
		return false;
	}
	fseek(f, 0, SEEK_END);
	long fsize = ftell(f);
	fseek(f, 0, SEEK_SET);
	// Streamed, not slurped -- see FNG_SCAN_WINDOW's note on the 8 MB
	// allocation this used to need and the screens it cost.
	bool ok = findFngInContainerFile(f, fsize, src, screenName, outBuf, outLen);
	fclose(f);
	if (!ok) {
		char b[192];
		snprintf(b, sizeof(b), "fng screen: %s not found in %s", screenName,
			FNG_SOURCE_PATH[src]);
		dlog(b);
	}
	return ok;
}

// ---- the decompressed FrontB.lzc, held across screen loads ----------------
//
// FRONTEND/FrontB.lzc is one 1.75 MB outer JDLZ block holding all 130 frontend
// .fng screens AND the two frontend texture packs. Every screen load needs it,
// and until now every screen load re-read all 1.75 MB off the SD card and
// re-inflated it from scratch -- which is what made menu navigation stall for
// a second or more per screen and starve the DSP long enough to break the
// music up. The contents are read-only and identical every time, so the port
// inflates it once and keeps it.
//
// The cost is holding the inflated block resident. It is released before the
// world opens (frontCacheRelease() in worldEnter()) and re-inflated on the way
// back, so the frontend's memory and the pager's 32 MB budget never overlap --
// which is the same reason the showroom model is dropped at world entry.
static u8* g_frontOuter = NULL;
static u32 g_frontOuterLen = 0;

static void frontCacheRelease(void) {
	if (!g_frontOuter)
		return;
	free(g_frontOuter);
	g_frontOuter = NULL;
	g_frontOuterLen = 0;
	dlog("fng cache: FrontB.lzc released");
}

// Returns the inflated block, loading it on first use. NULL on any failure,
// which the callers already treat as "this screen has no FrontB source".
static const u8* frontCacheGet(const Config* cfg, u32* outLen) {
	if (g_frontOuter) {
		*outLen = g_frontOuterLen;
		return g_frontOuter;
	}
	char path[600];
	if (!buildGamePath(cfg, "FRONTEND/FrontB.lzc", path, sizeof(path)))
		return NULL;
	const u64 t0 = svcGetSystemTick();
	FILE* f = fopen(path, "rb");
	if (!f) {
		char b[640];
		snprintf(b, sizeof(b), "fng cache: failed to open %s", path);
		dlog(b);
		return NULL;
	}
	fseek(f, 0, SEEK_END);
	long fsize = ftell(f);
	fseek(f, 0, SEEK_SET);
	u8* fileBuf = (u8*)malloc((size_t)fsize);
	if (!fileBuf || fread(fileBuf, 1, (size_t)fsize, f) != (size_t)fsize) {
		dlog("fng cache: failed to read FrontB.lzc");
		free(fileBuf);
		fclose(f);
		return NULL;
	}
	fclose(f);
	const u64 t1 = svcGetSystemTick();

	u32 consumed = 0;
	bool ok = jdlz_decompress(fileBuf, (size_t)fsize, 0, &g_frontOuter, &g_frontOuterLen,
		&consumed);
	free(fileBuf);
	if (!ok) {
		dlog("fng cache: FrontB.lzc outer JDLZ decompress failed");
		g_frontOuter = NULL;
		g_frontOuterLen = 0;
		return NULL;
	}
	const u64 t2 = svcGetSystemTick();
	char b[192];
	snprintf(b, sizeof(b),
		"fng cache: FrontB.lzc inflated %ld -> %u KB (read %.0f ms, jdlz %.0f ms)",
		fsize, g_frontOuterLen >> 10, TKMS(t0, t1), TKMS(t1, t2));
	dlog(b);
	*outLen = g_frontOuterLen;
	return g_frontOuter;
}

// ---------------------------------------------------- the engage race dialog
//
// UI_EngageRaceDialog.fng, the "Incoming Mobile Message" D-Pad Up raises over a
// race start. RaceEngageDialog::Setup (Speed.elf 0x800E8570) fills seven of its
// widgets from the career event under the car -- eventdb.h lists them and what
// each is given. The parts that need the career tables (the purse) or the track
// table (the length) are resolved by the world before it loads the screen and
// left here; loadFngScreen() writes them into the widgets while it has
// English.bin open, the way Setup writes them while the package starts.
//
// SummonTheRightEngageDialog (0x800E6CEC) raises one of three packages, and
// the kind says which and for what: a race start's UI_EngageRaceDialog, a
// world challenge's or a showcase's UI_EngageEventDialog (EventEngageDialog,
// 0x800E6F7C), or, a challenge having run out of time, UI_EngageShopDialog
// (EngageShopDialog, 0x800E7800) as the failure dialog, the uniques dialog,
// or -- a shop under the car -- the shop's own "enter?" dialog, whose Accept
// is the walk-in, careerEnterShop() (#370).
typedef enum {
	ENGAGE_KIND_NONE = 0,
	ENGAGE_KIND_RACE,
	ENGAGE_KIND_CHALLENGE,
	ENGAGE_KIND_SHOWCASE,
	ENGAGE_KIND_FAILURE,
	ENGAGE_KIND_UNIQUES,
	ENGAGE_KIND_SHOP,     // EngageShopDialog's own arm: a shop under the car (#370)
} EngageKind;

typedef struct {
	EngageKind kind;    // ENGAGE_KIND_NONE whenever no dialog is being raised
	const EventRec* ev; // the race arm's event
	u32 purse;          // GetEventPurse__17PlayerCareerState (0x801275B0)
	u32 distanceM;      // TrackInfo+0x98 of the event's first track
	bool haveDistance;
	int bodyVariant;    // bRandom(N)+1, see eventdb_engage_body_variants()
	// EventEngageDialog's: the challenge or the showcase, the body's language
	// hash (GetEngageChallengeDialogBody's bRandom pick, drawn once as the
	// dialog comes up) and FillFromWithRandomName's sender.
	const WorldChallengeRec* challenge;
	const ShowcaseRec* showcase;
	u32 bodyId;
	char bodyLabel[40];
	const char* fromName;
	// EngageShopDialog's uniques arm: the goal shop the challenge reached.
	const ShopRec* shop;
} EngageDlgInput;
static EngageDlgInput g_engageDlg;

static const char* engageDialogFng(void) {
	switch (g_engageDlg.kind) {
		case ENGAGE_KIND_CHALLENGE:
		case ENGAGE_KIND_SHOWCASE: return "UI_EngageEventDialog.fng";
		case ENGAGE_KIND_FAILURE:
		case ENGAGE_KIND_UNIQUES:
		case ENGAGE_KIND_SHOP:     return "UI_EngageShopDialog.fng";
		default:                   return "UI_EngageRaceDialog.fng";
	}
}

// The two buttons, by object hash. NotificationMessage (0x800E82FC) is the
// whole of their behaviour:
//   * 0x35F8620B, which the package raises once it is up, makes Decline
//     current, so the dialog opens on Decline rather than Accept. The .fng
//     agrees: Decline is the one authored in its highlight colour.
//   * PAD_LEFT makes Accept current and PAD_RIGHT Decline, each only if it is
//     not current already -- the buttons sit at x -150 and +150.
//   * ACCEPT on Accept is AcceptRace (0x800E81E4), on Decline DeclineRace
//     (0x800E8280); PAD_BACK is DeclineRace whichever is current.
#define ENGAGE_ACCEPT_BTN_HASH  0xD72F002Au
#define ENGAGE_DECLINE_BTN_HASH 0x63857DE0u
#define ENGAGE_SEL_ACCEPT  0
#define ENGAGE_SEL_DECLINE 1
// EventEngageDialog's third, "Button3", the one a showcase shows.
#define ENGAGE_BUTTON3_HASH     0xB8A7C6CEu
#define ENGAGE_SEL_BUTTON3 2
// What a button's Highlight (0x249DB7B7) and UnHighlight (0x7AB5521A) scripts
// key its String to -- the first colour key of each script's track in the
// shipped .fng, stored B,G,R,A like every FEng colour. The port has no script
// player, so the key is applied directly rather than played.
#define ENGAGE_BTN_HIGHLIGHT_RGBA C2D_Color32(0xCC, 0xF4, 0x8A, 0xFF)
#define ENGAGE_BTN_NORMAL_RGBA    C2D_Color32(0xE1, 0xE1, 0xE1, 0xFF)

static bool engageDialogOwns(u32 objHash) {
	return objHash == ENGAGE_DLG_SUBJECT_HASH || objHash == ENGAGE_DLG_TYPE_HASH ||
		objHash == ENGAGE_DLG_BODY_HASH || objHash == ENGAGE_DLG_FROM_HASH ||
		objHash == ENGAGE_DLG_DISTANCE_HASH || objHash == ENGAGE_DLG_PURSE_HASH;
}

// One shipped frame ("Subject: %s", "From: %s") with its %s replaced by `arg`.
// By hand rather than through snprintf, so that shipped text is never read as
// a format string.
static void engageFrame(const char* frameUtf8, const char* arg, char* out, size_t cap) {
	const char* p = strstr(frameUtf8, "%s");
	if (!p) {
		snprintf(out, cap, "%s", frameUtf8);
		return;
	}
	snprintf(out, cap, "%.*s%s%s", (int)(p - frameUtf8), frameUtf8, arg, p + 2);
}

// What Setup gives the String `objHash`. False leaves the widget blank: Setup
// overwrites all six, so falling back to the authored placeholder would show
// layout debris rather than anything retail does.
static bool engageDialogText(const LangTable* lang, u32 objHash, char* out, size_t cap) {
	const EventRec* ev = g_engageDlg.ev;
	char arg[256], frame[256];
	const char* raw = NULL;
	switch (objHash) {
		case ENGAGE_DLG_SUBJECT_HASH:
			raw = lang ? langbin_lookup(lang, eventdb_engage_subject_id(ev)) : NULL;
			if (!raw)
				return false;
			langTextToUtf8(raw, arg, sizeof(arg));
			raw = langbin_lookup(lang, ENGAGE_DLG_SUBJECT_FMT_ID);
			langTextToUtf8(raw ? raw : "%s", frame, sizeof(frame));
			engageFrame(frame, arg, out, cap);
			return true;
		case ENGAGE_DLG_TYPE_HASH:
			raw = lang ? langbin_lookup(lang, eventdb_engage_type_id(ev)) : NULL;
			if (!raw)
				return false;
			langTextToUtf8(raw, out, cap);
			return true;
		case ENGAGE_DLG_BODY_HASH: {
			// FEngSetLanguageHash with GetEngageDialogBody's label hash.
			char label[64];
			u32 h = eventdb_engage_body_label(ev, g_engageDlg.bodyVariant, label, sizeof(label));
			raw = lang ? langbin_lookup(lang, h) : NULL;
			if (!raw)
				return false;
			langTextToUtf8(raw, out, cap);
			return true;
		}
		case ENGAGE_DLG_FROM_HASH:
			// GetEngageDialogFrom (0x80121D54): the record's own sender
			// string when it has one, otherwise opponent 0's name.
			raw = (lang && ev->senderStringId) ? langbin_lookup(lang, ev->senderStringId) : NULL;
			if (raw)
				langTextToUtf8(raw, arg, sizeof(arg));
			else
				snprintf(arg, sizeof(arg), "%s", ev->fromName);
			raw = lang ? langbin_lookup(lang, ENGAGE_DLG_FROM_FMT_ID) : NULL;
			langTextToUtf8(raw ? raw : "%s", frame, sizeof(frame));
			engageFrame(frame, arg, out, cap);
			return true;
		case ENGAGE_DLG_DISTANCE_HASH: {
			// "%$f %s". EA's printf (SPEED2.EXE 0x43EDFD) gives a %f with no
			// precision 3 places, not C's 6, and '$' only adds grouping,
			// which a race length never reaches. The quotient is single
			// precision (frsp, then fdivs by 1600.0f), so it is formed as a
			// float here too. The unit word follows the units byte ("km"
			// when it is set: Speed.elf 0x800E8628's bne, SPEED2.EXE
			// 0x4B5417's sete), but the number does not -- both platforms
			// divide by 1600 either way, so a metric profile reads the mile
			// figure labelled "km". Retail's own quirk, kept.
			if (!g_engageDlg.haveDistance)
				return false;
			raw = lang ? langbin_lookup(lang, unitsMetric()
				? ENGAGE_DLG_UNIT_KM_ID : ENGAGE_DLG_UNIT_MILES_ID) : NULL;
			langTextToUtf8(raw ? raw : "", arg, sizeof(arg));
			const float d = (float)g_engageDlg.distanceM / ENGAGE_DLG_DISTANCE_DIVISOR;
			snprintf(out, cap, "%.3f %s", (double)d, arg);
			return true;
		}
		case ENGAGE_DLG_PURSE_HASH:
			// "%$d" -- formatCashGrouped() is that same grouping.
			formatCashGrouped(g_engageDlg.purse, out, cap);
			return true;
		default:
			return false;
	}
}

// ---- UI_EngageEventDialog / UI_EngageShopDialog ---------------------------
//
// EventEngageDialog::Setup (0x800E7520), for a world challenge: the body
// GetEngageChallengeDialogBody (0x8012DAFC) prints -- a random one of the
// challenge type's ENGAGE_*_GENERIC_<n>_BODY strings, its %s the time limit
// as Timer::PrintToString writes it -- the subject by type
// (GetEngageChallengeDialogSubject, 0x8012DC44), and "From: " a random Quick
// Race name. For a showcase, StartMagazineMode and magazine mode: both
// button backings (0x949F4947, 0x949F4948), Accept and Cancel invisible and
// disabled, Button3's group (0xB1000CC8) and Button3 shown and enabled, its
// label 0xDE02CF84, and the body and subject by the showcase's type
// (GetEnterShowcaseDialogBody / Subject, 0x8012B4D4 / 0x8012B58C).
// EngageShopDialog::Setup's failure arm (0x800E7E74, a challenge on and
// failed): body 0xC4DF3B44, Accept's label 0x039DF715 and an empty title.
#define ENGAGE_EVT_BACKING1_HASH  0x949F4947u
#define ENGAGE_EVT_BACKING2_HASH  0x949F4948u
#define ENGAGE_EVT_BUTTON3_GROUP  0xB1000CC8u
#define ENGAGE_BUTTON3_SHOOT_ID   0xDE02CF84u
#define ENGAGE_SHOP_TITLE_HASH    0x02EDBDE5u
#define ENGAGE_SHOP_BODY_HASH     0x04A04E7Cu
#define ENGAGE_FAIL_BODY_ID       0xC4DF3B44u
#define ENGAGE_FAIL_ACCEPT_ID     0x039DF715u
// Its uniques arm (a challenge on, not failed, at its goal shop): the title is
// the shop's GetEngageDialogHeader, the body GetEnterUniquesShopMessageBody
// (0x8012DD30), FEngSNPrintf of GetLocalizedString(0xE514579D) -- "Yo, dawg,
// get inside to pick up yer uniques." Accept keeps its authored label.
#define ENGAGE_UNIQUES_BODY_ID    0xE514579Du
// Its shop arm (no challenge on), EngageShopDialog::Setup (SpeedPS
// 0x800E7E74): title GetEngageDialogHeader, body GetEngageDialogBody
// (0x80122214), Accept's label by ShopDataDesc +0x50, the shop type -- the
// crib's 0x67F55A89, every other shop's 0x054B17DC (#370).
//   GetEngageDialogBody: the crib (type 0) 0x987EECDA. Any other shop not
//   entered yet (HasBeenEntered 0x80121FFC: its state record not 5) takes
//   FEngHashString("%s_BODY", the shop's name) when the label is in the
//   database (IsLabelInDatabase) -- the shop's one-time introduction --
//   and 0x15D6B438 otherwise and every time after.
#define ENGAGE_SHOP_CRIB_BODY_ID    0x987EECDAu
#define ENGAGE_SHOP_GENERIC_BODY_ID 0x15D6B438u
#define ENGAGE_SHOP_CRIB_ACCEPT_ID  0x67F55A89u
#define ENGAGE_SHOP_ACCEPT_ID       0x054B17DCu
// Timer: 4000 ticks a second, what race_print_time() prints.
#define ENGAGE_TIMER_TICKS        4000.0f

// GetEngageChallengeDialogSubject's language hash by challenge type, 0 for
// none (it writes nothing).
static u32 engageChallengeSubjectId(u8 type) {
	switch (type) {
		case WC_TYPE_PERF:     return 0xA517FD7Au;
		case WC_TYPE_VISUAL:   return 0x48157D57u;
		case WC_TYPE_3:        return 0xBF178F39u;
		case WC_TYPE_SHOWCASE: return 0xE5B2C887u;
		default:               return 0;
	}
}

// GetEnterShowcaseDialogBody / Subject by showcase type: 1 in-game magazine,
// 2 in-game DVD, 3 frontend magazine, 4 frontend DVD.
static u32 engageShowcaseTextId(s8 type, bool subject) {
	static const u32 kBody[4] = { 0x8FF3F225u, 0x1DEFB577u, 0x74B2A894u, 0xA747EA86u };
	static const u32 kSubj[4] = { 0x1E4CBC67u, 0x99829679u, 0x16549076u, 0xE0F2E528u };
	if (type < 1 || type > 4)
		return 0;
	return subject ? kSubj[type - 1] : kBody[type - 1];
}

// ShopDataDesc::GetEngageDialogHeader (SpeedPS.elf 0x80122158): CRIB_1's
// handle (0x7FC8D0D0) has its own, the rest go by shop type 0..5.
static u32 shopEngageHeaderId(const ShopRec* shop) {
	static const u32 kByKind[6] = { 0x7CE21662u, 0xA5F04BD7u, 0x0B9253E9u, 0xAF258EE8u,
		0x4DC0A646u, 0xA4E5EE6Cu };
	if (!shop)
		return 0;
	if (shop->handle == 0x7FC8D0D0u)
		return 0x6AA654C5u;
	return shop->kind >= 0 && shop->kind < 6 ? kByKind[(int)shop->kind] : 0;
}

static bool engageEventOwns(u32 objHash) {
	switch (g_engageDlg.kind) {
		case ENGAGE_KIND_UNIQUES:
			return objHash == ENGAGE_SHOP_TITLE_HASH || objHash == ENGAGE_SHOP_BODY_HASH;
		case ENGAGE_KIND_SHOP:
			return objHash == ENGAGE_SHOP_TITLE_HASH || objHash == ENGAGE_SHOP_BODY_HASH ||
				objHash == ENGAGE_ACCEPT_BTN_HASH;
		case ENGAGE_KIND_CHALLENGE:
		case ENGAGE_KIND_SHOWCASE:
			return objHash == ENGAGE_DLG_SUBJECT_HASH || objHash == ENGAGE_DLG_BODY_HASH ||
				objHash == ENGAGE_DLG_FROM_HASH ||
				(g_engageDlg.kind == ENGAGE_KIND_SHOWCASE && objHash == ENGAGE_BUTTON3_HASH);
		case ENGAGE_KIND_FAILURE:
			return objHash == ENGAGE_SHOP_TITLE_HASH || objHash == ENGAGE_SHOP_BODY_HASH ||
				objHash == ENGAGE_ACCEPT_BTN_HASH;
		default:
			return false;
	}
}

// One language string straight into `out`; false when it is not there.
static bool engageLangText(const LangTable* lang, u32 id, char* out, size_t cap) {
	const char* raw = (lang && id) ? langbin_lookup(lang, id) : NULL;
	if (!raw)
		return false;
	langTextToUtf8(raw, out, cap);
	return true;
}

// What Setup gives the String `objHash`; false leaves it blank, as the
// race's engageDialogText() does.
static bool engageEventText(const LangTable* lang, u32 objHash, char* out, size_t cap) {
	char frame[512];
	const bool showcase = g_engageDlg.kind == ENGAGE_KIND_SHOWCASE;
	if (g_engageDlg.kind == ENGAGE_KIND_UNIQUES)
		return engageLangText(lang, objHash == ENGAGE_SHOP_TITLE_HASH
			? shopEngageHeaderId(g_engageDlg.shop) : ENGAGE_UNIQUES_BODY_ID, out, cap);
	if (g_engageDlg.kind == ENGAGE_KIND_SHOP) {
		const ShopRec* shop = g_engageDlg.shop;
		if (objHash == ENGAGE_SHOP_TITLE_HASH)
			return engageLangText(lang, shopEngageHeaderId(shop), out, cap);
		if (objHash == ENGAGE_ACCEPT_BTN_HASH)
			return engageLangText(lang, shop->kind == 0 ? ENGAGE_SHOP_CRIB_ACCEPT_ID
				: ENGAGE_SHOP_ACCEPT_ID, out, cap);
		// The body: bodyId is the "%s_BODY" label's hash, set at the open
		// while the shop was still unentered; not in the database, the
		// generic line.
		if (shop->kind == 0)
			return engageLangText(lang, ENGAGE_SHOP_CRIB_BODY_ID, out, cap);
		if (g_engageDlg.bodyId && engageLangText(lang, g_engageDlg.bodyId, out, cap))
			return true;
		return engageLangText(lang, ENGAGE_SHOP_GENERIC_BODY_ID, out, cap);
	}
	switch (objHash) {
		case ENGAGE_DLG_BODY_HASH: {
			if (showcase)
				return engageLangText(lang, engageShowcaseTextId(g_engageDlg.showcase->type, false),
					out, cap);
			if (!engageLangText(lang, g_engageDlg.bodyId, frame, sizeof(frame)))
				return false;
			// Timer::SetTime(float(+0x10)), PrintToString(.., 0).
			char t[16];
			race_print_time((s32)((float)g_engageDlg.challenge->timeLimit * ENGAGE_TIMER_TICKS),
				0, t);
			engageFrame(frame, t, out, cap);
			return true;
		}
		case ENGAGE_DLG_SUBJECT_HASH:
			return engageLangText(lang, showcase
				? engageShowcaseTextId(g_engageDlg.showcase->type, true)
				: engageChallengeSubjectId(g_engageDlg.challenge->type), out, cap);
		case ENGAGE_DLG_FROM_HASH:
			if (!g_engageDlg.fromName ||
					!engageLangText(lang, ENGAGE_DLG_FROM_FMT_ID, frame, sizeof(frame)))
				return false;
			engageFrame(frame, g_engageDlg.fromName, out, cap);
			return true;
		case ENGAGE_BUTTON3_HASH:
			return engageLangText(lang, ENGAGE_BUTTON3_SHOOT_ID, out, cap);
		case ENGAGE_SHOP_BODY_HASH:
			return engageLangText(lang, ENGAGE_FAIL_BODY_ID, out, cap);
		case ENGAGE_ACCEPT_BTN_HASH:
			return engageLangText(lang, ENGAGE_FAIL_ACCEPT_ID, out, cap);
		default:
			// The failure dialog's title: FEPrintf of an empty string.
			return false;
	}
}

// The visibility Setup leaves. Objects whose INIT chains to HIDE and that
// carry no MsgR stay down -- the rule feDialogScreen's title and save icon
// follow. Both packages author their Button3 group and Button3 with that
// INIT too, but with responses: the group answers 0xAADD0187 with FadeOut,
// Button3 the accept message (0x0C407210) with a message of its own and
// 0xAADD0187 with FadeOut. None of them ever runs FadeIn or Highlight, so
// nothing but magazine mode's FEngSetVisible brings either back, and they
// are kept down by name as well. A showcase then gets magazine mode's
// SetInvisible / SetVisible calls on top.
static void engageEventVisibility(MenuState* m) {
	int down = 0;
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		const bool button3 = w->hasObjHash &&
			(w->objHash == ENGAGE_EVT_BUTTON3_GROUP || w->objHash == ENGAGE_BUTTON3_HASH);
		if (w->initHides && (!w->hasMsgResp || button3)) {
			menuHideSubtree(m, i, true);
			down++;
		}
	}
	if (g_engageDlg.kind == ENGAGE_KIND_SHOWCASE) {
		for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
			const FngWidget* w = &m->screen.widgets[i];
			if (!w->hasObjHash)
				continue;
			if (w->objHash == ENGAGE_EVT_BACKING1_HASH || w->objHash == ENGAGE_EVT_BACKING2_HASH ||
					w->objHash == ENGAGE_ACCEPT_BTN_HASH || w->objHash == ENGAGE_DECLINE_BTN_HASH)
				menuHideSubtree(m, i, true);
			else if (w->objHash == ENGAGE_EVT_BUTTON3_GROUP || w->objHash == ENGAGE_BUTTON3_HASH)
				menuHideSubtree(m, i, false);
		}
	}
	char b[160];
	snprintf(b, sizeof(b), "engage dialog: %s -- %d INIT-hidden object(s) left down%s",
		m->screenName, down, g_engageDlg.kind == ENGAGE_KIND_SHOWCASE
			? ", magazine mode: Button3 up, Accept / Cancel down" : "");
	dlog(b);
}

// ---- UI_ShowCase_Preview: the in-game photo shoot (#268 B) ----------------
// ShowcaseMagazineDialog (SpeedPS.elf 0x800E8A08), which LaunchMagazine
// switches to for an in-game magazine or DVD cover (showcase types 1 and 2).
// Four buttons -- Control Car, Show Off, Cycle Cameras, Take Picture -- each
// a String with a box Group beside it and a bracket Group that marks the
// current one, a darkened frame around the cover's window, and the masthead
// and the extra MagazineTextureHandler loads into that window when the
// picture is taken. Retail's notification handler is swapped per mode
// (MenuNotificationHandler, ControlCar..., ShowOff..., TakePicture...), which
// is ShootMode here.
//
// PORT: the user's layout (2026-10-22): the street, with the frame, the
// masthead and the extra over it, stays on the top screen; the buttons and
// the legend go to the bottom one, where they take a tap as well as the pad.
// The PC package's legend is three Strings over three backings
// (0xB8A7C6CC..CE, 0x69BA0835..37) where the PS2's names the JOY_EVENT
// icons -- slot 2 is the PS2's 0xD0E625F2 / 0x609FF3E8, the one every mode
// prints into, slot 1 the PS2's 0xD0E625F3 / 0x609FF3E9, which only the
// picture's Back uses. The icons (0xE0AF7B8D..8F) stay down: a 3DS has no
// mouse to point them out.
#define SHOOT_FNG "UI_ShowCase_Preview.fng"
#define SHOOT_BUTTONS 4
// +0x60..+0x6C, the four button Strings, and +0x70..+0x7C, their box Groups.
static const u32 SHOOT_BTN_HASH[SHOOT_BUTTONS] = {
	0x95AD0949u, 0x95AD094Au, 0x95AD094Bu, 0x95AD094Cu,
};
static const u32 SHOOT_BOX_HASH[SHOOT_BUTTONS] = {
	0xC2EA8DE7u, 0xC2EA8DE8u, 0xC2EA8DE9u, 0xC2EA8DEAu,
};
// The brackets around each button, shown by its box's Highlight (the EV
// key that script fires); Take Picture's is the one the code names.
static const u32 SHOOT_BRACKET_HASH[SHOOT_BUTTONS] = {
	0xF9F1F5CDu, 0xF9F1F5CEu, 0xF9F1F5CFu, 0xF9F1F5D0u,
};
#define SHOOT_BTN_CONTROL 0
#define SHOOT_BTN_SHOWOFF 1
#define SHOOT_BTN_CYCLE   2
#define SHOOT_BTN_PICTURE 3
#define SHOOT_FRAME_HASH  0x2253BD97u  // the window's darkened surround
#define SHOOT_MAST_HASH   0xB6638240u  // "MagazineMast"
#define SHOOT_EXTRA_HASH  0x824FA72Fu  // "MagazineExtra"
static const u32 SHOOT_LEGEND_HASH[3] = { 0xB8A7C6CCu, 0xB8A7C6CDu, 0xB8A7C6CEu };
static const u32 SHOOT_BACKING_HASH[3] = { 0x69BA0835u, 0x69BA0836u, 0x69BA0837u };
static const u32 SHOOT_ICON_HASH[3] = { 0xE0AF7B8Du, 0xE0AF7B8Eu, 0xE0AF7B8Fu };
#define SHOOT_EVENT_HASH 0x47FF4E7Cu   // "_Event_Handler_", LeaveThisScreen's FORWARD
// The legend's language hashes: Select, Back, Accept.
#define SHOOT_LANG_SELECT 0x79AD657Fu
#define SHOOT_LANG_BACK   0x001335F0u
#define SHOOT_LANG_ACCEPT 0x4F876B6Fu
// The boxes' INIT, Highlight and UnHighlight put the Group at x -180 where
// its SA says -172; the port runs no scripts, so the children move instead.
#define SHOOT_BOX_SCRIPT_X (-180.0f)
// The boxes' colour: INIT / UnHighlight black at 120, Highlight at 255.
#define SHOOT_BOX_ALPHA    120
#define SHOOT_BOX_ALPHA_HI 255
// The frame's INIT alpha (the SA's too) and FadeIn's 300 ms to 255, which
// the mast and the extra share from 0.
#define SHOOT_FRAME_ALPHA 80
#define SHOOT_FADE_MS 300.0f
// A button's Highlight (looped, 1200 ms): the highlight colour at alpha 0,
// 255 by 440 ms, held to 760 ms, back to 0 at 1200. UnHighlight is white.
#define SHOOT_HILITE_MS 1200
#define SHOOT_HILITE_RGB C2D_Color32(0xCC, 0xF4, 0x8A, 0)
// ShowOff's SetBrake (0x80323E04).
#define SHOOT_SHOWOFF_BRAKE 0.8f

typedef enum {
	SHOOT_MENU = 0,  // MenuNotificationHandler
	SHOOT_CONTROL,   // ControlCarNotificationHandler: the car is the player's
	SHOOT_SHOWOFF,   // ShowOffNotificationHandler: the car held on its brake
	SHOOT_PICTURE,   // TakePictureNotificationHandler: the cover up, Accept / Back
} ShootMode;

typedef struct {
	bool pending;               // LaunchMagazine asked; the engage close opens it
	bool up;
	const ShowcaseRec* sc;
	ShootMode mode;
	int current;                // +0x5C, the current button
	const MagSetup* mag;        // +0x80
	MagSelection sel;           // +0x88
	MagTex mast, extra;         // ms_TextureHandler's two
	u64 fadeAt;                 // TakePicture's FadeIn, 0 when none has run
	u64 hiliteAt;               // the current button's Highlight
	// The package's widgets, -1 where not authored.
	int btn[SHOOT_BUTTONS], box[SHOOT_BUTTONS], bracket[SHOOT_BUTTONS];
	int frame, mast_w, extra_w;
	int legend[3], backing[3];
	char label[3][32];          // Select, Back, Accept, resolved at load
	int saveTick;               // +0x9C: Yes's tick count to the grab
	int grabFrames;             // frames the grab has run, for its give-up
	// ShowcaseMagazineDialog +0x9C / +0xA0 / +0xA4: Show Off has the hood,
	// the doors, the trunk open (ShowOffNotificationHandler 0x800E9624).
	bool partOpen[3];
} ShootState;
static ShootState g_shoot;
// g_ShowcaseMagazineDatabaseFile: loaded the first time a shoot needs it and
// kept (LoadShowcaseMagazineDatabase skips the load when it is there).
static MagDb g_magDb;
static bool g_magDbLoaded;

// ---- UI_MagazineReward.fng: the frontend magazine (#268 B step 4) ---------
// LaunchMagazine's frontend arm (types 3 and 4) pays the showcase as the shoot
// does and leaves the world for EnterFrontendMagazineReward (0x8018669C):
// UIMagazineReward (SpeedPS.elf 0x801868FC, SPEED2.EXE ~0x565880) over
// UIMagazineBack (0x80187200). The cover is put together live: UI_MagazineBack's
// one image behind, the career car through the car setup's
// SelectCarCameraMover orientation, and the masthead, the model and the extra
// over it out of UI_MagazineReward's three images -- every one a 512x512
// texture of FRONTEND/MAGAZINES_STREAMING_HIGH.bin with the cover in its
// top-left 331x429 (MagazineTextureHandler::Init(0, 0)), placed at (84,35) so
// that corner is the window between the package's four bars.
// PORT: the user's layout (frontend menus: navigation down, the car up) -- the
// cover on the top screen at its full height, Continue on the touch screen.
#define MAGREWARD_FNG "UI_MagazineReward.fng"
#define MAGREWARD_CHICK_HASH  0x82227F6Du  // "MagazineChick"
#define MAGREWARD_LABEL_HASH  0xB8A7C6CFu  // the ctor's Continue String
#define MAGREWARD_BUTTON_HASH 0x69BA0838u  // and its button image
#define MAGREWARD_LANG_CONTINUE 0xDE02CF84u
// The four bars around the cover's window: left, right, top, bottom.
static const u32 MAGREWARD_BAR_HASH[4] = {
	0x1641F9E1u, 0xF894E302u, 0xF894E61Au, 0xF894E63Bu,
};
// UI_MagazineBack.fng's "MagazineBack" (texture 0xB65D77FC): 512x512 at
// (84,35), the same rect as the reward's three.
#define MAGBACK_X 84.0f
#define MAGBACK_Y 35.0f
#define MAGBACK_SIZE 512.0f
// The four textures are box-filtered to this: the cover's 331x429 of a 512
// texture is 165x214 texels at 256, against 185x240 pixels on the screen.
#define MAGREWARD_TEX_DIM 256
// The Continue button's scale on the touch screen: its 144x24 at 1:1.
#define MAGREWARD_BOT_SCALE 1.0f
