// The Strings ReplayMenu prints itself, which the loader leaves blank.
static bool replayOwns(u32 objHash) {
	return objHash == REPLAY_W_LAP || objHash == REPLAY_W_HIDE || objHash == REPLAY_W_START ||
		objHash == REPLAY_W_SELECT || objHash == REPLAY_W_LAPTIME || objHash == REPLAY_W_LAPNUM ||
		objHash == REPLAY_W_NUMLAPS || objHash == REPLAY_W_EVENT;
}

// The ctor's three words out of English.bin while the loader has it open.
static void replayResolveLabels(const LangTable* lang) {
	static const u32 kHash[3] = { REPLAY_LANG_LAP, REPLAY_LANG_HIDE, REPLAY_LANG_START };
	static const char* const kFallback[3] = { "Lap", "Hide", "Start" };
	for (int k = 0; k < 3; k++) {
		const char* raw = lang ? langbin_lookup(lang, kHash[k]) : NULL;
		if (raw)
			langTextToUtf8(raw, g_replayUi.label[k], sizeof(g_replayUi.label[k]));
		else
			snprintf(g_replayUi.label[k], sizeof(g_replayUi.label[k]), "%s", kFallback[k]);
	}
}

// The Strings the shoot prints itself: the legend's three.
static bool shootOwns(u32 objHash) {
	for (int k = 0; k < 3; k++)
		if (objHash == SHOOT_LEGEND_HASH[k])
			return true;
	return false;
}

