// Whether widget i is `root` or sits anywhere under it.
static bool shootUnder(const MenuState* m, int i, int root) {
	if (root < 0)
		return false;
	for (int cur = i, k = 0; cur >= 0 && k < 64; cur = m->screen.widgets[cur].parentIndex, k++)
		if (cur == root)
			return true;
	return false;
}

// The mode's buttons and legend as ReturnMenuButtons, ControlCar(MenuButtons),
// ShowOff(MenuButtons) and TakePicture / RemoveMenuButtons leave them: every
// button and box in the menu, only its own under Control Car and Show Off,
// none for the picture, whose TakePicture also takes Take Picture's bracket
// down. The current button's bracket is the one up (its box's Highlight).
// Legend slot 2 says Select, Back, Back, Accept; slot 1 only the picture's
// Back. The mast and the extra are up only over a picture whose textures
// loaded (TakePictureNotificationHandler's per-tick SetVisible).
static void shootSync(MenuState* m) {
	const ShootMode md = g_shoot.mode;
	for (int k = 0; k < SHOOT_BUTTONS; k++) {
		const bool on = md == SHOOT_MENU || (md == SHOOT_CONTROL && k == SHOOT_BTN_CONTROL) ||
			(md == SHOOT_SHOWOFF && k == SHOOT_BTN_SHOWOFF);
		menuHideSubtree(m, g_shoot.btn[k], !on);
		menuHideSubtree(m, g_shoot.box[k], !on);
		menuHideSubtree(m, g_shoot.bracket[k], md == SHOOT_PICTURE || k != g_shoot.current);
	}
	menuHideSubtree(m, g_shoot.mast_w, md != SHOOT_PICTURE || !g_shoot.mast.valid);
	menuHideSubtree(m, g_shoot.extra_w, md != SHOOT_PICTURE || !g_shoot.extra.valid);
	const char* word[3] = { NULL, NULL, NULL };
	if (md == SHOOT_MENU)
		word[2] = g_shoot.label[0];
	else if (md == SHOOT_PICTURE) {
		word[1] = g_shoot.label[1];
		word[2] = g_shoot.label[2];
	} else
		word[2] = g_shoot.label[1];
	if (!m->prBuf)
		m->prBuf = C2D_TextBufNew(256);
	else
		C2D_TextBufClear(m->prBuf);
	for (int k = 0; k < 3; k++) {
		menuHideSubtree(m, g_shoot.legend[k], !word[k]);
		menuHideSubtree(m, g_shoot.backing[k], !word[k]);
		menuSetWidgetText(m, word[k] ? m->prBuf : NULL, g_shoot.legend[k], word[k] ? word[k] : "");
	}
}

// Setup's share, done by hand once the layout exists since the package's INIT
// scripts are not run: the boxes' scripted x, the split, what the ctor and the
// INITs leave down -- the legend's icons, the event handler's marker String --
// and then ReturnMenuButtons, Setup's one call, through shootSync().
static void shootSetup(MenuState* m) {
	const FngScreen* sc = &m->screen;
	const int n = sc->widgetCount < FNG_MAX_WIDGETS ? sc->widgetCount : FNG_MAX_WIDGETS;
	for (int k = 0; k < SHOOT_BUTTONS; k++) {
		g_shoot.btn[k] = gmFind(m, SHOOT_BTN_HASH[k]);
		g_shoot.box[k] = gmFind(m, SHOOT_BOX_HASH[k]);
		g_shoot.bracket[k] = gmFind(m, SHOOT_BRACKET_HASH[k]);
	}
	g_shoot.frame = gmFind(m, SHOOT_FRAME_HASH);
	g_shoot.mast_w = gmFind(m, SHOOT_MAST_HASH);
	g_shoot.extra_w = gmFind(m, SHOOT_EXTRA_HASH);
	for (int k = 0; k < 3; k++) {
		g_shoot.legend[k] = gmFind(m, SHOOT_LEGEND_HASH[k]);
		g_shoot.backing[k] = gmFind(m, SHOOT_BACKING_HASH[k]);
	}
	for (int k = 0; k < SHOOT_BUTTONS; k++) {
		const int b = g_shoot.box[k];
		if (b < 0)
			continue;
		const float dx = SHOOT_BOX_SCRIPT_X - sc->widgets[b].posX;
		for (int i = 0; i < n; i++)
			if (shootUnder(m, i, b))
				m->worldPosX[i] += dx;
	}
	// The street with the cover's frame, the mast and the extra stays up;
	// the buttons, the title and the legend go to the touch screen.
	int top = 0;
	for (int i = 0; i < n; i++) {
		const bool up = shootUnder(m, i, g_shoot.frame) || i == g_shoot.mast_w ||
			i == g_shoot.extra_w;
		m->layoutBottom[i] = !up;
		top += up;
	}
	m->splitToBottom = true;
	m->splitBotScale = m->layoutScale;  // until shootLayoutBottom() fits the panel
	m->isShoot = true;
	for (int k = 0; k < 3; k++)
		menuHideSubtree(m, gmFind(m, SHOOT_ICON_HASH[k]), true);
	menuHideSubtree(m, gmFind(m, SHOOT_EVENT_HASH), true);
	shootLayoutBottom(m);
	shootSync(m);
	char b[200];
	snprintf(b, sizeof(b), "shoot: %s -- %d widget(s) up top (frame %d, mast %d, extra %d), "
		"buttons %d/%d/%d/%d", m->screenName, top, g_shoot.frame, g_shoot.mast_w,
		g_shoot.extra_w, g_shoot.btn[0], g_shoot.btn[1], g_shoot.btn[2], g_shoot.btn[3]);
	dlog(b);
}

// The scripted colours, set each frame before the draw: the boxes' black at
// INIT / UnHighlight's 120 and Highlight's 255 for the current one, and the
// frame at INIT's 80 or on TakePicture's FadeIn to 255 over 300 ms, which the
// mast and the extra share from 0. Both Groups carry Color tracks, so the
// loader left them out of groupTint[].
static void shootTick(MenuState* m) {
	if (!m->isShoot)
		return;
	const int n = m->screen.widgetCount < FNG_MAX_WIDGETS ? m->screen.widgetCount : FNG_MAX_WIDGETS;
	float f = 0.0f;
	if (g_shoot.fadeAt) {
		f = (float)(osGetTime() - g_shoot.fadeAt) / SHOOT_FADE_MS;
		if (f > 1.0f)
			f = 1.0f;
	}
	const u8 frameA = (u8)(SHOOT_FRAME_ALPHA + (255 - SHOOT_FRAME_ALPHA) * f + 0.5f);
	for (int i = 0; i < n; i++) {
		if (i != g_shoot.frame && shootUnder(m, i, g_shoot.frame)) {
			m->groupTint[i] = C2D_Color32(255, 255, 255, frameA);
			continue;
		}
		for (int k = 0; k < SHOOT_BUTTONS; k++)
			if (i != g_shoot.box[k] && shootUnder(m, i, g_shoot.box[k]))
				m->groupTint[i] = C2D_Color32(0, 0, 0,
					k == g_shoot.current ? SHOOT_BOX_ALPHA_HI : SHOOT_BOX_ALPHA);
	}
	const u8 a = (u8)(255.0f * f + 0.5f);
	if (g_shoot.mast_w >= 0)
		m->groupTint[g_shoot.mast_w] = C2D_Color32(255, 255, 255, a);
	if (g_shoot.extra_w >= 0)
		m->groupTint[g_shoot.extra_w] = C2D_Color32(255, 255, 255, a);
}

// The texture handler's SetTextureHash: the loaded masthead and extra in
// place of the placeholders the package names.
static void shootImage(const MenuState* m, int i, C2D_Image* img) {
	if (!m->isShoot)
		return;
	if (i == g_shoot.mast_w && g_shoot.mast.valid)
		*img = g_shoot.mast.image;
	else if (i == g_shoot.extra_w && g_shoot.extra.valid)
		*img = g_shoot.extra.image;
}

