// The same swap for the frontend magazine's three.
static void magRewardImage(const MenuState* m, int i, C2D_Image* img) {
	if (!m->isMagReward)
		return;
	if (i == g_magReward.mast_w && g_magReward.mast.valid)
		*img = g_magReward.mast.image;
	else if (i == g_magReward.chick_w && g_magReward.chick.valid)
		*img = g_magReward.chick.image;
	else if (i == g_magReward.extra_w && g_magReward.extra.valid)
		*img = g_magReward.extra.image;
}

