// OwnedPartInventory::OwnsCarPart's (0x801358BC) slots that are never owned.
static bool bodyShopNeverOwned(int slot) {
	return slot == 0x3F || (slot >= 0x44 && slot <= 0x47) || slot == 0x49;
}

// GetWordToSetBitFor's word, as an offset into the profile's inventory block,
// and its bit; -1 when the bit falls outside the block.
static int bodyShopOwnedWord(int slot, int entity, int idx, int* bit) {
	int base = -1, size = 0;
	switch (slot) {
	case 0x1D: case 0x1E: base = 0x16C; size = 0x100; break;
	case 0x07: base = 0x26C; size = 0x10; break;
	case 0x0C: base = 0x27C; size = 0x10; break;
	case 0x20: base = 0x28C; size = 0x08; break;
	case 0x09: base = 0x298; size = 0x08; break;   // object +0x294, written at +0x298
	case 0xA2: base = 0x3B0; size = 0x10; break;   // object +0x29C, written at +0x3B0
	default: break;
	}
	if (idx < 0)
		return -1;
	if (base < 0) {
		*bit = idx & 31;
		return entity >= 0 && entity * 4 + 4 <= 0x15C ? entity * 4 : -1;
	}
	*bit = idx % 32;
	const int off = base + (idx / 32) * 4;
	return off + 4 <= base + size ? off : -1;
}

static bool bodyShopOwnsBit(int cs, int slot, int entity, int idx) {
	if (cs < 0 || cs >= PROFILE_CAREER_ARRAYS || bodyShopNeverOwned(slot))
		return false;
	int bit = 0;
	const int off = bodyShopOwnedWord(slot, entity, idx, &bit);
	if (off < 0)
		return false;
	u32 w;
	memcpy(&w, &gProfile.careerVisualInv[cs][off], sizeof(w));
	return (w >> bit) & 1u;
}

// OwnedPartInventory::BuyCarPart (0x80135858): word |= 1 << bit.
static void bodyShopSetOwned(int cs, int slot, int entity, int idx) {
	if (cs < 0 || cs >= PROFILE_CAREER_ARRAYS || bodyShopNeverOwned(slot))
		return;
	int bit = 0;
	const int off = bodyShopOwnedWord(slot, entity, idx, &bit);
	if (off < 0)
		return;
	u32 w;
	memcpy(&w, &gProfile.careerVisualInv[cs][off], sizeof(w));
	w |= 1u << bit;
	memcpy(&gProfile.careerVisualInv[cs][off], &w, sizeof(w));
}

// The owned bit for part `hash` in `slot` of the career car, found by its
// place in the car's list (BuyCarPart off any screen that has the database).
static void customizeOwnPart(const CarPartDb* db, int cs, int slot, u32 hash) {
	if (!db || cs < 0 || cs >= PROFILE_CAREER_ARRAYS || !hash)
		return;
	const u32 car = gProfile.careerParts[cs][0];
	int idx = 0;
	for (CarPart p = carpartdb_get(db, car, slot, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(db, car, slot, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
		if (carpartdb_hash(p) == hash) {
			bodyShopSetOwned(cs, slot, stargazer_unlockable(db, slot, p), idx);
			return;
		}
	}
}

// GetUnlockablePartCost (0x8012E228).
static int bodyShopPartCost(const PerfDb* pdb, int entity, int level) {
	if (level == 4)
		return 0;
	if (level == 0) {
		if (entity != 0x4C)
			return 0;
		level = 1;
	}
	const PerfUnlockRec* u = pdb ? perfdb_unlock(pdb, entity) : NULL;
	return u && level >= 1 && level <= 3 ? (int)(s16)u->level[level - 1].ratingMax : 0;
}

// IsPartAvailable under the session's filter (see the top of this block).
// CareerUnlocker::IsCarPartUnlocked's filter-4 arm (0x8012F530) asks a
// manufacturer vinyl (unlockable 0x3D) its cheat code alone, by the part's
// name hash (EasterEggs::IsManufacturerVinylUnlocked; PC 0x579DA0), and
// QuickRaceUnlocker's (0x8012F088; PC 0x529D60) adds stock and the visual
// code of the part's level (#446).
static bool bodyShopAvailable(const PerfDb* pdb, const PerfUnlockCtx* ctx, int cs, int slot,
		int entity, int idx, int level, u32 hash) {
	bool ok = false;
	if (ctx->filter & PERF_FILTER_CAREER)
		ok = level == 0 || bodyShopOwnsBit(cs, slot, entity, idx);
	if (ctx->filter & PERF_FILTER_ONLINE)
		ok = ok || (entity == 0x3D ? cheats_manufacturer_vinyl(hash)
			: (pdb && perfdb_entity_unlocked(pdb, ctx, entity, level)));
	if (ctx->filter & PERF_FILTER_QUICKRACE)
		ok = ok || level == 0 || cheats_visual_level(level);
	return ok;
}

// GetPartsList for one slot: `carbon` picks the 0x29A list (the carbon
// parts) over the plain one. Fills `c` when given, else only counts.
static int bodyShopPartsList(const CarPartDb* db, const PerfDb* pdb, const PerfUnlockCtx* ctx,
		const LangTable* lang, int cs, u32 car, int slot, bool carbon, BodyShopCat* c) {
	int n = 0, idx = 0;
	for (CarPart p = carpartdb_get(db, car, slot, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(db, car, slot, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
		const bool cf = carpartdb_attr(db, p, UNIQUES_ATTR_HOOD_VINYL, 0) != 0;
		// GetIcePartsList (0x8015E708): no carbon split, and slot 9 only its
		// kit-5 parts (the split hoods) -- the body shop's hoods are the rest.
		if (g_bodyShop.iceMode) {
			if (slot == 0x09 && carpartdb_kit(p) != 5)
				continue;
		} else {
			if (cf != carbon)
				continue;
			if (slot == 0x09 && carpartdb_kit(p) == 5)
				continue;
		}
		const int level = carpartdb_level(p);
		const int entity = stargazer_unlockable(db, slot, p);
		if (!bodyShopAvailable(pdb, ctx, cs, slot, entity, idx, level, carpartdb_hash(p)))
			continue;
		n++;
		if (!c || c->count >= BODYSHOP_MAX_PARTS)
			continue;
		const int i = c->count++;
		c->hash[i] = carpartdb_hash(p);
		c->level[i] = (u8)level;
		c->entity[i] = (u8)entity;
		c->index[i] = (s16)idx;
		c->hoodVinyls[i] = cf;
		c->price[i] = bodyShopPartCost(pdb, entity, level);
		const u32 nameId = carpartdb_attr(db, p, UNIQUES_ATTR_NAME_ID, 0);
		const char* raw = (lang && nameId) ? langbin_lookup(lang, nameId) : NULL;
		if (raw) {
			langTextToUtf8(raw, c->name[i], sizeof(c->name[i]));
		} else {
			const char* nm = carpartdb_name(db, p);
			snprintf(c->name[i], sizeof(c->name[i]), "%s", nm ? nm : "");
		}
	}
	return n;
}

static const BodyShopCat* bodyShopCurrent(const MenuState* m) {
	if (!m || !m->isBodyShop || !g_bodyShop.built || m->selected < 0 ||
			m->selected >= g_bodyShop.ncat)
		return NULL;
	return &g_bodyShop.cat[m->selected];
}

static void bodyShopAddCategory(int slot, u32 icon, u32 label, const char* fallback, u8 kind) {
	if (g_bodyShop.ncat >= BODYSHOP_MAX_CATS)
		return;
	BodyShopCat* c = &g_bodyShop.cat[g_bodyShop.ncat++];
	memset(c, 0, sizeof(*c));
	c->slot = slot;
	c->icon = icon;
	c->label = label;
	c->fallback = fallback;
	c->kind = kind;
}

// CarCustomizeManager's paint setup (+0x54), the cart the graphics shop's
// screens add to and its Purchase installs: {part, CAR_SLOT_ID} pairs, one
// per slot. AddPaintShopPart (0x8016EEA4) takes the slot's old entry out and
// appends the new one; GetPaintSetupPrice (0x8016FA88) sums GetCarPartCost
// over the entries DoesPaintPartHaveCost (0x8016FA6C) passes -- every slot
// but 0x34..0x3E, the vinyl colours. The cost, entity and list index are
// kept with the part (GetCarPartCost's MapCarPartToUnlockable and level,
// OwnedPartInventory's bit) since the port reads them off the database once.
// UI_Paint (ChoosePaintScreen), the vinyls and the decals add to it.
#define PAINT_SETUP_MAX 96   // a decal zone's removal alone is eight entries
typedef struct {
	int slot;        // CAR_SLOT_ID
	u32 hash;        // the part
	int price;       // GetCarPartCost
	u8 entity;       // MapCarPartToUnlockable
	s16 index;       // its place in the slot's list (the owned bit)
	u8 kit;          // a vinyl's group
	bool unique;     // a vinyl kit, all four layers
	bool colours;    // a vinyl with NUMCOLOURS
} PaintSetupEntry;
static PaintSetupEntry g_paintSetup[PAINT_SETUP_MAX];
static int g_paintSetupCount = 0;
static int g_paintSetupPrice = 0;
static char g_paintCatText[2][256];   // the exit question, the empty Purchase's OK

static bool paintPartHasCost(int slot) {
	return !(slot > 0x33 && slot < 0x3F);
}

static void paintSetupReprice(void) {
	int sum = 0;
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].hash && paintPartHasCost(g_paintSetup[k].slot))
			sum += g_paintSetup[k].price;
	g_paintSetupPrice = sum;
}

// ClearPaintSetup (0x8016F778).
static void paintSetupClear(void) {
	g_paintSetupCount = 0;
	g_paintSetupPrice = 0;
}

// GetPaintSetupPart (0x8016EE00): the slot's part in the setup, 0 for none.
static u32 paintSetupPart(int slot) {
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].slot == slot)
			return g_paintSetup[k].hash;
	return 0;
}

// AddPaintShopPart (0x8016EEA4): the slot's entry goes, the part is appended.
static void paintSetupAdd(int slot, u32 hash, int price, int entity, int index) {
	if (!hash)
		return;
	int n = 0;
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].slot != slot)
			g_paintSetup[n++] = g_paintSetup[k];
	g_paintSetupCount = n;
	if (g_paintSetupCount >= PAINT_SETUP_MAX)
		return;
	PaintSetupEntry* e = &g_paintSetup[g_paintSetupCount++];
	e->slot = slot;
	e->hash = hash;
	e->price = price;
	e->entity = (u8)entity;
	e->index = (s16)index;
	paintSetupReprice();
}

// RevertPaintSetup's paint arm (0x8016F648, category 2): the entries in
// slot 0x3F and 0x44..0x4A go -- the roof and mirror paints (0x4B, 0x4C)
// stay, as they do in retail.
static void paintSetupRevertPaint(void) {
	int n = 0;
	for (int k = 0; k < g_paintSetupCount; k++) {
		const int s = g_paintSetup[k].slot;
		if (s == 0x3F || (s > 0x43 && s < 0x4B))
			continue;
		g_paintSetup[n++] = g_paintSetup[k];
	}
	g_paintSetupCount = n;
	paintSetupReprice();
}

// The career record's mirrors of its slot array (profile_career_choose()):
// BASE_PAINT and the part paints, kept with the parts they copy.
static void paintSyncCareerMirrors(int cs) {
	const unsigned int* parts = gProfile.careerParts[cs];
	ProfileCarRecord* c = &gProfile.careerCar[cs];
	c->basePaint    = parts[0x40];   // CAR_SLOT_ID 0x3F
	c->paintSpoiler = parts[0x46];   // 0x45
	c->paintRim     = parts[0x4A];   // 0x49
	c->paintSpinner = parts[0x4B];   // 0x4A
	c->paintRoof    = parts[0x4C];   // 0x4B
	c->paintMirror  = parts[0x4D];   // 0x4C
	for (int v = 0; v < 4; v++)
		c->vinylLayer[v] = parts[0x41 + v];
}

