//   * BuildColorLists (0x8017C094): GetPartsList(slot) through
//     IsColorAvailable (unlock entity 0x17 at the part's level), a
//     PAINT_SWATCH_n each (13), its FEColor {b, g, r, a} = BLUE 0x136707,
//     GREEN 0x2DDC8F0, RED 0xD99A, 0xFF (hudColourRgb()); the highlight on
//     the stage's last pick (+0x78 / +0x8C /
//     +0xA0, 1 to begin with and again on a B);
//   * chosen: DAT_803D9724 (0xA4), DAT_803D9728 (0xA6), DAT_803D972C (0xA5),
//     GetRidePartAttributes' installed parts until a swatch moves.
// PORT: the preview's tach is hud.c's own cluster (the in-game one, the same
// HUD_CustomTextures sets) drawn where it races, on the top screen; the
// swatches are drawn on the bottom screen (drawHudPicker()).
#define HUDPICK_MAX 13
#define HUD_ATTR_INDEX 0x311151F8u   // HUDINDEX, g_displayHUDattributes
typedef struct {
	int stage;
	u32 rowStyle[BODYSHOP_MAX_PARTS];  // each 0xA3 row's HUDINDEX
	int nCol[3];
	u32 colHash[3][HUDPICK_MAX];
	u32 colRgb[3][HUDPICK_MAX];        // 0x00RRGGBB
	int last[3];                       // 1-based
	int cur;                           // +0x60, 1-based
	u32 chosen[3];                     // lists 0, 1, 2 -> slots 0xA4, 0xA6, 0xA5
	u32 tint[3];                       // the preview's fill / needle / plate
	char title[3][64];
	Hud* hud;
	u32 hudStyle;
	bool hudTried;
} HudPick;
static HudPick g_hudPick;

// A Custom Gauges colour part's 0x00RRGGBB, hud.c's tint (#477). The
// attribute names are bStringHash's: "RED" 0x0000D99A, "GREEN" 0x02DDC8F0,
// "BLUE" 0x00136707 -- the part RED is {207, 48, 48}. Read the other way
// round, red and blue traded places: "Red" and "Orange" drew blue, "Blue"
// orange, and no swatch was red or yellow.
static u32 hudColourRgb(const CarPartDb* db, CarPart p) {
	return ((carpartdb_attr(db, p, 0x0000D99Au, 0) & 0xFF) << 16) |
		((carpartdb_attr(db, p, 0x02DDC8F0u, 0) & 0xFF) << 8) |
		(carpartdb_attr(db, p, 0x00136707u, 0) & 0xFF);
}
static bool g_spinnerBrowse;      // ... with ChooseSpinnerBrand's (UI_ChooseSpinner)
static bool g_rimBrandBrowse;      // the next body shop load is ChooseRimBrand's
static bool g_rimsBrowse;          // ... RimsBrowser's
static u32  g_rimBrand;            // DAT_803D96E0: the brand ChooseRimBrand chose
static u32  g_rimBrandLabel;       // its IconOption's name (GetBrandNameFromHash)
static u32  g_rimBrandLast;        // ChooseRimBrand's FEngGetLastButton, a brand; 0 none
static bool g_carbonBrowse;        // the next body shop load is SetupCarbonParts'
static int  g_carbonSnap = 9;      // its SnapToItem slot
static int  g_iceLastSlot;         // UI_ICEMAIN's FEngGetLastButton: the row a sub-screen left from
// IceSelectionScreen's mode (0x803D84EC) for the trunk audio screens, each
// UI_ICEMAIN again (CalcNextScreenFromChooseIceCategory leaves every mode but
// 7 and 8 on it): 0 the shop, 2 the layouts with one fitted (StartBrowsing at
// once), 3 a stock trunk's Audio Components / Trunk Layout, 4 and 5 the
// audio slots (from 3 and from a new layout). Kept across the screen loads.
enum { ICE_MODE_MAIN = 0, ICE_MODE_TRUNK_LAYOUT = 2, ICE_MODE_TRUNK_STOCK = 3,
	ICE_MODE_TRUNK_SLOTS = 4, ICE_MODE_TRUNK_SLOTS_NEW = 5 };
static int  g_iceMode;
static void bodyShopStartBrowsing(MenuState* m);
// ChooseDecalCategory's levels (+0x170 the level, +0x174 the parents, +0x180
// the last option per level) and ChooseDecalScreen's colour toggle (+0x138)
// and kept part (+0x13C, here its brand). The level is 0 on every entry.
static struct {
	u32 level;
	u32 parent[3];
	u8 lastIdx[3];
	bool white;
	u32 keepBrand;
	u32 dlgValue;   // the option a hub question is about
	int dlgRow;     // the overlay row its question is about
	int hoodLevel;  // the car's hood's level, read at Setup
} g_decal;

// What the car has on each layer, read off the database as a vinyl screen
// comes up: the part, its group, kit-ness, colours and what a setup entry
// for it costs (BuildVinylAndColorsListForSwap moves installed vinyls into
// the setup).
static PaintSetupEntry g_vinylInst[4];

// The vinyl kits seen so far, so the preview can tell one without the
// database (IsUniqueOnPreview).
static u32 g_vinylUniqueSeen[16];
static int g_vinylUniqueSeenCount;

static void vinylNoteUnique(u32 h) {
	for (int k = 0; k < g_vinylUniqueSeenCount; k++)
		if (g_vinylUniqueSeen[k] == h)
			return;
	if (g_vinylUniqueSeenCount < 16)
		g_vinylUniqueSeen[g_vinylUniqueSeenCount++] = h;
}

static bool vinylIsUnique(u32 h) {
	for (int k = 0; h && k < g_vinylUniqueSeenCount; k++)
		if (g_vinylUniqueSeen[k] == h)
			return true;
	return false;
}

// IsVinylColorSlotForVinylSlot (0x8016FC08): layer L's colours are
// 0x4D + 4 (L - 0x40) .. + 3.
static bool vinylColourOf(int layer, int slot) {
	if (layer < 0x40 || layer > 0x43)
		return false;
	const int c0 = 0x4D + (layer - 0x40) * 4;
	return slot >= c0 && slot < c0 + 4;
}

// A vinyl part's facts off the database: its place in the slot-0x40 list
// (the owned bit), cost, group, kit-ness and colours. False when the car has
// no such vinyl.
static bool vinylPartInfo(const CarPartDb* db, const PerfDb* pdb, u32 car, u32 hash,
		PaintSetupEntry* e) {
	int idx = 0;
	for (CarPart p = carpartdb_get(db, car, 0x40, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(db, car, 0x40, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
		if (carpartdb_hash(p) != hash)
			continue;
		const int entity = stargazer_unlockable(db, 0x40, p);
		e->hash = hash;
		e->entity = (u8)entity;
		e->index = (s16)idx;
		e->price = bodyShopPartCost(pdb, entity, carpartdb_level(p));
		e->kit = (u8)carpartdb_kit(p);
		e->unique = carpartdb_attr(db, p, VINYL_ATTR_UNIQUE, 0) == 0x40;
		e->colours = carpartdb_attr(db, p, VINYL_ATTR_COLOURS, 0) != 0;
		if (e->unique)
			vinylNoteUnique(hash);
		return true;
	}
	return false;
}

// g_vinylInst off the career car (GetInstalledPart for 0x40..0x43).
static void vinylReadInstalled(const CarPartDb* db, const PerfDb* pdb, int cs, u32 car) {
	memset(g_vinylInst, 0, sizeof(g_vinylInst));
	for (int k = 0; k < 4; k++) {
		PaintSetupEntry* e = &g_vinylInst[k];
		e->slot = 0x40 + k;
		const u32 h = cs >= 0 && cs < PROFILE_CAREER_ARRAYS
			? uniquesGetPart(gProfile.careerParts[cs], 0x40 + k) : 0;
		if (h && db && !vinylPartInfo(db, pdb, car, h, e))
			e->hash = h;   // not in this car's list: kept, as the car wears it
		e->slot = 0x40 + k;
	}
}

// The setup's entry for a slot, -1 for none.
static int paintSetupFind(int slot) {
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].slot == slot)
			return k;
	return -1;
}

// IsVinylInCurrentSetup (0x8016FF70): an entry for the layer, a removal (no
// part) counting only when `orNone`.
static bool vinylInSetup(int layer, bool orNone) {
	const int k = paintSetupFind(layer);
	return k >= 0 && (g_paintSetup[k].hash != 0 || orNone);
}

// IsVinylInstalled (0x8016FC88).
static bool vinylInstalled(int layer) {
	return layer >= 0x40 && layer <= 0x43 && g_vinylInst[layer - 0x40].hash != 0;
}

// IsUniqueInCurrentSetup (0x8016FDF0) / IsUniqueInstalled(0xA9) (0x8016FCC8).
static bool vinylUniqueInSetup(void) {
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].slot >= 0x40 && g_paintSetup[k].slot <= 0x43 &&
				g_paintSetup[k].hash && (g_paintSetup[k].unique || vinylIsUnique(g_paintSetup[k].hash)))
			return true;
	return false;
}

static bool vinylUniqueInstalled(void) {
	for (int k = 0; k < 4; k++)
		if (g_vinylInst[k].hash && (g_vinylInst[k].unique || vinylIsUnique(g_vinylInst[k].hash)))
			return true;
	return false;
}

// The layer's vinyl as the setup leaves it: GetVinylInSetup, else the car's.
// `entry` gets the setup's or the car's record when wanted.
static u32 vinylEffective(int layer, const PaintSetupEntry** entry) {
	const int k = paintSetupFind(layer);
	const PaintSetupEntry* e = k >= 0 ? &g_paintSetup[k]
		: (layer >= 0x40 && layer <= 0x43 ? &g_vinylInst[layer - 0x40] : NULL);
	if (entry)
		*entry = e;
	return e ? e->hash : 0;
}

// RemoveVinylAndColorsFromSetup (0x8016F200): the layer's entry and its
// colours' go.
static void vinylSetupRemoveLayer(int layer) {
	int n = 0;
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].slot != layer && !vinylColourOf(layer, g_paintSetup[k].slot))
			g_paintSetup[n++] = g_paintSetup[k];
	g_paintSetupCount = n;
}

static void vinylSetupRemoveAll(void) {
	for (int l = 0x40; l < 0x44; l++)
		vinylSetupRemoveLayer(l);
}

// IsDecalSlot (0x80170E48) / IsDecalLayoutSlot (0x80170E5C).
static bool decalIsSlot(int slot) { return slot >= 0x61 && slot < 0x99; }
static bool decalIsLayoutSlot(int slot) { return slot >= 0x34 && slot < 0x3F; }

// The career car's part in a slot (GetInstalledPart), 0 for none.
static u32 decalInstalled(int slot) {
	const int cs = gProfile.currentCarSlot;
	return cs >= 0 && cs < PROFILE_CAREER_ARRAYS ? uniquesGetPart(gProfile.careerParts[cs], slot) : 0;
}

// RemoveDecal (0x801708EC): the slot's entries go, and a decal the car
// wears is taken off with a {slot, no part} entry.
static void decalSetupRemove(int slot) {
	if (!decalIsSlot(slot))
		return;
	int n = 0;
	for (int k = 0; k < g_paintSetupCount; k++)
		if (g_paintSetup[k].slot != slot)
			g_paintSetup[n++] = g_paintSetup[k];
	g_paintSetupCount = n;
	if (decalInstalled(slot) && g_paintSetupCount < PAINT_SETUP_MAX) {
		PaintSetupEntry* e = &g_paintSetup[g_paintSetupCount++];
		memset(e, 0, sizeof(*e));
		e->slot = slot;
	}
	paintSetupReprice();
}

// RemoveAllDecalsFromSetup (0x80170844), RevertPaintSetup(1): every decal
// and decal layout entry goes.
static void decalSetupRemoveAll(void) {
	int n = 0;
	for (int k = 0; k < g_paintSetupCount; k++)
		if (!decalIsSlot(g_paintSetup[k].slot) && !decalIsLayoutSlot(g_paintSetup[k].slot))
			g_paintSetup[n++] = g_paintSetup[k];
	g_paintSetupCount = n;
	paintSetupReprice();
}

static void vinylSetupAppend(const PaintSetupEntry* e) {
	if (g_paintSetupCount < PAINT_SETUP_MAX)
		g_paintSetup[g_paintSetupCount++] = *e;
}

// AddVinylToPaintSetup (0x8016F08C): a kit, or anything over a kit in the
// setup, clears every layer's entries first; else only this layer's.
static void vinylSetupAdd(int layer, const PaintSetupEntry* part) {
	if (!part || !part->hash || layer < 0x40 || layer > 0x43)
		return;
	if (g_paintSetupCount > 0) {
		if (part->unique || vinylUniqueInSetup())
			vinylSetupRemoveAll();
		else
			vinylSetupRemoveLayer(layer);
	}
	PaintSetupEntry e = *part;
	e.slot = layer;
	vinylSetupAppend(&e);
	paintSetupReprice();
}

// RemoveVinyl (0x8016FFCC): the layer's entries go and, when the car has a
// vinyl there, a removal entry (no part) takes their place. With a kit on
// the car or in the setup every layer's entries go, the removal on the kit's.
static void vinylSetupRemove(int layer) {
	if (layer < 0x40 || layer > 0x43)
		return;
	if (!vinylUniqueInstalled() && !vinylUniqueInSetup()) {
		vinylSetupRemoveLayer(layer);
	} else {
		for (int l = 0x40; l < 0x44; l++)
			if (g_vinylInst[l - 0x40].hash && (g_vinylInst[l - 0x40].unique ||
					vinylIsUnique(g_vinylInst[l - 0x40].hash)))
				layer = l;
		vinylSetupRemoveAll();
	}
	if (vinylInstalled(layer)) {
		PaintSetupEntry e;
		memset(&e, 0, sizeof(e));
		e.slot = layer;
		vinylSetupAppend(&e);
	}
	paintSetupReprice();
}

// BuildVinylAndColorsListForSwap (0x80170330): the layer's setup entries
// (taken out), else the car's vinyl and colours, else a removal.
static int vinylSwapList(int layer, PaintSetupEntry* out, int cap) {
	int n = 0;
	if (vinylInSetup(layer, true)) {
		int m = 0;
		for (int k = 0; k < g_paintSetupCount; k++) {
			const PaintSetupEntry* e = &g_paintSetup[k];
			if ((e->slot == layer || vinylColourOf(layer, e->slot)) && n < cap)
				out[n++] = *e;
			else
				g_paintSetup[m++] = *e;
		}
		g_paintSetupCount = m;
	} else if (vinylInstalled(layer)) {
		out[n++] = g_vinylInst[layer - 0x40];
		const int cs = gProfile.currentCarSlot;
		for (int c = 0x4D; c < 0x5C && n < cap; c++) {
			const u32 h = cs >= 0 && cs < PROFILE_CAREER_ARRAYS
				? uniquesGetPart(gProfile.careerParts[cs], c) : 0;
			if (vinylColourOf(layer, c) && h) {
				memset(&out[n], 0, sizeof(out[n]));
				out[n].slot = c;
				out[n].hash = h;
				n++;
			}
		}
	} else {
		memset(&out[n], 0, sizeof(out[n]));
		out[n].slot = layer;
		n++;
	}
	return n;
}

// SwapVinyl (0x8017010C): each layer's list is moved onto the other layer,
// its colours with it (MapVinylColorSlotToVinylColorSlotForVinylSlot), and
// both are appended to the setup.
static void vinylSetupSwap(int a, int b) {
	if (a < 0x40 || a > 0x43 || b < 0x40 || b > 0x43)
		return;
	PaintSetupEntry la[5], lb[5];
	const int na = vinylSwapList(a, la, 5);
	if (na == 0)
		return;
	const int nb = vinylSwapList(b, lb, 5);
	for (int k = 0; k < na; k++)
		la[k].slot = la[k].slot == a ? b : la[k].slot + (b - a) * 4;
	for (int k = 0; k < nb; k++)
		lb[k].slot = lb[k].slot == b ? a : lb[k].slot + (a - b) * 4;
	for (int k = 0; k < na; k++)
		vinylSetupAppend(&la[k]);
	for (int k = 0; k < nb; k++)
		vinylSetupAppend(&lb[k]);
	paintSetupReprice();
}

// ResetPreviewToPaintSetup (0x8017066C) on `parts`: the career car with the
// setup over it, a vinyl entry over a kit on the preview clearing the four
// layers first.
static void paintSetupPreviewParts(unsigned int* parts, int cs) {
	memcpy(parts, gProfile.careerParts[cs], sizeof(gProfile.careerParts[cs]));
	for (int k = 0; k < g_paintSetupCount; k++) {
		const PaintSetupEntry* e = &g_paintSetup[k];
		if (e->slot >= 0x40 && e->slot <= 0x43) {
			bool kit = false;
			for (int l = 0x40; l < 0x44 && !kit; l++)
				kit = vinylIsUnique(uniquesGetPart(parts, l));
			for (int l = 0x40; kit && l < 0x44; l++)
				uniquesSetPart(parts, l, 0);
		}
		uniquesSetPart(parts, e->slot, e->hash);
	}
}

// PreviewVinyl (0x8017052C) over that: a kit -- or anything while one is on
// the preview or in the setup -- clears the four layers before it goes on.
static void vinylPreviewParts(unsigned int* parts, int layer, u32 hash) {
	bool kit = vinylUniqueInSetup() || vinylIsUnique(hash);
	for (int l = 0x40; l < 0x44 && !kit; l++)
		kit = vinylIsUnique(uniquesGetPart(parts, l));
	for (int l = 0x40; kit && l < 0x44; l++)
		uniquesSetPart(parts, l, 0);
	uniquesSetPart(parts, layer, hash);
}

// The next screen, asked for by a screen's handler and taken by the frontend
// loop once the pads are read: a push of `g_feNavPush`, or a pop back down the
// stack (ChangeToNextScreen / ChangeToPrevScreen).
static char g_feNavPush[64];
static bool g_feNavPop;

static void feNavPush(const char* screen) {
	snprintf(g_feNavPush, sizeof(g_feNavPush), "%s", screen);
	g_feNavPop = false;
}

static void feNavPop(void) {
	g_feNavPush[0] = 0;
	g_feNavPop = true;
}

// A push that takes the current screen's place on the stack instead of going
// over it: the way back from the new screen is the one under the old.
static bool g_feNavReplace;
static void feNavReplace(const char* screen) {
	feNavPush(screen);
	g_feNavReplace = true;
}

// The screen built again in place (ChooseDecalCategory's ChangeLevel: the
// list cleared and Setup run again on the new level).
static bool g_feNavReload;
static void feNavReload(void) {
	g_feNavReload = true;
}

static void vinylLayerRefreshIcons(MenuState* m);
static void paintStartBrowsing(MenuState* m);

// ChoosePaintScreen (UI_Paint.fng, GC 0x80177548 and on), the PAINT row of
// the graphics shop. Its categories are BuildPaintCategoryList's (0x80178400,
// the 84F4 == 0 arm: the plain paint shop) -- nine CAR_SLOT_IDs, each an
// IconOption locked by IsPaintMenuLocked (0x8017986C). A category's swatches
// are BuildPaintList's (0x80178C48): GetPartsList's parts of the slot whose
// brand attribute (0xEBB03E66) is the screen's brand, through IsPaintAvailable
// (0x80179654), at most sixty, coloured RED/GREEN/BLUE with DISPRED/DISPGREEN/
// DISPBLUE over them. The port reads each slot's paints off GLOBALB.BUN once
// at Setup and lets the database go; the brand filter runs on that.
#define PAINT_SCREEN          "UI_Paint.fng"
#define PAINT_HIGHLIGHT_HASH  0x9BA6D658u // U2_Paint_HighLight
#define PAINT_TEXT_HASH       0xEF653AFFu // Paint_text, the brand's name
#define PAINT_CASH_HASH       0x0013C45Eu // CASH
#define PAINT_PANEL_HASH      0xDB285767u // the swatch group (FadeIn / FadeOut)
#define PAINT_ICONHI_HASH     0xDF422345u // U2_Icon_Highlight, hidden while browsing
#define PAINT_LOCKICON_HASH   0x23A43844u // SHOW with an empty list
#define PAINT_BRANDSEL_HASH   0x031A9C0Au // hidden in the vinyl-colour mode only
#define PAINT_TYPES_A_HASH    0x9DE5BA07u // the paint-type legends: slots 0x3F,
#define PAINT_TYPES_B_HASH    0x7A1FF30Du // 0x45, 0x4B and 0x4C only
#define PAINT_MSG_BUY_YES     0xD05FC3A3u
#define PAINT_MSG_NO          0x34DC1BCFu
#define PAINT_MSG_OK          0x34DC1BECu
#define PAINT_TEXT_BUY        0xC4C5D271u
#define PAINT_TEXT_NO_CASH    0xD1AC60BEu
#define PAINT_BRAND_GLOSS     0x02DAAB07u
#define PAINT_BRAND_METALLIC  0x03437A52u
#define PAINT_BRAND_PEARL     0x03797533u
#define PAINT_COLS            20          // [0x63]
#define PAINT_MAX_SWATCHES    60
#define PAINT_MAX_CATS        9
#define PAINT_MAX_PARTS       288         // the body slots hold 270
#define PAINT_ATTR_BRAND      0xEBB03E66u

typedef struct {
	u32 hash, brand;
	u8 r, g, b, level;
	u8 entity;
	bool avail;      // IsPaintAvailable
	s16 index;       // its place in the slot's list
	int price;       // GetCarPartCost
} PaintPart;

typedef struct {
	int slot;
	u32 icon, label;
	const char* fallback;
	bool locked;     // IsPaintMenuLocked
	bool canPaint;   // CanPaintThisPart
	u32 okText;      // the ShowOk A raises when it cannot
	int nparts;
	PaintPart part[PAINT_MAX_PARTS];
} PaintCat;

// ShowOk texts A raises on a part that cannot take paint, and the two
// dialogs of the buy.
enum { PAINT_DLG_CANT, PAINT_DLG_SPINNER, PAINT_DLG_ENGINE, PAINT_DLG_CARBON_SPOILER,
	PAINT_DLG_CARBON_ROOF, PAINT_DLG_CARBON_MIRROR, PAINT_DLG_BUY, PAINT_DLG_NO_CASH,
	PAINT_DLG_COUNT };
static const u32 PAINT_DLG_ID[PAINT_DLG_COUNT] = { 0x73BC702Eu, 0x6BCBCEEAu, 0xD286BE3Au,
	0xE7337E9Du, 0xAD460262u, 0xF152BEFAu, PAINT_TEXT_BUY, PAINT_TEXT_NO_CASH };

static struct {
	bool built;
	bool browsing;       // [0x67]
	bool startBrowse;    // [0x6B]
	int carSlot;
	u32 car;
	int ncat;
	PaintCat cat[PAINT_MAX_CATS];
	u32 brand;           // [0x62]
	int list[PAINT_MAX_SWATCHES];   // BuildPaintList's, indices into the category's parts
	int count;           // [100]
	int sel;             // [0x5F], an index into list
	char dlgText[PAINT_DLG_COUNT][256];
	bool lockShown;      // the lock up after an empty build
	int nnames;
	u32 nameBrand[16];
	char name[16][48];   // bStringHash("_PAINT", brand)'s text
	u32 swatchHash[PAINT_MAX_SWATCHES];   // FEHashUpper("PAINT_SWATCH_%d")
	bool haveSwatchHash;
} g_paint;

// GetPaintBrandHashFromCarSlotId (0x8017A0EC).
static u32 paintBrandForSlot(int slot) {
	switch (slot) {
	case 0x3F: case 0x45: case 0x4B: case 0x4C: return PAINT_BRAND_GLOSS;
	case 0x44: return 0x0016BDCEu;
	case 0x46: return 0xD6640DFFu;
	case 0x47: return 0x066350F0u;
	case 0x49: case 0x4A: return 0x0000DA27u;
	default: return slot >= 0x4D && slot <= 0x5C ? 0x03E871F1u : 0u;
	}
}

// IsPaintAvailable (0x80179654): the brand picks the unlockable -- 0x25 the
// default, gloss's -- and UnlockSystem::IsUnlockableUnlocked (0x8012FFF4)
// asks it under the session's filter: ONLINE (4) for a career walk-in,
// CAREER (2) from the crib, whose CareerUnlocker arm (0x8012F848) answers
// only the ONLINE bit and so turns every paint down there. The vinyl
// colours' brand (0x3E871F1) is always open. Main-menu Customize's filter
// is QUICKRACE (1), and QuickRaceUnlocker::IsUnlockableUnlocked (0x8012F2F0;
// OnlineUnlocker's 0x8012F45C calls the same) is CareerUnlocker asked with
// filter 4 -- CalculateIfUnlocked, the ONLINE ask below (#517).
static bool paintAvailable(const PerfDb* pdb, const PerfUnlockCtx* ctx, u32 brand, int level) {
	int entity = 0x25;
	switch (brand) {
	case PAINT_BRAND_METALLIC: entity = 0x26; break;
	case 0x0016BDCEu: entity = 0x28; break;
	case 0x0000DA27u: entity = 0x4D; break;
	case PAINT_BRAND_PEARL: entity = 0x27; break;
	case 0x066350F0u: entity = 0x4E; break;
	case 0xD6640DFFu: entity = 0x4F; break;
	case 0x03E871F1u: return true;
	default: break;
	}
	if (careerInProgress() && g_customizeEntry == CUSTOMIZE_ENTRY_CRIB)
		return false;
	PerfUnlockCtx c = *ctx;
	c.filter = PERF_FILTER_ONLINE;
	return pdb && perfdb_entity_unlocked(pdb, &c, entity, level);
}

static const PaintCat* paintCurrent(const MenuState* m) {
	if (!m || !m->isPaint || !g_paint.built || m->selected < 0 || m->selected >= g_paint.ncat)
		return NULL;
	return &g_paint.cat[m->selected];
}

static void paintAddCategory(int slot, u32 icon, u32 label, const char* fallback) {
	if (g_paint.ncat >= PAINT_MAX_CATS)
		return;
	PaintCat* c = &g_paint.cat[g_paint.ncat++];
	memset(c, 0, sizeof(*c));
	c->slot = slot;
	c->icon = icon;
	c->label = label;
	c->fallback = fallback;
}

// The installed part CanPaintThisPart (0x80178AA0) looks at: there, over
// level 0 and -- for the spoiler, the roof scoop and the mirrors -- with
// neither carbon attribute (0x721AFF7C, 0x6509EC92); for the spinner paint
// the rim must carry 0x931FF82E. A carbon one's ShowOk is the category's own.
static bool paintPartTakesPaint(const CarPartDb* db, const unsigned int* parts, u32 car,
		int partSlot, bool spinner, bool* carbon) {
	*carbon = false;
	const u32 h = uniquesGetPart(parts, partSlot);
	const CarPart p = h ? carpartdb_get(db, car, partSlot, h, NULL, CARPARTDB_ANY_LEVEL) : NULL;
	if (!p)
		return false;
	if (partSlot == 0x0C || partSlot == 0x07 || partSlot == 0x20)
		*carbon = carpartdb_attr(db, p, 0x721AFF7Cu, 0) != 0 || carpartdb_attr(db, p, 0x6509EC92u, 0) != 0;
	if (carpartdb_level(p) == 0 || *carbon)
		return false;
	if (spinner)
		return carpartdb_attr(db, p, 0x931FF82Eu, 0xFFFFFFFFu) != 0xFFFFFFFFu;
	return true;
}

// Setup (0x80178334) on the plain paint shop: the categories as dynItems,
// each slot's paints read now, the first category on (SetInitialPos(1), which
// is 1-based) with its slot's brand.
static void paintItems(const Config* cfg, MenuState* out, const LangTable* lang) {
	char b[256];
	char bunPath[600];
	out->isPaint = true;
	g_paint.built = false;
	g_paint.ncat = 0;
	g_paint.browsing = false;
	g_paint.startBrowse = false;
	g_paint.count = 0;
	g_paint.sel = 0;
	for (int k = 0; k < PAINT_DLG_COUNT; k++) {
		const char* raw = lang ? langbin_lookup(lang, PAINT_DLG_ID[k]) : NULL;
		snprintf(g_paint.dlgText[k], sizeof(g_paint.dlgText[k]), "%s", raw ? raw : "");
	}
	if (!g_paint.haveSwatchHash) {
		for (int k = 0; k < PAINT_MAX_SWATCHES; k++) {
			char nm[32];
			snprintf(nm, sizeof(nm), "PAINT_SWATCH_%d", k + 1);
			g_paint.swatchHash[k] = race_string_hash(nm);
		}
		g_paint.haveSwatchHash = true;
	}
	const bool vinylMode = g_paintMode == 1;
	if (!vinylMode) {
		paintAddCategory(0x3F, 0xA3B76154u, 0xEF5B4A75u, "Body Paint");
		paintAddCategory(0x45, 0xA8D7E6EDu, 0xDDA5B898u, "Spoiler Paint");
		paintAddCategory(0x4B, 0xD2241205u, 0xEF644B90u, "Roof Scoop Paint");
		paintAddCategory(0x4C, 0xDF5C2BCAu, 0x4D90F415u, "Mirror Paint");
		paintAddCategory(0x49, 0xD223F84Au, 0x0F030942u, "Rim Paint");
		paintAddCategory(0x4A, 0xD223F84Au, 0xDD3BEBF9u, "Spinner Paint");
		paintAddCategory(0x46, 0x7EB55A26u, 0xDACD9FFFu, "Brake Paint");
		paintAddCategory(0x44, 0x4E875A92u, 0x3B3BFAF0u, "Engine Paint");
		paintAddCategory(0x47, 0xA6343AECu, 0xBA1CC49Cu, "Exhaust Paint");
	}
	g_vinylColCount = 0;

	const int cs = gProfile.currentCarSlot;
	const u32 car = cs >= 0 && cs < PROFILE_CAREER_ARRAYS ? gProfile.careerParts[cs][0] : 0;
	g_paint.carSlot = cs;
	g_paint.car = car;
	static CarPartDb db;
	const bool haveDb = car && cfg &&
		buildGamePath(cfg, "GLOBAL/GLOBALB.BUN", bunPath, sizeof(bunPath)) &&
		carpartdb_load(bunPath, &db);
	// BuildPaintCategoryList's 84F4 == 1 arm (#479): one IconOption per
	// NUMREMAPCOLOURS of the vinyl, PAINT_ICON_<n> over label 0xC034CE3D,
	// unlocked, on GetCarSlotIDForVinylPaintLayer's slot -- layer L's colour n
	// is 0x4D + 4 (L - 0x40) + n - 1.
	g_vinylColRemap = 0;
	if (vinylMode && haveDb && g_vinylColPart.hash) {
		const CarPart vp = carpartdb_get(&db, car, 0x40, g_vinylColPart.hash, NULL, CARPARTDB_ANY_LEVEL);
		g_vinylColRemap = vp ? (int)carpartdb_attr(&db, vp, carpartdb_string_hash("NUMREMAPCOLOURS"), 0) : 0;
		const int layer = g_vinylSlot >= 0x40 && g_vinylSlot <= 0x43 ? g_vinylSlot : 0x40;
		static const char* const kCol[4] = { "Vinyl Colour 1", "Vinyl Colour 2", "Vinyl Colour 3",
			"Vinyl Colour 4" };
		for (int n = 1; n <= g_vinylColRemap && n <= 4; n++) {
			char nm[32];
			snprintf(nm, sizeof(nm), "PAINT_ICON_%d", n);
			paintAddCategory(0x4D + (layer - 0x40) * 4 + n - 1, race_string_hash(nm), 0xC034CE3Du,
				kCol[n - 1]);
		}
	}
	const PerfDb* pdb = cfg ? perfDb(cfg) : NULL;
	PerfUnlockCtx ctx;
	perfBuildCtx(&ctx);
	const u32 kRed = carpartdb_string_hash("RED"), kGreen = carpartdb_string_hash("GREEN"),
		kBlue = carpartdb_string_hash("BLUE"), kDRed = carpartdb_string_hash("DISPRED"),
		kDGreen = carpartdb_string_hash("DISPGREEN"), kDBlue = carpartdb_string_hash("DISPBLUE");
	const u32 none = 0xFFFFFFFFu;
	for (int i = 0; i < g_paint.ncat; i++) {
		PaintCat* c = &g_paint.cat[i];
		c->locked = true;
		if (!haveDb)
			continue;
		int idx = 0, over = 0;
		for (CarPart p = carpartdb_get(&db, car, c->slot, 0, NULL, CARPARTDB_ANY_LEVEL); p;
				p = carpartdb_get(&db, car, c->slot, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
			if (c->nparts >= PAINT_MAX_PARTS) {
				over++;
				continue;
			}
			PaintPart* pp = &c->part[c->nparts++];
			pp->hash = carpartdb_hash(p);
			pp->brand = carpartdb_attr(&db, p, PAINT_ATTR_BRAND, 0);
			pp->level = (u8)carpartdb_level(p);
			pp->entity = (u8)stargazer_unlockable(&db, c->slot, p);
			pp->index = (s16)idx;
			pp->price = bodyShopPartCost(pdb, pp->entity, pp->level);
			pp->avail = paintAvailable(pdb, &ctx, pp->brand, pp->level);
			u32 r = carpartdb_attr(&db, p, kRed, 0), g = carpartdb_attr(&db, p, kGreen, 0),
				bl = carpartdb_attr(&db, p, kBlue, 0), v;
			if ((v = carpartdb_attr(&db, p, kDRed, none)) != none) r = v;
			if ((v = carpartdb_attr(&db, p, kDGreen, none)) != none) g = v;
			if ((v = carpartdb_attr(&db, p, kDBlue, none)) != none) bl = v;
			pp->r = (u8)r;
			pp->g = (u8)g;
			pp->b = (u8)bl;
		}
		// IsPaintMenuLocked: GetNext before the first test, so the slot's
		// head part is never the one that opens it.
		const u32 want = paintBrandForSlot(c->slot);
		for (int k = 1; k < c->nparts && c->locked; k++)
			if (c->part[k].avail && c->part[k].brand == want)
				c->locked = false;
		if (over) {
			snprintf(b, sizeof(b), "paint: slot 0x%X has %d paint(s) past the port's %d", c->slot,
				over, PAINT_MAX_PARTS);
			dlog(b);
		}
	}
	// CanPaintThisPart and the ShowOk text A raises instead, off the car as
	// it stands.
	if (haveDb && cs >= 0 && cs < PROFILE_CAREER_ARRAYS) {
		const unsigned int* parts = gProfile.careerParts[cs];
		for (int i = 0; i < g_paint.ncat; i++) {
			PaintCat* c = &g_paint.cat[i];
			bool carbon = false;
			c->okText = PAINT_DLG_CANT;
			switch (c->slot) {
			case 0x3F:
				c->canPaint = true;
				break;
			case 0x44: {
				// IsEnginePaintable (0x8016FBAC): the engine part over level 2.
				const u32 h = uniquesGetPart(parts, 0x0D);
				const CarPart p = h ? carpartdb_get(&db, car, 0x0D, h, NULL, CARPARTDB_ANY_LEVEL) : NULL;
				c->canPaint = p && carpartdb_level(p) > 2;
				c->okText = PAINT_DLG_ENGINE;
				break;
			}
			case 0x46:
				// AreBrakesPaintable (0x8016FB14): performance part 0x28, 0x29
				// or 0x2B installed.
				c->canPaint = perfdb_part_installed(&ctx, 0x28) || perfdb_part_installed(&ctx, 0x29) ||
					perfdb_part_installed(&ctx, 0x2B);
				break;
			case 0x45:
				c->canPaint = paintPartTakesPaint(&db, parts, car, 0x0C, false, &carbon);
				if (carbon)
					c->okText = PAINT_DLG_CARBON_SPOILER;
				break;
			case 0x47:
				c->canPaint = paintPartTakesPaint(&db, parts, car, 0x10, false, &carbon);
				break;
			case 0x49:
				c->canPaint = paintPartTakesPaint(&db, parts, car, 0x1D, false, &carbon);
				break;
			case 0x4A:
				c->canPaint = paintPartTakesPaint(&db, parts, car, 0x1D, true, &carbon);
				c->okText = PAINT_DLG_SPINNER;
				break;
			case 0x4B:
				c->canPaint = paintPartTakesPaint(&db, parts, car, 0x07, false, &carbon);
				if (carbon)
					c->okText = PAINT_DLG_CARBON_ROOF;
				break;
			case 0x4C:
				c->canPaint = paintPartTakesPaint(&db, parts, car, 0x20, false, &carbon);
				if (carbon)
					c->okText = PAINT_DLG_CARBON_MIRROR;
				break;
			default:
				break;
			}
		}
	}
	// The vinyl-colour mode: IconOption +0x24 0 (never locked) and
	// CanPaintThisPart's first test (84F4 == 1 says yes).
	for (int i = 0; vinylMode && i < g_paint.ncat; i++) {
		g_paint.cat[i].locked = false;
		g_paint.cat[i].canPaint = true;
	}
	if (haveDb) {
		carpartdb_free(&db);
		g_paint.built = true;
	}
	// RefreshHeader's brand names, each looked up once.
	g_paint.nnames = 0;
	g_paint.lockShown = false;
	for (int i = 0; i < g_paint.ncat; i++)
		for (int k = 0; k < g_paint.cat[i].nparts && g_paint.nnames < 16; k++) {
			const u32 br = g_paint.cat[i].part[k].brand;
			int f = 0;
			for (int j = 0; j < g_paint.nnames && !f; j++)
				f = g_paint.nameBrand[j] == br;
			if (f)
				continue;
			const char* raw = lang ? langbin_lookup(lang, carpartdb_string_hash_from("_PAINT", br)) : NULL;
			g_paint.nameBrand[g_paint.nnames] = br;
			g_paint.name[g_paint.nnames][0] = '\0';
			if (raw)
				langTextToUtf8(raw, g_paint.name[g_paint.nnames], sizeof(g_paint.name[0]));
			g_paint.nnames++;
		}
	int n = 0;
	for (int i = 0; i < g_paint.ncat && n < MENU_MAX_ITEMS; i++) {
		const PaintCat* c = &g_paint.cat[i];
		MenuItem* it = &out->dynItems[n];
		memset(it, 0, sizeof(*it));
		it->iconHash = c->icon;
		it->labelHash = c->label;
		it->fallbackLabel = c->fallback;
		it->modeValue = -1;
		out->itemLocked[n] = c->locked;
		n++;
	}
	out->itemCount = n;
	out->useDynItems = true;
	out->selected = 0;
	g_paint.brand = g_paint.ncat > 0 ? paintBrandForSlot(g_paint.cat[0].slot) : PAINT_BRAND_GLOSS;
	int o = snprintf(b, sizeof(b), "paint: Setup -- car slot %d (0x%08X), filter %u, setup %d "
		"($%d)%s:", cs, (unsigned)car, (unsigned)ctx.filter, g_paintSetupCount, g_paintSetupPrice,
		vinylMode ? " -- vinyl colours" : "");
	for (int i = 0; i < g_paint.ncat && o < (int)sizeof(b); i++) {
		const PaintCat* c = &g_paint.cat[i];
		int av = 0;
		for (int k = 0; k < c->nparts; k++)
			av += c->part[k].avail;
		o += snprintf(b + o, sizeof(b) - o, " %X=%d/%d%s%s", c->slot, av, c->nparts,
			c->locked ? "L" : "", c->canPaint ? "" : "x");
	}
	dlog(b);
	if (vinylMode) {
		snprintf(b, sizeof(b), "paint: vinyl-colour mode -- layer 0x%X, vinyl 0x%08X, NUMREMAPCOLOURS %d, "
			"%s", (unsigned)g_vinylSlot, (unsigned)g_vinylColPart.hash, g_vinylColRemap,
			g_vinylColFromY ? "from the layers' Y" : "from the vinyl browser");
		dlog(b);
		// Setup: with fewer than two colours BuildPaintList and
		// StartBrowsingPaints at once -- the one list is the screen.
		if (g_vinylColRemap < 2 && g_paint.ncat > 0 && g_paint.built)
			paintStartBrowsing(out);
	}
}

// BuildPaintList (0x80178C48): with [0x6B] (StartBrowsingPaints) the brand
// follows the setup's or the car's part in the slot first; then the slot's
// available paints of the brand, the selection on that part when it is among
// them, else on the first.
static void paintBuildList(const MenuState* m) {
	const PaintCat* c = paintCurrent(m);
	g_paint.count = 0;
	g_paint.sel = 0;
	if (!c)
		return;
	const int cs = g_paint.carSlot;
	u32 cur = paintSetupPart(c->slot);
	if (!cur && cs >= 0 && cs < PROFILE_CAREER_ARRAYS)
		cur = uniquesGetPart(gProfile.careerParts[cs], c->slot);
	if (cur && g_paint.startBrowse) {
		for (int k = 0; k < c->nparts; k++)
			if (c->part[k].hash == cur)
				g_paint.brand = c->part[k].brand;
	}
	g_paint.startBrowse = false;
	for (int k = 0; k < c->nparts && g_paint.count < PAINT_MAX_SWATCHES; k++) {
		const PaintPart* p = &c->part[k];
		if (p->brand != g_paint.brand || !p->avail)
			continue;
		if (cur && p->hash == cur)
			g_paint.sel = g_paint.count;
		g_paint.list[g_paint.count++] = k;
	}
}

static const PaintPart* paintSelected(const MenuState* m) {
	const PaintCat* c = paintCurrent(m);
	if (!c || g_paint.sel < 0 || g_paint.sel >= g_paint.count)
		return NULL;
	return &c->part[g_paint.list[g_paint.sel]];
}

// The car the paint screens show: ResyncPreview's own parts with the setup
// over them (ResetPreviewToPaintSetup, 0x8017066C) and, while a list is up,
// the selected swatch (PreviewPaintPart, 0x8016E460). Each frame from
// syncCarModel() on UI_Paint and the category screen, with the body shop's
// settle.
static void paintPreviewSync(const MenuState* m) {
	const int cs = gProfile.currentCarSlot;
	const PaintCat* c = m && m->isPaint ? paintCurrent(m) : NULL;
	if (m && m->isVinylLayer)
		vinylLayerRefreshIcons((MenuState*)m);
	const PaintPart* sp = c && g_paint.browsing ? paintSelected(m) : NULL;
	const bool vinylMode = m && m->isPaint && g_paintMode == 1 && g_vinylColPart.hash;
	const bool want = cs >= 0 && cs < PROFILE_CAREER_ARRAYS && (g_paintSetupCount > 0 || sp || vinylMode);
	static int s_seen = -1;
	static u64 s_at = 0;
	if (!want) {
		s_seen = -1;
		if (g_carPreview.on) {
			g_carPreview.on = false;
			g_profileCarChanged = true;
		}
		return;
	}
	// The preview's signature: the setup and the swatch.
	u32 sig = 2166136261u;
	for (int k = 0; k < g_paintSetupCount; k++)
		sig = (sig ^ g_paintSetup[k].hash ^ (u32)g_paintSetup[k].slot) * 16777619u;
	if (sp)
		sig = (sig ^ sp->hash ^ (u32)c->slot) * 16777619u;
	if (vinylMode) {
		sig = (sig ^ g_vinylColPart.hash ^ (u32)g_vinylSlot ^ 0x479u) * 16777619u;
		for (int k = 0; k < g_vinylColCount; k++)
			sig = (sig ^ g_vinylCol[k].hash ^ (u32)g_vinylCol[k].slot) * 16777619u;
	}
	const int row = (int)(sig & 0x7FFFFFFF);
	if (g_carPreview.on && g_carPreview.row == row)
		return;
	if (row != s_seen) {
		s_seen = row;
		s_at = osGetTime();
		if (g_carPreview.on)
			return;
	} else if (osGetTime() - s_at < UNIQUES_PREVIEW_SETTLE_MS) {
		return;
	}
	paintSetupPreviewParts(g_carPreview.parts, cs);
	// StopBrowsingPaints' 84F4 == 1 arm: the four layers cleared under a kit,
	// PreviewPaintPart(layer, vinyl), then every colour in the list (#479).
	if (vinylMode) {
		vinylPreviewParts(g_carPreview.parts, g_vinylSlot, g_vinylColPart.hash);
		for (int k = 0; k < g_vinylColCount; k++)
			uniquesSetPart(g_carPreview.parts, g_vinylCol[k].slot, g_vinylCol[k].hash);
	}
	if (sp)
		uniquesSetPart(g_carPreview.parts, c->slot, sp->hash);
	g_carPreview.on = true;
	g_carPreview.slot = cs;
	g_carPreview.row = row;
	g_profileCarChanged = true;
	char b[160];
	snprintf(b, sizeof(b), "paint: preview -- setup %d entr%s%s, swatch 0x%08X in slot 0x%X",
		g_paintSetupCount, g_paintSetupCount == 1 ? "y" : "ies", "", sp ? (unsigned)sp->hash : 0u,
		c ? (unsigned)c->slot : 0u);
	dlog(b);
}

// CareerUnlocker::IsDecalBrandUnlocked (0x8012F94C): a brand no performance
// package sells is open; one that some package sells is open once a career
// car that has been chosen (FECarRecord +0x7F8, ProfileCarRecord::chosen)
// owns it (OwnsBrand).
static bool paintDecalBrandUnlocked(const PerfDb* pdb, u32 brand) {
	bool inPackage = false;
	for (int i = 0; pdb && i < pdb->numPackages && !inPackage; i++) {
		const PerformancePackage* pk = &pdb->packages[i];
		for (u32 k = 0; k < pk->numParts && k < PERFDB_MAX_PARTS && !inPackage; k++)
			for (u32 j = 0; j < pk->part[k].numBrands && j < PERFDB_MAX_PART_BRANDS; j++)
				if (pk->part[k].brand[j] == brand) {
					inPackage = true;
					break;
				}
	}
	if (!inPackage)
		return true;
	for (int s = 0; s < PROFILE_NUM_CAREER_SLOTS; s++) {
		if (!gProfile.careerCar[s].chosen)
			continue;
		for (int k = 0; k < PROFILE_NUM_PERF_PARTS && gProfile.careerOwnedBrands[s][k]; k++)
			if (gProfile.careerOwnedBrands[s][k] == brand)
				return true;
	}
	return false;
}

// CareerUnlocker::AreAnyDecalsUnlocked (0x8012F9E8): the first career car's
// (GetCarFiltered(4, 0)) decal parts in slot 0x61, each by its brand
// attribute 0xEBB03E66, until one is open.
static bool paintDecalsUnlocked(const Config* cfg, int* nDecals) {
	*nDecals = 0;
	int slot = -1;
	for (int s = 0; s < PROFILE_NUM_CAREER_SLOTS && slot < 0; s++)
		if (gProfile.careerCar[s].inUse && gProfile.careerCar[s].hasRide && gProfile.careerParts[s][0])
			slot = s;
	if (slot < 0 || !cfg)
		return false;
	char bunPath[600];
	static CarPartDb db;
	if (!buildGamePath(cfg, "GLOBAL/GLOBALB.BUN", bunPath, sizeof(bunPath)) ||
			!carpartdb_load(bunPath, &db))
		return false;
	const PerfDb* pdb = perfDb(cfg);
	const u32 car = gProfile.careerParts[slot][0];
	bool open = false;
	for (CarPart p = carpartdb_get(&db, car, 0x61, 0, NULL, CARPARTDB_ANY_LEVEL); p && !open;
			p = carpartdb_get(&db, car, 0x61, 0, p, CARPARTDB_ANY_LEVEL)) {
		(*nDecals)++;
		open = paintDecalBrandUnlocked(pdb, carpartdb_attr(&db, p, 0xEBB03E66u, 0));
	}
	carpartdb_free(&db);
	return open;
}

// ChoosePaintShopCategory's ctor and Setup on what the table leaves: the
// decal row's lock and the two dialog texts the screen raises.
static void paintCategoryItems(const Config* cfg, MenuState* out, const LangTable* lang) {
	out->isPaintCat = true;
	g_paintMode = 0;   // the PAINT row's UI_Paint is the plain shop (#479)
	g_vinylColFromY = false;
	static const u32 ids[2] = { PAINTCAT_TEXT_EXIT, PAINTCAT_TEXT_NOTHING };
	for (int k = 0; k < 2; k++) {
		const char* raw = lang ? langbin_lookup(lang, ids[k]) : NULL;
		snprintf(g_paintCatText[k], sizeof(g_paintCatText[k]), "%s", raw ? raw : "");
	}
	// The ctor's CleanUpVinylsInPaintList / CleanUpDecalsInPaintList touch
	// only vinyl and decal entries, of which the port's setup has none yet;
	// the paint entries stay for the trip back from UI_Paint. The setup is
	// emptied on the way into the shop (careerEnterShop()) and out of it.
	paintSetupReprice();
	int nDecals = 0;
	const bool decals = !careerInProgress() || paintDecalsUnlocked(cfg, &nDecals);
	for (int i = 0; i < out->itemCount && i < MENU_MAX_ITEMS; i++) {
		const MenuItem* it = menuItemAt(out, i);
		if (it && it->modeValue == 1)
			out->itemLocked[i] = !decals;
	}
	char b[160];
	snprintf(b, sizeof(b), "paint categories: %d row(s), decals %s (%d decal part(s) looked at)",
		out->itemCount, decals ? "open" : "locked", nDecals);
	dlog(b);
}

// ChooseVinylLayerScreen's dialog texts: the kit question (0x80C151D5) and
// the layer's Change / Remove (0x6D7902C), read as the screen comes up for
// the package CalcFEngDialogPackageName picks.
static char g_vinylLayerText[2][256];

static bool vinylOpenDb(const Config* cfg, CarPartDb* db) {
	char bunPath[600];
	return cfg && buildGamePath(cfg, "GLOBAL/GLOBALB.BUN", bunPath, sizeof(bunPath)) &&
		carpartdb_load(bunPath, db);
}

// IsUniqueOnPreview (0x8016FD80) of the preview the layer screen shows: the
// setup over the car.
static bool vinylUniqueOnPreview(void) {
	for (int l = 0x40; l < 0x44; l++) {
		const PaintSetupEntry* e = NULL;
		const u32 h = vinylEffective(l, &e);
		if (h && ((e && e->unique) || vinylIsUnique(h)))
			return true;
	}
	return false;
}

// Setup's AddLayerOption icons (0x80176AD0): the group's icon of the layer's
// vinyl -- the setup's, else the car's -- the kit icon on every layer while a
// kit is in the setup or on the car and its preview, else the layer's own.
static u32 vinylLayerIcon(int k) {
	const int layer = 0x40 + k;
	if (vinylUniqueInSetup() || (vinylUniqueInstalled() && vinylUniqueOnPreview()))
		return VINYL_UNIQUE_ICON;
	const PaintSetupEntry* e = NULL;
	const u32 h = vinylEffective(layer, &e);
	if (h && e && e->kit < 28)
		return VINYL_GROUP_ICON[e->kit];
	return VINYL_LAYER_ICON0 + (u32)k;
}

// PORT: the header's "[L] < Reorder Layers > [R]". MENU_MIN_TEXT_PX lifts the
// title above its authored size, so it ran out over the right arrow; it is
// fitted to the room between the arrows (menuTextFitBox()). The PC shows the
// shoulder keys' names beside the arrows; here the L / R pad badges stand for
// both, so the arrows are taken down (paintCatHides()) and each badge sits
// centred where its arrow was -- the user, 2026-11-06: "I don't like both
// arrows and button icons being there, its one or the other". A tap on a
// badge is that shoulder (vinylLayerTouch()).
static struct {
	int arrow[2], slot[2];
} g_vlHdr = { { -1, -1 }, { -1, -1 } };

static void vinylLayerFitHeader(MenuState* m) {
	g_vlHdr.arrow[0] = g_vlHdr.arrow[1] = g_vlHdr.slot[0] = g_vlHdr.slot[1] = -1;
	int arrow[2] = { -1, -1 }, title = -1, slot[2] = { -1, -1 };
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		const u32 rh = w->resourceHash, oh = w->hasObjHash ? w->objHash : 0;
		if (w->type == FNG_TYPE_IMAGE && (rh == 0xCF6F0439u || oh == 0xCF6F0439u))
			arrow[0] = i;
		else if (w->type == FNG_TYPE_IMAGE && (rh == 0xABA93D3Fu || oh == 0xABA93D3Fu))
			arrow[1] = i;
		else if (w->type == FNG_TYPE_STRING && w->hasStringHash && w->stringHash == 0xB9AC83EBu)
			title = i;
	}
	for (int k = 0; k < m->padGlyphCount; k++) {
		if (m->padGlyphKey[k] == 'L')
			slot[0] = m->padGlyphIdx[k];
		else if (m->padGlyphKey[k] == 'R')
			slot[1] = m->padGlyphIdx[k];
	}
	char b[160];
	if (arrow[0] < 0 || arrow[1] < 0) {
		dlog("vinyl layers: header arrows not found, header left as authored");
		return;
	}
	const FngWidget* a0 = &m->screen.widgets[arrow[0]];
	const FngWidget* a1 = &m->screen.widgets[arrow[1]];
	const float in0 = m->worldPosX[arrow[0]] + (a0->hasSize ? a0->sizeW * 0.5f : 0.0f);
	const float in1 = m->worldPosX[arrow[1]] - (a1->hasSize ? a1->sizeW * 0.5f : 0.0f);
	if (title >= 0 && in1 > in0)
		m->textBoxW[title] = in1 - in0;
	// Each badge centred (justify h bit 0x1, its own vertical bits kept) on
	// its arrow, which only goes once the badge has taken its place.
	for (int k = 0; k < 2; k++) {
		if (slot[k] < 0)
			continue;
		FngWidget* r = &m->screen.widgets[slot[k]];
		const u32 j = r->hasJustify ? r->justify : 0x5u;
		r->justify = (j & 0xCu) | 0x1u;
		r->hasJustify = true;
		m->worldPosX[slot[k]] = m->worldPosX[arrow[k]];
		g_vlHdr.arrow[k] = arrow[k];
		g_vlHdr.slot[k] = slot[k];
	}
	snprintf(b, sizeof(b), "vinyl layers: header -- title box %.1f between the arrows; L / R badges on the "
		"arrows (x %.1f / %.1f), arrows down", title >= 0 ? m->textBoxW[title] : 0.0f,
		slot[0] >= 0 ? m->worldPosX[slot[0]] : 0.0f, slot[1] >= 0 ? m->worldPosX[slot[1]] : 0.0f);
	dlog(b);
}

static void vinylLayerRefreshIcons(MenuState* m) {
	for (int k = 0; k < 4 && k < m->itemCount; k++) {
		m->dynItems[k].iconHash = vinylLayerIcon(k);
		// The drawn icon is the one resolved at load (itemIcons); a group's
		// icon is in the screen's cache once any layer showed it.
		const C2D_Image img = texcache_find(&m->texCache, m->dynItems[k].iconHash);
		if (img.tex)
			m->itemIcons[k] = img;
	}
}

// The ctor and Setup (0x80176AD0): the four layers, the selection on the
// layer last changed, the Total Cost in a career (drawPaintCategory()).
static void vinylLayerItems(const Config* cfg, MenuState* out, const LangTable* lang) {
	out->isVinylLayer = true;
	feCamStop("ChooseVinylLayerScreen");   // its constructor's StopLookingAtParts
	static const u32 ids[2] = { 0x80C151D5u, 0x06D7902Cu };
	for (int k = 0; k < 2; k++) {
		const char* raw = lang ? langbin_lookup(lang, ids[k]) : NULL;
		snprintf(g_vinylLayerText[k], sizeof(g_vinylLayerText[k]), "%s", raw ? raw : "");
	}
	const int cs = gProfile.currentCarSlot;
	const u32 car = cs >= 0 && cs < PROFILE_CAREER_ARRAYS ? gProfile.careerParts[cs][0] : 0;
	static CarPartDb db;
	const bool haveDb = car && vinylOpenDb(cfg, &db);
	vinylReadInstalled(haveDb ? &db : NULL, cfg ? perfDb(cfg) : NULL, cs, car);
	if (haveDb)
		carpartdb_free(&db);
	static const char* const kName[4] = { "Vinyl Layer 1", "Vinyl Layer 2", "Vinyl Layer 3",
		"Vinyl Layer 4" };
	for (int k = 0; k < 4; k++) {
		MenuItem* it = &out->dynItems[k];
		memset(it, 0, sizeof(*it));
		it->iconHash = vinylLayerIcon(k);
		it->labelHash = VINYL_LAYER_ICON0 + (u32)k;
		it->fallbackLabel = kName[k];
		it->modeValue = 0x40 + k;
		out->itemLocked[k] = false;
	}
	out->itemCount = 4;
	out->useDynItems = true;
	if (g_vinylSlot < 0x40 || g_vinylSlot > 0x43)
		g_vinylSlot = 0x40;
	out->selected = g_vinylSlot - 0x40;
	paintSetupReprice();
	char b[224];
	int o = snprintf(b, sizeof(b), "vinyl layers: Setup -- car slot %d, layer 0x%X selected, setup %d "
		"entr%s:", cs, (unsigned)g_vinylSlot, g_paintSetupCount, g_paintSetupCount == 1 ? "y" : "ies");
	for (int k = 0; k < 4 && o < (int)sizeof(b); k++)
		o += snprintf(b + o, sizeof(b) - o, " %X=0x%08X(g%d%s)", 0x40 + k,
			(unsigned)g_vinylInst[k].hash, g_vinylInst[k].kit, g_vinylInst[k].unique ? ",kit" : "");
	dlog(b);
}

// SetupVinyls (0x8016497C): the 28 groups as categories, each a list of the
// slot-0x40 parts of the group that IsPartAvailable passes, locked when it
// is empty. Group 0x14 is the hood vinyls.
static void vinylBrowserBuild(const CarPartDb* db, const PerfDb* pdb, const PerfUnlockCtx* ctx,
		const LangTable* lang, int cs, u32 car) {
	for (int g = 0; g < 28; g++) {
		if (g_bodyShop.ncat >= BODYSHOP_MAX_CATS)
			break;
		BodyShopCat* c = &g_bodyShop.cat[g_bodyShop.ncat++];
		memset(c, 0, sizeof(*c));
		c->slot = 0x40;
		c->kind = BODYSHOP_KIND_VINYL;
		c->group = VINYL_CATS[g].group;
		c->icon = VINYL_GROUP_ICON[c->group];
		c->label = VINYL_CATS[g].label;
		c->fallback = VINYL_CATS[g].fallback;
		if (!db) {
			c->locked = true;
			continue;
		}
		int idx = 0;
		for (CarPart p = carpartdb_get(db, car, 0x40, 0, NULL, CARPARTDB_ANY_LEVEL); p;
				p = carpartdb_get(db, car, 0x40, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
			if (carpartdb_kit(p) != c->group)
				continue;
			const int level = carpartdb_level(p);
			const int entity = stargazer_unlockable(db, 0x40, p);
			const bool avail = bodyShopAvailable(pdb, ctx, cs, 0x40, entity, idx, level, carpartdb_hash(p));
			if (entity == 0x3D) {
				// The manufacturer vinyls, open only on their cheat code (#446).
				const char* nm = carpartdb_name(db, p);
				char vb[128];
				snprintf(vb, sizeof(vb), "vinyls: manufacturer vinyl %s (0x%08X, L%d, group 0x%X) %s",
					nm ? nm : "?", (unsigned)carpartdb_hash(p), level, (unsigned)c->group,
					avail ? "open" : "locked");
				dlog(vb);
			}
			if (!avail)
				continue;
			if (c->count >= BODYSHOP_MAX_PARTS)
				break;
			const int i = c->count++;
			c->hash[i] = carpartdb_hash(p);
			c->level[i] = (u8)level;
			c->entity[i] = (u8)entity;
			c->index[i] = (s16)idx;
			c->price[i] = bodyShopPartCost(pdb, entity, level);
			c->vUnique[i] = carpartdb_attr(db, p, VINYL_ATTR_UNIQUE, 0) == 0x40;
			c->vColours[i] = carpartdb_attr(db, p, VINYL_ATTR_COLOURS, 0) != 0;
			if (c->vUnique[i])
				vinylNoteUnique(c->hash[i]);
			const u32 nameId = carpartdb_attr(db, p, UNIQUES_ATTR_NAME_ID, 0);
			const char* raw = (lang && nameId) ? langbin_lookup(lang, nameId) : NULL;
			if (raw) {
				langTextToUtf8(raw, c->name[i], sizeof(c->name[i]));
			} else {
				const char* nm = carpartdb_name(db, p);
				snprintf(c->name[i], sizeof(c->name[i]), "%s", nm ? nm : "");
			}
		}
		c->locked = c->count == 0;
	}
	{
		int open = 0, parts = 0;
		for (int i = 0; i < g_bodyShop.ncat; i++) {
			open += !g_bodyShop.cat[i].locked;
			parts += g_bodyShop.cat[i].count;
		}
		char b[200];
		snprintf(b, sizeof(b), "vinyls: SetupVinyls -- %d of %d groups open, %d vinyls; IsShopEnterable "
			"0x2B9FF067 %d, 0xCB1B31D5 %d, 0x351B5B8A %d, 0x611B814A %d", open, g_bodyShop.ncat, parts,
			perfShopEnterable(NULL, 0x2B9FF067u), perfShopEnterable(NULL, 0xCB1B31D5u),
			perfShopEnterable(NULL, 0x351B5B8Au), perfShopEnterable(NULL, 0x611B814Au));
		dlog(b);
		int o = snprintf(b, sizeof(b), "vinyls: groups open (group=vinyls):");
		for (int i = 0; i < g_bodyShop.ncat && o < (int)sizeof(b); i++)
			if (!g_bodyShop.cat[i].locked)
				o += snprintf(b + o, sizeof(b) - o, " %X=%d", g_bodyShop.cat[i].group, g_bodyShop.cat[i].count);
		dlog(b);
	}
	// The conflicts' view of the hood: a hood that takes the vinyls off
	// (0x721AFF7C) bars the hood vinyls.
	const u32 hood = cs >= 0 && cs < PROFILE_CAREER_ARRAYS
		? uniquesGetPart(gProfile.careerParts[cs], 0x09) : 0;
	const CarPart hp = hood && db ? carpartdb_get(db, car, 0x09, hood, NULL, CARPARTDB_ANY_LEVEL) : NULL;
	g_bodyShop.hoodNoVinyls = hp && carpartdb_attr(db, hp, UNIQUES_ATTR_HOOD_VINYL, 0) != 0;
	static const u32 ids[VS_TEXT_COUNT] = { 0x3706F93Du, 0xD8B8402Au, 0xEB587F14u };
	for (int k = 0; k < VS_TEXT_COUNT; k++) {
		const char* raw = lang ? langbin_lookup(lang, ids[k]) : NULL;
		snprintf(g_bodyShop.vinylText[k], sizeof(g_bodyShop.vinylText[k]), "%s", raw ? raw : "");
	}
}

// ---- The car specialties shop's locks (#372 step 5) ----
// GetIcePartsList (0x8015E708): every part NewGetFirstCarPart / NextCarPart
// hands out for the tuning car in `slot`, at any level, that passes
// IsPartAvailable -- slot 9 (Split Hoods) only its kit-5 parts, slot 0x1D
// (Spinners) only the SPINNER rims whose OUTER_RADIUS is the car type's.
// Returns the count; the port needs no list for the locks.
typedef struct {
	const CarPartDb* db;
	const PerfDb* pdb;
	PerfUnlockCtx ctx;
	int cs;
	u32 car;
	s8 wheelOuter;
} IceLockCtx;

static int iceListCount(const IceLockCtx* k, int slot) {
	int n = 0, idx = 0;
	if (!k->db)
		return 0;
	for (CarPart p = carpartdb_get(k->db, k->car, slot, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(k->db, k->car, slot, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
		if (slot == 0x09 && carpartdb_kit(p) != 5)
			continue;
		if (slot == 0x1D && ((s8)carpartdb_attr(k->db, p, UNIQUES_ATTR_OUTER, 0) != k->wheelOuter ||
				carpartdb_attr(k->db, p, UNIQUES_ATTR_RIM_BRAND, 0) != 0xC8D1A75Eu))
			continue;   // bStringHash("SPINNER")
		const int level = carpartdb_level(p);
		if (bodyShopAvailable(k->pdb, &k->ctx, k->cs, slot, stargazer_unlockable(k->db, slot, p),
				idx, level, carpartdb_hash(p)))
			n++;
	}
	return n;
}

// IceCategoryIsLocked (0x8015ECB0). Nitrous Purge (0xA2) wants nitrous level
// 1 or 2 available, then one part; 0x9B nitrous level 3, then two parts;
// 0x9D its level-3 part passing IsPartAvailable -- against slot 0x22, as the
// exe passes it (0x8015EEC4) -- then two parts. The rest: locked at one part
// or fewer for 0x1D, 0x22, 0x99..0x9A, 0x9F..0xA1 and 0xA3 (their first part
// is the stock "none"), at none for any other slot.
static bool iceCategoryLocked(const IceLockCtx* k, int slot) {
	if (slot == 0xA2) {
		if (!(k->pdb && (perfdb_package_available(k->pdb, &k->ctx, 2, 1) ||
				perfdb_package_available(k->pdb, &k->ctx, 2, 2))))
			return true;
		return iceListCount(k, 0xA2) < 1;
	}
	if (slot == 0x9B) {
		if (!(k->pdb && perfdb_package_available(k->pdb, &k->ctx, 3, 3)))
			return true;
		return iceListCount(k, 0x9B) < 2;
	}
	if (slot == 0x9D) {
		const CarPart p = k->db ? carpartdb_get(k->db, k->car, 0x9D, 0, NULL, 3) : NULL;
		if (!(p && bodyShopAvailable(k->pdb, &k->ctx, k->cs, 0x22,
				stargazer_unlockable(k->db, 0x22, p), 0, carpartdb_level(p), carpartdb_hash(p))))
			return true;
		return iceListCount(k, 0x9D) < 2;
	}
	const bool hasNone = slot == 0x1D || slot == 0x22 || slot == 0x99 || slot == 0x9A ||
		(slot >= 0x9F && slot <= 0xA1) || slot == 0xA3;
	return iceListCount(k, slot) <= (hasNone ? 1 : 0);
}

// IsNeonCompletelyLocked (0x8015F050): 0x9A, 0x9D and 0x9B all locked.
static bool iceNeonLocked(const IceLockCtx* k) {
	return iceCategoryLocked(k, 0x9A) && iceCategoryLocked(k, 0x9D) && iceCategoryLocked(k, 0x9B);
}

// RideInfo::TrunkAudioSlotAvailable (SpeedPS 0x80245904; SPEED2.EXE
// 0x6103F0 the same, its level-3 jump table at 0x6104E4 / 0x6104F0): slots
// 0x23..0x23+n by the layout's level (CarPart byte 5 >> 5) and the car type
// (RideInfo +0, CarTypeInfo +0x840): level 1 n = 1 (3 on types 8..10),
// level 2 n = 3 (5 on 8..10), level 3 n = 4 (11 on 8..10, 5 on types 5, 13,
// 15, 18, 22, 25, 26, 28 and 30), past 3 n = 0; none without a layout or at
// level 0.
static bool iceTrunkSlotAvailable(int level, int carType, int slot) {
	if ((unsigned)(slot - 0x23) > 0xBu || level <= 0)
		return false;
	const bool big = carType >= 8 && carType <= 10;
	int n = 0;
	if (level == 1)
		n = big ? 3 : 1;
	else if (level == 2)
		n = big ? 5 : 3;
	else if (level == 3) {
		static const u8 kFive[] = { 5, 13, 15, 18, 22, 25, 26, 28, 30 };
		n = big ? 11 : 4;
		for (size_t i = 0; i < sizeof(kFive); i++)
			if (carType == kFive[i])
				n = 5;
	}
	return slot <= n + 0x23;
}

// The car type's wheel OUTER_RADIUS, which GetIcePartsList holds the
// spinners to (CarTypeInfo's, cardb wheelOuter).
static s8 iceWheelOuter(const char* bunPath, u32 car) {
	s8 r = 0;
	CarDb* cdb = (CarDb*)malloc(sizeof(CarDb));
	if (cdb && cardb_load(bunPath, cdb))
		for (int i = 0; i < cdb->count; i++)
			if (cdb->recs[i].nameHash == car) {
				r = cdb->recs[i].wheelOuter;
				break;
			}
	free(cdb);
	return r;
}

// ---- The decals: ChooseDecalCategory (UI_DecalMain) and ChooseDecalScreen
// (UI_DecalsOverlayInvis), GC 0x801668B8..0x80169370 --------------------------
// The hub is a tree of IconOptions: level 0 the two windows (leaves) and four
// zones; a door lists its six decal slots, a quarter (and the hood, which no
// level-0 option reaches -- SPEED2.EXE's Setup adds the same six) its decal
// layouts, each layout its slots. A leaf brings the decal list up over the
// hub; A on a layout first puts the layout in the setup (InstallNeededLayout-
// Part), asking when decals are on the zone. The port shows it on
// PartSelectionScreen's package as the vinyls do -- the options as its
// categories, the decal list as its parts list -- and builds the hub again
// in place on a level change.
// The hub's HelpHash (+0x28) follows the level (feHelpHash()); its Total
// Cost is up in a career (drawDecalTotal()).

// MapDecalSlotToDecalLayoutSlot (0x80168C0C).
static int decalLayoutSlotOf(int slot) {
	if (slot >= 0x61 && slot < 0x99)
		return 0x34 + (slot - 0x61) / 8;
	return 0xA9;
}

// TranslateToWidebodyLayoutSlotIfNecessary (0x80170A08): under a widebody kit
// (slot 6 over level 0) the door and quarter layouts are the widebody's own.
static int decalWideLayoutSlot(int slot, int kitLevel) {
	if (kitLevel > 0 && slot >= 0x37 && slot <= 0x3A)
		return slot + 4;
	return slot;
}

// The zone a hub option's Y and InstallNeededLayoutPart clear, its first
// decal slot (RemoveDecalsForCurrentZone 0x801673F4), 0xA9 for none.
static int decalZoneBase(u32 v) {
	if (v == 0x10001) return 0x79;
	if (v == 0x10002) return 0x81;
	if (v == 0x10003 || v == 0x20006 || v == 0x20007) return 0x89;
	if (v == 0x10004 || v == 0x20008 || v == 0x20009) return 0x91;
	if (v == 0x10005 || v == 0x2000A || v == 0x2000B) return 0x61;
	return 0xA9;
}

// NeedsNewLayoutPart's (0x80167180) layout slot and which layout (1-based),
// 0 for an option that names none.
static int decalOptionLayout(u32 v, int* n) {
	*n = 0;
	switch (v) {
	case 0x20006: *n = 1; return 0x39;
	case 0x20007: *n = 2; return 0x39;
	case 0x20008: *n = 1; return 0x3A;
	case 0x20009: *n = 2; return 0x3A;
	case 0x2000A: *n = 1; return 0x34;
	case 0x2000B: *n = 2; return 0x34;
	default: return 0xA9;
	}
}

// GetLayoutPart (0x80170B70): the n-th part the car fits in the (widebody)
// layout slot.
static CarPart decalLayoutPart(const CarPartDb* db, u32 car, int slot, int n, int kitLevel, int* idxOut) {
	if (!db || !decalIsLayoutSlot(slot) || n < 1)
		return NULL;
	const int t = decalWideLayoutSlot(slot, kitLevel);
	int i = 0;
	for (CarPart p = carpartdb_get(db, car, t, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(db, car, t, 0, p, CARPARTDB_ANY_LEVEL), i++)
		if (i == n - 1) {
			if (idxOut)
				*idxOut = i;
			return p;
		}
	return NULL;
}

static int decalNumDecals(const CarPartDb* db, CarPart p) {
	return p ? (int)carpartdb_attr(db, p, carpartdb_string_hash("NUM_DECALS"), 0) : 0;
}

// GetNumDecalsForInstalledLayoutPart (0x80170AB8): the setup's part in the
// (widebody) slot, else the car's.
static int decalNumDecalsInstalled(const CarPartDb* db, u32 car, int slot, int kitLevel) {
	const int t = decalWideLayoutSlot(slot, kitLevel);
	u32 h = paintSetupPart(t);
	if (!h)
		h = decalInstalled(t);
	const CarPart p = h ? carpartdb_get(db, car, t, h, NULL, CARPARTDB_ANY_LEVEL) : NULL;
	return decalNumDecals(db, p);
}

// IsDecalWhite (0x8015E054): a decal whose NAME is not its brand.
static bool decalIsWhite(const CarPartDb* db, CarPart p) {
	return p && carpartdb_attr(db, p, carpartdb_string_hash("NAME"), 0) !=
		carpartdb_attr(db, p, 0xEBB03E66u, 0);
}

static void decalAddOption(const CarPartDb* db, const PerfDb* pdb, const PerfUnlockCtx* ctx, int cs,
		u32 car, int kitLevel, u32 value, bool leaf, u32 icon, u32 label, bool lock) {
	if (g_bodyShop.ncat >= BODYSHOP_MAX_CATS)
		return;
	BodyShopCat* c = &g_bodyShop.cat[g_bodyShop.ncat++];
	memset(c, 0, sizeof(*c));
	c->kind = BODYSHOP_KIND_DECAL;
	c->value = value;
	c->leaf = leaf;
	c->icon = icon;
	c->label = label;
	c->fallback = "Decals";
	c->headerPrice = -1;
	c->slot = leaf ? (int)value : 0xA9;
	// AddCategoryOptionLock (0x80167530): IsCarPartUnlocked of the option's
	// layout slot's first part.
	if (lock) {
		int ls = 0;
		switch (value) {
		case 0x69: ls = 0x35; break;
		case 0x71: ls = 0x36; break;
		case 0x10001: ls = 0x37; break;
		case 0x10002: ls = 0x38; break;
		case 0x10003: ls = 0x39; break;
		case 0x10004: ls = 0x3A; break;
		case 0x10005: ls = 0x34; break;
		default: break;
		}
		const CarPart p = db ? carpartdb_get(db, car, ls, 0, NULL, CARPARTDB_ANY_LEVEL) : NULL;
		c->locked = !(p && bodyShopAvailable(pdb, ctx, cs, ls, stargazer_unlockable(db, ls, p), 0,
			carpartdb_level(p), carpartdb_hash(p)));
	}
	// NeedsNewLayoutPart and DecalsInstalledOnCurrentLayout's widest layout.
	int n = 0;
	const int ls = decalOptionLayout(value, &n);
	if (db && n > 0) {
		int idx = 0;
		const CarPart lp = decalLayoutPart(db, car, ls, n, kitLevel, &idx);
		c->layoutSlot = ls;
		c->needsLayout = decalNumDecals(db, lp) != decalNumDecalsInstalled(db, car, ls, kitLevel);
		if (lp) {
			const int t = decalWideLayoutSlot(ls, kitLevel);
			c->layoutHash = carpartdb_hash(lp);
			c->layoutEntity = stargazer_unlockable(db, t, lp);
			c->layoutPrice = bodyShopPartCost(pdb, c->layoutEntity, carpartdb_level(lp));
			c->layoutIndex = idx;
		}
		const int a = decalNumDecals(db, decalLayoutPart(db, car, ls, 1, kitLevel, NULL));
		const int b = decalNumDecals(db, decalLayoutPart(db, car, ls, 2, kitLevel, NULL));
		c->zoneMax = a > b ? a : b;
	}
}

// ChooseDecalCategory::Setup (0x801677E8): the options of the level.
static void decalBrowserBuild(const CarPartDb* db, const PerfDb* pdb, const PerfUnlockCtx* ctx, int cs,
		u32 car) {
	// The widebody kit's level (GetInstalledPart(6)): the quarters' second
	// layout only without one, the door and quarter layouts its own with one.
	int kitLevel = 0;
	const u32 kh = decalInstalled(0x06);
	const CarPart kp = kh && db ? carpartdb_get(db, car, 0x06, kh, NULL, CARPARTDB_ANY_LEVEL) : NULL;
	kitLevel = kp ? carpartdb_level(kp) : 0;
	const u32 hh = decalInstalled(0x09);
	const CarPart hp = hh && db ? carpartdb_get(db, car, 0x09, hh, NULL, CARPARTDB_ANY_LEVEL) : NULL;
	g_decal.hoodLevel = hp ? carpartdb_level(hp) : 0;
	const u32 v = g_decal.level;
#define DOPT(val, leaf, icon, label) decalAddOption(db, pdb, ctx, cs, car, kitLevel, val, leaf, icon, label, false)
	if (v == 0) {
		static const u32 val[6] = { 0x69, 0x71, 0x10001, 0x10002, 0x10003, 0x10004 };
		static const u32 icon[6] = { 0x52DED91Du, 0xAC7937B4u, 0xDA88B711u, 0xC9A967C4u, 0x2C710C4Du,
			0xFFA7D360u };
		for (int k = 0; k < 6; k++)
			decalAddOption(db, pdb, ctx, cs, car, kitLevel, val[k], k < 2, icon[k], icon[k], true);
		// PORT (#325, the user 2026-11-01: "activate hood decals"): retail
		// builds the hood page (0x10005) below but adds no entry for it here,
		// so nothing leads to it. The port adds one, last, labelled with the
		// shipped "Hood" (0x414F19D7); FrontB has no hood category icon, so it
		// shows the hood's first layout icon (0x154FA42F). The lock is retail's
		// (AddCategoryOptionLock, slot 0x34), and A under an aftermarket hood
		// is ChooseDecalCategory's own 0xD104AD36.
		decalAddOption(db, pdb, ctx, cs, car, kitLevel, 0x10005, false, 0x154FA42Fu, 0x414F19D7u, true);
	} else if (v == 0x10001 || v == 0x10002) {
		const u32 base = v == 0x10001 ? 0x79 : 0x81;
		const u32 icon = v == 0x10001 ? 0xFE957F48u : 0x2E40EADBu;
		for (u32 k = 0; k < 6; k++)
			DOPT(base + k, true, icon + k, 0x89BB9CEAu + k);
	} else if (v == 0x10003 || v == 0x10004) {
		// #482: SPEED2.EXE's icons (Setup 0x546C00), the GameCube's the other
		// way round. FrontB's DECAL_LREAR_QP_LAYOUT2 / DECAL_RREAR_QP_LAYOUT2
		// (...9C / ...E2) draw one big decal -- layout 1, slot 0x89 / 0x91 alone
		// -- and LAYOUT1 (...9B / ...E1) two small ones, layout 2's 0x89 + 0x8A /
		// 0x91 + 0x92. The GameCube's order showed each with the other's picture.
		const bool l = v == 0x10003;
		DOPT(l ? 0x20006 : 0x20008, false, l ? 0x13AE389Cu : 0x5CED1BE2u, 0xB348F286u);
		if (kitLevel == 0)
			DOPT(l ? 0x20007 : 0x20009, false, l ? 0x13AE389Bu : 0x5CED1BE1u, 0xB348F287u);
	} else if (v == 0x10005) {
		DOPT(0x2000A, false, 0x154FA42Fu, 0xB348F286u);
		DOPT(0x2000B, false, 0x154FA430u, 0xB348F287u);
	} else if (v == 0x20006 || v == 0x20007) {
		// SPEED2.EXE's too: layout 1's one slot shows the layout's own icon;
		// 0xC813D5BB / BC are layout 2's two (#482).
		DOPT(0x89, true, v == 0x20006 ? 0x13AE389Cu : 0xC813D5BBu, 0x89BB9CEAu);
		if (v == 0x20007)
			DOPT(0x8A, true, 0xC813D5BCu, 0x89BB9CEBu);
	} else if (v == 0x20008 || v == 0x20009) {
		DOPT(0x91, true, v == 0x20008 ? 0x5CED1BE2u : 0x392F21C1u, 0x89BB9CEAu);
		if (v == 0x20009)
			DOPT(0x92, true, 0x392F21C2u, 0x89BB9CEBu);
	} else if (v == 0x2000A || v == 0x2000B) {
		const int nn = v == 0x2000A ? 4 : 8;
		const u32 icon = v == 0x2000A ? 0xFDE2B3CFu : 0x4ADCF090u;
		for (int k = 0; k < nn; k++)
			DOPT(0x61 + k, true, icon + k, 0x89BB9CEAu + k);
	}
#undef DOPT
	char b[256];
	int o = snprintf(b, sizeof(b), "decals: ChooseDecalCategory::Setup -- level 0x%X, kit L%d, %d option(s):",
		(unsigned)v, kitLevel, g_bodyShop.ncat);
	for (int i = 0; i < g_bodyShop.ncat && o < (int)sizeof(b); i++) {
		const BodyShopCat* c = &g_bodyShop.cat[i];
		o += snprintf(b + o, sizeof(b) - o, " %X%s%s", (unsigned)c->value, c->leaf ? "" : "*",
			c->locked ? "L" : "");
		if (c->layoutSlot && o < (int)sizeof(b))
			o += snprintf(b + o, sizeof(b) - o, "(layout 0x%X 0x%08X %s, zone max %d)", (unsigned)c->layoutSlot,
				(unsigned)c->layoutHash, c->needsLayout ? "needed" : "in", c->zoneMax);
	}
	dlog(b);
	// What the car wears in the layout slots.
	o = snprintf(b, sizeof(b), "decals: layouts on the car / in the setup:");
	for (int s = 0x34; s < 0x3F && o < (int)sizeof(b); s++) {
		const u32 h = decalInstalled(s);
		const int k = paintSetupFind(s);
		const CarPart p = h && db ? carpartdb_get(db, car, s, h, NULL, CARPARTDB_ANY_LEVEL) : NULL;
		if (h || k >= 0)
			o += snprintf(b + o, sizeof(b) - o, " %X=0x%08X(n%d)%s", (unsigned)s, (unsigned)h,
				decalNumDecals(db, p), k >= 0 ? "+setup" : "");
	}
	dlog(b);
}

// ChooseDecalScreen::Setup (0x80169118) for a leaf: node 0 the "none", then
// GetDecalsList's decals of the slot on the colour side IsDecalWhite puts
// them (white flag set: the coloured ones) that IsDecalAvailable passes; the
// list snaps to the kept brand after a toggle, else to the setup's or the
// car's decal, else to its head. RefreshHeader's price is the layout slot's
// part's cost.
static void decalBuildList(const CarPartDb* db, const PerfDb* pdb, const LangTable* lang, u32 car,
		BodyShopCat* c) {
	c->count = 0;
	const int slot = c->slot;
	{
		const int i = c->count++;
		c->hash[i] = 0;
		c->price[i] = 0;
		c->brand[i] = 0;
		const char* raw = lang ? langbin_lookup(lang, 0x2B5ABCF4u) : NULL;
		if (raw)
			langTextToUtf8(raw, c->name[i], sizeof(c->name[i]));
		else
			snprintf(c->name[i], sizeof(c->name[i]), "None");
	}
	int idx = 0, total = 0, dropped = 0;
	for (CarPart p = carpartdb_get(db, car, slot, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(db, car, slot, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
		total++;
		if (decalIsWhite(db, p) == g_decal.white)
			continue;
		const u32 brand = carpartdb_attr(db, p, 0xEBB03E66u, 0);
		if (!paintDecalBrandUnlocked(pdb, brand))
			continue;
		if (c->count >= BODYSHOP_MAX_PARTS) {
			dropped++;
			continue;
		}
		const int i = c->count++;
		const int level = carpartdb_level(p);
		c->hash[i] = carpartdb_hash(p);
		c->level[i] = (u8)level;
		c->entity[i] = (u8)stargazer_unlockable(db, slot, p);
		c->index[i] = (s16)idx;
		c->price[i] = bodyShopPartCost(pdb, c->entity[i], level);
		c->brand[i] = brand;
		const u32 nameId = carpartdb_attr(db, p, UNIQUES_ATTR_NAME_ID, 0);
		const char* raw = (lang && nameId) ? langbin_lookup(lang, nameId) : NULL;
		if (raw) {
			langTextToUtf8(raw, c->name[i], sizeof(c->name[i]));
		} else {
			const char* nm = carpartdb_name(db, p);
			snprintf(c->name[i], sizeof(c->name[i]), "%s", nm ? nm : "");
		}
	}
	// The snap.
	g_bodyShop.sel = 0;
	bool kept = false;
	for (int i = 1; g_decal.keepBrand && i < c->count; i++)
		if (c->brand[i] == g_decal.keepBrand) {
			g_bodyShop.sel = i;
			kept = true;
		}
	if (!kept) {
		u32 h = paintSetupPart(slot);
		if (!h)
			h = decalInstalled(slot);
		for (int i = 1; h && i < c->count; i++)
			if (c->hash[i] == h)
				g_bodyShop.sel = i;
	}
	// RefreshHeader's price.
	const int ls = decalLayoutSlotOf(slot);
	u32 lh = paintSetupPart(ls);
	if (!lh)
		lh = decalInstalled(ls);
	c->headerPrice = -1;
	if (lh) {
		const CarPart lp = carpartdb_get(db, car, ls, lh, NULL, CARPARTDB_ANY_LEVEL);
		c->headerPrice = lp ? bodyShopPartCost(pdb, stargazer_unlockable(db, ls, lp), carpartdb_level(lp)) : 0;
	}
	char b[224];
	snprintf(b, sizeof(b), "decals: ChooseDecalScreen::Setup -- slot 0x%X, %s side, %d of %d decal(s) listed%s, "
		"on row %d (%s), layout 0x%X 0x%08X $%d", (unsigned)slot, g_decal.white ? "coloured" : "white",
		c->count - 1, total, dropped ? " (list full, some dropped)" : "", g_bodyShop.sel,
		c->name[g_bodyShop.sel], (unsigned)ls, (unsigned)lh, c->headerPrice);
	dlog(b);
}

// IsRimAvailable (0x8015E9A0) over the FRONT_WHEEL parts, counted: the brand
// (0xEBB03E66), the car type's OUTER_RADIUS and IsPartAvailable --
// AddRimCategory's GetPartsList(0x1D, brand).
static int rimPartsCount(const CarPartDb* db, const PerfDb* pdb, const PerfUnlockCtx* ctx, int cs,
		u32 car, u32 brand, s8 outer) {
	int n = 0, idx = 0;
	for (CarPart p = carpartdb_get(db, car, 0x1D, 0, NULL, CARPARTDB_ANY_LEVEL); p;
			p = carpartdb_get(db, car, 0x1D, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
		if (carpartdb_attr(db, p, UNIQUES_ATTR_RIM_BRAND, 0) != brand ||
				(s8)carpartdb_attr(db, p, UNIQUES_ATTR_OUTER, 0) != outer)
			continue;
		if (bodyShopAvailable(pdb, ctx, cs, 0x1D, stargazer_unlockable(db, 0x1D, p), idx, carpartdb_level(p),
				carpartdb_hash(p)))
			n++;
	}
	return n;
}

static bool careerCurrentCarIsSUV(void);

// IsCarbonPartConverterAvailable(slot, 3): 0x60's entity 0x56, 0x5D's 0x55
// (as PartsCategoryCarbonIsLocked reads it, below).
static bool carbonConverterAvailable(const PerfDb* pdb, const PerfUnlockCtx* ctx, int slot) {
	return pdb && (ctx->filter & PERF_FILTER_ONLINE) &&
		perfdb_entity_unlocked(pdb, ctx, slot == 0x60 ? 0x56 : 0x55, 3);
}

// Setup / SetupBodyShop: the categories as dynItems, each part list built
// now off the databases, which are let go again. False, having said why, when
// there is no career car or no parts database.
static void bodyShopItems(const Config* cfg, MenuState* out, const LangTable* lang) {
	char b[256];
	char bunPath[600];
	memset(g_bodyShop.cat, 0, sizeof(g_bodyShop.cat));
	g_bodyShop.built = false;
	g_bodyShop.ncat = 0;
	g_bodyShop.browsing = false;
	g_bodyShop.sel = 0;
	out->isBodyShop = true;
	g_bodyShop.vinylMode = g_vinylBrowse;
	g_vinylBrowse = false;
	g_bodyShop.decalMode = g_decalBrowse && !g_bodyShop.vinylMode;
	g_decalBrowse = false;
	g_bodyShop.iceMode = g_iceBrowse && !g_bodyShop.vinylMode && !g_bodyShop.decalMode;
	g_iceBrowse = false;
	g_bodyShop.neonMode = g_bodyShop.iceMode && g_neonBrowse;
	g_neonBrowse = false;
	g_bodyShop.spinnerMode = g_bodyShop.iceMode && !g_bodyShop.neonMode && g_spinnerBrowse;
	g_spinnerBrowse = false;
	const bool plainShop = !g_bodyShop.vinylMode && !g_bodyShop.decalMode && !g_bodyShop.iceMode;
	g_bodyShop.rimBrandMode = plainShop && g_rimBrandBrowse;
	g_bodyShop.rimsMode = plainShop && !g_bodyShop.rimBrandMode && g_rimsBrowse;
	g_rimBrandBrowse = g_rimsBrowse = false;
	g_bodyShop.carbonMode = plainShop && !g_bodyShop.rimBrandMode && !g_bodyShop.rimsMode && g_carbonBrowse;
	g_carbonBrowse = false;
	for (int k = 0; k < BS_DLG_COUNT; k++) {
		const char* raw = lang ? langbin_lookup(lang, BODYSHOP_DLG_ID[k]) : NULL;
		snprintf(g_bodyShop.dlgText[k], sizeof(g_bodyShop.dlgText[k]), "%s", raw ? raw : "");
	}
	for (int k = 0; k < ICE_FN_COUNT; k++) {
		const char* raw = lang ? langbin_lookup(lang, ICE_FN_TEXT_ID[k]) : NULL;
		snprintf(g_bodyShop.iceFnText[k], sizeof(g_bodyShop.iceFnText[k]), "%s", raw ? raw : "");
	}
	g_bodyShop.purging = false;
	// IceSelectionScreen::Setup (0x80169CB8), mode 0: MENU_ITEMS_ICEMAIN's
	// rows, Custom Gauges left out from the crib (0x803D84E0 == 1). The plain
	// slots browse UI_IcePartsOverlay (IcePartsBrowser); the rest open screens
	// of their own (BODYSHOP_KIND_ICE, #372 5c).
	if (g_bodyShop.spinnerMode) {
		// ChooseSpinnerBrand's rows come off the database, below.
	} else if (g_bodyShop.neonMode) {
		for (size_t r = 0; r < sizeof(MENU_ITEMS_NEON) / sizeof(MENU_ITEMS_NEON[0]); r++) {
			const MenuItem* it = &MENU_ITEMS_NEON[r];
			bodyShopAddCategory(it->modeValue, it->iconHash, it->labelHash, it->fallbackLabel,
				BODYSHOP_KIND_PARTS);
		}
	} else if (g_bodyShop.iceMode && (g_iceMode == ICE_MODE_TRUNK_STOCK ||
			g_iceMode == ICE_MODE_TRUNK_LAYOUT)) {
		// Setup's mode 3: Audio Components (an IceCategoryThing on 0x23,
		// +0x6C 4) and Trunk Layout (0x22); mode 2 the layouts alone, browsed
		// at once (below).
		if (g_iceMode == ICE_MODE_TRUNK_STOCK)
			bodyShopAddCategory(0x23, 0x76167B7Eu, 0x28BF66F6u, "AUDIO COMPONENTS", BODYSHOP_KIND_ICE);
		bodyShopAddCategory(0x22, 0xF7E5B04Au, 0xC8D23393u, "TRUNK LAYOUT", BODYSHOP_KIND_PARTS);
	} else if (g_bodyShop.iceMode && g_iceMode != ICE_MODE_MAIN) {
		// Modes 4 and 5: a row per slot 0x23..0x2E that
		// IsTrunkAudioSlotAvailable passes (iceTrunkSlotAvailable(), after
		// the database is up).
		for (int s = 0x23; s < 0x2F; s++)
			bodyShopAddCategory(s, 0xE803E1CDu, 0, NULL, BODYSHOP_KIND_PARTS);
	} else if (g_bodyShop.iceMode) {
		for (size_t r = 0; r < sizeof(MENU_ITEMS_ICEMAIN) / sizeof(MENU_ITEMS_ICEMAIN[0]); r++) {
			const MenuItem* it = &MENU_ITEMS_ICEMAIN[r];
			const int slot = it->modeValue;
			if (slot == 0xA3 && g_customizeEntry == CUSTOMIZE_ENTRY_CRIB)
				continue;
			const bool plain = slot == 0x99 || slot == 0x9F || slot == 0xA1 || slot == 0x09 ||
				slot == 0xA0 || slot == 0xA2 || slot == 0xA3;
			bodyShopAddCategory(slot, it->iconHash, it->labelHash, it->fallbackLabel,
				plain ? BODYSHOP_KIND_PARTS : BODYSHOP_KIND_ICE);
		}
	}
	// SetupCarbonParts (0x801645A4): ResetCategories, the four carbon lists
	// (AddCategory's carbon flag), then a CategoryNode per converter, 0x60 and
	// 0x5D: named and pictured by whether the slot holds the plain part, locked
	// without IsCarbonPartConverterAvailable.
	if (g_bodyShop.carbonMode) {
		static const struct { int slot; u32 hash; const char* fb; } kC[4] = {
			{ 0x09, 0xF7363420u, "Carbon Hoods" }, { 0x0C, 0xC43176D4u, "Carbon Spoilers" },
			{ 0x07, 0x643BDE3Cu, "Carbon Roof Scoops" }, { 0x20, 0x10B5E8D1u, "Carbon Mirrors" } };
		for (int k = 0; k < 4; k++) {
			bodyShopAddCategory(kC[k].slot, kC[k].hash, kC[k].hash, kC[k].fb, BODYSHOP_KIND_PARTS);
			g_bodyShop.cat[g_bodyShop.ncat - 1].carbon = true;
		}
		const int ccs = gProfile.currentCarSlot;
		const bool okCs = ccs >= 0 && ccs < PROFILE_CAREER_ARRAYS;
		const bool plain60 = okCs && uniquesGetPart(gProfile.careerParts[ccs], 0x60) == CARBON_CONV_PLAIN;
		const bool plain5d = okCs && uniquesGetPart(gProfile.careerParts[ccs], 0x5D) == CARBON_CONV_PLAIN;
		bodyShopAddCategory(0x60, plain60 ? 0xF8111A17u : 0x8F5DC19Fu, plain60 ? 0xF8111A17u : 0x1036E38Eu,
			"Carbon Body", BODYSHOP_KIND_CONV);
		bodyShopAddCategory(0x5D, plain5d ? 0x246DE0CBu : 0x2BDB0653u, plain5d ? 0xB229FA7Eu : 0xE170F115u,
			"Carbon Hood", BODYSHOP_KIND_CONV);
	}
	if (plainShop && !g_bodyShop.rimBrandMode && !g_bodyShop.rimsMode && !g_bodyShop.carbonMode) {
	bodyShopAddCategory(0x01, 0x739C4A1Bu, 0x739C4A1Bu, "Front Bumpers", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x02, 0x015C767Cu, 0x015C767Cu, "Rear Bumpers", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x0B, 0x4E6C2AF9u, 0x4E6C2AF9u, "Side Skirts", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x0C, 0xBB034EA6u, 0xBB034EA6u, "Spoilers", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x09, 0x028F7092u, 0x028F7092u, "Hoods", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x07, 0x79165861u, 0x79165861u, "Roof Scoops", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x0E, 0xF69AC384u, 0x3DC6A111u, "Headlights", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x0F, 0x2CBB2D1Cu, 0x663437A9u, "Taillights", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x20, 0xC83DE19Au, 0x0DD35467u, "Side Mirrors", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x10, 0xA434A006u, 0x2ACED725u, "Exhaust Tips", BODYSHOP_KIND_PARTS);
	bodyShopAddCategory(0x1D, 0x0294D2A3u, 0x0294D2A3u, "Rims", BODYSHOP_KIND_RIMS);
	bodyShopAddCategory(0x5E, 0x24911E04u, 0x24911E04u, "Carbon Fiber", BODYSHOP_KIND_CARBON);
	bodyShopAddCategory(0x06, 0x945E9BC5u, 0x945E9BC5u, "Widebody Kits", BODYSHOP_KIND_PARTS);
	}

	const int cs = gProfile.currentCarSlot;
	const u32 car = cs >= 0 && cs < PROFILE_CAREER_ARRAYS ? gProfile.careerParts[cs][0] : 0;
	g_bodyShop.carSlot = cs;
	g_bodyShop.car = car;
	static CarPartDb db;
	const bool haveDb = car && cfg &&
		buildGamePath(cfg, "GLOBAL/GLOBALB.BUN", bunPath, sizeof(bunPath)) &&
		carpartdb_load(bunPath, &db);
	const PerfDb* pdb = cfg ? perfDb(cfg) : NULL;
	PerfUnlockCtx ctx;
	perfBuildCtx(&ctx);
	if (!haveDb) {
		snprintf(b, sizeof(b), "body shop: car slot %d (0x%08X) -- no career car or no parts "
			"database, every category locked", cs, (unsigned)car);
		dlog(b);
	}
	if (g_bodyShop.vinylMode) {
		vinylReadInstalled(haveDb ? &db : NULL, pdb, cs, car);
		vinylBrowserBuild(haveDb ? &db : NULL, pdb, &ctx, lang, cs, car);
	}
	if (g_bodyShop.decalMode)
		decalBrowserBuild(haveDb ? &db : NULL, pdb, &ctx, cs, car);
	// The IceSelectionThing ctor (0x801693B8) locks every row on
	// IceCategoryIsLocked(slot); Neon's IceCategoryThing on
	// IsNeonCompletelyLocked.
	IceLockCtx ik;
	memset(&ik, 0, sizeof(ik));
	if (g_bodyShop.iceMode && haveDb) {
		ik.db = &db;
		ik.pdb = pdb;
		ik.ctx = ctx;
		ik.cs = cs;
		ik.car = car;
		ik.wheelOuter = iceWheelOuter(bunPath, car);
	}
	// GetInstalledPart(0xD) / (0x22)'s level (byte 5 >> 5), for the neon
	// screen's A.
	g_bodyShop.engineLevel = g_bodyShop.trunkLevel = -1;
	if (g_bodyShop.iceMode && haveDb && cs >= 0 && cs < PROFILE_CAREER_ARRAYS) {
		for (int k = 0; k < 2; k++) {
			const int s = k ? 0x22 : 0x0D;
			const u32 h = uniquesGetPart(gProfile.careerParts[cs], s);
			const CarPart p = h ? carpartdb_get(&db, car, s, h, NULL, CARPARTDB_ANY_LEVEL) : NULL;
			*(k ? &g_bodyShop.trunkLevel : &g_bodyShop.engineLevel) = p ? carpartdb_level(p) : -1;
		}
	}
	// Modes 4 / 5: the slots the layout has room for, each row named
	// "Trunk Slot %d" by its place (RefreshHeader's FEngPrintf of 0x3F4B9E43
	// with GetOptionIndex, 1-based).
	if (g_bodyShop.iceMode && (g_iceMode == ICE_MODE_TRUNK_SLOTS ||
			g_iceMode == ICE_MODE_TRUNK_SLOTS_NEW)) {
		const char* fmt = lang ? langbin_lookup(lang, 0x3F4B9E43u) : NULL;
		int w = 0;
		for (int i = 0; i < g_bodyShop.ncat; i++) {
			if (!iceTrunkSlotAvailable(g_bodyShop.trunkLevel, g_profileCarType, g_bodyShop.cat[i].slot))
				continue;
			g_bodyShop.cat[w] = g_bodyShop.cat[i];
			char* lb = g_bodyShop.trunkLabel[w];
			const char* pc = fmt ? strstr(fmt, "%d") : NULL;
			if (pc)
				snprintf(lb, sizeof(g_bodyShop.trunkLabel[0]), "%.*s%d%s", (int)(pc - fmt), fmt, w + 1, pc + 2);
			else
				snprintf(lb, sizeof(g_bodyShop.trunkLabel[0]), "Trunk Slot %d", w + 1);
			g_bodyShop.cat[w].fallback = lb;
			w++;
		}
		g_bodyShop.ncat = w;
		snprintf(b, sizeof(b), "ice: trunk audio mode %d -- layout level %d, car type %d: %d slot(s)",
			g_iceMode, g_bodyShop.trunkLevel, g_profileCarType, w);
		dlog(b);
	}
	// ChooseSpinnerBrand::Setup (0x8016C2C0): GetPartsList(0x1D,
	// bStringHash("SPINNER")) -- IsRimAvailable (0x8015E9A0): the brand
	// (0xEBB03E66), OUTER_RADIUS the car type's (CarTypeInfo +0xDC) and
	// IsPartAvailable -- then a RimsCategory per run of parts sharing a
	// GetName (bStrICmp), each with the rims icon 0x0294D2A3 and locked when
	// it holds none. Its list (BuildPartsIconList, 0x8016C764) is the run,
	// each row RefreshHeader's "%s %d\"" of the name and INNER_RADIUS.
	// RimsBrowser::Setup (0x80165F90) the same over GetPartsList(0x1D, the
	// chosen brand): a RimsCategory per GetName run, its option title
	// RefreshHeader's "%s %s" -- GetBrandNameFromHash, then the design's
	// 0x4732DA07 name or its GetName.
	const bool rimScreens = g_bodyShop.rimBrandMode || g_bodyShop.rimsMode;
	const s8 rimOuter = haveDb && rimScreens ? iceWheelOuter(bunPath, car) : ik.wheelOuter;
	const u32 rimBrand = g_bodyShop.rimsMode ? g_rimBrand : 0xC8D1A75Eu;
	char brandName[40] = "";
	if (g_bodyShop.rimsMode) {
		const char* rb = (lang && g_rimBrandLabel) ? langbin_lookup(lang, g_rimBrandLabel) : NULL;
		if (rb)
			langTextToUtf8(rb, brandName, sizeof(brandName));
	}
	if ((g_bodyShop.spinnerMode || g_bodyShop.rimsMode) && haveDb) {
		char prev[64] = "";
		BodyShopCat* sc = NULL;
		int idx = 0;
		for (CarPart p = carpartdb_get(&db, car, 0x1D, 0, NULL, CARPARTDB_ANY_LEVEL); p;
				p = carpartdb_get(&db, car, 0x1D, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
			if (carpartdb_attr(&db, p, UNIQUES_ATTR_RIM_BRAND, 0) != rimBrand ||
					(s8)carpartdb_attr(&db, p, UNIQUES_ATTR_OUTER, 0) != rimOuter)
				continue;
			const int level = carpartdb_level(p);
			const int entity = stargazer_unlockable(&db, 0x1D, p);
			if (!bodyShopAvailable(pdb, &ctx, cs, 0x1D, entity, idx, level, carpartdb_hash(p)))
				continue;
			const char* nm = carpartdb_name(&db, p);
			if (!nm)
				nm = "";
			const u32 nameId = carpartdb_attr(&db, p, UNIQUES_ATTR_NAME_ID, 0);
			if (!sc || strcasecmp(nm, prev) != 0) {
				if (g_bodyShop.ncat >= BODYSHOP_MAX_CATS)
					break;
				char* lb = g_bodyShop.spinLabel[g_bodyShop.ncat];
				if (g_bodyShop.rimsMode) {
					char grp[40];
					const char* rn = (lang && nameId) ? langbin_lookup(lang, nameId) : NULL;
					if (rn)
						langTextToUtf8(rn, grp, sizeof(grp));
					else
						snprintf(grp, sizeof(grp), "%s", nm);
					snprintf(lb, sizeof(g_bodyShop.spinLabel[0]), "%s%s%s", brandName,
						brandName[0] ? " " : "", grp);
				} else {
					snprintf(lb, sizeof(g_bodyShop.spinLabel[0]), "%s", nm);
				}
				bodyShopAddCategory(0x1D, 0x0294D2A3u, g_bodyShop.rimsMode ? 0u : nameId, lb,
					BODYSHOP_KIND_PARTS);
				sc = &g_bodyShop.cat[g_bodyShop.ncat - 1];
				snprintf(prev, sizeof(prev), "%s", nm);
			}
			if (sc->count >= BODYSHOP_MAX_PARTS)
				continue;
			const int k = sc->count++;
			sc->hash[k] = carpartdb_hash(p);
			sc->level[k] = (u8)level;
			sc->entity[k] = (u8)entity;
			sc->index[k] = (s16)idx;
			sc->price[k] = bodyShopPartCost(pdb, entity, level);
			char base[40];
			const char* raw = (lang && nameId) ? langbin_lookup(lang, nameId) : NULL;
			if (raw)
				langTextToUtf8(raw, base, sizeof(base));
			else
				snprintf(base, sizeof(base), "%s", nm);
			snprintf(sc->name[k], sizeof(sc->name[k]), "%s %d\"", base,
				(int)(s8)carpartdb_attr(&db, p, UNIQUES_ATTR_INNER, 0));
		}
		if (g_bodyShop.rimsMode)
			snprintf(b, sizeof(b), "rims: RimsBrowser::Setup -- brand 0x%08X (%s), OUTER_RADIUS %d, "
				"%d design(s)", (unsigned)rimBrand, brandName, (int)rimOuter, g_bodyShop.ncat);
		else
			snprintf(b, sizeof(b), "spinners: ChooseSpinnerBrand::Setup -- OUTER_RADIUS %d, %d design(s)",
				(int)ik.wheelOuter, g_bodyShop.ncat);
		dlog(b);
	}
	// ChooseRimBrand::Setup (0x80165238): IsSUV picks the brand list, each an
	// AddRimCategory(brand, icon, name). The installed rim's brand is the
	// last button when none is held.
	u32 rimHaveBrand = 0;
	if (g_bodyShop.rimBrandMode) {
		static const u32 kCar[16][3] = {
			{ 0x352D08D1u, 0xF75128B1u, 0x0CF90EF1u }, { 0x0013053Eu, 0x20EDAD1Eu, 0xD2E7035Eu },
			{ 0x00009536u, 0xF224AB29u, 0x6B3D4F56u }, { 0x02B77FEBu, 0x0E38DE9Eu, 0x300B420Bu },
			{ 0xA26AD820u, 0xBE399DF3u, 0x9D50E640u }, { 0x0324AC97u, 0x0EA60B4Au, 0x30786EB7u },
			{ 0x695FCE00u, 0xE50D0313u, 0x412BD420u }, { 0x48E25793u, 0x9A00EB73u, 0xA08A29B3u },
			{ 0x00197AF7u, 0x36C04F4Au, 0xD2ED7917u }, { 0x00000648u, 0x6C2FA9DBu, 0xFB7DFC68u },
			{ 0x0019E1DBu, 0x3F85C14Du, 0xD2EDDFFBu }, { 0xDD544A02u, 0x27EBD095u, 0x29F66022u },
			{ 0x001C39B5u, 0x20F6E195u, 0xD2F037D5u }, { 0x001E6A3Bu, 0x20F9121Bu, 0xD2F2685Bu },
			{ 0x001EF762u, 0x20F99F42u, 0xD2F2F582u }, { RIM_BRAND_STOCK, 0x0F3990B6u, 0x310BF423u } };
		static const u32 kSuv[10][3] = {
			{ 0x00148BBAu, 0x20EF339Au, 0xD2E889DAu }, { 0x0015A5C4u, 0x20F04DA4u, 0xD2E9A3E4u },
			{ 0xA26AD820u, 0xBE399DF3u, 0x9D50E640u }, { 0xC3A1AC32u, 0x9F4D4412u, 0xBE87BA52u },
			{ 0x66BA72E5u, 0x28DE92C5u, 0x3E867905u }, { 0x00000648u, 0x6C2FA9DBu, 0xFB7DFC68u },
			{ 0x0019E1DBu, 0x3F85C14Du, 0xD2EDDFFBu }, { 0x029E75D1u, 0x8B71EBF0u, 0x6322F230u },
			{ 0xBF3608C0u, 0xF6CA43BEu, 0xC49C11FEu }, { RIM_BRAND_STOCK, 0x0F3990B6u, 0x310BF423u } };
		const bool suv = careerCurrentCarIsSUV();
		const int nb = suv ? 10 : 16;
		for (int k = 0; k < nb; k++) {
			const u32* e = suv ? kSuv[k] : kCar[k];
			bodyShopAddCategory(0x1D, e[1], e[2], "Rims", BODYSHOP_KIND_RIMS);
			BodyShopCat* rc = &g_bodyShop.cat[g_bodyShop.ncat - 1];
			rc->value = e[0];
			rc->count = haveDb ? rimPartsCount(&db, pdb, &ctx, cs, car, e[0], rimOuter) : 0;
			rc->locked = e[0] != RIM_BRAND_STOCK && rc->count == 0;
		}
		const u32 have = haveDb ? uniquesGetPart(gProfile.careerParts[cs], 0x1D) : 0;
		const CarPart hp = have ? carpartdb_get(&db, car, 0x1D, have, NULL, CARPARTDB_ANY_LEVEL) : NULL;
		rimHaveBrand = hp ? carpartdb_attr(&db, hp, UNIQUES_ATTR_RIM_BRAND, 0) : 0;
		snprintf(b, sizeof(b), "rims: ChooseRimBrand::Setup -- %s list, OUTER_RADIUS %d, installed "
			"brand 0x%08X, last button 0x%08X", suv ? "SUV" : "car", (int)rimOuter,
			(unsigned)rimHaveBrand, (unsigned)g_rimBrandLast);
		dlog(b);
	}
	for (int i = 0; i < g_bodyShop.ncat; i++) {
		BodyShopCat* c = &g_bodyShop.cat[i];
		if (g_bodyShop.rimBrandMode) {
			// AddRimCategory's, above.
		} else if (g_bodyShop.spinnerMode || g_bodyShop.rimsMode) {
			c->locked = c->count == 0;
		} else if (c->kind == BODYSHOP_KIND_VINYL || c->kind == BODYSHOP_KIND_DECAL) {
			// vinylBrowserBuild()'s, decalBrowserBuild()'s
		} else if (g_bodyShop.iceMode) {
			if (haveDb && c->kind == BODYSHOP_KIND_PARTS)
				bodyShopPartsList(&db, pdb, &ctx, lang, cs, car, c->slot, false, c);
			c->locked = !haveDb || (c->slot == 0x9E ? iceNeonLocked(&ik) : iceCategoryLocked(&ik, c->slot));
		} else if (!haveDb) {
			c->locked = true;
		} else if (g_bodyShop.carbonMode && c->kind == BODYSHOP_KIND_CONV) {
			// The converter's parts (IsPartAvailable), first and last kept:
			// the Yes toggles between the plain part and the other.
			int idx = 0, n = 0;
			for (CarPart p = carpartdb_get(&db, car, c->slot, 0, NULL, CARPARTDB_ANY_LEVEL); p;
					p = carpartdb_get(&db, car, c->slot, 0, p, CARPARTDB_ANY_LEVEL), idx++) {
				const int level = carpartdb_level(p);
				const int entity = stargazer_unlockable(&db, c->slot, p);
				if (!bodyShopAvailable(pdb, &ctx, cs, c->slot, entity, idx, level, carpartdb_hash(p)))
					continue;
				const int k = n == 0 ? 0 : 1;
				n++;
				c->hash[k] = carpartdb_hash(p);
				c->level[k] = (u8)level;
				c->entity[k] = (u8)entity;
				c->index[k] = (s16)idx;
				c->price[k] = bodyShopPartCost(pdb, entity, level);
				snprintf(c->name[k], sizeof(c->name[k]), "%s", carpartdb_name(&db, p) ? carpartdb_name(&db, p) : "");
			}
			c->count = n > 2 ? 2 : n;
			c->locked = !carbonConverterAvailable(pdb, &ctx, c->slot);
		} else if (g_bodyShop.carbonMode) {
			// CarbinCategoryIsLocked: the carbon list holds no part.
			bodyShopPartsList(&db, pdb, &ctx, lang, cs, car, c->slot, true, c);
			c->locked = c->count == 0;
		} else if (c->kind == BODYSHOP_KIND_PARTS) {
			bodyShopPartsList(&db, pdb, &ctx, lang, cs, car, c->slot, false, c);
			c->locked = c->count <= 1;
		} else if (c->kind == BODYSHOP_KIND_RIMS) {
			// PartsCategoryRimsIsLocked (0x8015EA90; SPEED2.EXE 0x539C20, #517):
			// under CAREER alone (the crib's Change Parts) the lock is
			// AreAnyRimsOwnedInCareerMode -- any word of the current career
			// car's rim inventory (+0x16C, 0x100 bytes) set. Both builds lock
			// the row when a rim is owned and open it when none is: retail's
			// own sense, kept. Else two available FRONT_WHEEL parts open it.
			c->count = bodyShopPartsList(&db, pdb, &ctx, NULL, cs, car, 0x1D, false, NULL) +
				bodyShopPartsList(&db, pdb, &ctx, NULL, cs, car, 0x1D, true, NULL);
			if (ctx.filter == PERF_FILTER_CAREER) {
				bool owned = false;
				if (cs >= 0 && cs < PROFILE_CAREER_ARRAYS)
					for (int o = 0x16C; o < 0x16C + 0x100 && !owned; o++)
						owned = gProfile.careerVisualInv[cs][o] != 0;
				c->locked = owned;
				char rb[128];
				snprintf(rb, sizeof(rb), "body shop: rims under CAREER -- AreAnyRimsOwnedInCareerMode %d, "
					"the row %s", owned ? 1 : 0, owned ? "locked" : "open");
				dlog(rb);
			} else {
				c->locked = c->count < 2;
			}
		} else {
			// PartsCategoryCarbonIsLocked (0x8015EC10): open while any of the
			// four carbon lists holds a part (CarbinCategoryIsLocked) or the
			// 0x60 converter is available, else while the 0x5D one is
			// (IsCarbonPartConverterAvailable, entities 0x56 / 0x55, level 3).
			static const int kCarbon[4] = { 0x09, 0x0C, 0x20, 0x07 };
			for (int k = 0; k < 4; k++)
				c->count += bodyShopPartsList(&db, pdb, &ctx, NULL, cs, car, kCarbon[k], true, NULL);
			const bool conv60 = pdb && (ctx.filter & PERF_FILTER_ONLINE) &&
				perfdb_entity_unlocked(pdb, &ctx, 0x56, 3);
			const bool conv5d = pdb && (ctx.filter & PERF_FILTER_ONLINE) &&
				perfdb_entity_unlocked(pdb, &ctx, 0x55, 3);
			c->locked = !(c->count > 0 || conv60) && !conv5d;
		}
	}
	// CustomHUD_Browser's rows: each part's HUDINDEX (RefreshHeader's
	// g_displayHUDattributes); HUD_Customizer's three colour lists
	// (BuildColorLists: slot 0xA4, then 0xA6 twice).
	if (g_bodyShop.iceMode && !g_bodyShop.neonMode && !g_bodyShop.spinnerMode && haveDb &&
			g_iceMode == ICE_MODE_MAIN) {
		memset(g_hudPick.rowStyle, 0, sizeof(g_hudPick.rowStyle));
		for (int i = 0; i < g_bodyShop.ncat; i++) {
			const BodyShopCat* c = &g_bodyShop.cat[i];
			for (int k = 0; c->slot == 0xA3 && k < c->count; k++) {
				const CarPart p = carpartdb_get(&db, car, 0xA3, c->hash[k], NULL, CARPARTDB_ANY_LEVEL);
				g_hudPick.rowStyle[k] = p ? carpartdb_attr(&db, p, HUD_ATTR_INDEX, 0) : 0;
			}
		}
		for (int li = 0; li < 3; li++) {
			const int slot = li == 0 ? 0xA4 : 0xA6;
			int n = 0;
			for (CarPart p = carpartdb_get(&db, car, slot, 0, NULL, CARPARTDB_ANY_LEVEL);
					p && n < HUDPICK_MAX; p = carpartdb_get(&db, car, slot, 0, p, CARPARTDB_ANY_LEVEL)) {
				if (pdb && !perfdb_entity_unlocked(pdb, &ctx, 0x17, carpartdb_level(p)))
					continue;
				g_hudPick.colHash[li][n] = carpartdb_hash(p);
				g_hudPick.colRgb[li][n] = hudColourRgb(&db, p);
				n++;
			}
			g_hudPick.nCol[li] = n;
			static const u32 kTitle[3] = { 0x3A9CCF4Eu, 0xDED7CA79u, 0x6A0B254Cu };
			const char* raw = lang ? langbin_lookup(lang, kTitle[li]) : NULL;
			if (raw)
				langTextToUtf8(raw, g_hudPick.title[li], sizeof(g_hudPick.title[li]));
			else
				snprintf(g_hudPick.title[li], sizeof(g_hudPick.title[li]), "%s",
					li == 0 ? "Paint Fill" : li == 1 ? "Paint Lines" : "Paint Needle");
		}
		snprintf(b, sizeof(b), "custom gauges: BuildColorLists -- 0xA4 %d, 0xA6 %d colour(s) available",
			g_hudPick.nCol[0], g_hudPick.nCol[1]);
		dlog(b);
	}
	// The conflict checks' view of the car.
	g_bodyShop.carbonHoodLevel = 0;
	g_bodyShop.kitHash = 0;
	g_bodyShop.kitLevel = 0;
	for (int k = 0; k < 4; k++) {
		g_bodyShop.vinylHash[k] = 0;
		g_bodyShop.vinylKit[k] = 0;
	}
	if (haveDb) {
		const unsigned int* parts = gProfile.careerParts[cs];
		const u32 cf = uniquesGetPart(parts, 0x5D);
		const CarPart cp = cf ? carpartdb_get(&db, car, 0x5D, cf, NULL, CARPARTDB_ANY_LEVEL) : NULL;
		g_bodyShop.carbonHoodLevel = cp ? carpartdb_level(cp) : 0;
		const u32 kh = uniquesGetPart(parts, 0x06);
		const CarPart kp = kh ? carpartdb_get(&db, car, 0x06, kh, NULL, CARPARTDB_ANY_LEVEL) : NULL;
		g_bodyShop.kitHash = kh;
		g_bodyShop.kitLevel = kp ? carpartdb_level(kp) : 0;
		for (int k = 0; k < 4; k++) {
			const u32 v = uniquesGetPart(parts, 0x40 + k);
			const CarPart vp = v ? carpartdb_get(&db, car, 0x40 + k, v, NULL, CARPARTDB_ANY_LEVEL) : NULL;
			g_bodyShop.vinylHash[k] = vp ? v : 0;
			g_bodyShop.vinylKit[k] = vp ? (u8)carpartdb_kit(vp) : 0;
		}
		carpartdb_free(&db);
		g_bodyShop.built = true;
	}

	int n = 0;
	for (int i = 0; i < g_bodyShop.ncat && n < MENU_MAX_ITEMS; i++) {
		const BodyShopCat* c = &g_bodyShop.cat[i];
		MenuItem* it = &out->dynItems[n];
		memset(it, 0, sizeof(*it));
		it->iconHash = c->icon;
		it->labelHash = c->label;
		it->fallbackLabel = c->fallback;
		it->modeValue = -1;
		out->itemLocked[n] = c->locked;
		n++;
	}
	out->itemCount = n;
	out->useDynItems = true;
	// FEngGetLastButton, a slot id: 1 the first time in.
	if (g_bodyShop.lastSlot <= 0)
		g_bodyShop.lastSlot = 1;
	out->selected = 0;
	for (int i = 0; i < g_bodyShop.ncat && plainShop && !rimScreens && !g_bodyShop.carbonMode; i++)
		if (g_bodyShop.cat[i].slot == g_bodyShop.lastSlot)
			out->selected = i;
	// IceSelectionScreen::Setup's SetInitialPos(FEngGetLastButton): back
	// from the neon screen on the Neon row.
	const bool iceMain = g_bodyShop.iceMode && !g_bodyShop.neonMode && !g_bodyShop.spinnerMode;
	for (int i = 0; i < g_bodyShop.ncat && iceMain; i++)
		if (g_iceLastSlot && g_bodyShop.cat[i].slot == g_iceLastSlot)
			out->selected = i;
	if (iceMain)
		g_iceLastSlot = 0;
	// ChooseSpinnerBrand::Setup: FEngSetLastButton on the installed spinner's
	// design, SetInitialPos on it.
	// SetupCarbonParts' SnapToItem: the slot it was given (9 on the way in,
	// a converter's own after its Yes).
	for (int i = 0; i < g_bodyShop.ncat && g_bodyShop.carbonMode; i++)
		if (g_bodyShop.cat[i].slot == g_carbonSnap)
			out->selected = i;
	// ChooseRimBrand: SetInitialPos on the last button's brand.
	if (g_bodyShop.rimBrandMode) {
		const u32 want = g_rimBrandLast ? g_rimBrandLast : rimHaveBrand;
		for (int i = 0; want && i < g_bodyShop.ncat; i++)
			if (g_bodyShop.cat[i].value == want)
				out->selected = i;
	}
	// RimsBrowser::Setup: the installed rim's design the same way.
	if ((g_bodyShop.spinnerMode || g_bodyShop.rimsMode) && cs >= 0 && cs < PROFILE_CAREER_ARRAYS) {
		const u32 have = uniquesGetPart(gProfile.careerParts[cs], 0x1D);
		for (int i = 0; have && i < g_bodyShop.ncat; i++)
			for (int k = 0; k < g_bodyShop.cat[i].count; k++)
				if (g_bodyShop.cat[i].hash[k] == have)
					out->selected = i;
	}
	// Mode 2's Setup ends in StartBrowsingParts on its one row.
	if (g_bodyShop.iceMode && g_iceMode == ICE_MODE_TRUNK_LAYOUT && g_bodyShop.ncat > 0 &&
			!g_bodyShop.cat[0].locked)
		bodyShopStartBrowsing(out);
	// The decal hub: SetInitialPos on the level's last option.
	if (g_bodyShop.decalMode) {
		const int li = g_decal.lastIdx[(g_decal.level >> 16) & 3];
		out->selected = li < g_bodyShop.ncat ? li : 0;
	}
	// The vinyls open on the layer's vinyl's group.
	if (g_bodyShop.vinylMode) {
		const PaintSetupEntry* e = NULL;
		if (vinylEffective(g_vinylSlot, &e) && e)
			for (int i = 0; i < g_bodyShop.ncat; i++)
				if (g_bodyShop.cat[i].group == e->kit)
					out->selected = i;
	}
	int o = snprintf(b, sizeof(b), "body shop: %s -- car slot %d (0x%08X), filter %u:",
		g_bodyShop.vinylMode ? "SetupVinyls" : g_bodyShop.decalMode ? "ChooseDecalCategory"
		: g_bodyShop.rimBrandMode ? "ChooseRimBrand" : g_bodyShop.rimsMode ? "RimsBrowser"
		: g_bodyShop.carbonMode ? "SetupCarbonParts"
		: g_bodyShop.spinnerMode ? "ChooseSpinnerBrand" : g_bodyShop.iceMode ? "IceSelectionScreen"
		: "SetupBodyShop", cs, (unsigned)car, (unsigned)ctx.filter);
	for (int i = 0; i < g_bodyShop.ncat && o < (int)sizeof(b); i++)
		o += snprintf(b + o, sizeof(b) - o, " %X=%d%s", g_bodyShop.vinylMode ? g_bodyShop.cat[i].group
			: g_bodyShop.cat[i].slot, g_bodyShop.cat[i].count, g_bodyShop.cat[i].locked ? "L" : "");
	dlog(b);
	for (int i = 0; i < g_bodyShop.ncat; i++) {
		const BodyShopCat* c = &g_bodyShop.cat[i];
		if (c->kind != BODYSHOP_KIND_PARTS || c->count == 0)
			continue;
		o = snprintf(b, sizeof(b), "body shop: slot 0x%X --", c->slot);
		for (int k = 0; k < c->count && o < (int)sizeof(b); k++)
			o += snprintf(b + o, sizeof(b) - o, " %s(L%d $%d)", c->name[k], c->level[k], c->price[k]);
		dlog(b);
	}
}

// PreviewPart (0x8016E360) of a body shop row on `parts`: a hood over level 0
// takes the hood decals off when any are on, then the part goes in (a front
// rim on the rear too).
static void bodyShopPreviewParts(unsigned int* parts, int slot, u32 hash, int level) {
	if (slot == 0x09 && level != 0) {
		bool decals = false;
		for (int k = 0x61; k < 0x69; k++)
			decals = decals || uniquesGetPart(parts, k) != 0;
		for (int k = 0x61; decals && k < 0x69; k++)
			uniquesSetPart(parts, k, 0);
	}
	uniquesSetPart(parts, slot, hash);
	if (slot == 0x1D)
		uniquesSetPart(parts, 0x1E, hash);
}

// Each frame from syncCarModel() on the body shop: while browsing the car
// wears the selected row (PreviewPart, on StartBrowsingParts and every
// ScrollVertical); otherwise its own parts (StopBrowsingParts'
// ResyncPreview). The same settle as the uniques screen's.
static void bodyShopPreviewSync(const MenuState* m) {
	const BodyShopCat* c = bodyShopCurrent(m);
	const int cs = gProfile.currentCarSlot;
	if ((g_bodyShop.vinylMode || g_bodyShop.decalMode) && !(c && g_bodyShop.browsing)) {
		paintPreviewSync(m);   // the setup alone (ResetPreviewToPaintSetup)
		return;
	}
	// ChooseSpinnerBrand previews off its rows as well (Setup and the
	// horizontal scroll, 0xB5971BF1 / 0x9120409E): the installed spinner on
	// its own design's row, else the design's first part.
	int r = g_bodyShop.sel;
	if ((g_bodyShop.spinnerMode || g_bodyShop.rimsMode) && !g_bodyShop.browsing && c) {
		const u32 have = cs >= 0 && cs < PROFILE_CAREER_ARRAYS
			? uniquesGetPart(gProfile.careerParts[cs], 0x1D) : 0;
		r = 0;
		for (int k = 0; have && k < c->count; k++)
			if (c->hash[k] == have)
				r = k;
	}
	const bool want = c && (g_bodyShop.browsing || g_bodyShop.spinnerMode || g_bodyShop.rimsMode) && r >= 0 &&
		r < c->count && cs >= 0 && cs < PROFILE_CAREER_ARRAYS;
	static int s_seen = -1;
	static u64 s_at = 0;
	if (!want) {
		s_seen = -1;
		if (g_carPreview.on) {
			g_carPreview.on = false;
			g_profileCarChanged = true;
		}
		return;
	}
	const int row = (m->selected * BODYSHOP_MAX_PARTS + r) * 4 + (g_vinylSlot - 0x40) +
		(g_bodyShop.vinylMode ? 0x100000 : 0) + (g_bodyShop.decalMode ? 0x200000 : 0) +
		(g_bodyShop.iceMode ? 0x400000 : 0) + (g_bodyShop.rimsMode ? 0x800000 : 0);
	if (g_carPreview.on && g_carPreview.row == row)
		return;
	if (row != s_seen) {
		s_seen = row;
		s_at = osGetTime();
		if (g_carPreview.on)
			return;
	} else if (osGetTime() - s_at < UNIQUES_PREVIEW_SETTLE_MS) {
		return;
	}
	if (c->kind == BODYSHOP_KIND_VINYL) {
		// PreviewVinyl over ResetPreviewToPaintSetup.
		paintSetupPreviewParts(g_carPreview.parts, cs);
		vinylPreviewParts(g_carPreview.parts, g_vinylSlot, c->hash[r]);
	} else if (c->kind == BODYSHOP_KIND_DECAL) {
		// PreviewPaintPart (0x8016E460) over ResetPreviewToPaintSetup: the
		// row's decal in the slot, "none" taking it off.
		paintSetupPreviewParts(g_carPreview.parts, cs);
		uniquesSetPart(g_carPreview.parts, c->slot, c->hash[r]);
	} else {
		memcpy(g_carPreview.parts, gProfile.careerParts[cs], sizeof(g_carPreview.parts));
		bodyShopPreviewParts(g_carPreview.parts, c->slot, c->hash[r], c->level[r]);
	}
	g_carPreview.on = true;
	g_carPreview.slot = cs;
	g_carPreview.row = row;
	g_profileCarChanged = true;
	char b[160];
	snprintf(b, sizeof(b), "body shop: PreviewPart -- %s (0x%08X) in slot 0x%X", c->name[r],
		(unsigned)c->hash[r], (unsigned)c->slot);
	dlog(b);
}

// ChoosePerformancePackages::Setup's options: Customize, a PPPackage per
// level below GetEndPerfPackageEnum -- except for a career's crib, which
// skips them -- and Return To Stock. Each package row's label and icon are
// bStringHash("PERFORMANCE_PACKAGE_%d") and ("PERFORMANCE_ICON_PACKAGE_%d"),
// Street / Pro / Extreme Package, and it is locked (+0x24) unless
// IsPerfPackageAvailable passes for its level.
static void perfPackageItems(MenuState* out, const Config* cfg) {
	static const MenuItem kCustomize = { PERFPKG_ICON_CUSTOMIZE, PERFPKG_LABEL_CUSTOMIZE,
		"Customize", NULL, PERFPKG_MODE_CUSTOMIZE };
	static const MenuItem kStock = { PERFPKG_ICON_STOCK, PERFPKG_LABEL_STOCK,
		"Return To Stock", NULL, PERFPKG_MODE_STOCK };
	static const char* const kLevelName[4] = { "", "Street Package", "Pro Package",
		"Extreme Package" };
	int n = 0;
	out->dynItems[n++] = kCustomize;
	const bool packages = !(careerInProgress() && g_customizeEntry == CUSTOMIZE_ENTRY_CRIB);
	int locked = 0;
	if (packages) {
		const PerfDb* pdb = cfg ? perfDb(cfg) : NULL;
		PerfUnlockCtx ctx;
		perfBuildCtx(&ctx);
		const int end = perfdb_end_package_level(ctx.currentShopHandle);
		char key[40];
		for (int lv = 1; lv < end && n < MENU_MAX_ITEMS - 1; lv++) {
			MenuItem* it = &out->dynItems[n];
			memset(it, 0, sizeof(*it));
			snprintf(key, sizeof(key), "PERFORMANCE_PACKAGE_%d", lv);
			it->labelHash = race_string_hash(key);
			snprintf(key, sizeof(key), "PERFORMANCE_ICON_PACKAGE_%d", lv);
			it->iconHash = race_string_hash(key);
			it->fallbackLabel = kLevelName[lv & 3];
			it->modeValue = PERFPKG_MODE_PACKAGE;
			out->itemLocked[n] = !(pdb &&
				perfdb_package_available(pdb, &ctx, g_perfPackageType, lv));
			locked += out->itemLocked[n];
			n++;
		}
	}
	out->dynItems[n++] = kStock;
	out->itemCount = n;
	out->useDynItems = true;
	out->selected = 0;
	out->isPerfPackage = true;
	// The car and its preview ride are read afresh each visit.
	g_perfRide.tried = false;
	char b[160];
	if (packages)
		snprintf(b, sizeof(b), "perf package: type %d -- Customize, %d package(s) (%d locked), "
			"Return To Stock (shop 0x%08X)", g_perfPackageType, n - 2, locked,
			customizeInShop() ? (unsigned)g_shopIn.handle : 0u);
	else
		snprintf(b, sizeof(b), "perf package: type %d -- Customize and Return To Stock (crib)",
			g_perfPackageType);
	dlog(b);
}

// The package panel's words, resolved while the language table is open: every
// level's part names (RefreshHeader can land on any of them), the three words
// PartInfoWidget::Draw (0x801721BC) prints, and RefreshHeader's discount and
// "n/a". The discount strings are printf formats ("10%% Discount:"), which
// FEPrintf collapses to one '%'.
typedef struct {
	char partName[PERFDB_LEVEL_MAX + 1][PERFDB_MAX_PARTS][48];
	char word[PP_STR_COUNT][32];
	char discount[2][32];
	char na[16];
} PerfPkgText;
static PerfPkgText g_perfPkgText;

static void perfPackageResolve(MenuState* m, const Config* cfg, const LangTable* lang) {
	PerfPkgText* t = &g_perfPkgText;
	memset(t, 0, sizeof(*t));
	m->pkPanel = m->pkDiscount = m->pkSavings = m->pkCost = m->pkCostLabel = -1;
	u32 hn[PERFDB_MAX_PARTS], hp[PERFDB_MAX_PARTS], hi[PERFDB_MAX_PARTS];
	char key[32];
	for (int k = 0; k < PERFDB_MAX_PARTS; k++) {
		m->pkName[k] = m->pkPrice[k] = m->pkIcon[k] = -1;
		m->pkPurchased[k] = false;
		snprintf(key, sizeof(key), "PARTNAME_%d", k + 1);
		hn[k] = race_string_hash(key);
		snprintf(key, sizeof(key), "PARTPRICE_%d", k + 1);
		hp[k] = race_string_hash(key);
		snprintf(key, sizeof(key), "PURCHASED_ICON_%d", k + 1);
		hi[k] = race_string_hash(key);
	}
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		if (!w->hasObjHash)
			continue;
		const u32 h = w->objHash;
		if (h == PERFPKG_PANEL_HASH && m->pkPanel < 0)
			m->pkPanel = i;
		else if (h == PERFPKG_DISCOUNT_HASH)
			m->pkDiscount = i;
		else if (h == PERFPKG_SAVINGS_HASH)
			m->pkSavings = i;
		else if (h == PERFPKG_COST_HASH)
			m->pkCost = i;
		else if (h == PERFPKG_COST_LABEL_HASH)
			m->pkCostLabel = i;
		for (int k = 0; k < PERFDB_MAX_PARTS; k++) {
			if (h == hn[k] && w->type == FNG_TYPE_STRING)
				m->pkName[k] = i;
			else if (h == hp[k] && w->type == FNG_TYPE_STRING)
				m->pkPrice[k] = i;
			else if (h == hi[k])
				m->pkIcon[k] = i;
		}
	}
	const PerfDb* pdb = cfg ? perfDb(cfg) : NULL;
	for (int lv = PERFDB_LEVEL_MIN; pdb && lv <= PERFDB_LEVEL_MAX; lv++) {
		const PerformancePackage* pk = perfdb_package(pdb, g_perfPackageType, lv);
		for (int k = 0; pk && k < (int)pk->numParts && k < PERFDB_MAX_PARTS; k++) {
			const char* raw = lang ? langbin_lookup(lang, pk->part[k].nameHash) : NULL;
			langTextToUtf8(raw ? raw : "", t->partName[lv][k], sizeof(t->partName[lv][k]));
		}
	}
	for (int k = 0; k < PP_STR_COUNT; k++) {
		const char* raw = lang ? langbin_lookup(lang, PERFPARTS_STR_ID[k]) : NULL;
		langTextToUtf8(raw ? raw : "", t->word[k], sizeof(t->word[k]));
	}
	static const u32 kDiscount[2] = { PERFDB_STR_DISCOUNT_10, PERFDB_STR_DISCOUNT_20 };
	for (int k = 0; k < 2; k++) {
		const char* raw = lang ? langbin_lookup(lang, kDiscount[k]) : NULL;
		char u[32];
		langTextToUtf8(raw ? raw : "", u, sizeof(u));
		size_t o = 0;
		for (const char* p = u; *p && o + 1 < sizeof(t->discount[k]); p++) {
			if (p[0] == '%' && p[1] == '%')
				p++;
			t->discount[k][o++] = *p;
		}
		t->discount[k][o] = '\0';
	}
	const char* raw = lang ? langbin_lookup(lang, PERFDB_STR_NA) : NULL;
	langTextToUtf8(raw ? raw : "", t->na, sizeof(t->na));
	int bound = 0;
	for (int k = 0; k < PERFDB_MAX_PARTS; k++)
		bound += (m->pkName[k] >= 0) + (m->pkPrice[k] >= 0) + (m->pkIcon[k] >= 0);
	char b[160];
	snprintf(b, sizeof(b), "perf package: panel %d, %d/%d part cell(s), discount %d savings %d "
		"cost %d/%d", m->pkPanel, bound, 3 * PERFDB_MAX_PARTS, m->pkDiscount, m->pkSavings,
		m->pkCost, m->pkCostLabel);
	dlog(b);
}

// RefreshHeader (0x80172854) for the current option. A locked row and every
// row that is not a package put the panel down (its HIDE, or the root's
// PackageFadeOut); a package row puts it up (PackageFadeIn, FEngSetVisible)
// and BuildPackagePartsList fills it -- every PURCHASED_ICON hidden, a
// PartInfoWidget per part, the cells past the last part invisible. In a
// career shop GetPerfPackageCost's numbers follow: the discount label (20% in
// CC_MEGALOW), the saving and the total, each "n/a" below 1; anywhere else
// those four cells go.
static void perfPackageRefresh(MenuState* m, const Config* cfg) {
	perfStatsRefresh(m, cfg);
	if (!m->isPerfPackage || m->pkPanel < 0)
		return;
	const PerfPkgText* t = &g_perfPkgText;
	const int sel = m->selected;
	const int level = perfPackageLevelAt(m, sel);
	const bool locked = sel >= 0 && sel < MENU_MAX_ITEMS && m->itemLocked[sel];
	for (int k = 0; k < PERFDB_MAX_PARTS; k++)
		m->pkPurchased[k] = false;
	if (level <= 0 || locked) {
		menuHideSubtree(m, m->pkPanel, true);
		return;
	}
	const PerfDb* pdb = cfg ? perfDb(cfg) : NULL;
	const PerformancePackage* pk = pdb ? perfdb_package(pdb, g_perfPackageType, level) : NULL;
	if (!pk) {
		menuHideSubtree(m, m->pkPanel, true);
		return;
	}
	if (!m->prBuf) {
		m->prBuf = C2D_TextBufNew(1024);
		if (!m->prBuf)
			return;
	}
	C2D_TextBufClear(m->prBuf);
	menuHideSubtree(m, m->pkPanel, false);
	PerfUnlockCtx ctx;
	perfBuildCtx(&ctx);
	const bool career = careerInProgress();
	char price[PERFDB_MAX_PARTS][24];
	for (int k = 0; k < PERFDB_MAX_PARTS; k++) {
		menuHideSubtree(m, m->pkIcon[k], true);
		const bool have = k < (int)pk->numParts;
		if (m->pkName[k] >= 0)
			m->layoutHidden[m->pkName[k]] = !have;
		if (m->pkPrice[k] >= 0)
			m->layoutHidden[m->pkPrice[k]] = !have;
		if (!have)
			continue;
		const PerfPackagePart* part = &pk->part[k];
		const int id = (int)part->partId;
		const char* data;
		if (perfdb_part_installed(&ctx, id)) {
			data = t->word[PP_STR_INSTALLED];
			m->pkPurchased[k] = true;
		} else if (!career) {
			data = t->word[PP_STR_NOT_INSTALLED];
		} else if (!perfdb_owns_part(&ctx, id)) {
			formatCashGrouped(part->price, price[k], sizeof(price[k]));
			data = price[k];
		} else {
			data = t->word[PP_STR_OWNED];
			m->pkPurchased[k] = true;
		}
		menuSetWidgetText(m, m->prBuf, m->pkName[k], t->partName[level][k]);
		menuSetWidgetText(m, m->prBuf, m->pkPrice[k], data);
	}
	char b[200];
	if (!(career && g_customizeEntry != CUSTOMIZE_ENTRY_CRIB)) {
		const int cells[4] = { m->pkDiscount, m->pkSavings, m->pkCost, m->pkCostLabel };
		for (int c = 0; c < 4; c++)
			if (cells[c] >= 0)
				m->layoutHidden[cells[c]] = true;
		snprintf(b, sizeof(b), "perf package: RefreshHeader -- level %d, %u part(s), no prices",
			level, (unsigned)pk->numParts);
		dlog(b);
		return;
	}
	PerfPackageCost cost;
	perfdb_package_cost(pdb, &ctx, g_perfPackageType, level, &cost);
	const bool mega = ctx.currentShopHandle == PERFDB_CC_MEGALOW_HASH;
	char save[24], total[24];
	if (cost.savings < 1)
		snprintf(save, sizeof(save), "%s", t->na);
	else
		formatCashGrouped((unsigned)cost.savings, save, sizeof(save));
	if (cost.cost < 1)
		snprintf(total, sizeof(total), "%s", t->na);
	else
		formatCashGrouped((unsigned)cost.cost, total, sizeof(total));
	menuSetWidgetText(m, m->prBuf, m->pkDiscount, t->discount[mega ? 1 : 0]);
	menuSetWidgetText(m, m->prBuf, m->pkSavings, save);
	menuSetWidgetText(m, m->prBuf, m->pkCost, total);
	snprintf(b, sizeof(b), "perf package: RefreshHeader -- level %d, %u part(s), %d not owned, "
		"full %d cost %d saving %d (%s), cash %d", level, (unsigned)pk->numParts,
		cost.numNotOwned, cost.full, cost.cost, cost.savings, t->discount[mega ? 1 : 0],
		gProfile.cash);
	dlog(b);
	// #429: each part's state as the cells were chosen -- the car slot, the
	// installed byte and the owned bit -- so a price on a part the player
	// thinks is fitted can be read off a tester's log.
	int o = snprintf(b, sizeof(b), "perf package: slot %d type %d level %d parts",
		gProfile.currentCarSlot, g_perfPackageType, level);
	for (u32 k = 0; k < pk->numParts && k < PERFDB_MAX_PARTS && o > 0 && o < (int)sizeof(b); k++) {
		const int id = (int)pk->part[k].partId;
		o += snprintf(b + o, sizeof(b) - (size_t)o, " 0x%02X inst %d owned %d", id,
			perfdb_part_installed(&ctx, id) ? 1 : 0, perfdb_owns_part(&ctx, id) ? 1 : 0);
	}
	dlog(b);
}

// PartInfoWidget::Draw's "Purchased" on a price cell. False for any other
// widget.
static bool perfPackageTextColor(const MenuState* m, int wi, u32* rgba) {
	if (!m->isPerfPackage || wi < 0)
		return false;
	for (int k = 0; k < PERFDB_MAX_PARTS; k++) {
		if (wi == m->pkPrice[k] && m->pkPurchased[k]) {
			*rgba = menuWidgetColor(m, wi, 207, 128, 48, 255);
			return true;
		}
	}
	return false;
}

// CarCustomizeManager's chosen brands (+0x40, one per package part): what
// ChooseBrandsScreen::SetChosenBrands (0x801745E4) writes and the buys hand to
// OwnedPartInventory. The manager is in .bss, so they are 0 until the first
// buy, and every buy leaves the ones it read at -1 -- which the next package
// with no brands at all then records as the brand of each part it buys.
static u32 g_perfChosenBrand[PERFDB_MAX_PARTS];
// What a buy question is about: the package the package screen's Buy takes
// (DAT_803D96D8, GetCurrentPerfPackage) or the part the list's takes
// (DAT_803D96D4, GetCurrentPart). Each dialog posts to the screen that raised
// it; the port has one dispatch for both (perfPackageMessage()), so `package`
// says which one that was.
static struct {
	bool package;
	int level;
	int partId;
} g_perfBuy;

// UI_PerformanceBrandSelect.fng, ChooseBrandsScreen (Speed.elf 0x80174280),
// a UIWidgetMenu of BrandScrollerThing rows (FEToggleImageWidget). Setup
// (0x80174438) adds, for the package Buy took (the list is down), a row per
// part among its first four that has any brand, enabled only with a choice of
// two or more, and hides the UP/DOWN hint below two rows; for the list's part
// one row, always enabled, and that hint down. SetInitialOption(0) focuses the
// first enabled row.
#define PERFBRAND_SCREEN "UI_PerformanceBrandSelect.fng"
// The LEFT/RIGHT hint, which UP and DOWN (0x801742CC) show for a row with a
// choice and hide for one without; and the UP/DOWN hint.
#define PERFBRAND_HINT_BRAND_HASH  0xB34A6C2Bu
#define PERFBRAND_HINT_SELECT_HASH 0x6D017BC5u
// Draw's texture when GetTextureInfo has no DECAL_ICON for the brand.
#define PERFBRAND_NO_ICON_TEX      0x74CE8C0Bu
// The backing group's placement off the row: Position's (+0x18, +0x1C), set
// from DAT_8032C6D8 / DC in Setup.
#define PERFBRAND_BACKING_DX 232.0f
#define PERFBRAND_BACKING_DY 64.0f
// BlinkArrows' Blink, and the name's Highlight loop (the rows' Kd scripts).
#define PERFBRAND_BLINK_MS 400.0f
#define PERFBRAND_NAME_LOOP_MS 1200.0f

typedef struct {
	int rows;
	int partId[PERFBRAND_ROWS];
	int numBrands[PERFBRAND_ROWS];
	u32 brand[PERFBRAND_ROWS][PERFDB_MAX_PART_BRANDS];
	int index[PERFBRAND_ROWS];      // BrandScrollerThing +0x60
	bool enabled[PERFBRAND_ROWS];   // FEToggleWidget +0x24
	bool visited[PERFBRAND_ROWS];   // UnHighlight has played
	int sel;
	u64 focusMs;                    // SetFocus's Highlight started
	int blinkSide;                  // the arrow BlinkArrows started, -1 none
	u64 blinkMs;
	bool hintBrand;
	char name[PERFBRAND_ROWS][48];
	char display[PERFBRAND_ROWS][PERFDB_MAX_PART_BRANDS][32];
	u32 icon[PERFBRAND_ROWS][PERFDB_MAX_PART_BRANDS]; // DECAL_ICON_<brand>
	float titleX, titleY, pitch, dataX, dataY, dataW, imageH;
} PerfBrandSel;
static PerfBrandSel g_perfBrand;

// Setup's rows and the screen's widgets, while the language table is open.
static void perfBrandResolve(MenuState* m, const Config* cfg, const LangTable* lang) {
	PerfBrandSel* bs = &g_perfBrand;
	memset(bs, 0, sizeof(*bs));
	bs->blinkSide = -1;
	m->isPerfBrand = true;
	const PerfDb* pdb = cfg ? perfDb(cfg) : NULL;
	const PerfPackagePart* parts[PERFBRAND_ROWS] = { NULL };
	if (g_perfBuy.package) {
		const PerformancePackage* pk = pdb ? perfdb_package(pdb, g_perfPackageType, g_perfBuy.level)
			: NULL;
		for (u32 j = 0; pk && j < pk->numParts && j < PERFBRAND_ROWS; j++) {
			if (pk->part[j].numBrands == 0)
				continue;
			parts[bs->rows] = &pk->part[j];
			bs->enabled[bs->rows] = pk->part[j].numBrands > 1;
			bs->rows++;
		}
	} else {
		parts[0] = pdb ? perfdb_part(pdb, g_perfBuy.partId) : NULL;
		bs->rows = parts[0] ? 1 : 0;
		bs->enabled[0] = true;
	}
	char key[64];
	for (int r = 0; r < bs->rows; r++) {
		const PerfPackagePart* p = parts[r];
		bs->partId[r] = (int)p->partId;
		bs->numBrands[r] = p->numBrands < PERFDB_MAX_PART_BRANDS ? (int)p->numBrands
			: PERFDB_MAX_PART_BRANDS;
		const char* raw = lang ? langbin_lookup(lang, p->nameHash) : NULL;
		langTextToUtf8(raw ? raw : "", bs->name[r], sizeof(bs->name[r]));
		for (int k = 0; k < bs->numBrands[r]; k++) {
			bs->brand[r][k] = p->brand[k];
			// GetBrandDisplayName, and GetImageHashFromBrand's
			// FEngHashString("DECAL_ICON_%s") of the brand's name.
			const PerfBrand* br = perfdb_brand(pdb, p->brand[k]);
			snprintf(bs->display[r][k], sizeof(bs->display[r][k]), "%s", br ? br->display : "");
			snprintf(key, sizeof(key), "DECAL_ICON_%s", br ? br->name : "");
			for (char* c = key; *c; c++)
				if (*c >= 'a' && *c <= 'z')
					*c = (char)(*c - 'a' + 'A');
			bs->icon[r][k] = race_string_hash(key);
		}
	}
	bs->sel = -1;
	for (int r = 0; r < bs->rows && bs->sel < 0; r++)
		if (bs->enabled[r])
			bs->sel = r;
	if (bs->sel < 0)
		bs->sel = 0;
	bs->focusMs = osGetTime();
	bs->hintBrand = true;

	u32 hn[PERFBRAND_ROWS], hd[PERFBRAND_ROWS], hi[PERFBRAND_ROWS], hb[PERFBRAND_ROWS];
	u32 ha[PERFBRAND_ROWS][2];
	for (int r = 0; r < PERFBRAND_ROWS; r++) {
		m->pbName[r] = m->pbData[r] = m->pbImage[r] = m->pbBacking[r] = -1;
		m->pbArrow[r][0] = m->pbArrow[r][1] = -1;
		snprintf(key, sizeof(key), "OPTION_NAME_%d", r + 1);
		hn[r] = race_string_hash(key);
		snprintf(key, sizeof(key), "OPTION_DATA_%d", r + 1);
		hd[r] = race_string_hash(key);
		snprintf(key, sizeof(key), "OPTION_IMAGE_%d", r + 1);
		hi[r] = race_string_hash(key);
		snprintf(key, sizeof(key), "OPTION_BACKING_%d", r + 1);
		hb[r] = race_string_hash(key);
		snprintf(key, sizeof(key), "LEFT_ARROW_%d", r + 1);
		ha[r][0] = race_string_hash(key);
		snprintf(key, sizeof(key), "RIGHT_ARROW_%d", r + 1);
		ha[r][1] = race_string_hash(key);
	}
	m->pbHintBrand = m->pbHintSel = m->pbScroll[0] = m->pbScroll[1] = -1;
	const u32 kMaster[2] = { race_string_hash("TITLE_MASTER"), race_string_hash("DATA_MASTER") };
	float mx[2] = { 0 }, my[2] = { 0 }, mw[2] = { 0 }, mh[2] = { 0 };
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		if (!w->hasObjHash)
			continue;
		const u32 h = w->objHash;
		if (h == PERFBRAND_HINT_BRAND_HASH && w->type == FNG_TYPE_GROUP)
			m->pbHintBrand = i;
		else if (h == PERFBRAND_HINT_SELECT_HASH && w->type == FNG_TYPE_GROUP)
			m->pbHintSel = i;
		else if (h == SCROLLBAR_ARROW_1_HASH && w->type == FNG_TYPE_IMAGE)
			m->pbScroll[0] = i;
		else if (h == SCROLLBAR_ARROW_2_HASH && w->type == FNG_TYPE_IMAGE)
			m->pbScroll[1] = i;
		for (int r = 0; r < PERFBRAND_ROWS; r++) {
			if (w->type == FNG_TYPE_STRING && h == hn[r])
				m->pbName[r] = i;
			else if (w->type == FNG_TYPE_STRING && h == hd[r])
				m->pbData[r] = i;
			else if (w->type == FNG_TYPE_IMAGE && h == hi[r])
				m->pbImage[r] = i;
			else if (w->type == FNG_TYPE_GROUP && h == hb[r])
				m->pbBacking[r] = i;
			else if (w->type == FNG_TYPE_IMAGE && h == ha[r][0])
				m->pbArrow[r][0] = i;
			else if (w->type == FNG_TYPE_IMAGE && h == ha[r][1])
				m->pbArrow[r][1] = i;
		}
		for (int k = 0; k < 2; k++)
			if (w->type == FNG_TYPE_IMAGE && h == kMaster[k] && w->hasSize) {
				mw[k] = w->sizeW;
				mh[k] = w->sizeH;
				mx[k] = m->worldPosX[i] - mw[k] * 0.5f;
				my[k] = m->worldPosY[i] - mh[k] * 0.5f;
			}
	}
	// UIWidgetMenu::SetInitialPositions: the rows start on TITLE_MASTER's
	// top-left and step by its height; the value column is DATA_MASTER's.
	bs->titleX = mx[0];
	bs->titleY = my[0];
	bs->pitch = mh[0];
	bs->dataX = mx[1];
	bs->dataY = my[1];
	bs->dataW = mw[1];
	const int img0 = m->pbImage[0];
	bs->imageH = (img0 >= 0 && m->screen.widgets[img0].hasSize) ? m->screen.widgets[img0].sizeH
		: 0.0f;
	int bound = 0;
	for (int r = 0; r < PERFBRAND_ROWS; r++)
		bound += (m->pbName[r] >= 0) + (m->pbData[r] >= 0) + (m->pbImage[r] >= 0) +
			(m->pbBacking[r] >= 0) + (m->pbArrow[r][0] >= 0) + (m->pbArrow[r][1] >= 0);
	char b[256];
	snprintf(b, sizeof(b), "perf brands: %s %d, %d row(s), first enabled %d; %d/%d row widget(s), "
		"hints %d/%d, rows at %.0f,%.0f step %.0f, data %.0f,%.0f w %.0f, image h %.1f",
		g_perfBuy.package ? "package level" : "part", g_perfBuy.package ? g_perfBuy.level
		: g_perfBuy.partId, bs->rows, bs->sel, bound, 6 * PERFBRAND_ROWS, m->pbHintBrand,
		m->pbHintSel, bs->titleX, bs->titleY, bs->pitch, bs->dataX, bs->dataY, bs->dataW, bs->imageH);
	dlog(b);
	for (int r = 0; r < bs->rows; r++) {
		snprintf(b, sizeof(b), "perf brands: row %d part %d \"%s\" -- %d brand(s)%s, first %s "
			"(icon 0x%08X)", r, bs->partId[r], bs->name[r], bs->numBrands[r],
			bs->enabled[r] ? "" : " (disabled)", bs->display[r][0], (unsigned)bs->icon[r][0]);
		dlog(b);
	}
}

// BrandScrollerThing::Draw for every row: the part's name, the current
// brand's display name.
static void perfBrandFill(MenuState* m) {
	const PerfBrandSel* bs = &g_perfBrand;
	if (!m->isPerfBrand)
		return;
	if (!m->prBuf) {
		m->prBuf = C2D_TextBufNew(512);
		if (!m->prBuf)
			return;
	}
	C2D_TextBufClear(m->prBuf);
	for (int r = 0; r < PERFBRAND_ROWS; r++) {
		const bool on = r < bs->rows;
		menuSetWidgetText(m, m->prBuf, m->pbName[r], on ? bs->name[r] : "");
		menuSetWidgetText(m, m->prBuf, m->pbData[r],
			on && bs->numBrands[r] > 0 ? bs->display[r][bs->index[r]] : "");
	}
}

// FEToggleImageWidget::Position (0x801546BC) for the rows Setup added, the
// rest down; the masters hidden as on the parts list (perfPartsLayout()), the
// UP/DOWN hint per Setup and the scroll bar per FEScrollBar::Update.
static void perfBrandLayout(MenuState* m) {
	const PerfBrandSel* bs = &g_perfBrand;
	if (!m->isPerfBrand)
		return;
	for (int r = 0; r < PERFBRAND_ROWS; r++) {
		const bool on = r < bs->rows;
		const int parts[5] = { m->pbName[r], m->pbData[r], m->pbImage[r], m->pbArrow[r][0],
			m->pbArrow[r][1] };
		for (int k = 0; k < 5; k++)
			if (parts[k] >= 0)
				m->layoutHidden[parts[k]] = !on;
		menuHideSubtree(m, m->pbBacking[r], !on);
		if (!on)
			continue;
		const float y = bs->titleY + bs->pitch * (float)r;
		const float dy = bs->dataY + bs->pitch * (float)r;
		const float half = bs->imageH * 0.5f;
		prsPlace(m, m->pbName[r], bs->titleX, 0.0f, y + half, false);
		prsPlace(m, m->pbData[r], bs->dataX, bs->dataW, dy + bs->imageH + 1.0f, true);
		if (m->pbImage[r] >= 0) {
			m->worldPosX[m->pbImage[r]] = bs->dataX + bs->dataW * 0.5f;
			m->worldPosY[m->pbImage[r]] = dy + half;
		}
		for (int s = 0; s < 2; s++) {
			const int a = m->pbArrow[r][s];
			if (a < 0)
				continue;
			const FngWidget* w = &m->screen.widgets[a];
			const float aw = w->hasSize ? w->sizeW : 0.0f, ah = w->hasSize ? w->sizeH : 0.0f;
			const float left = s == 0 ? bs->dataX - aw : bs->dataX + bs->dataW;
			m->worldPosX[a] = left + aw * 0.5f;
			m->worldPosY[a] = y + half + ah * 0.5f;
		}
		perfPartsMoveGroup(m, m->pbBacking[r], bs->titleX + PERFBRAND_BACKING_DX,
			y + PERFBRAND_BACKING_DY);
	}
	const u32 kMaster[2] = { race_string_hash("TITLE_MASTER"), race_string_hash("DATA_MASTER") };
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		if (w->hasObjHash && (w->objHash == kMaster[0] || w->objHash == kMaster[1]))
			m->layoutHidden[i] = true;
	}
	if (!g_perfBuy.package || bs->rows < 2)
		menuHideSubtree(m, m->pbHintSel, true);
	menuHideSubtree(m, m->pbHintBrand, !bs->hintBrand);
	const bool bar = bs->rows > 1;
	for (int s = 0; s < 2; s++)
		if (m->pbScroll[s] >= 0)
			m->layoutHidden[m->pbScroll[s]] = !bar;
	if (m->scrollHandleWidget >= 0)
		m->layoutHidden[m->scrollHandleWidget] = !bar;
	perfBrandFill(m);
}

// A row's name and value this frame: Highlight on the focused row (the name's
// lime fading in and out on a loop, the value's steady), UnHighlight's white
// on a row focus has left, and Disable's -- which is also what a row never
// focused still shows -- grey. False for any other widget.
static bool perfBrandTextColor(const MenuState* m, int wi, u64 now, u32* rgba) {
	if (!m->isPerfBrand || wi < 0)
		return false;
	const PerfBrandSel* bs = &g_perfBrand;
	for (int r = 0; r < bs->rows && r < PERFBRAND_ROWS; r++) {
		const bool name = wi == m->pbName[r];
		if (!name && wi != m->pbData[r])
			continue;
		if (r == bs->sel && bs->enabled[r]) {
			u8 a = 255;
			if (name) {
				const float t = fmodf((float)(now - bs->focusMs), PERFBRAND_NAME_LOOP_MS);
				const float k = t < 440.0f ? t / 440.0f : t < 760.0f ? 1.0f
					: 1.0f - (t - 760.0f) / 440.0f;
				a = (u8)(255.0f * k + 0.5f);
			}
			*rgba = menuWidgetColor(m, wi, 204, 244, 138, a);
		} else if (bs->enabled[r] && bs->visited[r]) {
			*rgba = menuWidgetColor(m, wi, 255, 255, 255, 255);
		} else {
			*rgba = menuWidgetColor(m, wi, 50, 50, 50, 255);
		}
		return true;
	}
	return false;
}

// The rows' images: the option arrows (AddToggleImageOption's 0x9943D584 on
// both), the backing parts under their group's script colour, and the brand
// art. Same contract as traxImageTint(): 0 for any other widget, -1 for one
// that is down, else 1 with its colour and how far a Blink grows it.
static int perfBrandImageTint(const MenuState* m, int i, u64 now, u32* rgba, float* grow) {
	if (!m->isPerfBrand)
		return 0;
	const PerfBrandSel* bs = &g_perfBrand;
	for (int r = 0; r < bs->rows && r < PERFBRAND_ROWS; r++) {
		if (i == m->pbImage[r]) {
			*rgba = menuWidgetColor(m, i, 255, 255, 255, 255);
			return 1;
		}
		for (int s = 0; s < 2; s++) {
			if (i != m->pbArrow[r][s])
				continue;
			if (r != bs->sel || !bs->enabled[r])
				return -1;
			u8 cr = 255, cg = 255, cb = 255, a = 150;
			const float t = (float)(now - bs->blinkMs);
			if (bs->blinkSide == s && t < PERFBRAND_BLINK_MS) {
				const float half = PERFBRAND_BLINK_MS * 0.5f;
				const float k = t < half ? t / half : 1.0f - (t - half) / half;
				const float w = t < half ? 0.0f : (t - half) / half;
				cr = (u8)(202.0f + 53.0f * w + 0.5f);
				cg = (u8)(244.0f + 11.0f * w + 0.5f);
				cb = (u8)(138.0f + 117.0f * w + 0.5f);
				a = (u8)(150.0f + 105.0f * k + 0.5f);
				*grow = 6.0f * k;
			}
			*rgba = menuWidgetColor(m, i, cr, cg, cb, a);
			return 1;
		}
	}
	const FngWidget* w = &m->screen.widgets[i];
	for (int cur = w->parentIndex, n = 0; cur >= 0 && n < 64;
			cur = m->screen.widgets[cur].parentIndex, n++) {
		for (int r = 0; r < bs->rows && r < PERFBRAND_ROWS; r++) {
			if (cur != m->pbBacking[r])
				continue;
			const bool hi = r == bs->sel && bs->enabled[r];
			const u32 g = menuWidgetColor(m, cur, hi ? 128 : 255, hi ? 128 : 255, hi ? 128 : 255,
				hi ? 255 : 100);
			const u32 own = w->hasColor ? C2D_Color32(w->colorR, w->colorG, w->colorB, w->colorA)
				: 0xFFFFFFFFu;
			u32 c = 0;
			for (int sh = 0; sh < 32; sh += 8)
				c |= (((((g >> sh) & 0xFF) * ((own >> sh) & 0xFF)) + 0x80) >> 8) << sh;
			*rgba = c;
			return ((c >> 24) & 0xFF) ? 1 : -1;
		}
	}
	return 0;
}

// Draw's texture on the brand art -- its DECAL_ICON, or 0x74CE8C0B where
// GetTextureInfo finds none -- and the arrows' sprite.
static void perfBrandImage(const MenuState* m, int i, C2D_Image* img) {
	if (!m->isPerfBrand)
		return;
	const PerfBrandSel* bs = &g_perfBrand;
	for (int r = 0; r < bs->rows && r < PERFBRAND_ROWS; r++) {
		if (i == m->pbImage[r] && bs->numBrands[r] > 0) {
			C2D_Image t = texcache_find(&m->texCache, bs->icon[r][bs->index[r]]);
			if (!t.tex)
				t = texcache_find(&m->texCache, PERFBRAND_NO_ICON_TEX);
			if (t.tex)
				*img = t;
		} else if (i == m->pbArrow[r][0] || i == m->pbArrow[r][1]) {
			const C2D_Image t = texcache_find(&m->texCache, OPTIONS_ARROW_TEX_HASH);
			if (t.tex)
				*img = t;
		}
	}
}

// The results screen's widgets and both of ResultsUpdate's views, while the
// language table is still open. The stats screen's own, likewise.
static void postRaceResolve(MenuState* m, int scr, const LangTable* lang) {
	const PostRace* pr = &g_postRace;
	m->isPostResults = scr == 1;
	m->isPostStats = scr == 3;
	m->isPostTourn = scr == 4 || scr == 5;
	m->isPostSponsor = scr == 7;
	m->prHiRows = 0;
	if (m->isPostStats)
		postRaceStatsResolve(m, lang);
	if (m->isPostSponsor)
		postRaceSponsorResolve(m);
	if (m->isPostTourn)
		m->prHiRows = pr->tournHi[scr - 4];
	if (!m->isPostResults)
		return;
	if (pr->playerRow >= 0 && pr->playerRow < POSTRACE_ROWS)
		m->prHiRows = (u8)(1u << pr->playerRow);
	m->prHeader = -1;
	for (int k = 0; k < POSTRACE_ROWS; k++)
		m->prTime[k] = -1;
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		if (w->type != FNG_TYPE_STRING || !w->hasObjHash)
			continue;
		if (w->objHash == PR_HEADER3_HASH)
			m->prHeader = i;
		int col = 0;
		const int r = postRaceCell(w->objHash, &col);
		if (r >= 0 && col == 3)
			m->prTime[r] = i;
	}
	const s32 lead = pr->rowCount > 0 ? pr->rows[0].time : 0;
	char t[16];
	for (int r = 0; r < pr->rowCount; r++) {
		if (pr->rows[r].disconnected) {
			// #321c: no time for a racer who left -- the PC's word
			// (0xA7DB717F, the leaderboard's and PRTimeBehind's 0xC) in
			// both columns.
			const char* raw = lang ? langbin_lookup(lang, 0xA7DB717Fu) : NULL;
			langTextToUtf8(raw ? raw : "Disconnected", m->prTimeStr[0][r],
				sizeof(m->prTimeStr[0][r]));
			snprintf(m->prTimeStr[1][r], sizeof(m->prTimeStr[1][r]), "%s", m->prTimeStr[0][r]);
			continue;
		}
		race_print_time(pr->rows[r].time, 0, t);
		snprintf(m->prTimeStr[0][r], sizeof(m->prTimeStr[0][r]), "%s", t);
		if (r == 0) {
			const char* raw = lang ? langbin_lookup(lang, PR_TEXT_NO_GAP) : NULL;
			langTextToUtf8(raw ? raw : "", m->prTimeStr[1][0], sizeof(m->prTimeStr[1][0]));
		} else {
			race_print_time(pr->rows[r].time - lead, 2, t);
			snprintf(m->prTimeStr[1][r], sizeof(m->prTimeStr[1][r]), "%s", t);
		}
	}
	static const u32 kHead[2] = { PR_TEXT_FINISH_TIME, PR_TEXT_TIME_BEHIND };
	for (int v = 0; v < 2; v++) {
		const char* raw = lang ? langbin_lookup(lang, kHead[v]) : NULL;
		langTextToUtf8(raw ? raw : "", m->prHeadStr[v], sizeof(m->prHeadStr[v]));
	}
	m->prGap = false;
	m->prAcc = 0.0f;
	m->prAt = PR_FINISH_VIEW_SEC;
}

// After computeMenuLayout(), which resets layoutHidden: Setup's hides. The
// countdown, the disconnect line, the tournament pair's server wait and
// Outrun OVERTIME are online or Outrun only (their INIT chains to HIDE and
// nothing in career shows them), SetUnusedEntriesInvisible(6, n) takes down
// rows n+1..6, and every row's bar stays at its INIT's alpha 0 except a
// highlighted row's, which the HIGHLIGHT script brings up.
static void postRaceLayout(MenuState* m) {
	// The stats screen's: Setup hides the lap list's two headers for a drag
	// or a point-to-point race, which have no list.
	if (m->isPostStats && (g_postRace.drag || g_postRace.pointToPoint)) {
		menuHideSubtree(m, m->psHead[0], true);
		menuHideSubtree(m, m->psHead[1], true);
	}
	// The sponsor screen's first RefreshHeader, once the TERMS lines' scale
	// is known.
	if (m->isPostSponsor)
		postRaceSponsorLayout(m);
	if (!m->isPostResults && !m->isPostTourn)
		return;
	const PostRace* pr = &g_postRace;
	const int rows = m->isPostTourn ? pr->tournCount : pr->rowCount;
	for (int i = 0; i < m->screen.widgetCount && i < FNG_MAX_WIDGETS; i++) {
		const FngWidget* w = &m->screen.widgets[i];
		if (!w->hasObjHash)
			continue;
		const u32 h = w->objHash;
		int col = 0;
		const int r = postRaceCell(h, &col);
		if (h == PR_COUNTDOWN_HASH || h == PR_DISCONNECT_HASH || h == PR_WAIT_AUTH_HASH ||
				h == PR_OVERTIME_HASH || (r >= 0 && r >= rows))
			menuHideSubtree(m, i, true);
		if (w->type == FNG_TYPE_GROUP && h >= PR_BAR_HASH && h < PR_BAR_HASH + POSTRACE_ROWS &&
				!(m->prHiRows & (1u << (h - PR_BAR_HASH))))
			menuHideSubtree(m, i, true);
	}
}

// ResultsUpdate (the toggle's arm): HEADER_TEXT_3 and the time column to the
// view now up.
static void postRaceResultsUpdate(MenuState* m) {
	if (!m->prBuf) {
		m->prBuf = C2D_TextBufNew(256);
		if (!m->prBuf)
			return;
	}
	C2D_TextBufClear(m->prBuf);
	const int v = m->prGap ? 1 : 0;
	menuSetWidgetText(m, m->prBuf, m->prHeader, m->prHeadStr[v]);
	for (int r = 0; r < g_postRace.rowCount && r < POSTRACE_ROWS; r++)
		menuSetWidgetText(m, m->prBuf, m->prTime[r], m->prTimeStr[v][r]);
}

// PostRaceResultsScreen::NotificationMessage's 0xC98356BA arm, once a frame.
// A drift returns before the toggle (0x800F4BB4): its header and score
// column stay as Setup printed them.
static void postRaceResultsTick(MenuState* m, float dt) {
	if (!m->isPostResults || g_postRace.drift)
		return;
	if (m->prAt < m->prAcc) {
		m->prGap = !m->prGap;
		m->prAcc = 0.0f;
		m->prAt = m->prGap ? PR_GAP_VIEW_SEC : PR_FINISH_VIEW_SEC;
		postRaceResultsUpdate(m);
	} else {
		m->prAcc += dt;
	}
}

// The HIGHLIGHT colour on a highlighted row's Strings, `color` left alone
// elsewhere.
static void postRaceTextColor(const MenuState* m, int i, u32* color) {
	if ((!m->isPostResults && !m->isPostTourn) || !m->prHiRows)
		return;
	const FngWidget* w = &m->screen.widgets[i];
	if (w->type != FNG_TYPE_STRING || !w->hasObjHash)
		return;
	int col = 0;
	const int r = postRaceCell(w->objHash, &col);
	if (r >= 0 && (m->prHiRows & (1u << r)))
		*color = PR_HIGHLIGHT_RGBA;
}

// ---------------------------------------------------------------------------
// UI_OptionsController.fng -- the Controls page's fourteen button labels
//
// The screen is console-authored, and the PC's own FRONTEND/FrontB.lzc ships
// it: 130 packages come out of that container and this is one of them, sitting
// unused because the PC jump table pushes the keyboard grid instead. So the
// port needs no file the PC release does not already have.
//
// SetupControllerButtons (Speed.elf 0x800EF44C) walks CButton_1..14, writing
// each the action its slot carries in the current scheme and hiding a slot the
// table has nothing for. The button identity itself is carried by the
// controller picture they sit around, which here is a PS2 DualShock -- the
// wrong hardware for this console -- so the port hides it and writes its own
// 3DS control on a second line. options.c's kControlActions holds the table
// and the header the whole of the reasoning.
// ---------------------------------------------------------------------------

#define CONTROLS_PAD_IMAGE_HASH 0xF1534C25u // Loading_controller_ps2.tga
// The nav bar slot the ctor writes (0x800EEE28 -> 0x800EF3F8) and the string
// it puts there outside an online session, 0xB0FCF98E "EA Messenger" being the
// other arm.
#define CONTROLS_PLAYER_SELECT_HASH   0x010CBA23u
#define CONTROLS_PLAYER_SELECT_STRING 0xB35B3AC3u // "Player Select"

// The 3DS control at each of the fourteen slots: this port's answer to the
// controller picture, and the only part of the screen retail has no data for.
// A slot is a control, not an action -- that is what the picture is -- so the
// scheme moves actions across this table and never the other way, and the
// bindings the world drives on come out of the same place the screen reads
// (controlsKeysFor below).
//
// Which control went where: slot 3 is the stick every scheme 0-4 steers with,
// slots 4-7 are the four D-pad directions the free-roam screens sit on, and
// the nine left over take the nine buttons this console has that are not
// START. Retail's pad has four shoulders where a 3DS has two, so the other two
// slots fall on ZL and ZR, which only a New 3DS carries -- and the port runs
// on nothing else (#264: an original 3DS is refused at boot), so every slot
// is a real button and every scheme binds all fourteen.
// PORT (#447): the table is controls.c's now (controls_slot_keys / _name),
// and the action on each slot is the profile's binding (controls_action_at).


static int controlsSlotOf(u32 objHash) {
	for (int i = 0; i < OPTIONS_CONTROL_BUTTONS; i++) {
		if (options_control_object(i) == objHash)
			return i;
	}
	return -1;
}

// The actions this port's world acts on. One it did not would read "Not Used"
// whichever slot a scheme puts it on, so the screen never names a button that
// does nothing; since Nitrous and Look Back (2026-10-28) there is none. Steer
// is bound and has no key: it is the stick.
static bool controlsActionBound(u32 action) {
	switch (action) {
	case OPT_ACT_ACCELERATE:
	case OPT_ACT_BRAKE:
	case OPT_ACT_STEER:
	case OPT_ACT_SHIFT_UP:
	case OPT_ACT_SHIFT_DOWN:
	case OPT_ACT_HANDBRAKE:
	case OPT_ACT_CHANGE_CAMERA:
	case OPT_ACT_LOOK_BACK:
	case OPT_ACT_NITROUS:
	case OPT_ACT_RESET_CAR:
	case OPT_ACT_ENTER_SHOP:
	case OPT_ACT_WORLD_MAP:
	case OPT_ACT_CAREER_STATS:
	case OPT_ACT_DISPLAY_SMS:
		return true;
	default:
		return false;
	}
}

// PORT (the user, 2026-11-09: "scrolling support for circle pad and d-pad so I
// don't have to individually press"): a direction held on the D-Pad or the
// Circle Pad steps again after NAV_REPEAT_DELAY ms, then every
// NAV_REPEAT_EVERY ms, as a list on the PC's keyboard does under the key's
// auto-repeat. The pulses are the held direction bits, ORed into the frame's
// presses; g_navRep keeps this frame's, so the driving (and the button that
// raised an in-world overlay, which closes it) can take them out again --
// a held steer or D-Pad binding is not a run of presses.
#define NAV_REPEAT_DELAY 400
#define NAV_REPEAT_EVERY 90
static u32 g_navRep;

static u32 navRepeat(u32 down, u32 held) {
	static const u32 dirs = KEY_DUP | KEY_DDOWN | KEY_DLEFT | KEY_DRIGHT |
		KEY_CPAD_UP | KEY_CPAD_DOWN | KEY_CPAD_LEFT | KEY_CPAD_RIGHT;
	static u32 s_dir;
	static u64 s_next;
	const u32 h = held & dirs;
	const u64 now = osGetTime();
	g_navRep = 0;
	if (h != s_dir || (down & dirs)) {
		s_dir = h;
		s_next = now + NAV_REPEAT_DELAY;
	} else if (h && now >= s_next) {
		s_next = now + NAV_REPEAT_EVERY;
		g_navRep = h & ~down;
	}
	return down | g_navRep;
}

// Which keys perform `action` under the scheme in force -- the same lookup the
// Controls screen prints, so the two can never disagree. 0 when no slot in
// this scheme carries it, or when the slot that does is a button this console
// has not got.
static u32 controlsKeysFor(u32 action) {
	u32 keys = 0;
	for (int i = 0; i < OPTIONS_CONTROL_BUTTONS; i++) {
		if (controls_action_at(i) != action)
			continue;
		keys |= controls_slot_keys(i);
	}
	return keys;
}

// PORT (#447): the slot action `hash` is bound to, -1 for none.
static int controlsSlotOfAction(u32 hash) {
	for (int i = 0; i < CONTROLS_ACTIONS; i++)
		if (controls_action_hash(i) == hash)
			return controls_slot_of(i);
	return -1;
}

// The engage widget's arrow for a D-pad slot (engage.h), or ENGAGE_DIR_BUTTON.
static int engageDirOfSlot(int slot) {
	switch (slot) {
	case 3:  return 0; // up
	case 6:  return 1; // right
	case 4:  return 2; // down
	case 5:  return 3; // left
	default: return ENGAGE_DIR_BUTTON;
	}
}

// PORT (#447): the held buttons as the menus read them -- the binding's swap
// (controls.h). The driving reads the real ones through controlsKeysFor().
static u32 menuKeysHeld(void) {
	return controls_menu_keys(hidKeysHeld());
}

// PORT: SELECT opens the world map as well as the scheme's own World Map
// button -- the user's alias (TASKS.md #263), as it was before the Controls
// rebuild gave SELECT to slot 14. It sits on top of retail's table, not in it:
// a scheme that moves World Map still moves it, and SELECT stays an extra. It
// stands aside when the live scheme puts an action the world acts on onto
// SELECT, so the alias never costs a pedal. Since Look Back is ported (#296's
// aside, 2026-10-28) that is every shipped scheme -- Control Type 2 brakes
// there and the others look back -- which the user chose over a remap: the
// map stays on D-Pad Down.
static int controlsSelectSlot(void) {
	for (int i = 0; i < OPTIONS_CONTROL_BUTTONS; i++) {
		if (controls_slot_keys(i) == KEY_SELECT)
			return i;
	}
	return -1;
}

static bool controlsSelectIsMapAlias(void) {
	const int slot = controlsSelectSlot();
	if (slot < 0)
		return false;
	return !controlsActionBound(controls_action_at(slot));
}

static u32 controlsWorldMapKeys(void) {
	u32 keys = controlsKeysFor(OPT_ACT_WORLD_MAP);
	if (controlsSelectIsMapAlias())
		keys |= KEY_SELECT;
	return keys;
}

// "<action>: <control>", the action from English.bin and the control from the
// slot. False leaves the widget blank, which is what retail does to a slot it
// has no action for (FEngSetInvisible at 0x800EF540).
//
// PORT: retail stacks the control under the action -- its authoring
// placeholder is "RESET_CAR\nXXXX" -- because a 640x480 canvas has the height
// for fourteen two-line labels and the room left on this panel does not. Two
// lines each at MENU_MIN_TEXT_PX need about 195 px where the band between the
// option rows and the footer is 136, so the two parts share a line here and
// controlsRelayout() re-spaces the grid around that. langTextToUtf8 still
// turns the table's own '^' into a line break, so the one action name that
// carries one ("Enter Shop /^Challenge Opponent") keeps it and that label
// alone runs to two lines.
static bool controlsButtonText(const LangTable* lang, int slot,
		char* out, size_t cap) {
	if (slot < 0 || slot >= OPTIONS_CONTROL_BUTTONS)
		return false;
	u32 action = controls_action_at(slot);
	// The port's SELECT alias for the map takes over a slot whose own action
	// the world does not act on, and the label says so rather than "Not Used"
	// (controlsWorldMapKeys()).
	if (slot == controlsSelectSlot() && controlsSelectIsMapAlias())
		action = OPT_ACT_WORLD_MAP;
	const char* raw = (lang && action) ? langbin_lookup(lang, action) : NULL;
	if (!raw)
		return false;
	char act[96];
	langTextToUtf8(raw, act, sizeof(act));
	char notUsed[64];
	const char* btn = controls_slot_name(slot);
	if (!controlsActionBound(action))
		btn = NULL;
	if (!btn) {
		const char* nu = lang ? langbin_lookup(lang, OPTIONS_NOT_USED_HASH) : NULL;
		if (!nu)
			return false;
		langTextToUtf8(nu, notUsed, sizeof(notUsed));
		btn = notUsed;
	}
	snprintf(out, cap, "%s: %s", act, btn);
	return true;
}

