// UICareerCrib's bWentToCribFromMainMenu, byte [0x836324] (Speed.elf
// r13-0x745C): set by Resume Career's crib arm (0x495A30), cleared by both
// ways out. It is what turns the crib's PAD_BACK from "Return to Explore
// Mode?" into "quit to the main menu?".
static bool g_wentToCribFromMainMenu = false;

// The profile snapshot CheckMemory compares against (MemoryCard 0x52A460 /
// 0x52A4C0 / 0x5032C0 on 0x83A9D0). Retail serialises the whole profile and
// compares bytes; the port counts the writes that can change it instead
// (careerSetEventState, the purse beside it, and UI_CareerCarSelect's switch),
// which is the same question.
// The snapshot is only taken when Autosave is on (UserProfile +0xA0F8, the
// +0xA108 the snapshot tests through its +0x10 profile pointer), so with it off
// CheckMemory never finds anything to save.
//
// And it is only taken when none is held: 0x52A460 returns at once while
// [0x83A9D0+0x16778] is set, and only 0x5032C0 clears it -- which the crib
// calls on its three ways out (Return to Explore's Yes after CheckMemory,
// Back to Main Menu's Yes, Performance Tuning's Yes), not when it hands over
// to its own sub-screens. So the snapshot the crib took on first showing is
// still the one compared after a trip to UI_CareerCarSelect and back, and a
// car switched there is what CheckMemory then finds.
static u32  g_profileEdits = 0;
static u32  g_cribSnapshot = 0;
static bool g_cribHaveSnapshot = false;

static void cribTakeSnapshot(void) {
	if (g_cribHaveSnapshot || !(gProfile.isLoaded && gProfile.autosave))
		return;
	g_cribHaveSnapshot = true;
	g_cribSnapshot = g_profileEdits;
}

static void cribDropSnapshot(void) {
	g_cribHaveSnapshot = false;
}

// The walk-ins' and the crib's way out to the world (#514): IsDirty against
// the snapshot -- only taken with Autosave on -- raises the memory card's
// save flow (EnterMemcard 0x141 / 0x151, DoSaveFlow(4)). In Autosave mode it
// saves at once; in Prompt mode it is state 5, SetupPromptSaveConfirm ("Are
// you sure you want to save the profile named %s?"), and the world opens
// after the answer. The exit only sets g_exitSaveAsk here; the frontend
// puts MC_Main.fng up where it reads g_cribEnterWorld, and the MCMAIN_SAVE
// handler's answer (g_exitSaveWorld) then lets the world open.
static bool g_exitSaveAsk = false;
static bool g_exitSaveWorld = false;
static bool g_dbgExitDirty = false;   // DbgExitDirty, a test aid
static void exitIsDirtySave(const char* who) {
	if (!(g_cribHaveSnapshot && (g_profileEdits != g_cribSnapshot || g_dbgExitDirty)))
		return;
	char b[128];
	if (!gProfile.autosaveNoPrompt && gProfile.name[0]) {
		g_exitSaveAsk = true;
		snprintf(b, sizeof(b), "%s: IsDirty -- profile changed, Prompt: asking before the world", who);
	} else {
		const bool ok = careerSaveProfile();
		snprintf(b, sizeof(b), "%s: IsDirty -- profile changed, %s", who,
			ok ? "saved" : "save FAILED");
	}
	dlog(b);
}

