// The mover's pose: the lens as the PICA wants it (vertical, degrees), the
// target and the eye. SelectCarCameraMover also blends two extras (camera
// +0xB4 / +0xB8) the port's camera has no use for.
typedef struct {
	float vfov, target[3], eye[3];
} FeCamPose;

static struct {
	bool looking;        // +0x30: a part's record is the desired pose
	bool moving;         // +0x2C == 0: blending from -> to
	FeCamPose from, to, cur;
	float t, dur;        // +0xFC, +0x100
	float minDur;        // +0x104
	float carFrom, carDelta;   // GarageMainScreen +0x120 / +0x124, degrees
	float tireFrom, tireDelta; // +0x130 / +0x134, degrees
	float tire;                // the steer now, degrees
	bool carDriven;      // the car's angle is the mover's this frame
	int slot;            // the record's slot, for the log
} g_feCam;

// The port's resting shot (#312, the PC garage's), which StopLookingAtParts
// returns to. PORT: retail's rest is StaticCameraInfoTable's (eye 9.4 m out at
// 1.4 m, 32 degrees -- the same 30-degree vertical lens once the FE lens below
// is applied); the port keeps the fitted shot it already had, so the shops
// open on the framing the garage has, and only a part's own record moves it.
static void feCamDefault(FeCamPose* p) {
	p->vfov = SCENE_CAR_FOV;
	p->eye[0] = SCENE_DISC_X;
	p->eye[1] = SCENE_DISC_Y - SCENE_CAR_DIST;
	p->eye[2] = SCENE_CAR_EYE_Z;
	p->target[0] = SCENE_DISC_X;
	p->target[1] = SCENE_DISC_Y + SCENE_CAR_AIM_Y;
	p->target[2] = SCENE_CAR_AIM_Z;
}

// A record's pose. The frontend's lens (eView) takes the record's fov as the
// horizontal angle times 1.1 and the vertical as fov / 2 * 1.265 * 0.75 (the
// 4:3 panel's), so the vertical is what the PICA is handed.
static void feCamRecPose(const FeCamRec* r, FeCamPose* p) {
	const float d2r = (float)M_PI / 180.0f;
	p->vfov = 2.0f * atanf(tanf(r->fov * 0.5f * 1.265f * 0.75f * d2r)) / d2r;
	memcpy(p->target, r->target, sizeof(p->target));
	memcpy(p->eye, r->eye, sizeof(p->eye));
}

// FindPartCameraInfo (0x800fa3c8). `set` is CarOrbiter +0x158 (the car type's
// SUV byte, CarTypeInfo +0x88A), `hummer` +0x15C (CarTypeInfo +0x840 == 8).
// `group` is a vinyl's group (CarPart byte 5 & 0x1F), -1 for none.
static const FeCamRec* feCamFind(int slot, int set, bool hummer, int group) {
	if (set && hummer && (slot == 0x0D || slot == 0x9B || slot == 0x44))
		return &FE_CAM_HUMMER_ENGINE;
	if ((unsigned)(slot - 0x22) < 0x0Du)
		slot = 0x22;
	if ((unsigned)(slot - 0x40) < 4u) {
		if (group == 0x14)
			return &FE_CAM_VINYL[set][0];
		if (group > 0x15 && group < 0x1C)
			return &FE_CAM_VINYL[set][group - 0x15];
		slot = 0x40;
	}
	for (int i = 0; i < 49; i++)
		if (FE_CAM_PART[set][i].slot == slot)
			return &FE_CAM_PART[set][i];
	return NULL;
}

static float feCamDegNow(void) {
	return g_carAngle * (180.0f / (float)M_PI);
}

// SetDesiredOrientation (0x8006ead8) and FindAnimationTime (0x8006eba4): the
// pose now becomes `from`, and the blend lasts the slowest of its moves --
// 50 lens degrees, 2.2 m of target or eye, or one car degree a step, a step
// 0.0055 s -- but no less than `minDur`. GarageMainScreen turns the car the
// shorter way round over the same time (and steers the tyres with it).
// PORT: the steps are taken at the GameCube's 60 Hz frame, so the times are
// the console's whatever the 3DS frontend runs at.
static void feCamSetDesired(const FeCamPose* to, float carDeg, float tireDeg) {
	const float dt = 1.0f / 60.0f;
	g_feCam.from = g_feCam.cur;
	g_feCam.to = *to;
	float steps = 0.0f;
	const float sf = fabsf(to->vfov - g_feCam.cur.vfov) / (dt * 50.0f);
	if (sf > steps) steps = sf;
	for (int v = 0; v < 2; v++) {
		const float* a = v ? g_feCam.cur.eye : g_feCam.cur.target;
		const float* b = v ? to->eye : to->target;
		const float dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
		const float sv = sqrtf(dx * dx + dy * dy + dz * dz) / (2.2f * dt);
		if (sv > steps) steps = sv;
	}
	float from = fmodf(feCamDegNow(), 360.0f);
	if (from < 0.0f) from += 360.0f;
	float delta = fmodf(carDeg - from, 360.0f);
	if (delta > 180.0f) delta -= 360.0f;
	if (delta < -180.0f) delta += 360.0f;
	if (fabsf(delta) > steps) steps = fabsf(delta);
	g_feCam.carFrom = from;
	g_feCam.carDelta = delta;
	g_feCam.tireFrom = g_feCam.tire;
	g_feCam.tireDelta = tireDeg - g_feCam.tire;
	g_feCam.t = 0.0f;
	g_feCam.dur = steps * 0.0055f;
	if (g_feCam.dur < g_feCam.minDur)
		g_feCam.dur = g_feCam.minDur;
	g_feCam.moving = true;
	g_feCam.carDriven = true;
}

// GarageMainScreen +0x164 / +0x160: the part SetLookatPart opened for the
// look (slot 0x44, Engine Paint: the hood), shut by the next look or
// StopLookingAtParts (#314).
static bool s_lookOpened = false;
static void feCamLookClose(void) {
	if (!s_lookOpened)
		return;
	s_lookOpened = false;
	feDoCarPartAnimNow(g_cfgMain, CARANIM_HOOD, false);
}

// SetLookatPart for the part in `slot` (a vinyl's `group`, else -1):
// SetDesiredPartLookAtOrientation (0x8006e930), at least 0.3 s.
static void feCamLookAt(int slot, int group, const char* why) {
	feCamLookClose();
	if (slot == 0x44) {
		s_lookOpened = true;
		feDoCarPartAnimNow(g_cfgMain, CARANIM_HOOD, true);
	}
	const int cs = gProfile.currentCarSlot;
	const u32 car = cs >= 0 && cs < PROFILE_CAREER_ARRAYS
		? gProfile.careerCar[cs].carTypeHash : 0;
	// PORT: the car type's SUV byte and type 8 are read off the career car's
	// name hash -- NAVIGATOR, ESCALADE, HUMMER (careerCurrentCarIsSUV()).
	const bool hummer = car == 0x6126DD4Du;
	const int set = (hummer || car == 0xCF704771u || car == 0x0219C94Au) ? 1 : 0;
	const FeCamRec* r = feCamFind(slot, set, hummer, group);
	char b[192];
	if (!r) {
		snprintf(b, sizeof(b), "shop camera: SetLookAtPart slot 0x%X (%s) -- no record, "
			"camera stays", (unsigned)slot, why);
		dlog(b);
		return;
	}
	FeCamPose p;
	feCamRecPose(r, &p);
	g_feCam.minDur = 0.3f;
	g_feCam.looking = true;
	g_feCam.slot = slot;
	feCamSetDesired(&p, r->car, r->tire);
	snprintf(b, sizeof(b), "shop camera: SetLookAtPart slot 0x%X group %d set %d (%s) -- record "
		"slot 0x%X, car %.1f deg, tyres %.1f, fov %.1f, %.2f s", (unsigned)slot, group, set, why,
		(unsigned)r->slot, r->car, r->tire, r->fov, g_feCam.dur);
	dlog(b);
}

// StopLookingAtParts (0x8006e990): back to the rest pose, at least 2.5 s.
// PORT: the car comes back to the port's rest angle and straight tyres.
static void feCamStop(const char* why) {
	feCamLookClose();
	if (!g_feCam.looking)
		return;
	FeCamPose p;
	feCamDefault(&p);
	g_feCam.minDur = 2.5f;
	g_feCam.looking = false;
	feCamSetDesired(&p, CAR_REST_ANGLE * (180.0f / (float)M_PI), 0.0f);
	char b[96];
	snprintf(b, sizeof(b), "shop camera: StopLookingAtParts (%s) -- %.2f s", why, g_feCam.dur);
	dlog(b);
}

// One frame of Update (0x8006e1cc, mode 0) and GarageMainScreen's car turn,
// then the top screen's view-projection. `shopScreen` is false off the body
// shop, vinyl and paint screens: a look left standing there (the paint shop
// never stops its own) is stopped. True while the car's angle is the mover's.
static bool feCamFrame(float dt, bool shopScreen, C3D_Mtx* vp) {
	static bool init = false;
	if (!init) {
		feCamDefault(&g_feCam.cur);
		init = true;
	}
	if (!shopScreen && g_feCam.looking)
		feCamStop("left the shop's screens");
	if (g_feCam.moving) {
		g_feCam.t += dt;
		float k = 1.0f;
		if (g_feCam.dur > 0.0f && g_feCam.t < g_feCam.dur)
			k = g_feCam.t / g_feCam.dur;
		const float s = (sinf((k * 180.0f - 90.0f) * ((float)M_PI / 180.0f)) + 1.0f) * 0.5f;
		FeCamPose* c = &g_feCam.cur;
		const FeCamPose* a = &g_feCam.from;
		const FeCamPose* b = &g_feCam.to;
		c->vfov = a->vfov + (b->vfov - a->vfov) * s;
		for (int i = 0; i < 3; i++) {
			c->target[i] = a->target[i] + (b->target[i] - a->target[i]) * s;
			c->eye[i] = a->eye[i] + (b->eye[i] - a->eye[i]) * s;
		}
		const float deg = g_feCam.carFrom + g_feCam.carDelta * k;
		g_carAngle = deg * ((float)M_PI / 180.0f);
		g_feCam.tire = g_feCam.tireFrom + g_feCam.tireDelta * k;
		if (k >= 1.0f) {
			g_feCam.moving = false;
			g_feCam.carDriven = g_feCam.looking;
		}
	}
	model3d_camera(vp, g_feCam.cur.eye, g_feCam.cur.target, g_feCam.cur.vfov,
		C3D_AspectRatioTop, SCENE_NEAR, SCENE_FAR);
	return g_feCam.moving || g_feCam.looking;
}

// Mtx_LookAt's basis for an eye looking at `look`: forward, right = forward x
// up, and the up square to both, unit length. False for a degenerate view.
static bool lookBasis(const float eye[3], const float look[3], const float up[3],
		float f[3], float r[3], float u[3]) {
	for (int i = 0; i < 3; i++)
		f[i] = look[i] - eye[i];
	const float fl = sqrtf(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);
	if (fl <= 1e-6f)
		return false;
	for (int i = 0; i < 3; i++)
		f[i] /= fl;
	r[0] = f[1] * up[2] - f[2] * up[1];
	r[1] = f[2] * up[0] - f[0] * up[2];
	r[2] = f[0] * up[1] - f[1] * up[0];
	const float rl = sqrtf(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);
	if (rl <= 1e-6f)
		return false;
	for (int i = 0; i < 3; i++)
		r[i] /= rl;
	u[0] = r[1] * f[2] - r[2] * f[1];
	u[1] = r[2] * f[0] - r[0] * f[2];
	u[2] = r[0] * f[1] - r[1] * f[0];
	return true;
}

// The top screen's car camera as the car's light, neon and flares see it --
// the eView RenderFrontEndCars and RenderFEFlares are handed. The lens is
// SCENE_CAR_FOV vertically; the eView's angle is the horizontal one.
static CarNeonView g_sceneNeonView;

static bool sceneCarView(void) {
	// The shops' part camera's pose (g_feCam), the rest shot when none.
	const float* eye  = g_feCam.cur.eye;
	const float* look = g_feCam.cur.target;
	static const float zUp[3] = { 0.0f, 0.0f, 1.0f };
	float f[3], r[3], u[3];
	if (!lookBasis(eye, look, zUp, f, r, u))
		return false;
	model3d_set_car_view(eye, r, u, f);
	CarNeonView* v = &g_sceneNeonView;
	memcpy(v->eye, eye, sizeof(v->eye));
	memcpy(v->right, r, sizeof(v->right));
	memcpy(v->up, u, sizeof(v->up));
	memcpy(v->fwd, f, sizeof(v->fwd));
	const float ty = tanf(g_feCam.cur.vfov * ((float)M_PI / 360.0f));
	const float tx = ty * C3D_AspectRatioTop;
	v->pxX = 200.0f / tx;
	v->pxY = 120.0f / ty;
	v->fov = (u16)(2.0f * atanf(tx) * (65536.0f / (2.0f * (float)M_PI)) + 0.5f);
	return true;
}

// --------------------------------------------------------------- the world
//
// TASKS.md #132/#116. The real L4RA world, paged section by section out of
// nfsu2data/TRACKS/L4RA the way retail pages STREAML4RA.BUN -- world.c is the
// pager, tools/track_pack.py wrote both the sections and the WORLD.NFSX index
// it reads -- with the car driven across it by carsim.c off the selected
// record's own drivetrain and rigid body.
//
// The loaded track set (#271): TrackInfo +0x40 of the track the world was
// entered for (trackdb.h) -- "L4RA", the city, unless a race on another set
// opened it. Every track file is formatted with it, as SPEED2.EXE formats
// TRACKS\%s.BUN, TRACKS\STREAM%s.BUN and Tracks\Routes%s\... off the loading
// track's record (0x57DD4B, 0x57A5A8, 0x57F40E..0x57F56C).
static char g_region[8] = "L4RA";
// TheRaceParameters +0 (the track) and +4 (eTrackDirection, reversed) as the
// world load reads them, set with g_region (worldPickRegion()): the world
// animations' race gate and FwdRev tree (#239) are made from them.
static int g_worldTrack = 4000;
static bool g_worldReversed = false;
#define WORLD_TRACK_DIR_FMT   "TRACKS/%s"
// The retail resident track file, copied as-is: world.c reads its
// visible-section tables (#191).
#define WORLD_TRACK_BUN_FMT   "TRACKS/%s.BUN"
// Retail's free-roam trigger polygons, also copied as-is (#214). Optional in
// exactly the way L4RA.BUN is: without it the world still drives, it just has
// no events, shops, banks or neighbourhood names under the car.
#define WORLD_TRACK_PATHS_FMT "TRACKS/ROUTES%s/PathsFreeRoam.bin"
// The GPS's road graph, beside them.
#define WORLD_TRACK_ROUTES_FMT "TRACKS/ROUTES%s/RoutesFreeRoam.bin"

// buildGamePath() of one of the loaded set's files, `fmt` taking the set.
static bool regionPath(const Config* cfg, const char* fmt, char* out, size_t cap) {
	char rel[96];
	snprintf(rel, sizeof(rel), fmt, g_region);
	return buildGamePath(cfg, rel, out, cap);
}

// Exposure. The sections carry the retail baked vertex lighting, same as the
// frontend rooms, so these are scene.v.pica's own controls: the shader's term
// is min(1, baked^INV_GAMMA * GAIN + AMBIENT), and the texture is modulated
// by it.
//
// Two recalibrations got here. The first pair -- ambient 0.55, gain 1.15 --
// was set against the dark road art that preceded #136's grey, and clipped
// 24% of the world's vertices to flat white while lifting the darkest corners
// to over half brightness. The second -- 0.40/0.95 -- halved the damage but
// kept its shape, because an additive lift is the wrong instrument: whatever
// it is set to, the output floor is the lift, and a night city with a floor
// of 0.40 is an evenly grey street by construction.
//
// So this pair does not lift at all. Sampling 38023 baked vertices across 40
// L4RA sections gives p10 0.059, median 0.212, p90 0.678 -- the art has the
// whole range in it, and 3.0% of it is already black. Through 0.40/0.95 that
// became p10 0.456, median 0.602, an 11.5% clipped fraction and a 2.19:1
// range. Through a gamma it becomes p10 0.207, median 0.423, 2.2% clipped and
// 3.89:1 -- nearly double the contrast for a fifth of the clipping, and since
// x^k maps 0 to 0 the unlit corners are finally allowed to be unlit.
//
// 1/1.8 rather than the usual 1/2.2 because 2.2 flattens the midtones further
// than this art wants (3.04:1 against 3.89:1 for the same 2.2% clipped). The
// 0.02 floor is not an exposure control -- it is there so a surface with no
// baked light at all still shows its texture rather than reading as a hole.
//
// The sky and the car shadow are drawn through these same numbers and are
// unaffected: both are authored with white vertex colour, and 1^k = 1.
#define WORLD_AMBIENT      0.02f
#define WORLD_GAIN         0.98f
#define WORLD_INV_GAMMA    (1.0f / 1.8f)

// The frontend rooms keep the plain lift-and-gain they were tuned against.
#define SCENE_INV_GAMMA    1.0f

// Chase camera: retail's CubicCameraMover, see worldCamera(). The near plane is
// Camera+0xBC as Update 0x80071D3C sets it for every outside view. The far
// plane is long because a section's own skyline shells stand hundreds of metres
// out (see world.c's note on the big bounding boxes).
#define WORLD_NEAR         0.5f
// Was 700, sized to a 520 m draw radius. It only has to clear DRAW_RADIUS plus
// the skydome that sits at 80% of it, so it comes in with the radius -- which
// also buys back depth precision across the range that is actually drawn, the
// near field where z-fighting on road decals would show.
#define WORLD_FAR        560.0f
// The PC's player-view widening (SPEED2.EXE 0x5C7F79): the horizontal angle is
// the camera's times WIDEN (0x7A27DC), the vertical one the camera's times
// WIDEN / YDIV (0x7A27E0, 0x7A27D8) times the viewport's height over width.
#define WORLD_VIEW_WIDEN   1.1f
#define WORLD_VIEW_YDIV    0.8695652f

// ------------------------------------------------ sky, fog and shadow (#148)
//
// Without these three the world reads as a lit street floating in a void: the
// pager's DRAW_RADIUS is a hard edge into black, the upper half of the frame
// is black wherever a building does not cover it, and the car hovers as soon
// as the camera gets low.
//
// The dome is the retail SKYDOME (tools/sky_pack.py), a unit hemisphere drawn
// centred on the *camera* -- not on the car -- with depth off, so its size is
// free to be whatever sits comfortably inside the far plane. Its base sits at
// eye level, which puts the horizon band on the horizon; everything below that
// line is the clear colour, and the clear colour is the fog colour, so the
// ground plane runs out into the same haze the sky meets.
#define WORLD_SKY_RADIUS  (WORLD_FAR * 0.80f)

// The horizon colour of SKY_NIGHT_A's bottom rows, as measured by
// sky_pack.py's horizon_rgb(). Used for the fog, for the clear, and so for
// every pixel of the frame that is neither sky nor world.
#define WORLD_FOG_RGB      0x243044u

// exp(-(density*z)^gradient). Tuned so the fog is ~97% at world.c's
// DRAW_RADIUS -- a section reaches the edge of the draw radius already the
// colour of the horizon, which is the whole point -- while leaving the first
// hundred metres close to clear.
//
// Moved with DRAW_RADIUS when that came in from 520 m to 400 m for the frame
// cost (see the comment there). Solving exp(-(d*400)^2) = 0.03 gives
// d*400 = 1.872, i.e. 0.00468; at 100 m that is still only 22% fogged, so the
// near field is as clear as it was.
#define WORLD_FOG_DENSITY  0.00468f
#define WORLD_FOG_GRADIENT 2.0f

// The car's blob shadow (tools/shadow_pack.py): a unit disc scaled by the real
// body box -- cardb.h's CarChassis carries every car's box to the centimetre --
// and lifted clear of the road surface.
//
// PORT: this is a blob under the car, not a projection of it, because there is
// no light rig in the world to project from yet. The spread is a fraction of
// the body's HALF extents and is a little over 1 on purpose: the ramp's alpha
// is already zero at the rim, so the visible blob is a good deal smaller than
// the disc it is painted on. The lift is the smallest value that stops the
// disc z-fighting the tarmac it lies on.
#define WORLD_SHADOW_SPREAD 1.05f
#define WORLD_SHADOW_LIFT   0.06f

// The car's collision footprint. It is the record's own body box, but taken at
// less than full size: the box spans the bodywork including mirrors and
// bumpers, and a footprint that wide catches on doorways the car visibly fits
// through. The height band is unchanged from the circle days.
//
// BODY_LO is the floor of the band, and it exists so that a face the car is
// meant to ride over is not also a wall that stops it. That rule is right. It
// used to be enforced by setting the floor to the ground probe's headroom,
// 1.2 m, on the reasoning that anything the probe would let the car climb -- a
// kerb, a driveway lip, the sloped foot of a ramp -- has to stay out of the
// band. 1.2 m is the wrong way to enforce it, and it is what the user hit with
// "no bounding? I clipped through this" (TASKS.md #180):
//
//   - The ordering already protects the climb. carsim_step() runs the ground
//     probe BEFORE this test and snaps pos[2] straight up to whatever it found
//     ("a ramp: the road came up to meet the wheels"), so by the time a kerb is
//     tested the car is standing on top of it and the kerb face is at or below
//     from[2] -- out of the band for any positive floor. The floor only has to
//     clear the sub-decimetre steps where two road tiles meet.
//   - Meanwhile 1.2 m is taller than most of what the city fences itself off
//     with, so the car drove through it. Measured over 521 sampled road points
//     in 14 sections, splitting steep faces by whether anything standable sits
//     on top of them: the climbable population (seams, kerbs, lips) ends by
//     0.3 m, and the barrier population (fences, railings, low walls) starts at
//     0.3 and peaks at 0.6-0.8 m. At a 1.2 m floor 50.8% of barriers were
//     intangible; at 0.35 m, 7.5% are. The ornate iron railing the user clipped
//     through in C59 tops out 1.1 m over the pavement.
//
// BODY_HI is roof height, so the band ends below an awning or a sign gantry the
// car is supposed to drive under.
#define WORLD_FOOTPRINT        0.92f   // fraction of the record's body box
#define WORLD_BODY_LO      0.35f               // m above the contact point
#define WORLD_BODY_HI      3.0f                // m above the contact point

// Both the D-pad and the circle pad drive, so the same run is reachable from a
// scripted PostMessage test (which can only send buttons) and from a console.
#define WORLD_STICK_DEAD    24     // circle pad units
#define WORLD_STICK_FULL 156.0f

static World* g_world = NULL;

// The NIS people's ground (#483): TopologyCoordinate::GetElevation under the
// person's bone 1, asked on the car's topology a little over the bone so a
// person on rising ground still finds the surface above the scene's plane.
#define CROWD_GROUND_HEADROOM 2.5f
static bool crowdGroundZ(const float p[3], float* outZ) {
	return g_world && world_ground_z(g_world, p, CROWD_GROUND_HEADROOM, outZ);
}
static Crowd* crowdLoad(const char* path) {
	crowd_ground_source(crowdGroundZ);
	return crowd_load(path, dlog);
}
// CBasicCharacterAnimEntity::RenderEffects (#497): each person crowd_draw()
// just drew gets a CHARACTERSHADOW quad under the feet.
static void crowdShadowsDraw(Crowd* c, const C3D_Mtx* vp) {
	const Tex3DS_SubTexture* sub = NULL;
	const C3D_Tex* tex = crowd_shadow_tex(c, &sub);
	if (!tex)
		return;
	static float quad[128][4][3];
	const int n = crowd_shadow_quads(c, quad, 128);
	carshadow_draw_quads(tex, sub, vp, (const float (*)[4][3])quad, n);
}
