// WORLD.NFSL, open while the world is. NULL lights a car by its rig alone.
static LightDb* g_lightDb = NULL;
// The event manager's triggers (#298, emevents.h): TRACKS/L4RA/WORLD.NFSE,
// open while the world is. NULL sets nothing off: no roadside wooshes.
static EmEvents* g_emEvents = NULL;
// The props a car knocks over (#318, smokeable.h): TRACKS/L4RA/WORLD.NFSK,
// open while the world is. NULL: the cars pass through the barrels and signs.
static Smokeables* g_smokeables = NULL;
// The world animations (#239, worldanim.h): TRACKS/L4RA/WORLD.NFSW, open
// while the world is. NULL: the jets, trains, cranes and spotlights are not
// drawn.
static WorldAnims* g_worldAnims = NULL;

// world_draw()'s one prop callback: the loose props (#318), then the world
// animations' models (#239, RenderWorldModels).
static void worldPropDraw(const World* w, const C3D_Mtx* vp, float ambient, float gain,
		float invGamma, void* ud) {
	(void)ud;
	if (g_smokeables)
		smokeable_draw(w, vp, ambient, gain, invGamma, g_smokeables);
	worldanim_draw(g_worldAnims, w, vp, ambient, gain, invGamma);
}
