static EnvMap* g_envMap = NULL;
static int     g_dbgEnvMap = 0;
static float   g_envMs = 0.0f;
// The rear-view mirror (#501, rvm.h): made beside the env map and kept; up
// this frame, what it cost and the scenery triangles it drew.
static Rvm*    g_rvm = NULL;
static bool    g_rvmOn = false;
static float   g_rvmMs = 0.0f;
static u32     g_rvmTris = 0;
