static Reflection* g_reflection = NULL;
static bool    g_reflOn = false;
static float   g_reflMs = 0.0f;
static u32     g_reflTris = 0, g_reflMirrors = 0, g_reflBatches = 0;
// EnvMapEyeOffset: the env camera stands this far over the car's position
// (UpdateEnvironmentMapCameras).
#define WORLD_ENV_EYE_LIFT 0.95f

// The frontend car's reflection: the same capture with the room in the faces.
// eDataRender (Speed.elf 0x803118b8) gives the frontend car
// CARSELECTENVMAP, and TheOnlyEnvMap's sphere map when that is missing --
// as it is from every retail build's data -- and with no world car
// UpdateEnvironmentMapCameras stands the env eye over the frontend car. So
// on PC the garage's lights are in the paint and the CARBONFIBRE trim, which
// the DEFAULT material reflects at 2.0, reads silver rather than its dark
// weave. The faces are turned the way SPEED2.EXE's frontend car reads its
// cube (envmap.c, #312). g_envFeScene is the room the faces hold: another
// room, or the world's faces after a drive, starts a whole new capture.
static const Model3D* g_envFeScene = NULL;
static float g_envFeYaw = 0.0f;
// How many more frames' faces the sphere map is owed (#319): six from the
// last move, one face a frame. Held still, it is whole and nothing in it
// changes, so the capture stops until the car turns or another room or car
// comes in.
static int g_envFeOwed = 0;
static float g_envFeCarZ = 0.0f;

// Made outside a frame, from syncCarModel(), and kept for the world.
static void feEnvOpen(const Config* cfg) {
	if (g_envMap || cfg->dbgEnvMap == 1)
		return;
	g_envMap = envmap_create(dlog);
}

static u32 feEnvFace(void* ctx, const C3D_Mtx* vp, const float eye[3], const float fwd[3]) {
	(void)eye;
	(void)fwd;
	model3d_draw_scene_turned((const Model3D*)ctx, vp, g_envFeYaw, SCENE_CAR_AMBIENT,
		SCENE_CAR_GAIN, SCENE_INV_GAMMA);
	return 0;
}

// Inside the frame, before the top screen's room: the faces from over the
// car standing at `carPos` (its model origin), in the frame of the top
// screen's camera, then the sphere map -- or nothing at all when the last six
// frames' faces already hold the room as it stands (the car keeps the sphere
// map it has), unless `live`. Leaves no target bound when it draws.
static void feEnvRender(const Model3D* scene, const float carPos[3], float discYaw,
		bool live) {
	if (!g_envMap || !scene)
		return;
	if (g_envFeScene != scene) {
		envmap_set_schedule(g_envMap, 1);
		envmap_reset(g_envMap);
		g_envFeScene = scene;
		g_envFeOwed = 6;
	}
	if (discYaw != g_envFeYaw || carPos[2] != g_envFeCarZ)
		g_envFeOwed = 6;
	if (!g_envFeOwed && !live)
		return;
	if (g_envFeOwed)
		g_envFeOwed--;
	g_envFeYaw = discYaw;
	g_envFeCarZ = carPos[2];
	const float camEye[3] = { SCENE_DISC_X, SCENE_DISC_Y - SCENE_CAR_DIST, SCENE_CAR_EYE_Z };
	const float envEye[3] = { carPos[0], carPos[1], carPos[2] + WORLD_ENV_EYE_LIFT };
	envmap_render_with(g_envMap, feEnvFace, (void*)scene, camEye, envEye, true);
}
// Every car's head- and tail-light this frame, as UpdateCarDynamicLights
// poses them, and whose they are: 0 the player's, k + 1 the field's car k,
// CAR_DYN_TRAFFIC + k traffic car k. g_litCar is the car being drawn, whose
// own lights its query leaves out (CarRenderInfo::Render takes its pack out
// of the list first).
#define CAR_DYN_TRAFFIC (1 + OPPONENT_MAX)
#define CAR_DYN_MAX ((1 + OPPONENT_MAX + TRAFFIC_MAX) * CARLIGHTS_DYNAMIC)
static LightDbLight g_carDyn[CAR_DYN_MAX];
static s8 g_carDynOwner[CAR_DYN_MAX];
static int g_carDynCount = 0;
static int g_litCar = -1;
// The flag girl's flares' lights (#497, FlagGirlFlareEffect's eDynamicLightPack:
// an omni light at each flare while it burns), raceNisFlares().
#define FLARE_DYN_MAX 4
static LightDbLight g_flareDyn[FLARE_DYN_MAX];
static int g_flareDynCount = 0;
// How many lights the player's car took last frame, for the pager line.
static int g_playerLit = 0;

static bool lightSectionLoaded(int section, void* ud) {
	return world_section_loaded((const World*)ud, section);
}

// QueryLightDatabase for the car being drawn (model3d.h's light query): the
// lamps of the sections that are loaded, then every other car's lamps.
static int carWorldLights(const float pos[3], Model3DCarLight* out, int max, void* ud) {
	(void)ud;
	LightDbQuery q;
	lightdb_query_reset(&q);
	lightdb_query_static(&q, g_lightDb, pos, lightSectionLoaded, g_world);
	for (int i = 0; i < g_carDynCount; i++)
		if (g_carDynOwner[i] != g_litCar)
			lightdb_query_light(&q, &g_carDyn[i], pos);
	for (int i = 0; i < g_flareDynCount; i++)
		lightdb_query_light(&q, &g_flareDyn[i], pos);
	const int n = q.n < max ? q.n : max;
	for (int i = 0; i < n; i++) {
		memcpy(out[i].pos, q.light[i]->pos, sizeof(out[i].pos));
		lightdb_hit_colour(&q, i, pos, out[i].rgb);
	}
	if (g_litCar == 0)
		g_playerLit = n;
	return n;
}
// The world's two pieces of dressing, loaded from the same directory as the
// sections and owned for as long as the world is open. Either may be NULL --
// an install whose tools/sky_pack.py and tools/shadow_pack.py have not been
// run still drives, it just drives in a void again.
static Model3D* g_sky = NULL;
static Model3D* g_shadow = NULL;
// MARKER_GPS_AID, the arrow Player::RenderGPSArrow hangs over the car while the
// GPS has a path (gps.h, tools/gps_arrow_pack.py). Optional like the two above.
static Model3D* g_gpsArrow = NULL;
// PORT (#471, the user's own): the profile's GPS colour on the arrow. Its
// colour is all in the baked vertex colours (both its textures are grey), so
// a colour other than retail's turns each vertex's hue by the colour's hue
// less retail's blue and scales its saturation and value by the colour's:
// the body's shading ramp and the glow's cyan lean survive, and Blue gives
// back the baked colours exactly. g_gpsArrowCol keeps those; g_gpsArrowTint
// is the index last written, -1 none.
static float* g_gpsArrowCol = NULL;
static int    g_gpsArrowTint = -1;

static void gpsRgbToHsv(const float c[3], float* h, float* s, float* v) {
	const float mx = fmaxf(c[0], fmaxf(c[1], c[2])), mn = fminf(c[0], fminf(c[1], c[2]));
	const float d = mx - mn;
	*v = mx;
	*s = mx > 0.0f ? d / mx : 0.0f;
	if (d <= 0.0f) {
		*h = 0.0f;
		return;
	}
	float hh = (mx == c[0]) ? (c[1] - c[2]) / d
		: (mx == c[1]) ? 2.0f + (c[2] - c[0]) / d
		: 4.0f + (c[0] - c[1]) / d;
	hh *= 60.0f;
	*h = hh < 0.0f ? hh + 360.0f : hh;
}

static void gpsHsvToRgb(float h, float s, float v, float out[3]) {
	h = fmodf(h, 360.0f);
	if (h < 0.0f)
		h += 360.0f;
	const float c = v * s, x = c * (1.0f - fabsf(fmodf(h / 60.0f, 2.0f) - 1.0f)), m = v - c;
	float r, g, b;
	switch ((int)(h / 60.0f) % 6) {
	case 0:  r = c; g = x; b = 0; break;
	case 1:  r = x; g = c; b = 0; break;
	case 2:  r = 0; g = c; b = x; break;
	case 3:  r = 0; g = x; b = c; break;
	case 4:  r = x; g = 0; b = c; break;
	default: r = c; g = 0; b = x; break;
	}
	out[0] = r + m;
	out[1] = g + m;
	out[2] = b + m;
}

static void gpsArrowTint(int index) {
	if (!g_gpsArrow || index == g_gpsArrowTint)
		return;
	u8* vp = (u8*)model3d_vertex_dest(g_gpsArrow);
	const int n = model3d_vertex_count(g_gpsArrow);
	if (!vp || n <= 0)
		return;
	if (!g_gpsArrowCol) {
		g_gpsArrowCol = (float*)malloc(sizeof(float) * 3 * (size_t)n);
		if (!g_gpsArrowCol)
			return;
		for (int i = 0; i < n; i++)
			memcpy(&g_gpsArrowCol[i * 3], vp + i * MODEL3D_VERTEX_BYTES + 12, sizeof(float) * 3);
	}
	g_gpsArrowTint = index;
	const u32 ref = options_gps_colour_rgb(0), want = options_gps_colour_rgb(index);
	const float refC[3] = { ((ref >> 16) & 0xFF) / 255.0f, ((ref >> 8) & 0xFF) / 255.0f,
		(ref & 0xFF) / 255.0f };
	const float wantC[3] = { ((want >> 16) & 0xFF) / 255.0f, ((want >> 8) & 0xFF) / 255.0f,
		(want & 0xFF) / 255.0f };
	float rh, rs, rv, wh, ws, wv;
	gpsRgbToHsv(refC, &rh, &rs, &rv);
	gpsRgbToHsv(wantC, &wh, &ws, &wv);
	for (int i = 0; i < n; i++) {
		float* dst = (float*)(vp + i * MODEL3D_VERTEX_BYTES + 12);
		const float* org = &g_gpsArrowCol[i * 3];
		if (want == ref) {
			memcpy(dst, org, sizeof(float) * 3);
			continue;
		}
		float h, s, v;
		gpsRgbToHsv(org, &h, &s, &v);
		gpsHsvToRgb(h + (wh - rh), fminf(1.0f, s * ws / rs), fminf(1.0f, v * wv / rv), dst);
	}
	GSPGPU_FlushDataCache(vp, (u32)n * MODEL3D_VERTEX_BYTES);
}
