static Minimap* g_minimap = NULL;

// Free roam is Location4's own track record: "(40XX-41XX) Circuit/Sprint",
// path Location4\Track_4000, the one the whole 40XX/41XX family hangs off. It
// is also the id whose TRACKMAP4000.BIN is the plain Bayview city map, which
// is exactly what a free-roam minimap wants -- every other Location4 record
// carries the same art origin/span (checked across all 67 of them) but its own
// route drawn on top.
#define MINIMAP_FREEROAM_TRACK 4000
static float  g_worldPos[3] = { 0.0f, 0.0f, 0.0f };
static float  g_worldYaw = 0.0f;   // 0 = facing world +X, the car model's front

// ------------------------------------------------- per-area screen tint (#253)
//
// Why the stadium looks warmer and brighter than the rest of the city: retail
// grades the whole finished frame, sky included, by a colour picked from where
// the car is. The tint comes out of L4RA.BUN's ParameterMaps (parammaps.h), and
// it is the one per-area effect that is visible on the GameCube. The per-area
// fog in the same file only reaches eClearHorizon, which is drawn during a
// horizon transition and not in normal play.
//
// The chain, Speed.elf:
//   UpdateAllScreenEmotion (0x8020CB6C) adds SE_PaletteFile's palette 2 every
//   frame, a type-3 effect whose function is Unique (0x8020CD48). Unique reads
//   UniqueFXAccessorNight and UniqueFXAccessorSunrise at the car's XY, each a
//   ParameterAccessorBlendByDistance captured with a distance of 50.0. It
//   blends them by GetSunPercent (0x80241B4C), which is HorizPercentThru, 0
//   all game, so the result is the Night layer. Fields 0..2 land in
//   ScreenEffectDB+0x178..0x180.
//   eDisplayFrame copies those into ScreenTint, and eScreenQuadReplace(0x6F)
//   draws psScreenContrast (0x801E5E48) over the frame. Its nine TEV stages,
//   with T the tint/255, L the luma of a half-res capture of the frame, S a
//   saturation term built from the capture's R-L, G-L and B-L, and a small
//   contrast-ramp read, come to
//
//       colour = T * (1 - S) + ramp        alpha = 0x80/255 + L
//
//   blended as GXSetBlendMode(BLEND, DSTCLR, SRCALPHA), i.e.
//
//       frame = frame * (colour + alpha)
//
// The PICA200 has that exact blend: source factor DST_COLOR, destination
// factor SRC_ALPHA. So this is the same full-screen pass, one quad.
//
// PORT: the quad is flat. S, L and the ramp are per-pixel in retail and need
// a capture of the frame to read back, so they are held at a typical night
// frame's values instead. The multiplier is then divided by the neutral
// tint's (grey 128, set 0), because the port's exposure (WORLD_GAIN and
// WORLD_INV_GAMMA) was set without this pass. What carries over is how each
// area differs from neutral. The stadium's set 8, (255, 144, 10), gives
// (1.39, 1.05, 0.64) per channel. City Core's set 6, (56, 34.5, 140), gives
// (0.78, 0.72, 1.04).
#define TINT_LAYER      "Night Screen Tint"
#define TINT_BLEND_DIST 50.0f    // Unique's CaptureData distance
#define TINT_SAT        0.15f    // S
#define TINT_LUMA       0.15f    // L
#define TINT_RAMP       0.02f    // the two ramp reads, 0.5 each

static ParamMaps*    g_pmaps = NULL;
static ParamAccessor g_tintNight;
// The horizon fog's intensity (hfog.h), hfogFrameUpdate()'s.
#define HFOG_LAYER      "Horizon Fog Visibility"
static ParamAccessor g_hfogVis;
static u8   g_tintRgb[3];   // this frame's quad, screenTintUpdate()'s
static bool g_tintOn;       // and whether it is anything but neutral

// Once a frame, before the 2D pass: where the car is, and the quad's colour.
static void screenTintUpdate(void) {
	g_tintOn = false;
	// g_TintingEnable (#326): FUN_005caad0 sets the tint's flag, 0x8707D1,
	// only with it on and a tint to draw.
	if (!g_tintNight.layer || !g_display.b.tinting)
		return;
	paramaccessor_capture(&g_tintNight, g_worldPos[0], g_worldPos[1], TINT_BLEND_DIST);
	const float k = 1.0f - TINT_SAT;
	const float c = 0x80 / 255.0f + TINT_LUMA + TINT_RAMP;
	const float neutral = k * (128.0f / 255.0f) + c;
	u8 rgb[3];
	bool identity = true;
	for (int i = 0; i < 3; i++) {
		float t = g_tintNight.values[i] / 255.0f;
		if (t < 0.0f) t = 0.0f;
		if (t > 1.0f) t = 1.0f;
		// The multiplier, as colour + alpha with alpha fixed at 0x80.
		const float m = (k * t + c) / neutral;
		float v = m * 255.0f - 128.0f + 0.5f;
		if (v < 0.0f) v = 0.0f;
		if (v > 255.0f) v = 255.0f;
		rgb[i] = (u8)v;
		if (rgb[i] != 127 && rgb[i] != 128)
			identity = false;
	}
	// One line per area entered, so a log says which set a screenshot is in.
	static int lastSet = -1;
	const int set = parammaps_set_at(g_tintNight.layer, g_worldPos[0], g_worldPos[1]);
	if (set != lastSet) {
		char b[160];
		snprintf(b, sizeof(b), "tint: set %d at %.0f,%.0f -- target %.0f,%.0f,%.0f "
			"(now %.0f,%.0f,%.0f, quad %u,%u,%u)", set, g_worldPos[0], g_worldPos[1],
			parammaps_field(g_tintNight.layer, set, 0),
			parammaps_field(g_tintNight.layer, set, 1),
			parammaps_field(g_tintNight.layer, set, 2),
			g_tintNight.values[0], g_tintNight.values[1], g_tintNight.values[2],
			rgb[0], rgb[1], rgb[2]);
		dlog(b);
		lastSet = set;
	}
	memcpy(g_tintRgb, rgb, sizeof(g_tintRgb));
	g_tintOn = !identity;
}

// Straight after the 2D pass's C2D_SceneBegin on the top screen: over the
// finished 3D frame, under the HUD, as eDisplayFrame orders it. Once an eye
// in stereo (stereo.h): it multiplies what is under it, so it cannot go in
// the 2D's overlay.
// Over a w x h target: the top screen's, or the photo shoot's grab strip.
static void screenTintDrawRect(float w, float h) {
	if (!g_tintOn)
		return;
	C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_DST_COLOR, GPU_SRC_ALPHA,
		GPU_ZERO, GPU_ONE);
	C3D_DepthTest(false, GPU_ALWAYS, GPU_WRITE_COLOR);
	C2D_DrawRectSolid(0.0f, 0.0f, 0.0f, w, h,
		C2D_Color32(g_tintRgb[0], g_tintRgb[1], g_tintRgb[2], 0x80));
	// citro2d only issues the quad on a flush, and the blend is read then.
	C2D_Flush();
	C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_SRC_ALPHA,
		GPU_ONE_MINUS_SRC_ALPHA, GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA);
}

static void screenTintDraw(void) {
	screenTintDrawRect(400.0f, 240.0f);
}

// The rain's haze (#315): Rain::UpdateAndRender's AddScreenEffect(2), drawn
// as PC's FUN_005C7860 does (rain.h): a 2x modulate over the frame (src *
// dst + dst * src), colour writes only, before the tint. Its colour is
// CalculateFogInfo's: the Normal Fog set's, moved toward the Night Raining
// Fog set's by the intensity (#407; WORLD_FOG_RGB only without the layer).
static void rainHazeDrawRect(float w, float h) {
	u8 rgb[3];
	if (!rain_haze(WORLD_FOG_RGB, rgb))
		return;
	C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_DST_COLOR, GPU_SRC_COLOR,
		GPU_ZERO, GPU_ONE);
	C3D_DepthTest(false, GPU_ALWAYS, GPU_WRITE_COLOR);
	C2D_DrawRectSolid(0.0f, 0.0f, 0.0f, w, h, C2D_Color32(rgb[0], rgb[1], rgb[2], 0xFF));
	C2D_Flush();
	C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_SRC_ALPHA,
		GPU_ONE_MINUS_SRC_ALPHA, GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA);
}

// The photo shoot's flash (#268 B): ShowcaseState::MakeCameraFlash
// (0x8012B384) adds SE_PaletteFile's palette 1 to the player's view. Its one
// effect is CurveAll (type 0, control 3): white at 0x80, scaled by 1, 1, 1,
// 0.7, 0.3, 0.1 (0x8036FDBC) over ScreenEffectDB::Update's (0x8020C6B4) six
// steps, one a frame, then switched off.
// PORT: what reads the effect back (the DB's slot 0, +0x70..+0x80) was not
// found. The colour over the frame at 0x80 times the step's intensity is
// assumed, drawn with the tint: over the 3D frame, under the HUD and the UI.
static const float kFlashCurve[6] = { 1.0f, 1.0f, 1.0f, 0.7f, 0.3f, 0.1f };
static int g_flashStep = -1;   // -1: no flash

// Once an eye in stereo, with the tint; `last` for the frame's last, which
// steps the curve.
static void cameraFlashDraw(bool last) {
	if (g_flashStep < 0)
		return;
	const u8 a = (u8)(0x80 * kFlashCurve[g_flashStep] + 0.5f);
	C3D_DepthTest(false, GPU_ALWAYS, GPU_WRITE_COLOR);
	C2D_DrawRectSolid(0.0f, 0.0f, 0.0f, 400.0f, 240.0f, C2D_Color32(255, 255, 255, a));
	C2D_Flush();
	if (!last)
		return;
	if (++g_flashStep >= 6) {
		g_flashStep = -1;
		dlog("flash: camera flash (palette 1) -- 6 frames drawn, alpha 128 to 13");
	}
}

// The free-roam trigger polygons and what is under the car right now (#214).
// Retail keeps the same four answers: PlayerCareerState::CanWeEngage reads a
// CareerEventData*, a WorldChallengeData*, a ShopDataDesc* and a ShowcaseData*
// from fixed slots (+0x7E08..+0x7E14), each one set by NotifyEnterTriggerZone
// and cleared by NotifyExitTriggerZone. The port holds the zones themselves
// rather than the records, because resolving a zone's handle to a career
// record is E4's job and the widget only needs to know something is there.
static TrackPaths* g_paths = NULL;
static const TrackPathZone* g_zoneRace = NULL; // RACE_START_TRIGGER, D-pad Up
static const TrackPathZone* g_zoneShop = NULL; // SHOP_TRIGGER
// How many zones the car was standing in this frame whose handle resolved to
// nothing, so the search walked past them (PlayerCareerState::IsEnterable --
// see the search itself). Telemetry only: a nonzero count beside a "-" zone
// is a trigger polygon that is still in the file for an event that is done.
static int g_zoneSkipped = 0;
static const TrackPathZone* g_zoneHood = NULL; // NEIGHBOURHOOD, the area name
// Player +0x234, the wrong-way flag: last frame's answer, which this frame's
// DetectWrongWay is given so the cue does not flicker on its own edge.
static bool g_wrongWay = false;
// The shop table (eventdb.h), which is what turns a SHOP_TRIGGER's handle into
// an icon. File-scope static rather than a local or a malloc: EventDb is ~12 KB,
// too much for a stack, and its lifetime is simply the world's.
static EventDb g_shops;
static bool g_shopsOk = false;

// PlayerCareerState::IsShopEnterable (Speed.elf 0x801243B8), forward-declared
// up beside perfBuildCtx() because the performance unlock table's SHOP kind
// asks it about a shop handle (the vinyls' and the parts' shop unlocks).
// The frontend's copy of the shop table, for a shop screen walked into out of
// the world, whose teardown lets the world's go (g_shopsOk): IsShopEnterable
// reads the same GLOBALB.BUN records either way. Read once.
static const Config* g_cfgMain = NULL;
static EventDb g_feShops;
static int g_feShopsState = 0;   // 0 not tried, 1 read, -1 unreadable

static bool perfShopEnterable(void* user, u32 shopHandle) {
	(void)user;
	const EventDb* db = g_shopsOk ? &g_shops : NULL;
	if (!db && g_feShopsState == 0 && g_cfgMain) {
		char bunPath[560];
		g_feShopsState = buildGamePath(g_cfgMain, "GLOBAL/GLOBALB.BUN", bunPath, sizeof(bunPath)) &&
			eventdb_load(bunPath, &g_feShops) ? 1 : -1;
		dlog(g_feShopsState > 0 ? "shops: frontend copy of the shop table read for IsShopEnterable"
			: "shops: frontend copy of the shop table UNREADABLE");
	}
	if (!db && g_feShopsState > 0)
		db = &g_feShops;
	if (!db)
		return false;
	const ShopRec* s = eventdb_shop_by_handle(db, shopHandle);
	if (!s) {
		char b[96];
		snprintf(b, sizeof(b), "shops: IsShopEnterable 0x%08X -- no such shop (%d in the table)",
			(unsigned)shopHandle, db->shopCount);
		dlog(b);
		return false;
	}
	// The career's stage (+0x71E4) has to have reached the shop's (+0x9D), and
	// a shop with needsEvent (+0x51) has to have been discovered -- its own
	// record's byte +4 at 1, which NotifyShopDiscovered writes as the car first
	// drives into its zone (careerNotifyShopDiscovered()).
	if (!gProfile.isLoaded || (int)gProfile.careerStage < (int)s->stage)
		return false;
	if (s->needsEvent) {
		bool found = false;
		for (u32 k = 0; k < gProfile.stateRecCount && k < (u32)PROFILE_NUM_STATE_RECORDS; k++)
			if (gProfile.stateRec[k].eventId == s->handle) {
				found = gProfile.stateRec[k].type == 1;
				break;
			}
		if (!found)
			return false;
	}
	// ShopDataDesc::IsShopUnlocked (0x80122044).
	switch (s->unlockKind) {
	case 0:
		return true;
	case 1:
		return profileHasCompletedEvent(s->unlockArg);
	case 2:
	case 3:
	case 4:
		return careerStageRacesWon(s->stage, s->unlockKind) >= (int)s->unlockArg;
	default:
		return false;
	}
}
// The shop the car is standing in, resolved once a frame beside g_zoneShop.
static const ShopRec* g_shopHere = NULL;

// The Engage widget's events (engage.h): what EventIndicator announces, and
