// The career event a RACE_START_TRIGGER currently offers, resolved the same
// way beside g_zoneRace. A start point is not one event: 65 of the shipped
// handles serve several, and which one is live depends on the career, so this
// is the career's EventPile's answer (careerFirstUnlockedEvent) rather than a
// handle lookup.
static const EventRec* g_eventHere = NULL;
// The career's own inputs to that query, taken from the loaded profile once
// when the world opens, because none of them changes while driving.
static EventProgress g_prog[PROFILE_NUM_STATE_RECORDS];
static int g_progCount = 0;

// WorldChallengeState (PlayerCareerState +0xC00, Speed.elf DAT_803B4CA4), the
// world challenge on (#268 K): +0x00 failed, +0x04 the clock in seconds,
// +0x08 the challenge, +0x118 the car's heading when it began (a u16 turn in
// retail, the radians it came from here) and +0x11C the state below. It is
// not part of the save: leaving for the frontend from the pause menu drops a
// challenge (NotifyExitingToFrontend), and so does the port.
typedef enum {
	WC_STATE_NONE = 0,
	WC_STATE_COUNTING,          // 1, the clock runs (Tick)
	WC_STATE_AT_GOAL_SHOP,      // 2, NotifyEnterShopTriggerArea
	WC_STATE_AT_GOAL_SHOWCASE,  // 3, NotifyEnterShowcase
	WC_STATE_SHOP_ENGAGED,      // 4, NotifyEngageShopTrigger
	WC_STATE_SUCCESS,           // 5, NotifyShowcasePictureTaken / NotifyUniqueChosen
	WC_STATE_FAILED,            // 6, NotifyFailedMission
	WC_STATE_FAILURE_ACCEPTED,  // 7, NotifyFailureAccepted
	WC_STATE_FAILURE_REJECTED,  // 8, NotifyFailureRejected: the retry
} WcState;
typedef struct {
	bool failed;
	float timer;
	const WorldChallengeRec* active;
	float carYaw;
	WcState state;
} WorldChallengeState;
static WorldChallengeState g_wc;
// GetTrackPathZoneData's (0x801240BC) other two answers for a
// RACE_START_TRIGGER, resolved beside g_eventHere: the showcase or the world
// challenge whose zone the car is in, when no event is.
static const ShowcaseRec* g_showcaseHere = NULL;
static const WorldChallengeRec* g_challengeHere = NULL;
// SetEngagingDialog(1) and RCMessage 0x11 without a button: a showcase's
// first visit and a failed challenge raise their dialog on their own. The
// world loop takes it as it takes D-Pad Up.
static bool g_engageRequested = false;
// A world way out an engage dialog's answer chose (the uniques walk-in), taken
// as the dialog's package goes.
static const char* g_engageLeaveTo = NULL;

// The race on, if any -- see raceStartTrack() for the flow.
typedef struct {
	bool on;
	const Config* cfg;
	Race race;
	const EventRec* ev;
	int track;            // which of ev->tracks is on
	float finishedSec;    // time since the car finished, while it has
	bool trackOver;       // raceTrackDone() has run; the post-race list is up
	bool rewardClaimed;   // HasAlreadyClaimedReward: the record was 1 already
	bool fromWorldMap;    // StartCareerEvent(ev, 1): IsPossibleToWinReward false
	// EventInProgressState's per-track RaceEventTrack, as much of it as
	// CalculateIfWon, GetPointsTotal and CalculateMarginOfVictory read: its
	// state (+0x14 -- 2 racing, 3 finished, 4 official), whether the player's
	// finish reason was 1 or 0xB, and each driver's finishing position, driver
	// 0 the player and k+1 field.car[k] (0 for a car that never started).
	u8 trackState[EVENTDB_MAX_EVENT_TRACKS];
	bool trackReasonOk[EVENTDB_MAX_EVENT_TRACKS];
	u8 trackPos[EVENTDB_MAX_EVENT_TRACKS][1 + OPPONENT_MAX];
	int drivers;          // the event's cars (+0x5C), the player included
	u32 carLabel[1 + OPPONENT_MAX]; // CAR_NAME_<name> per driver, this track
	float spawnPos[3];    // +0x7E40
	float spawnYaw;
	// The AI field RaceStarter builds behind the player (opponent.h). Rebuilt
	// per track, which is where retail runs AddCareerEventAIOpponents.
	OpponentField field;
	// Each car of the field's light flares (#296), by index into field.car,
	// and the seconds since its brake was last down -- what
	// UpdateBrakelightsState (0x80222ac8) keeps an AI car's brake lamp lit by.
	CarLights fieldLights[OPPONENT_MAX];
	float fieldBrakeSec[OPPONENT_MAX];
	// And its drop shadow and underglow (#296): RenderCars hands every car,
	// not only the player's, to CarRenderInfo::Render (0x80239018), which
	// draws the shadow grid under it and RenderNeon (0x802377f0) after it.
	CarShadow fieldShadow[OPPONENT_MAX];
	CarNeon fieldNeon[OPPONENT_MAX];
} RaceRun;
static RaceRun g_raceRun;
// Career free roam's racers (encounter.h, TASKS.md #268 H): g_raceRun.field
// holds their cars while no race is on.
static Encounter g_enc;
// The Outrun's share here (#268 H step 2): whether engage event 9 is up, as
// FEngHud::NotifyRandomEncounterCar last left it; whether the getaway was on
// last frame (NotifyBeginGetAway on its start); and the RaceOverMessage's
// 3 s after the player's finish, with what it shows.
static bool g_encOfferIcon;
static bool g_encGaWas;
typedef struct {
	bool  up;
	float sec;      // since EndGetAway
	bool  won;      // reason 6
	float raceSec;  // RacingCar +0x198
	int   purse;    // GetRandomEncounterPurse
} EncounterOver;
static EncounterOver g_encOver;
// Whether g_raceRun.field's cars are in the world: a race's, or free roam's
// racers.
static bool fieldLive(void) { return g_raceRun.on || g_enc.on; }
static const OpponentField* gmAiField(void) {
	return g_raceRun.on ? &g_raceRun.field : (g_enc.on ? g_enc.f : NULL);
}
static bool gmAiPoofed(int k) {
	return !g_raceRun.on && k >= 0 && k < ENCOUNTER_CARS && g_enc.poofed[k];
}
// Whether field car `o` is on the road this frame: built, drawn and collided
// with (a free-roam racer the manager has not placed is not).
static bool fieldCarOn(const Opponent* o) { return o->model && o->simReady && !o->inactive; }
// The field's cars drawn this frame at no level (too small on screen), A, B,
// C and D (world_car_lod), for the world log line.
static int g_carLodCount[5];
// The level each car's LOD search starts from, by g_CarLodLevel (+0x48):
// FUN_005d2850 sets 0x8A1C10/14 to 1 at Low and 0 at High, and FUN_006316d0
// hands them to every car's draw (FUN_00620ae0), which steps down from there
// while the car is too small on screen. So Low never draws a car's A.
static int carMinLod(void) { return g_display.b.carLod == 0 ? 1 : 0; }
// And g_LightGlowEnable's part in a car's lights: at 0 no flares (carlights.h).
static u32 carFlareFlags(void) { return g_display.b.lightGlow ? 0u : CARLIGHTS_NO_FLARES; }

// The field's models and what each car was given beside them.
// Each opponent's speed last frame, for its engine sound's speed gained.
static float g_aiSndLastSpeed[OPPONENT_MAX];

// What the skids, the drive-bys and the 3D positions read off a car
// (carsfx.h): its pose, the yaw and the steering, the pedals its driver gave
// it, and each wheel -- carsim numbers them as retail does, each with the
// topology's terrain under it (Wheel::CheckTerrain).
static void carSfxPose(CarSfxIn* c, const CarSim* s) {
	for (int k = 0; k < 3; k++) {
		c->pos[k] = s->pos[k];
		c->vel[k] = s->vel[k];
		c->fwd[k] = s->rot[0][k];
		c->left[k] = s->rot[1][k];
	}
	c->vfwd = s->vfwd;
	c->yaw = carsim_yaw(s);
	c->steerDeg = (float)s->steerU16 * (360.0f / 65536.0f);
	if (c->steerDeg >= 180.0f) c->steerDeg -= 360.0f;
	c->brake = s->brakeIn;
	c->ebrake = s->ebrakeIn;
	for (int w = 0; w < 4; w++) {
		const CarSimWheel* wh = &s->wheel[w];
		c->wheel[w].onGround = wh->onGround != 0;
		c->wheel[w].gripUse = wh->gripUse;
		c->wheel[w].slip[0] = wh->sndSlip[0];
		c->wheel[w].slip[1] = wh->sndSlip[1];
		c->wheel[w].terrain = wh->terrain;
	}
}

// What the opponents' sounds read off their cars this frame (carsfx.h),
// copy k car k; the count. The speed gained is over a 60 Hz step, as
// retail's Car +0x440 less its BeginMovement copy (+0x518) is.
static int raceAiSfxIn(CarSfxAiIn* out, float dt) {
	RaceRun* rr = &g_raceRun;
	if (!fieldLive()) return 0;
	int n = 0;
	for (int k = 0; k < rr->field.count && k < OPPONENT_MAX; k++) {
		Opponent* o = &rr->field.car[k];
		CarSfxAiIn* a = &out[n++];
		memset(a, 0, sizeof(*a));
		if (!o->simReady || o->inactive) {
			g_aiSndLastSpeed[k] = 0.0f;
			continue;
		}
		CarSim* s = &o->sim;
		const float speed = sqrtf(s->vel[0] * s->vel[0] + s->vel[1] * s->vel[1] +
			s->vel[2] * s->vel[2]);
		const int g = s->dtGear < 0 ? 0 : (s->dtGear > 9 ? 9 : s->dtGear);
		a->eng.speed = speed;
		a->eng.dSpeed = dt > 0.0f ? (speed - g_aiSndLastSpeed[k]) * (1.0f / 60.0f) / dt : 0.0f;
		g_aiSndLastSpeed[k] = speed;
		a->eng.steer = s->steerU16;
		a->eng.nitro = carsim_nos_on(s) != 0;
		a->eng.throttle = o->lastThr;
		// SFXCTL_AIPhysics +0xD8 (#497): IsPlayingEndNIS, or IsPlayingIntroNIS
		// before racing (stage 4) -- the scene's CAR_AUDIO events play.
		a->eng.nis = g_endNis.on || (g_introNis.on && rr->race.stage != RACE_STAGE_RACING);
		a->eng.gear = s->dtGear;
		a->eng.numGears = s->perf.numGears;
		a->eng.topSpeed = s->topSpeed;
		a->eng.upRpm = s->up[g];
		a->live = true;
		// The turbo's, nitrous' and skids' (the AICar state's SFX 2, 3, 5).
		a->car.nosLevel = carsim_nos_on(s);
		a->car.throttle = o->lastThr;
		a->car.speed = speed;
		carSfxPose(&a->car, s);
	}
	return n;
}

static void raceFieldFree(RaceRun* rr) {
	// What freeing a field gives back (#413: the testers' Street X field
	// loaded with linear down to 1.7 MB).
	dbgLinearRelease();
	const u32 linBefore = (u32)linearSpaceFree();
	const int had = rr->field.count;
	encounter_close(&g_enc);   // free roam's racers live in the same field
	carsfxAiShutdown();   // their engine sounds (CSTATEMGR_AICar's states)
	memset(g_aiSndLastSpeed, 0, sizeof(g_aiSndLastSpeed));
	opponent_free(&rr->field);
	for (int k = 0; k < OPPONENT_MAX; k++) {
		carlights_clear(&rr->fieldLights[k]);
		carshadow_free(&rr->fieldShadow[k]);
		carneon_clear(&rr->fieldNeon[k]);
	}
	if (had > 0) {
		char b[128];
		snprintf(b, sizeof(b), "opponents: field of %d freed -- linear %u -> %u KB free", had,
			(unsigned)(linBefore >> 10), (unsigned)(linearSpaceFree() >> 10));
		dlog(b);
	}
}
// A fresh RaceRun for a race start (#435). The record owns its field --
// free roam's two encounter racers live there between races, ~3.3 MB of
// linear memory each with their lights, shadows and neon -- and the last
// track's route; zeroing it over them lost both for the rest of the session,
// ~7 MB per race on the testers' logs. Free them first, then zero.
static void raceRunReset(RaceRun* rr) {
	race_free(&rr->race);
	raceFieldFree(rr);
	memset(rr, 0, sizeof(*rr));
}

// bRandom's global state, which the whole game shares and every draw advances.
// One per session rather than one per race, so a second race does not put up
// the same field as the first -- see opponent.h.
static u32 g_bRandom = OPPONENT_RNG_SEED;
// The career difficulty, 0 easy .. 2 hard, which indexes each opponent's
// skill triple and is the one setting behind how hard the AI drives.
//
// The chain, all of it read out of Speed.elf: GOCareerDifficulty::Act
// (0x800EBE54) cycles FEDatabase +0x354 over 0..2; RaceStarter::StartCareerEvent
// (0x8011D050) copies that into TheRaceParameters +0x78 (0x803FCAB8); and
// AddCareerEventAIOpponents indexes the opponent's skill[3] with it at
// 0x8011A418. FEDatabase +0x354 is the live copy of the save's own
// CareerSettings, the single u32 at payload 0xC723 that
// Default__14CareerSettings (0x80130DB8) initialises to 1 -- so a profile that
// has never been through the difficulty screen races on medium, not easy.
// Set from the loaded profile below; the default stands for "no profile".
static int g_careerDifficulty = 1;
// The live CareerSettings, read where retail reads FEDatabase +0x354: at each
// race's setup (StartCareerEvent; SPEED2.EXE 0x540531 / 0x5407AF) and each
// encounter's (0x532307). A change from Pause > Options so takes the next
// race or encounter, not the next world entry (#516).
static int careerDifficultyNow(void) {
	int d = (int)gProfile.careerSettings;
	if (d < 0) d = 0;
	if (d > 2) d = 2;
	if (d != g_careerDifficulty) {
		char b[80];
		snprintf(b, sizeof(b), "career: difficulty %d -> %d (the live CareerSettings)",
			g_careerDifficulty, d);
		dlog(b);
		g_careerDifficulty = d;
	}
	return d;
}
static RaceMarkers* g_raceMarkers;
static int g_careerStage = 0;

// RuntimeCareerStageInfo for `stage` (PlayerCareerState +0x69C4 + stage *
// 0x104, the save's stage records), NULL out of range.
static ProfileStageInfo* careerStageInfo(int stage) {
	return (stage >= 0 && stage < PROFILE_NUM_STAGES) ? &gProfile.stage[stage] : NULL;
}

// The sponsor the current stage signed (stage info +0xE8), 0 for none --
// what GetEventPurse pays a sponsor race from.
static u32 careerChosenSponsor(void) {
	const ProfileStageInfo* si = careerStageInfo(g_careerStage);
	return si ? si->sponsor[0] : 0;
}

// The career's sponsor bookkeeping (docs/formats/postrace-sponsor-re.md), on
// the stage records above.

// GetNumWorldRacesCompleted: the world-race slots that hold an event.
static int careerWorldRacesCompleted(const ProfileStageInfo* si) {
	int n = 0;
	for (int i = 0; si && i < PROFILE_STAGE_WORLD_RACES; i++)
		if (si->worldRace[i])
			n++;
	return n;
}

// GetAverageSponsorPointsPerRace (0x801248F0): 0 until a race has counted.
static float careerAvgSponsorPoints(const ProfileStageInfo* si) {
	return (si && si->sponsorPointRaces > 0)
		? si->sponsorPoints / (float)si->sponsorPointRaces : 0.0f;
}

// NotifyWonEvent (0x801247C4) on the event's own stage: the id into the first
// slot of its class's list that is empty or already holds it -- a world race
// (class 3, not an SUV race), a sponsor race (1) or a URL event (2).
static void careerNotifyWonEvent(const EventRec* ev) {
	ProfileStageInfo* si = ev ? careerStageInfo(ev->stage) : NULL;
	if (!si)
		return;
	unsigned int* list = NULL;
	int n = 0;
	if (ev->cls == EVENT_CLASS_REGULAR && ev->isSUV != 1) {
		list = si->worldRace;
		n = PROFILE_STAGE_WORLD_RACES;
	} else if (ev->cls == EVENT_CLASS_SPON) {
		list = si->sponsorRace;
		n = PROFILE_STAGE_SPONSOR_RACES;
	} else if (ev->cls == EVENT_CLASS_URL) {
		list = si->urlRace;
		n = PROFILE_STAGE_URL_RACES;
	}
	for (int i = 0; i < n; i++)
		if (list[i] == 0 || list[i] == ev->eventId) {
			list[i] = ev->eventId;
			return;
		}
}

// NotifyCommitSponsorPoints (0x80124B08): the margin's reputation into the
// stage's points and one more race counted -- except for the prologue's two
// D-Day events.
static float raceRepForMargin(float margin, const EventRec* ev);
static void careerCommitSponsorPoints(const EventRec* ev, float margin) {
	ProfileStageInfo* si = ev ? careerStageInfo(ev->stage) : NULL;
	if (!si || ev->eventId == CAREER_PROLOGUE_FIRST_EVENT ||
			ev->eventId == CAREER_PROLOGUE_DONE_EVENT)
		return;
	si->sponsorPoints += raceRepForMargin(margin, ev);
	si->sponsorPointRaces++;
}

// AllEventsInStageCompleted (0x80124288): every career event of the stage
// completed. Only stage 1 clears this way; the rest name a clear event.
static bool careerAllEventsInStageCompleted(int stage) {
	for (int i = 0; i < g_shops.count; i++)
		if ((int)g_shops.recs[i].stage == stage &&
				!profileHasCompletedEvent(g_shops.recs[i].eventId))
			return false;
	return true;
}

// CheckThatRequiredShowcasesHaveBeenCompleted (0x80124C54): every showcase
// of the stage marked required -- the STAGE_<n>_DVD_<k> covers -- completed,
// which is its own state record at 1.
static bool careerRequiredShowcasesCompleted(int stage) {
	for (int i = 0; i < g_shops.showcaseCount && i < EVENTDB_MAX_SHOWCASES; i++) {
		const ShowcaseRec* sc = &g_shops.showcases[i];
		if ((int)sc->stage == stage && sc->required && !profileHasCompletedEvent(sc->handle))
			return false;
	}
	return true;
}

// NotifyStageCleared (0x80125FB0): the career moves one stage on, but only
// off the stage it is on. Everything that reads the stage reads g_careerStage
// live -- the events a start point offers, the GPS's stage 0 rule, the
// sponsor screens -- and free roam's barrier groups follow it the next time
// they are set (worldSetFreeRoamGroups).
// Then CareerSpeech::HandleStageStarted, Rachel's call for the new stage
// 15 s on (#268 I).
static void careerSpeechStageStarted(int stage);
static void careerNotifyStageCleared(int stage) {
	if (stage != g_careerStage)
		return;
	g_careerStage = stage + 1;
	gProfile.careerStage = (unsigned)g_careerStage;
	g_profileEdits++;
	careerSpeechStageStarted(g_careerStage);
}

// CheckIfClearedStage (0x80124CE8) on the stage's record. A stage cleared
// before answers yes and does nothing more. Otherwise the stage table's clear
// event decides: 0 asks for every event of the stage, anything else for that
// event and the stage's required showcases. A stage that passes is marked
// cleared (+0xFC, the save's completed byte) and NotifyStageCleared runs.
static bool careerCheckIfClearedStage(int stage) {
	const StageRec* sd = g_shopsOk ? eventdb_stage(&g_shops, stage) : NULL;
	if (!sd || stage < 0 || stage >= PROFILE_NUM_STAGES)
		return false;
	if (gProfile.stageCompleted[stage])
		return true;
	const bool clear = sd->clearEvent == 0 ? careerAllEventsInStageCompleted(stage)
		: profileHasCompletedEvent(sd->clearEvent) && careerRequiredShowcasesCompleted(stage);
	if (!clear)
		return false;
	gProfile.stageCompleted[stage] = true;
	g_profileEdits++;
	careerNotifyStageCleared(stage);
	return true;
}

// CommitWinEvent's (0x80127050) tail, after the state byte, the purse and the
// sponsor points: SMSMessageQueue::NotifyCompleteEvent, then NotifyCommitEvent
// on the event's own stage -- NotifyWonEvent once more and
// CheckIfClearedStage. Both ways a career event is won end here: a race over
// (raceFinishEvent) and the prologue's shop visits (NotifyEnterShopFromFreeRoam).
// Last, WorldChallengeState::NotifyCareerEventCompleted, on the stage the
// career is on once that check has run (#268 K).
// CareerSpeech::HandleCareerEventEnd, from CommitWinEvent itself, is here too
// (careerSpeechEventEnd: its queue, #268 G).
// PORT: not ported from the same tail -- ShowcaseState::NotifyCompletedEvent
// (#268 B).
static void careerWcNotifyCareerEventCompleted(void);
static void careerSpeechEventEnd(const EventRec* ev, bool won);
static void careerCommitWinTail(const EventRec* ev) {
	if (!ev)
		return;
	careerSpeechEventEnd(ev, true);
	char b[192];
	const int sms = g_shopsOk ? sms_notify_complete_event(&gProfile, &g_shops, ev->eventId) : 0;
	careerNotifyWonEvent(ev);
	const int before = g_careerStage;
	const bool cleared = careerCheckIfClearedStage(ev->stage);
	const StageRec* sd = g_shopsOk ? eventdb_stage(&g_shops, ev->stage) : NULL;
	snprintf(b, sizeof(b), "career: %s committed -- %d SMS queued; CheckIfClearedStage(%d) %s "
		"(clear event %08X, %d world race(s) won); career stage %d -> %d", ev->name, sms,
		(int)ev->stage, cleared ? "cleared" : "not cleared", sd ? (unsigned)sd->clearEvent : 0u,
		careerWorldRacesCompleted(careerStageInfo(ev->stage)), before, g_careerStage);
	dlog(b);
	careerWcNotifyCareerEventCompleted();
}

// RuntimeCareerStageInfo::GetNumSponsorsToChooseFrom: the stage's sponsors
// whose world-race requirement is met and whose minimum average (+0xE) `avg`
// reaches.
static int careerSponsorsToChooseFrom(int stage, float avg) {
	const ProfileStageInfo* si = careerStageInfo(stage);
	const StageRec* sd = eventdb_stage(&g_shops, stage);
	if (!si || !sd)
		return 0;
	const int won = careerWorldRacesCompleted(si);
	int n = 0;
	for (int i = 0; i < sd->sponsorCount && i < EVENTDB_STAGE_SPONSORS; i++) {
		const SponsorRec* sp = sd->sponsorHash[i]
			? eventdb_sponsor_by_hash(&g_shops, sd->sponsorHash[i]) : NULL;
		if (sp && won >= sd->reqWorldRaces[i] && (float)sp->minAvgPoints <= avg)
			n++;
	}
	return n;
}

// cPostRaceScreenManager::NeedToAskForSponsor (0x800F652C): career (the
// caller's test), no event or a single race, the stage's own
// NeedToAskForSponsor (0x80124940: no sponsor yet, and one whose world races
// are won), past stage 1, and someone on offer at the last stage's average.
// Returns that count, 0 for no.
static int careerNeedToAskForSponsor(const EventRec* ev) {
	if ((ev && ev->trackCount >= 2) || g_careerStage <= 1)
		return 0;
	const ProfileStageInfo* si = careerStageInfo(g_careerStage);
	const StageRec* sd = eventdb_stage(&g_shops, g_careerStage);
	if (!si || !sd || si->sponsor[0] != 0)
		return 0;
	const int won = careerWorldRacesCompleted(si);
	bool any = false;
	for (int i = 0; i < sd->sponsorCount && i < EVENTDB_STAGE_SPONSORS; i++)
		if (sd->sponsorHash[i] && sd->reqWorldRaces[i] <= won)
			any = true;
	if (!any)
		return 0;
	return careerSponsorsToChooseFrom(g_careerStage,
		careerAvgSponsorPoints(careerStageInfo(g_careerStage - 1)));
}

// NotifyChooseSponsor (0x80125E80), only while the stage has none: the first
// locked career slot opens (UnlockACareerCarSlot, 0x80134048), the signing
// bonus goes into the bank and the sponsor is the stage's.
static void careerChooseSponsor(u32 nameHash) {
	ProfileStageInfo* si = careerStageInfo(g_careerStage);
	const SponsorRec* sp = eventdb_sponsor_by_hash(&g_shops, nameHash);
	char b[192];
	if (!si || !sp || si->sponsor[0] != 0) {
		snprintf(b, sizeof(b), "career: sponsor %08X not chosen -- %s", (unsigned)nameHash,
			!si ? "no stage" : !sp ? "not in the sponsor table" : "the stage has one");
		dlog(b);
		return;
	}
	int slot = -1;
	for (int i = 0; i < (int)gProfile.numCareerCars && i < PROFILE_NUM_CAREER_SLOTS; i++)
		if (gProfile.careerCar[i].locked) {
			gProfile.careerCar[i].locked = 0;
			slot = i;
			break;
		}
	if (sp->bonus > 0)
		gProfile.cash += (unsigned)sp->bonus;
	si->sponsor[0] = sp->nameHash;
	snprintf(b, sizeof(b), "career: stage %d signs %s -- $%d bonus, bank $%u, %s", g_careerStage,
		sp->name, (int)sp->bonus, (unsigned)gProfile.cash,
		slot >= 0 ? "a career slot unlocked" : "no locked career slot");
	if (slot >= 0) {
		char s[16];
		snprintf(s, sizeof(s), " (%d)", slot + 1);
		strncat(b, s, sizeof(b) - strlen(b) - 1);
	}
	dlog(b);
}
static bool g_ownsSUV = false;
// PlayerCareerState+0x7e2c (save payload 0xAD5A): whether the career has a car
