static bool g_lanRaceOn;               // the world's race is a LAN one
static int g_lanCarType = -1;          // this console's car, the record
static int g_lanRideSlot = -1;         // and the career slot it races, -1 stock
static bool g_lanLoadedSent;           // lanrace_loaded() said, this race
