static void lanWorldFrame(void);
// The event the crib's world map said Yes to: CribWorldMapScreen's start
// flag, which its tick (SPEED2.EXE 0x4E0F60) turns into StartCareerEvent(ev, 1)
// and the frontend's unload. A copy, since the screen's event table goes with
// the screen; the world's own record is looked up again by id when the race
// starts (mapRaceBegin()).
static EventRec g_mapEvent;
static bool g_mapEventPending = false;
// The frontend package a finished Quick Race leaves the world for, picked up
// by the world loop: PostRaceMenu::QuitGame (0x800F3590) ->
// CalculateFirstFrontendScreenToSeeAfterQuitRace (0x801322A0), which for game
// mode 4, Quick Race, is UI_QRModeSelect.fng.
static const char* g_worldLeaveTo = NULL;
#define QR_AFTER_RACE_SCREEN "UI_QRModeSelect.fng"
// The pause menu's Quit asks the same question: PauseMenu::QuitGame
// (0x80100A5C) passes quit type 0 too, so a Quick Race -- racing or not --
// quits to UI_QRModeSelect and career to UI_Main. Defined below the career
// flag it reads.
static const char* worldQuitScreen(void);
// The race files (raceStartTrack), here so world entry can find a Quick
// Race's grid before the race code below.
// Each takes the loaded set first (g_region).
#define RACE_PATHS_FMT     "TRACKS/ROUTES%s/Paths%d.bin"
#define RACE_MARKERS_FMT   "TRACKS/ROUTES%s/TrackPosMarkersAll.bin"
// The AI's roads (trackroute.h): "F", or "B" for a race run reversed.
#define RACE_ROUTES_FMT    "TRACKS/ROUTES%s/Routes%d%s.bin"

// TrackInfo +0x40 of `track`, the set its load brings in (trackdb.h); NULL
// when GLOBALB.BUN or the record is not there, which callers take as the
// loaded set. Read once: nothing in the table changes.
static const char* trackRegion(const Config* cfg, int track) {
	static TrackDb db; // ~24 KB, kept off the stack
	static bool tried = false, ok = false;
	if (!tried && cfg) {
		char bunPath[600];
		tried = true;
		ok = buildGamePath(cfg, "GLOBAL/GLOBALB.BUN", bunPath, sizeof(bunPath)) &&
			trackdb_load(bunPath, &db);
	}
	const TrackRec* r = ok ? trackdb_find(&db, (u16)track) : NULL;
	return r && r->regionName[0] ? r->regionName : NULL;
}

// Whether `region`'s world is on the card: its archive, which world_open()
// cannot do without (#270). A set not packed yet keeps the loaded one, and
// a race on it says what it is missing, as before #271.
static bool regionOnCard(const Config* cfg, const char* region) {
	char rel[64], path[600];
	struct stat st;
	snprintf(rel, sizeof(rel), WORLD_TRACK_DIR_FMT "/WORLD.NFSZ", region);
	return buildGamePath(cfg, rel, path, sizeof(path)) && stat(path, &st) == 0;
}

// BeginGameFlowSwitchTrack's other arm (Speed.elf 0x801971E8). Every switch
// unloads the track; then the old and new TrackInfo +0x40 are compared
// (bStrCmp), and when they differ RegionLoader::Unload and BeginLoading run in
// place of TrackLoader::BeginLoading -- the whole set goes and the new one
// comes in under the loading screen. Into a race on another set (a URL event
// on L4RG, #268 C) and back to free roam after it are the two cases.
// raceStartTrack() and raceFinishEvent() ask for it, and the world loop runs it
// once its pad pass is over (worldRegionSwitch()), since the world is still in
// use until then. The race's own state is copied out at that point, after the
// caller's NotifyEnterEvent and spawn point.
typedef struct {
	bool pending;
	bool race;           // into a race (track `track` of `ev`), else free roam
	char region[8];      // the set asked for, for the log
	int track;
	EventRec ev;         // a copy: the world's table goes with the world
	bool rewardClaimed;
	bool fromWorldMap;
	u8 trackState[EVENTDB_MAX_EVENT_TRACKS];
	bool trackReasonOk[EVENTDB_MAX_EVENT_TRACKS];
	u8 trackPos[EVENTDB_MAX_EVENT_TRACKS][1 + OPPONENT_MAX];
	float spawnPos[3];   // the race's way back, or free roam's spawn
	float spawnYaw;
} RegionSwitch;
static RegionSwitch g_regionSwitch;

static void regionSwitchAsk(bool race, int track, const char* region, const float pos[3],
	float yaw) {
	RegionSwitch* rs = &g_regionSwitch;
	rs->pending = true;
	rs->race = race;
	rs->track = track;
	snprintf(rs->region, sizeof(rs->region), "%s", region);
	if (pos) {
		rs->spawnPos[0] = pos[0];
		rs->spawnPos[1] = pos[1];
		rs->spawnPos[2] = pos[2];
		rs->spawnYaw = yaw;
	}
	char b[128];
	snprintf(b, sizeof(b), "region: %s -> %s asked (%s) -- RegionLoader, once this pass is over",
		g_region, region, race ? "a race" : "free roam");
	dlog(b);
}

// Grid position 1 of an event's first track -- the Quick Race's, or the one
// the crib's world map started -- as world entry's spawn: the
// sections around the grid are paged in under the loading screen, so the
// race start's own placement (raceStartTrack, on the player's drawn slot) is a
// few metres and not a trip across the city. False, leaving the index's own
// spawn to stand, when the markers or the track's grid are not on the card;
// raceStartTrack then says which.
static bool trackGridSpawn(const Config* cfg, const EventTrackEntry* t, float pos[3],
	float* yaw) {
	char path[600];
	if (!g_raceMarkers && regionPath(cfg, RACE_MARKERS_FMT, path, sizeof(path)))
		g_raceMarkers = race_markers_open(path, dlog);
	u16 angle;
	if (!g_raceMarkers ||
			!race_grid_slot(g_raceMarkers, t->trackId, (t->flags & 1) != 0, 1, pos, &angle))
		return false;
	*yaw = (float)angle * (2.0f * (float)M_PI / 65536.0f);
	return true;
}
static bool qrGridSpawn(const Config* cfg, float pos[3], float* yaw) {
	return trackGridSpawn(cfg, &g_qr.ev.tracks[0], pos, yaw);
}

// StartRace's reading of the settings, at the A that leaves car select: the
// race type's block (the type is g_qrRaceType, the mode select's pick) and its
// record. A circuit or sprint marks the world about to open as a race; any
// other type is said and left to free roam.
static void qrPrepare(void) {
	memset(&g_qr, 0, sizeof(g_qr));
	RaceSettings* rs = raceSettings();
	rs->raceType = g_qrRaceType;
	const RaceRecord* rec = raceset_record_const(rs);
	char b[224];
	if (g_qrRaceType == QR_RACE_FREERUN) {
		g_qr.freeRun = true;
		g_qr.freeRunTrack = (int)rec->trackId;
		g_qr.freeRunTraffic = (int)raceset_traffic(rs);
		g_qr.strength = raceset_difficulty(rs);
		snprintf(b, sizeof(b), "quick race: Free Run (SetupFreeRun) -- track %d, traffic level %d, "
			"AI skill %d%s", g_qr.freeRunTrack, g_qr.freeRunTraffic, g_qr.strength,
			g_qr.freeRunTrack == WORLD_FREE_ROAM_TRACK ? ", two free-roam racers" : "");
		dlog(b);
		return;
	}
	if (g_qrRaceType != QR_RACE_CIRCUIT && g_qrRaceType != QR_RACE_SPRINT &&
			g_qrRaceType != QR_RACE_DRAG && g_qrRaceType != QR_RACE_DRIFT &&
			g_qrRaceType != QR_RACE_URL && g_qrRaceType != QR_RACE_STREETX) {
		snprintf(b, sizeof(b), "quick race: race type %d has no RaceStarter setup in this "
			"port; free roam on track %d", g_qrRaceType, (int)rec->trackId);
		dlog(b);
		return;
	}
	g_qr.raceType = g_qrRaceType;
	g_qr.opponents = raceset_opponents(rs);
	g_qr.strength = raceset_difficulty(rs);
	g_qr.catchUp = raceset_catch_up(rs) != 0;
	int laps = (int)rec->laps;
	// The one-track event the race code reads, its type and class standing in
	// for TheRaceParameters' flags: +0x40 drag, +0x44 drift, +0x50 URL, +0x58
	// Street X (raceStartTrack tests the event's type and class).
	g_qr.ev.cls = g_qrRaceType == QR_RACE_URL ? EVENT_CLASS_URL : EVENT_CLASS_REGULAR;
	const char* name = "QUICK_RACE_CIRCUIT";
	switch (g_qrRaceType) {
	case QR_RACE_SPRINT:
		g_qr.ev.type = EVENT_TYPE_SPRINT;
		name = "QUICK_RACE_SPRINT";
		break;
	case QR_RACE_DRAG:
		// SetupDragRace: one lap (+0x20 = 1), catch up off (+0x7C = 0).
		g_qr.ev.type = EVENT_TYPE_DRAG;
		name = "QUICK_RACE_DRAG";
		laps = 1;
		g_qr.catchUp = false;
		break;
	case QR_RACE_DRIFT: {
		// SetupDriftRace: on a track with TrackInfo +0x80 set (the downhill
		// drifts, the only ones with traffic) one lap and no AI on the road
		// -- BuildLeaderBoard's score-only names stand in; elsewhere the
		// settings' laps and, g_tweakAIDriftOpponents being 1 on the disc,
		// GetNumOpponents.
		g_qr.ev.type = EVENT_TYPE_DRIFT;
		name = "QUICK_RACE_DRIFT";
		static TrackDb db;
		char path[600];
		const TrackRec* tr = g_cfgMain && buildGamePath(g_cfgMain, "GLOBAL/GLOBALB.BUN", path,
			sizeof(path)) && trackdb_load(path, &db) ? trackdb_find(&db, rec->trackId) : NULL;
		if (tr && tr->allowsTraffic) {
			laps = 1;
			g_qr.opponents = 0;
		}
		break;
	}
	case QR_RACE_URL:
		g_qr.ev.type = EVENT_TYPE_CIRCUIT;
		name = "QUICK_RACE_URL";
		break;
	case QR_RACE_STREETX:
		g_qr.ev.type = EVENT_TYPE_STREET;
		name = "QUICK_RACE_STREETX";
		break;
	default:
		g_qr.ev.type = EVENT_TYPE_CIRCUIT;
		break;
	}
	snprintf(g_qr.ev.name, sizeof(g_qr.ev.name), "%s", name);
	g_qr.ev.trackCount = 1;
	g_qr.ev.tracks[0].trackId = (s16)rec->trackId;
	g_qr.ev.tracks[0].flags = rec->direction != 0 ? 1 : 0;
	g_qr.ev.tracks[0].extra = (u8)(laps > 0 ? laps : 1);
	g_qr.pending = true;
	snprintf(b, sizeof(b), "quick race: %s -- track %d%s, %d lap(s), %d opponent(s), "
		"difficulty %d, catch up %s", g_qr.ev.name, (int)rec->trackId,
		rec->direction ? " reversed" : "", (int)g_qr.ev.tracks[0].extra, g_qr.opponents,
		g_qr.strength, g_qr.catchUp ? "on" : "off");
	dlog(b);
}

// A LAN game's race (#321c), StartRace's reading of the room's settings in
// place of the Quick Race's: the mode as the race type, the track, its
// direction and laps. No AI, no traffic, no catch up: the field is the other
// racers' cars (lanFieldBuild()).
// Outrun (mode 8, #488) is the PC's network race type 7: the cars on an
// Outrun spawn's grid (4091..4094, picked as the room is made), no route and
// no finish line, and the server's lead game (lanrace.c) ends it -- here the
// sprint's machinery with no route (raceStartTrack()'s `outrun`).
static void lanQrPrepare(const LanGo* go) {
	memset(&g_qr, 0, sizeof(g_qr));
	g_lanNoStartNote = g_lanNoStartSaid = g_lanAbortNote = false;
	const LanSettings* s = &go->set;
	int type = QR_RACE_CIRCUIT;
	const char* name = "LAN_CIRCUIT";
	g_qr.ev.cls = EVENT_CLASS_REGULAR;
	g_qr.ev.type = EVENT_TYPE_CIRCUIT;
	int laps = s->laps > 0 ? s->laps : 1;
	switch (s->mode) {
	case 1:
		type = QR_RACE_SPRINT; name = "LAN_SPRINT";
		g_qr.ev.type = EVENT_TYPE_SPRINT;
		break;
	case 8:
		type = QR_RACE_SPRINT; name = "LAN_OUTRUN";
		g_qr.ev.type = EVENT_TYPE_SPRINT;
		laps = 1;
		break;
	case 2:
		type = QR_RACE_DRAG; name = "LAN_DRAG";
		g_qr.ev.type = EVENT_TYPE_DRAG;
		laps = 1;
		break;
	case 3:
		type = QR_RACE_DRIFT; name = "LAN_DRIFT";
		g_qr.ev.type = EVENT_TYPE_DRIFT;
		break;
	case 4:
		type = QR_RACE_URL; name = "LAN_URL";
		g_qr.ev.cls = EVENT_CLASS_URL;
		break;
	case 10:
		type = QR_RACE_STREETX; name = "LAN_STREETX";
		g_qr.ev.type = EVENT_TYPE_STREET;
		break;
	default:
		break;
	}
	g_qrRaceType = type;
	raceSettings()->raceType = type;
	g_qr.raceType = type;
	g_qr.opponents = go->racers - 1;
	g_qr.strength = 1;
	g_qr.catchUp = false;
	snprintf(g_qr.ev.name, sizeof(g_qr.ev.name), "%s", name);
	g_qr.ev.trackCount = 1;
	g_qr.ev.tracks[0].trackId = (s16)s->track;
	g_qr.ev.tracks[0].flags = s->reverse ? 1 : 0;
	g_qr.ev.tracks[0].extra = (u8)laps;
	g_qr.pending = true;
	char b[192];
	snprintf(b, sizeof(b), "lan race: %s -- track %d%s, %d lap(s), %d racers, collision %s",
		name, (int)s->track, s->reverse ? " reversed" : "", laps, go->racers,
		s->collision ? "on" : "off");
	dlog(b);
}

// The track number career free roam runs as: StartCareerFreeRoam (Speed.elf
// 0x8011cbac) stores 4000 into TheRaceParameters before the track loads
// (WORLD_FREE_ROAM_TRACK, defined with the Quick Race block).

// StartCareerFreeRoam without its respawn point (DAT_803bbee0 clear, which is
// how LaunchFirstCareerMovie's DoWhatNext reaches it): the race parameters
// name track 4000 and DetermineStartingPositions(1) puts the one car on its
// grid, position 1 -- TrackPosMarkersAll's ForwardStartingPosition slot 0 for
// 4000, (1695.2, -883.6, 53.5) heading 0xF8BE.
static bool careerGridSpawn(const Config* cfg, float pos[3], float* yaw) {
	char path[600];
	if (!g_raceMarkers && regionPath(cfg, RACE_MARKERS_FMT, path, sizeof(path)))
		g_raceMarkers = race_markers_open(path, dlog);
	u16 angle;
	if (!g_raceMarkers ||
			!race_grid_slot(g_raceMarkers, WORLD_FREE_ROAM_TRACK, false, 1, pos, &angle))
		return false;
	*yaw = (float)angle * (2.0f * (float)M_PI / 65536.0f);
	return true;
}

// Whether the world was entered from career at all, profile or not, set at
// the A press that enters it: free roam's barriers are the career's
// (BARRIERS_CAREER<stage>) only then.
static bool g_worldFromCareer = false;

// The career slot whose own build the player's car `rec` drives -- the
// current slot, when the world came from career and that slot holds the car --
// or -1 for the record's stock build (TASKS.md #288).
// A Quick Race drives its car select row's slot instead (g_qrRideSlot, #390).
static int playerCareerSlot(const CarRec* rec) {
	const int slot = g_worldPresetRide ? PROFILE_WORK_SLOT
		: g_worldFromCareer ? gProfile.currentCarSlot : g_qrRideSlot;
	if (!gProfile.isLoaded || !rec || slot < 0 ||
			slot >= PROFILE_CAREER_ARRAYS ||
			gProfile.careerCar[slot].carTypeHash != rec->nameHash)
		return -1;
	return slot;
}

// ---- World challenges and showcases (TASKS.md #268 K) ----------------------
// Between races the career offers world challenges (eventdb.h
// WorldChallengeRec): drive into the start trigger, accept, and reach the
// goal -- a showcase to photograph, or a shop -- before the clock runs out.
// A showcase (ShowcaseRec) is a photo spot, enterable while its own state
// record is type 2 and not completed. Both kinds of zone are
// RACE_START_TRIGGERs, which GetTrackPathZoneData (0x801240BC) tries after
// the event pile.

// IsSUV (0x80243B44) of GetCurrentCareerCar: the hashes DoesPlayerOwnSUV
// asks of every career car, asked of the one the career drives.
static bool careerCurrentCarIsSUV(void) {
	const int s = gProfile.currentCarSlot;
	if (s < 0 || s >= PROFILE_CAREER_ARRAYS)
		return false;
	const u32 h = gProfile.careerCar[s].carTypeHash;
	return h == 0x0219C94Au || h == 0xCF704771u || h == 0x6126DD4Du;
}

// GetNumURLRacesCompleted / GetNumSponsorRacesCompleted: a stage list's
// non-zero slots, counted the way careerWorldRacesCompleted counts its own.
static int careerSlotsHeld(const unsigned int* list, int n) {
	int held = 0;
	for (int i = 0; i < n; i++)
		if (list[i])
			held++;
	return held;
}

#define CAREER_FINAL_RACE 0x04CCE3E1u // S5_CIRCUIT_36

// MaybeAddWorldChallenge's (0x80125104) test: a challenge not yet won whose
// counter (+0x06) on its stage's record has reached its count (+0x07) --
// except STAGE_5_VISUAL_5 while the career's own car is an SUV.
#define WC_SUV_EXCLUDED 0xDD15316Eu // bStringHash("STAGE_5_VISUAL_5")
// The counter (+0x06) a challenge's unlock reads, -1 for an unknown kind.
static int careerWcCounter(const ProfileStageInfo* si, const WorldChallengeRec* c) {
	switch (c->unlockKind) {
	case WC_UNLOCK_WORLD_RACES: return careerWorldRacesCompleted(si);
	case WC_UNLOCK_URL_RACES:   return careerSlotsHeld(si->urlRace, PROFILE_STAGE_URL_RACES);
	case WC_UNLOCK_OUTRUNS:     return si->outrunWins;
	case WC_UNLOCK_SPONSOR:     return careerSlotsHeld(si->sponsorRace, PROFILE_STAGE_SPONSOR_RACES);
	default:                    return -1;
	}
}
static bool careerMaybeAddWorldChallenge(const ProfileStageInfo* si,
		const WorldChallengeRec* c) {
	if (!si || profileHasCompletedEvent(c->nameHash))
		return false;
	const int n = careerWcCounter(si, c);
	if (n < 0 || n < c->unlockCount)
		return false;
	return !(g_hasCareerCar && careerCurrentCarIsSUV() && c->nameHash == WC_SUV_EXCLUDED);
}

// ---- The event pile (EventPile, PlayerCareerState +0x6834; TASKS.md #339) --
// What the career offers right now: up to 32 world challenges (+0x00) and 64
// events (+0x80), with a count per trigger-zone type (+0x180). Whatever asks
// whether an event is open asks the pile -- IsEventEnterable (0x80124350) is
// IsEventInPile, GetFirstUnlockedEvent (0x80124040) a zone's first event in
// it, IsEventVisibleOnRadar (0x80124184) that and a marker -- and
// BuildListOfEvents (0x80125A30) rebuilds it on every RecalcUnlockedZones.
// A rebuild keeps every open event the last one held, so the random top-up
// only fills the gaps a race leaves: which of a stage's races are on offer is
// chosen by bRandom, a few at a time, up to the stage's own maxima.
// Not saved: Default (0x80123934) resets it, and so does the port's profile
// load.
// PORT: NotifyBeginNewRace's rebuild at a race's start is not ported; nothing
// it could change is read before the rebuild free roam's return makes.
#define PILE_MAX_CHALLENGES 32
#define PILE_MAX_EVENTS 64
typedef struct {
	const WorldChallengeRec* challenge[PILE_MAX_CHALLENGES];
	const EventRec* event[PILE_MAX_EVENTS];
	u8 zoneCount[16]; // by get_event_trigger_zone_type
} EventPile;
static EventPile g_pile;

// EventPileTypes, what GetMaxNumberOfEventsByType and MatchesType take: the
// five world race kinds, the SUV races, and the same five as sponsor races.
enum {
	PILE_CIRCUIT, PILE_DRAG, PILE_DRIFT, PILE_SPRINT, PILE_STREET_X, PILE_SUV,
	PILE_SPON_CIRCUIT, PILE_SPON_DRAG, PILE_SPON_DRIFT, PILE_SPON_SPRINT,
	PILE_SPON_STREET_X, PILE_TYPE_COUNT
};

// Reset (0x80124E7C).
static void careerPileReset(void) {
	memset(&g_pile, 0, sizeof(g_pile));
}

// get_event_trigger_zone_type (0x80123770).
static int pileZoneType(const EventRec* e) {
	if (e->isSUV == 1)
		return 7;
	if (e->cls == EVENT_CLASS_URL)
		return 5;
	switch (e->type) {
	case EVENT_TYPE_STREET: return 2;
	case EVENT_TYPE_SPRINT: return 4;
	case EVENT_TYPE_DRAG:   return 1;
	case EVENT_TYPE_DRIFT:  return 3;
	default:                return 0;
	}
}

// CertainlyAddToPile (0x80124ED4): the zone type's count goes up, and the
// event takes the first free slot.
static void pileAddEvent(const EventRec* e) {
	g_pile.zoneCount[pileZoneType(e)]++;
	for (int i = 0; i < PILE_MAX_EVENTS; i++)
		if (!g_pile.event[i]) {
			g_pile.event[i] = e;
			return;
		}
}

static bool pileFull(void) {
	return g_pile.event[PILE_MAX_EVENTS - 1] != NULL;
}

// IsEventInPile (0x80124FE0), by id (+0x08).
static bool pileHasEvent(const EventRec* e) {
	for (int i = 0; e && i < PILE_MAX_EVENTS; i++)
		if (g_pile.event[i] && g_pile.event[i]->eventId == e->eventId)
			return true;
	return false;
}

static bool pileHasChallenge(const WorldChallengeRec* c) {
	for (int i = 0; c && i < PILE_MAX_CHALLENGES; i++)
		if (g_pile.challenge[i] == c)
			return true;
	return false;
}

// MaybeAddWorldChallenge's add: the first free challenge slot.
static void pileAddChallenge(const WorldChallengeRec* c) {
	for (int i = 0; i < PILE_MAX_CHALLENGES; i++)
		if (!g_pile.challenge[i]) {
			g_pile.challenge[i] = c;
			return;
		}
}

// MatchesType (0x8012524C). The world kinds are class 3 and not an SUV race
// (IsSUVRace, isSUV == 1), the sponsor kinds class 1, each by race type; the
// SUV kind is isSUV alone.
static bool pileMatchesType(const EventRec* e, int type) {
	static const s8 kRace[5] = {
		EVENT_TYPE_CIRCUIT, EVENT_TYPE_DRAG, EVENT_TYPE_DRIFT, EVENT_TYPE_SPRINT,
		EVENT_TYPE_STREET,
	};
	if (type == PILE_SUV)
		return e->isSUV == 1;
	if (type >= PILE_CIRCUIT && type <= PILE_STREET_X)
		return e->cls == EVENT_CLASS_REGULAR && e->isSUV != 1 && e->type == kRace[type];
	if (type >= PILE_SPON_CIRCUIT && type <= PILE_SPON_STREET_X)
		return e->cls == EVENT_CLASS_SPON && e->type == kRace[type - PILE_SPON_CIRCUIT];
	return false;
}

// GetNumberOfEventsByType (0x801254D4): the pile's events of that kind.
static int pileCountType(int type) {
	int n = 0;
	for (int i = 0; i < PILE_MAX_EVENTS; i++)
		if (g_pile.event[i] && pileMatchesType(g_pile.event[i], type))
			n++;
	return n;
}

// GetMaxSponsoredEventTypes (0x80125540): how many of the stage's sponsor's
// four race-type bytes (+0x04) ask for `category`, less the sponsor races of
// that kind already won (stage info +0x8C).
static int pileMaxSponsored(int category, int type) {
	const ProfileStageInfo* si = careerStageInfo(g_careerStage);
	const SponsorRec* sp = si && si->sponsor[0]
		? eventdb_sponsor_by_hash(&g_shops, si->sponsor[0]) : NULL;
	int n = 0;
	for (int k = 0; sp && k < 4; k++)
		if (sp->raceType[k] == category)
			n++;
	for (int k = 0; n && k < PROFILE_STAGE_SPONSOR_RACES; k++) {
		const EventRec* e = si->sponsorRace[k] ? eventdb_event_by_id(&g_shops, si->sponsorRace[k]) : NULL;
		if (e && pileMatchesType(e, type))
			n--;
	}
	return n;
}

// GetMaxNumberOfEventsByType (0x80125614): the stage record's maxima, the
// SUV kind's only while the career drives an SUV, the sponsor kinds from the
// contract; 0 for everything on a stage with no record.
static int pileMaxType(int type) {
	const StageRec* sd = eventdb_stage(&g_shops, g_careerStage);
	if (!sd)
		return 0;
	switch (type) {
	case PILE_CIRCUIT:       return sd->maxByKind[0];
	case PILE_DRAG:          return sd->maxByKind[1];
	case PILE_DRIFT:         return sd->maxByKind[3];
	case PILE_SPRINT:        return sd->maxByKind[4];
	case PILE_STREET_X:      return sd->maxByKind[2];
	case PILE_SUV:           return g_hasCareerCar && careerCurrentCarIsSUV() ? sd->maxByKind[7] : 0;
	case PILE_SPON_CIRCUIT:  return pileMaxSponsored(1, type);
	case PILE_SPON_DRAG:     return pileMaxSponsored(3, type);
	case PILE_SPON_DRIFT:    return pileMaxSponsored(2, type);
	case PILE_SPON_SPRINT:   return pileMaxSponsored(4, type);
	case PILE_SPON_STREET_X: return pileMaxSponsored(5, type);
	default:                 return -1;
	}
}

// GetRandomEvent (0x80125798): every event of the current stage not in the
// pile, not a URL or hidden one, not completed, not the final race, of the
// kind asked and, if an SUV race, with an SUV to drive; shuffled -- each
// place swapped with a bRandom(n) one -- and the first returned.
static const EventRec* pileRandomEvent(int type) {
	const bool suv = g_hasCareerCar && careerCurrentCarIsSUV();
	const EventRec* list[EVENTDB_MAX_EVENTS];
	int n = 0;
	for (int i = 0; i < g_shops.count && n < EVENTDB_MAX_EVENTS; i++) {
		const EventRec* e = &g_shops.recs[i];
		if (pileHasEvent(e) || (int)e->stage != g_careerStage || e->cls == EVENT_CLASS_URL ||
				e->isHidden || profileHasCompletedEvent(e->eventId) ||
				e->eventId == CAREER_FINAL_RACE || !pileMatchesType(e, type) ||
				(e->isSUV == 1 && !suv))
			continue;
		list[n++] = e;
	}
	for (int i = 0; i < n; i++) {
		const int j = (int)rideinfo_random(&g_bRandom, (u32)n);
		const EventRec* t = list[i];
		list[i] = list[j];
		list[j] = t;
	}
	return n ? list[0] : NULL;
}

// CheckThatRequiredShowcasesHaveBeenCompleted (0x80124C54): every showcase
// of the stage marked required (+0x35) done.
static bool careerRequiredShowcasesDone(int stage) {
	for (int i = 0; i < g_shops.showcaseCount && i < EVENTDB_MAX_SHOWCASES; i++) {
		const ShowcaseRec* sc = &g_shops.showcases[i];
		if ((int)sc->stage == stage && sc->required && !profileHasCompletedEvent(sc->handle))
			return false;
	}
	return true;
}

// CanDoURL (0x80124DAC): a URL event's rule (eventdb.h EventRec::urlRule)
// against the stage's counts.
static bool careerCanDoURL(const ProfileStageInfo* si, const EventRec* e) {
	if (!si)
		return false;
	const int world = careerWorldRacesCompleted(si);
	if (e->urlRule == 3)
		return ((s32)e->field10 >> 16) <= world;
	if (e->urlRule == 4)
		return careerRequiredShowcasesDone(g_careerStage) &&
			(int)(e->field10 >> 8 & 0xFF) <= world &&
			(int)(e->field10 >> 24) <= careerSlotsHeld(si->urlRace, PROFILE_STAGE_URL_RACES) &&
			(int)(e->field10 >> 16 & 0xFF) <= careerSlotsHeld(si->sponsorRace, PROFILE_STAGE_SPONSOR_RACES);
	return false;
}

// HasCompletedCareer (0x8012613C): the clear event of stage 5's StageData
// (the pointer stage 5's RuntimeCareerStageInfo keeps at +0x100) completed.
static bool careerHasCompletedCareer(void) {
	const StageRec* sd = g_shopsOk ? eventdb_stage(&g_shops, 5) : NULL;
	return sd && sd->clearEvent && profileHasCompletedEvent(sd->clearEvent);
}

static u32 careerCurrentShopEvent(void);
static u8 careerEventState(u32 eventId);
static bool dbgShopEventSpawnAt(float pos[3], float* yaw);
static char g_dbgWorldChallenge[32]; // Config's DbgWorldChallenge
static float g_dbgWcGoal;            // Config's DbgWcGoal
static bool g_dbgWcGoalMoved;        // DbgWcGoal done for this run of the challenge
static void careerPileLog(const char* why);

// BuildListOfEvents (0x80125A30). The pile it held is copied and the pile
// reset, then nothing is offered while a world challenge is on, nor on stage
// 0 until CareerSpeech has opened its races (+0x7E34), nor once they are
// closed again (+0x7E30) or the career is on DDAY_EVENT_B (+0x7E24).
// Stage 5 ends on one race: once S5_CIRCUIT_36's +0x10 event (S5_URL_9) is
// won and S5_CIRCUIT_36 is not, the pile is that race alone; and once the
// career is complete nothing at all is offered (#268 G). Otherwise, in order:
// the stage's world challenges; every event the old pile held that is still
// of this stage, open and drivable; each kind topped up at random to the
// stage's maximum; the stage's hidden events, up to its cap; and every URL
// event whose CanDoURL rule the stage's counts meet.
// PORT: outside career there is no career state, so no pile.
static void careerBuildListOfEvents(void) {
	const EventPile old = g_pile;
	careerPileReset();
	if (!g_worldFromCareer || !g_shopsOk)
		return;
	const int stage = g_careerStage;
	const u32 shopEv = careerCurrentShopEvent();
	if (!((stage != 0 || gProfile.csCanSeeEvents) && !g_wc.active &&
			(stage != 0 || (shopEv != CAREER_PROLOGUE_DONE_EVENT && !gProfile.stage0Timeout))))
		return;
	if (stage == 5) {
		const EventRec* fin = eventdb_event_by_id(&g_shops, CAREER_FINAL_RACE);
		if (fin && profileHasCompletedEvent(fin->field10) && !profileHasCompletedEvent(fin->eventId)) {
			pileAddEvent(fin);
			return;
		}
	}
	if (careerHasCompletedCareer())
		return;
	const ProfileStageInfo* si = careerStageInfo(stage);
	for (int i = 0; i < g_shops.challengeCount && i < EVENTDB_MAX_CHALLENGES; i++) {
		const WorldChallengeRec* c = &g_shops.challenges[i];
		if ((int)c->stage != stage)
			continue;
		if ((g_dbgWorldChallenge[0] && strcasecmp(c->name, g_dbgWorldChallenge) == 0) ||
				careerMaybeAddWorldChallenge(si, c))
			pileAddChallenge(c);
	}
	const bool suv = g_hasCareerCar && careerCurrentCarIsSUV();
	for (int i = 0; i < PILE_MAX_EVENTS; i++) {
		const EventRec* e = old.event[i];
		if (e && (int)e->stage == stage && (e->isSUV != 1 || suv) &&
				!profileHasCompletedEvent(e->eventId))
			pileAddEvent(e);
	}
	for (int t = 0; t < PILE_TYPE_COUNT; t++) {
		const int max = pileMaxType(t);
		int n = pileCountType(t);
		const EventRec* e;
		// PORT: the pile-full test is the port's; retail's maxima never let
		// the 64 slots fill.
		while ((max == -1 || n < max) && !pileFull() && (e = pileRandomEvent(t)) != NULL) {
			pileAddEvent(e);
			n = pileCountType(t);
		}
	}
	const StageRec* sd = eventdb_stage(&g_shops, stage);
	const int cap = sd ? sd->hiddenCap : -1;
	for (int i = 0; i < g_shops.count; i++) {
		int hidden = 0;
		for (int k = 0; k < PILE_MAX_EVENTS; k++)
			if (g_pile.event[k] && g_pile.event[k]->isHidden)
				hidden++;
		if (cap != -1 && cap <= hidden)
			break;
		const EventRec* e = &g_shops.recs[i];
		if ((int)e->stage == stage && e->isHidden && !profileHasCompletedEvent(e->eventId) &&
				!pileHasEvent(e))
			pileAddEvent(e);
	}
	for (int i = 0; i < g_shops.count; i++) {
		const EventRec* e = &g_shops.recs[i];
		if ((int)e->stage == stage && e->cls == EVENT_CLASS_URL &&
				!profileHasCompletedEvent(e->eventId) && !pileHasEvent(e) && careerCanDoURL(si, e))
			pileAddEvent(e);
	}
}

// IsWorldChallengeEnterable (0x8012430C), which is IsWorldChallengeInPile.
static bool careerChallengeInPile(const WorldChallengeRec* c) {
	return pileHasChallenge(c);
}

// GetFirstUnlockedEvent (0x80124040): the first event in table order whose
// start zone is this handle and that IsEventEnterable -- in the pile.
static const EventRec* careerFirstUnlockedEvent(u32 zoneHandle) {
	for (int i = 0; g_shopsOk && i < g_shops.count; i++)
		if (g_shops.recs[i].triggerHandle == zoneHandle && pileHasEvent(&g_shops.recs[i]))
			return &g_shops.recs[i];
	return NULL;
}

// IsEventVisibleOnRadar (0x80124184): not hidden, enterable, and an SUV race
// only with an SUV owned (DoesPlayerOwnSUV, 0x8012420C: g_ownsSUV).
static bool careerEventVisibleOnRadar(const EventRec* e) {
	return e && !e->isHidden && pileHasEvent(e) && (e->isSUV != 1 || g_ownsSUV);
}

// A shop's half of UnlockedTriggerZone::IsVisibleOnRadar (0x80128AD4):
// IsShopVisibleOnRadar (0x80124484) is IsShopEnterable (0x801243B8) -- the
// career's stage reached, a needsEvent shop discovered, IsShopUnlocked --
// and RecalcUnlockedZones' zone walk adds only an enterable shop. So a
// hidden (needsEvent) shop is off the minimap and the world map until the car
// first drives into its zone, and on them for good after (its record's byte
// +4 = 1 is saved). Outside the career every shop shows, as before.
// IsShopVisibleOnRadar's own arm (#517): at career stage 0 (+0x71E4) with no
// car of the career's own yet (+0x7E2C, g_hasCareerCar) only a car lot (shop
// type 4) is on the radar -- the shop the prologue sends the player to.
static bool careerShopOnRadar(const ShopRec* shop) {
	if (!shop)
		return false;
	if (!g_worldFromCareer)
		return true;
	// DbgRadarStage0=1 takes the stage-0 arm on any save, to see it.
	const bool stage0 = (g_careerStage == 0 && !g_hasCareerCar) ||
		(g_cfgMain && g_cfgMain->dbgRadarStage0);
	if (stage0 && shop->kind != 4)
		return false;
	return perfShopEnterable(NULL, shop->handle);
}

// What the pile holds, for the log: each kind's count against its maximum,
// then the events by name.
static void careerPileLog(const char* why) {
	static const char* kKind[PILE_TYPE_COUNT] = {
		"circuit", "drag", "drift", "sprint", "streetx", "suv",
		"s-circuit", "s-drag", "s-drift", "s-sprint", "s-streetx",
	};
	char b[320];
	int n = 0, events = 0, hidden = 0, url = 0, challenges = 0;
	for (int i = 0; i < PILE_MAX_EVENTS; i++)
		if (g_pile.event[i]) {
			events++;
			hidden += g_pile.event[i]->isHidden ? 1 : 0;
			url += g_pile.event[i]->cls == EVENT_CLASS_URL ? 1 : 0;
		}
	for (int i = 0; i < PILE_MAX_CHALLENGES; i++)
		challenges += g_pile.challenge[i] ? 1 : 0;
	const StageRec* sd = g_shopsOk ? eventdb_stage(&g_shops, g_careerStage) : NULL;
	n = snprintf(b, sizeof(b), "pile (%s): stage %d, %d event(s), %d challenge(s) --", why,
		g_careerStage, events, challenges);
	for (int t = 0; t < PILE_TYPE_COUNT && n < (int)sizeof(b) - 24; t++) {
		const int c = pileCountType(t), m = g_shopsOk ? pileMaxType(t) : 0;
		if (c || m > 0)
			n += snprintf(b + n, sizeof(b) - n, " %s %d/%d", kKind[t], c, m);
	}
	if (n < (int)sizeof(b) - 40)
		snprintf(b + n, sizeof(b) - n, " hidden %d/%d url %d%s", hidden, sd ? sd->hiddenCap : -1,
			url, careerHasCompletedCareer() ? " (career complete)" : "");
	dlog(b);
	n = 0;
	b[0] = 0;
	for (int i = 0; i < PILE_MAX_EVENTS; i++) {
		const EventRec* e = g_pile.event[i];
		if (!e)
			continue;
		if (n > (int)sizeof(b) - 40) {
			dlog(b);
			n = 0;
		}
		n += snprintf(b + n, sizeof(b) - n, "%s%s", n ? " " : "pile:   ", e->name);
	}
	if (n)
		dlog(b);
}

// ---- CareerSpeech (SpeedPS.elf 0x80188D18..0x8018AAA4; TASKS.md #268 G, I) --
// Rachel's career lines. Most run off eight timed events: AddTimerEvent
// (0x80189444) queues one, UpdateTimerEvents (0x801894A4) counts them down
// in career time (HandleTick, 0x80188DD4, from UpdateTick in free roam while
// the prologue does not have the car) and HandleSpeechEvent (0x801895D0)
// handles the one due once no line is playing. Two of them are not only
// lines: event 2 is NotifyCSCanSeeEvents, which opens stage 0's races 15 s
// into DDAY_EVENT_A, and the third event 1 (a stage 0 race over) is
// NotifyCSStage0Timeout, which closes them again. The rest speak at once:
// the Outrun taunts, the engage dialogs' lines, the showcase mode's and the
// neighbourhood's. speech.c turns each SpeechCmd* into its line.
// The struct is saved: the PC copies its 0x190 bytes raw at payload 0xC28F
// (PlayerCareerState +0x887C; SaveToBuffer SPEED2.EXE 0x514530, LoadFromBuffer
// 0x529230), the GameCube's 0x1D8 at 0x801893AC / 0x801893F0.
// careerSpeechLoadBlock() and careerSpeechStoreBlock() turn the PC's layout
// into this struct and back.
// NotifyEnterShopEvent queues DDAY_EVENT_A's two again on every Resume Career,
// as retail does once they have fired.
// The frontend's half (#268 I step 2) is HandleFESpeechEvent and its callers'
// screens: careerSpeechFE() and careerSpeechScreenOpened() below.
// Of those screens the port has the crib, the car lot, the performance
// categories, the sponsor list and (#372, raised since #418) the shops':
// PartSelectionScreen, ChooseDecalCategory, IceSelectionScreen,
// ChoosePaintShopCategory, ChooseVinylLayerScreen and ChoosePaintScreen.
// The dyno's (#417, #513): ChooseTuningCategory's accept raises 0x13..0x19
// (HandleTuningCategory, 0x80189F3C) and ChooseTuningSetting's open 0x1B; the
// uniques/performance picks queue timer events 8 and 9 (1 s).
#define CS_TIMER_SLOTS 8
#define CS_SHOWCASES 30
#define CS_FE_EVENTS 0x1C  // eFESpeechEvent; InitFESpeechEvents zeroes 0x1C
enum {
	CS_EV_STAGE0_RACE_END = 1, // HandleCareerEventEnd, a stage 0 race
	CS_EV_SEE_EVENTS = 2,      // HandleCareerEventBegin(DDAY_EVENT_A), 15 s
	CS_EV_DDAY_LINE = 3,       // the same, 40 s
	CS_EV_FES_4 = 4,           // HandleFESpeechEvent (step 2)
	CS_EV_STAGE1_WIN = 5,      // a stage 1 race won, once
	CS_EV_FES_11 = 6,          // HandleFESpeechEvent (step 2)
	CS_EV_STAGE_CLEARED = 7,   // a stage's clear event won (not stage 5's)
	CS_EV_UNIQUE_VISUAL = 8,   // UniquesBrowser (step 2)
	CS_EV_UNIQUE_PERF = 9,     // UniquesBrowser (step 2)
	CS_EV_FES_11_LATER = 10,   // HandleFESpeechEvent, 30 s (step 2)
	CS_EV_SPONSOR = 11,        // uiSponsorsMain (step 2)
	CS_EV_STAGE_STARTED = 12,  // HandleStageStarted, 15 s
	CS_EV_DVD_UNLOCK = 13,     // HandleShowcaseUnlock, a DVD cover
	CS_EV_MAG_UNLOCK = 14,     // HandleShowcaseUnlock, a magazine
	CS_EV_DVD_STARS = 15,      // HandleTick, the next cover's stars
};
typedef struct {
	int time;  // Timer ticks, 1/4000 s
	int event; // 0 for a free slot
	int arg;
} CsTimerEvent;
static struct {
	int ddayDone;        // +0x04, Rachel's own Outrun lines are past
	int stage0Step;      // +0x08, event 1's line: 0, 1, 2, then 3 for done
	int stage1Said;      // +0x0C, event 5's line has played
	int fes4Said;        // +0x10, FE event 4's first line (the car lot)
	int fes11Said;       // +0x14, FE event 0x11's first line (the crib)
	int sponsorOpen;     // +0x18, the sponsor list is up
	int sponsorSaid;     // +0x1C, the first sponsor line has played
	int dvdStarSaid[11]; // +0x20, by star count
	int dvdPending;      // +0x4C, a DVD unlock line is queued
	u8  dvdStar;         // +0x50, the dearest locked cover's stars
	u8  taunt;           // +0x51, the Outrun voice, an index of kCsTauntCharId
	u32 hood;            // +0x54, the neighbourhood the car was last in
	int hoodTime;        // +0x58, career timer at the last neighbourhood line
	int engageSaid[3];   // +0x5C..+0x64, the stage 0 engage lines
	int engagePlaying;   // +0x68, an engage line is the one speaking
	int fes2Seen;        // +0x6C, FE event 2 (PartSelectionScreen) was raised
	u32 showcase[CS_SHOWCASES]; // +0x70, the unlocks announced (sc +0x28)
	u8  showcaseCount;   // +0xE8
	u8  stageStarted;    // +0xE9, the stage NotifyStageCleared moved to
	int showcaseModeSaid;// +0xEC
	CsTimerEvent timer[CS_TIMER_SLOTS]; // +0xF0
	// +0x150 / +0x154: WorldTimer (0x8046FEE0) at the last tick and what it
	// has run since. PORT: nothing in CareerSpeech reads them, so the port does
	// not run them: worldClock keeps what the save had and goes back unchanged.
	int worldLast;       // +0x150
	int worldClock;      // +0x154
	int lastTicks;       // +0x158, the career clock the last tick saw
	int timerTicks;      // +0x15C, the career timer
	int realLast;        // +0x160, RealTimer (0x8046FED4) at the last tick
	int realClock;       // +0x164, RealTimer's run since: the FE lines' clock
	int fe[CS_FE_EVENTS];// +0x168, each FE event's realClock when last raised
} g_cs;

// gTauntCharId (0x8032D4B8): the five Outrun voices.
static const u32 kCsTauntCharId[5] = { 1, 2, 4, 8, 0x200 };

// Default (0x80188D18), the part ported.
static void careerSpeechDefault(void) {
	memset(&g_cs, 0, sizeof(g_cs));
}

// IsTimerEventQueued (0x801895A0).
static bool careerSpeechQueued(int event) {
	for (int i = 0; i < CS_TIMER_SLOTS; i++)
		if (g_cs.timer[i].event == event)
			return true;
	return false;
}

// AddTimerEvent (0x80189444): slot 0 if it is free, else the first free one
// after it; nothing when all eight are taken.
static void careerSpeechAdd(float seconds, int event, int arg) {
	int k = 0;
	if (g_cs.timer[0].event != 0) {
		for (k = 1; k < CS_TIMER_SLOTS && g_cs.timer[k].event != 0; k++)
			;
		if (k == CS_TIMER_SLOTS)
			return;
	}
	g_cs.timer[k].time = (int)(seconds * 4000.0f);
	g_cs.timer[k].event = event;
	g_cs.timer[k].arg = arg;
}

// bRandom (the game's one random stream).
static u32 csRandom(u32 n) {
	return rideinfo_random(&g_bRandom, n);
}

// SpeechCmdIE's call operator (0x80188BD4): one of its two CharIds, bRandom(2).
static void careerSpeechIE(u32 locations, u32 char0, u32 char1, bool purge) {
	const u32 pick = csRandom(2);
	speechPlayIntroEvent(locations, pick ? char1 : char0, purge);
}

// GetCsisMagName / GetCsisDvdName / GetCsisDvdStarName (0x80189FDC,
// 0x8018A010, 0x8018A044): the showcase's +0x28 to its Csis name. The tables
// are SpeedPS.elf's (0x8035E894, 0x8035E934; the stars 0x8035E984).
static u32 csCsisMagName(u32 handle) {
	static const u32 kMag[20][2] = {
		{ 0x9E101F88u, 0x10 }, { 0x601410DCu, 0x80 }, { 0x601417C4u, 0x4 },
		{ 0x9E102056u, 0x40000 }, { 0x9E10211Bu, 0x40 }, { 0x9E102177u, 0x1000000 },
		{ 0x9E1021D0u, 0x8000 }, { 0x72ECA090u, 0x8000 }, { 0x601462B5u, 0x1 },
		{ 0x601417C3u, 0x20 }, { 0x6014211Au, 0x8 }, { 0x9E102097u, 0x1000 },
		{ 0x9E1021DDu, 0x200000 }, { 0x60145E23u, 0x2000 }, { 0x60145E47u, 0x400000 },
		{ 0x9E1021E0u, 0x800 }, { 0x60142B3Bu, 0x100000 }, { 0xB5CBEFB2u, 0x800000 },
		{ 0x9E1021E1u, 0x2000000 }, { 0x60145EB8u, 0x4000 },
	};
	for (int i = 0; i < 20; i++)
		if (kMag[i][0] == handle)
			return kMag[i][1];
	return 0x10;
}
static u32 csCsisDvdName(u32 handle) {
	static const u32 kDvd[10][2] = {
		{ 0x9E101F9Eu, 0x1 }, { 0x9E101FB3u, 0x8 }, { 0x60145C24u, 0x100000 },
		{ 0x629FEDBAu, 0x20 }, { 0x601466BCu, 0x4 }, { 0x62968B8Eu, 0x40 },
		{ 0x6298F309u, 0x2 }, { 0x629CDEFCu, 0x200 }, { 0x60145BE1u, 0x10 },
		{ 0x601459F4u, 0x80 },
	};
	for (int i = 0; i < 10; i++)
		if (kDvd[i][0] == handle)
			return kDvd[i][1];
	return 0x1;
}
static u32 csCsisDvdStarName(u32 stars) {
	// Retail reads stars_27051[stars - 1] with no check; 1..10 are the table.
	return stars >= 1 && stars <= 10 ? 0x400u << (stars - 1) : 0;
}

static void worldRecalcUnlockedZones(void);
static bool g_pileProbing;

// NotifyCSCanSeeEvents (0x8012AE4C) and NotifyCSStage0Timeout (0x8012AE1C):
// the flag, RecalcUnlockedZones and NotifyMinimapNewRace -- which has nothing
// to reset here, the minimap reading the markers every frame.
static void careerNotifyCSCanSeeEvents(void) {
	gProfile.csCanSeeEvents = true;
	g_profileEdits++;
	dlog("career: CareerSpeech event 2 -- NotifyCSCanSeeEvents, stage 0's races open");
	if (!g_pileProbing)
		worldRecalcUnlockedZones();
}
static void careerNotifyCSStage0Timeout(void) {
	gProfile.stage0Timeout = true;
	g_profileEdits++;
	dlog("career: CareerSpeech event 1, third time -- NotifyCSStage0Timeout, stage 0's races close");
	if (!g_pileProbing)
		worldRecalcUnlockedZones();
}

// SMSMessageQueue::AddExternalMessage, events 4 and 6's.
static void careerSpeechSms(u32 hash) {
	if (!g_smsDb)
		return;
	if (sms_add_external_message(&gProfile, g_smsDb, hash) >= 0)
		g_profileEdits++;
}

// HandleSpeechEvent (0x801895D0). Every call is DoSpeechCall(cmd, 0): it
// waits behind a line already speaking.
static void careerSpeechHandle(int event, int arg) {
	char b[128];
	snprintf(b, sizeof(b), "career: CareerSpeech event %d (arg 0x%X)", event, (unsigned)arg);
	if (!g_pileProbing)
		dlog(b);
	switch (event) {
	case CS_EV_STAGE0_RACE_END: {
		// 0 -> 1 -> 2 -> 3, a timed line each (1, 4, 8); the last one is the
		// timeout. At 3 nothing more is said.
		u32 tp = 1;
		if (g_cs.stage0Step == 3)
			return;
		if (g_cs.stage0Step == 1) {
			tp = 4;
			g_cs.stage0Step = 2;
		} else if (g_cs.stage0Step == 0) {
			g_cs.stage0Step = 1;
		} else if (g_cs.stage0Step == 2) {
			g_cs.stage0Step = 3;
			tp = 8;
			careerNotifyCSStage0Timeout();
		}
		if (!g_pileProbing)
			speechPlayTimed(tp, false);
		return;
	}
	case CS_EV_SEE_EVENTS:
		if (!g_pileProbing)
			careerSpeechIE(0x400000, 8, 8, false);
		careerNotifyCSCanSeeEvents();
		return;
	case CS_EV_STAGE1_WIN:
		if (g_cs.stage1Said)
			return;
		if (!g_pileProbing)
			speechPlayCareerID(1, 0x20, false);
		g_cs.stage1Said = 1;
		return;
	default:
		break;
	}
	// DbgPileProbe (#339) runs the queue on made-up states: the lines stay
	// quiet.
	if (g_pileProbing)
		return;
	switch (event) {
	case CS_EV_DDAY_LINE:
		careerSpeechIE(0x8000, 1, 1, false);
		return;
	case CS_EV_FES_4:
		speechPlayCareerID(0x2000, 0x20, false);
		careerSpeechSms(0x51B30CECu);
		return;
	case CS_EV_FES_11:
		speechPlayCareerID(0x1000000, 0x20, false);
		careerSpeechSms(0x83914C51u);
		return;
	case CS_EV_STAGE_CLEARED:
		speechPlayCareerID(0x40, 0x20, false);
		return;
	case CS_EV_UNIQUE_VISUAL:
		speechPlayCareerID(0x80, 0x20, false);
		return;
	case CS_EV_UNIQUE_PERF:
		speechPlayCareerID(0x100, 0x20, false);
		return;
	case CS_EV_FES_11_LATER:
		speechPlayCareerID(0x800000, 0x10, false);
		return;
	case CS_EV_SPONSOR:
		speechPlayCareerID(0x20000, 0x20, false);
		return;
	case CS_EV_STAGE_STARTED: {
		// The new stage's area: stages 2 to 5 (DAT_8032D35C..68).
		static const u32 kArea[4] = { 1, 2, 4, 4 };
		if ((unsigned)(g_cs.stageStarted - 2) < 4)
			speechPlayIntroArea(kArea[g_cs.stageStarted - 2], 0x20, false);
		g_cs.stageStarted = 0;
		return;
	}
	case CS_EV_DVD_UNLOCK:
		speechPlayCareerDVD(csCsisDvdName((u32)arg), 1, false);
		g_cs.dvdPending = 0;
		return;
	case CS_EV_MAG_UNLOCK:
		speechPlayCareerMag(csCsisMagName((u32)arg), 1, false);
		return;
	case CS_EV_DVD_STARS:
		speechPlayCareerDVD(csCsisDvdStarName((u32)arg), 4, false);
		return;
	default:
		return;
	}
}

// UpdateTimerEvents (0x801894A4): every queued event counts down; the one
// furthest below the running lowest -- slot 0's, free or not, to begin with
// -- is handled once it is under one tick and no line is playing
// (IsSpeechDone, 0x8018A9B8).
static void careerSpeechUpdate(int ticks) {
	int best = 0;
	for (int i = 0; i < CS_TIMER_SLOTS; i++)
		if (g_cs.timer[i].event) {
			g_cs.timer[i].time -= ticks;
			if (g_cs.timer[i].time < g_cs.timer[best].time)
				best = i;
		}
	CsTimerEvent* t = &g_cs.timer[best];
	if (t->event && t->time < 1 && (g_pileProbing || !speechIsPlaying())) {
		careerSpeechHandle(t->event, t->arg);
		memset(t, 0, sizeof(*t)); // ClearTimerEvent
	}
}

// GetNeighbourhoodNameInfo's NeighbourhoodNameInfoTable (0x8036FBC0): each
// neighbourhood zone's +0x30 handle is bStringHash of its name. Beside each,
// FEngHashStringUpper("NEIGHBOURHOOD_%s") -- the string Player +0x9B0 holds
// and the NeighbourhoodIndicator prints -- and the Csis Locations flag
// HandleNeighbourhood (0x8018A54C) maps it to. EL_NORTE is in the table but
// in no shipped Paths file. JACKSON_HEIGHTS and PIGEON_PARK map to Locations
// the bank has no Intro_Events line for (0x200000, 0x100000) -- SPEED2.EXE's
// twin (0x524907..0x5249C7) maps them the same -- so retail says nothing for
// them either, and the bank's lines for 0x2 and 0x800 are never asked for.
static const struct { u32 zone, hash, locations; } kCsHood[13] = {
	{ 0x423B3BD3u, 0x5755251Fu, 0x200000 },   // JACKSON_HEIGHTS
	{ 0x1D59976Eu, 0xAB3ABABAu, 0x100000 },   // PIGEON_PARK
	{ 0x57C31EBBu, 0x101A3187u, 0x1 },        // BEACON_HILL_EAST
	{ 0x57CD0E91u, 0x1024215Du, 0x1 },        // BEACON_HILL_WEST
	{ 0x60BDFFCEu, 0xB8FCE39Au, 0x1000000 },  // HOTELS
	{ 0xD01BCE73u, 0x30372BBFu, 0x800000 },   // FINANCE
	{ 0x5AE835A2u, 0xBC4C1F6Eu, 0x8000 },     // FORT_UNION
	{ 0xF6D63DD7u, 0x5A5D44A3u, 0x10 },       // EL_NORTE
	{ 0x033F8BB5u, 0x4D451881u, 0x40000 },    // SOUTH_MARKET
	{ 0xD18FF6D6u, 0x31AB5422u, 0x80 },       // STADIUM
	{ 0x4F8940A0u, 0xAFA49DECu, 0x40 },       // AIRPORT
	{ 0xF7CF0B7Cu, 0xBB0877C8u, 0x8000000 },  // COAL_HARBOUR_EAST
	{ 0xF7D8FB52u, 0xBB12679Eu, 0x10000000 }, // COAL_HARBOUR_WEST
};

static int csHoodOfZone(const TrackPathZone* z) {
	const u32 h = z ? trackpath_handle(z) : 0;
	for (int i = 0; i < 13; i++)
		if (kCsHood[i].zone == h)
			return i;
	return -1;
}

// GetRandomHiddenEvent (0x80125948), from GetRandomHiddenEventFromPile: a
// draw over the pile's hidden events (+0x7F), but the walk that follows
// counts every event, hidden or not -- so it is one of the first n of the
// pile, n the hidden count. Retail's, kept.
static const EventRec* careerPileRandomHidden(void) {
	int n = 0;
	for (int i = 0; i < PILE_MAX_EVENTS; i++)
		if (g_pile.event[i] && g_pile.event[i]->isHidden)
			n++;
	if (n == 0)
		return NULL;
	int left = (int)csRandom((u32)n) + 1;
	for (int i = 0; i < PILE_MAX_EVENTS; i++)
		if (g_pile.event[i] && --left == 0)
			return g_pile.event[i];
	return NULL;
}

static const TrackPathZone* trackZoneByDataHandle(u32 handle);

// HandleNeighbourhood (0x8018A54C), from HandleTick past stage 1: as the car
// crosses into another neighbourhood, with no line speaking and 300 s since
// the last of these, a hidden event of the pile that lies in yet another
// neighbourhood has Rachel name its area (SpeechCmdIE(loc, 8, 0x10)).
static void careerSpeechNeighbourhood(void) {
	const int here = csHoodOfZone(g_zoneHood);
	if (here < 0)
		return;
	const u32 cur = kCsHood[here].hash;
	if (g_cs.hood == 0) {
		g_cs.hood = cur;
		g_cs.hoodTime = g_cs.timerTicks;
	}
	if (cur == g_cs.hood)
		return;
	g_cs.hood = cur;
	if (speechIsPlaying() || g_cs.timerTicks - g_cs.hoodTime < 300 * 4000)
		return;
	const EventRec* ev = careerPileRandomHidden();
	const TrackPathZone* tz = ev ? trackZoneByDataHandle(ev->triggerHandle) : NULL;
	const TrackPathZone* hz = tz && g_paths
		? trackpath_find(g_paths, tz->entry[0], tz->entry[1], TPZ_NEIGHBOURHOOD, NULL) : NULL;
	const int there = csHoodOfZone(hz);
	if (there < 0 || kCsHood[there].hash == cur)
		return;
	char b[160];
	snprintf(b, sizeof(b), "career: CareerSpeech HandleNeighbourhood -- %s lies in another "
		"neighbourhood (Locations 0x%lX)", ev->name, (unsigned long)kCsHood[there].locations);
	dlog(b);
	careerSpeechIE(kCsHood[there].locations, 8, 0x10, false);
	g_cs.hoodTime = g_cs.timerTicks;
}

// RealTimer (SpeedPS.elf 0x8046FED4): the console's real time in Timer ticks
// (1/4000 s). Retail's own runs from boot as well.
static int csRealTimer(void) {
	return (int)(svcGetSystemTick() * 4000ull / SYSCLOCK_ARM11);
}

// HandleTick (0x80188DD4): first its two clocks -- WorldTimer's and
// RealTimer's run since the last tick, a value of 0 or 0x7fffffff being one
// not set yet -- whatever the career clock says. RealTimer's is the frontend
// lines' repeat guard. Then, past the career clock's first 0.0, its step
// since the last tick, in Timer ticks, into the timer and the queue; then the
// neighbourhood line and the DVD star line.
static void careerSpeechTick(void) {
	const int real = csRealTimer();
	if (g_cs.realLast == 0 || g_cs.realLast == 0x7fffffff)
		g_cs.realLast = real;
	g_cs.realClock += real - g_cs.realLast;
	g_cs.realLast = real;
	if (gProfile.careerTime <= 0.0f)
		return;
	const int now = (int)(gProfile.careerTime * 4000.0f);
	if (g_cs.lastTicks == 0 || g_cs.lastTicks == 0x7fffffff)
		g_cs.lastTicks = now;
	const int d = now - g_cs.lastTicks;
	g_cs.lastTicks = now;
	g_cs.timerTicks += d;
	careerSpeechUpdate(d);
	if (g_careerStage > 1)
		careerSpeechNeighbourhood();
	if (g_cs.fes2Seen) {
		const int s = g_cs.dvdStar;
		if (g_cs.sponsorSaid && !g_cs.dvdPending && s != 0 && s < 11 && !g_cs.dvdStarSaid[s]) {
			careerSpeechAdd(1.0f, CS_EV_DVD_STARS, s);
			g_cs.dvdStarSaid[s] = 1;
			g_cs.dvdStar = 0;
		}
		g_cs.fes2Seen = 0;
	}
}

// HandleCareerEventBegin (0x80189144), from NotifyEnterShopEvent and
// NotifyEnterEvent: DDAY_EVENT_A queues event 2 at 15 s and event 3 at 40 s,
// each unless one is queued.
static void careerSpeechEventBegin(u32 eventId) {
	if (eventId != CAREER_PROLOGUE_FIRST_EVENT)
		return;
	if (!careerSpeechQueued(CS_EV_SEE_EVENTS))
		careerSpeechAdd(15.0f, CS_EV_SEE_EVENTS, 0);
	if (!careerSpeechQueued(CS_EV_DDAY_LINE))
		careerSpeechAdd(40.0f, CS_EV_DDAY_LINE, 0);
	dlog("career: CareerSpeech HandleCareerEventBegin(DDAY_EVENT_A) -- events 2 (15 s) and 3 (40 s) queued");
}

// HandleCareerEventEnd (0x801891F4), from CommitWinEvent (won) and
// CommitLoseEvent: a stage 0 race (STAGE_0_CIRCUIT_0/1, STAGE_0_SPRINT_0)
// queues event 1 a second on; DDAY_EVENT_A done ends event 1's count; and a
// won race queues stage 1's once-only line and a stage's cleared line.
static void careerSpeechEventEnd(const EventRec* ev, bool won) {
	const u32 id = ev->eventId;
	if (id < 0xCA207585u) {
		if ((id > 0xCA207582u || id == 0x1BCB7AB0u) && !careerSpeechQueued(CS_EV_STAGE0_RACE_END))
			careerSpeechAdd(1.0f, CS_EV_STAGE0_RACE_END, 0);
	} else if (id == CAREER_PROLOGUE_FIRST_EVENT) {
		g_cs.stage0Step = 3;
		g_cs.ddayDone = 1;
	}
	if (ev->cls != EVENT_CLASS_DDAY && won) {
		if (!g_cs.stage1Said && ev->stage == 1)
			careerSpeechAdd(1.0f, CS_EV_STAGE1_WIN, 0);
		const StageRec* sd = g_shopsOk ? eventdb_stage(&g_shops, ev->stage) : NULL;
		if (sd && sd->clearEvent == id && ev->stage != 5)
			careerSpeechAdd(1.0f, CS_EV_STAGE_CLEARED, 0);
	}
}

// HandleOutrunStart (0x80188FD0), from NotifyBeginGetAway: Rachel's own line
// the first time (never, in a career -- DDAY_EVENT_A's end has set +0x04),
// otherwise one of the five voices, drawn, taunts. DoSpeechCall(cmd, 1).
static void careerSpeechOutrunStart(void) {
	if (g_cs.ddayDone == 0) {
		speechPlayOutrun(0x20, 0x200, true);
		return;
	}
	g_cs.taunt = (u8)csRandom(5);
	speechPlayOutrun(1, kCsTauntCharId[g_cs.taunt], true);
}

// HandleOutrunEnd (0x80189058), from NotifyRandomEncounterFinished: the same
// voice's win or loss line, one of two each.
static void careerSpeechOutrunEnd(bool won) {
	if (g_cs.ddayDone == 0) {
		speechPlayOutrun(won ? 0x40 : 0x80, 0x200, true);
		g_cs.ddayDone = 1;
		return;
	}
	const u32 parms = won ? (csRandom(2) ? 0x10 : 8) : (csRandom(2) ? 2 : 4);
	speechPlayOutrun(parms, kCsTauntCharId[g_cs.taunt % 5], true);
}

// HandleStageStarted (0x8018A7F8), from NotifyStageCleared with the new
// stage: event 12 at 15 s unless one is waiting on +0xE9.
static void careerSpeechStageStarted(int stage) {
	if (g_cs.stageStarted == 0)
		careerSpeechAdd(15.0f, CS_EV_STAGE_STARTED, 0);
	g_cs.stageStarted = (u8)stage;
}

// IsShowcaseUnlocked / AddShowcaseUnlock (0x8018AA60 / 0x8018AAA4).
static bool careerSpeechShowcaseSaid(u32 h) {
	for (int i = 0; i < g_cs.showcaseCount && i < CS_SHOWCASES; i++)
		if (g_cs.showcase[i] == h)
			return true;
	return false;
}
static void careerSpeechShowcaseAdd(u32 h) {
	if (g_cs.showcaseCount < CS_SHOWCASES)
		g_cs.showcase[g_cs.showcaseCount++] = h;
}

// HandleShowcaseUnlock (0x8018A260), from RecalcDVDUnlocks and
// HandleWorldChallengeUnlock: a magazine's line (event 14) or a DVD cover's
// (event 13, only once the frontend's event 2 has been seen), each once.
static void careerSpeechShowcaseUnlock(const ShowcaseRec* sc) {
	if (!sc)
		return;
	if (sc->type == 1 || sc->type == 3) {
		if (!careerSpeechShowcaseSaid(sc->magHash)) {
			careerSpeechShowcaseAdd(sc->magHash);
			careerSpeechAdd(1.0f, CS_EV_MAG_UNLOCK, (int)sc->magHash);
		}
	} else if ((sc->type == 2 || sc->type == 4) && !careerSpeechShowcaseSaid(sc->magHash) &&
			g_cs.fes2Seen) {
		careerSpeechShowcaseAdd(sc->magHash);
		careerSpeechAdd(1.0f, CS_EV_DVD_UNLOCK, (int)sc->magHash);
		g_cs.dvdPending = 1;
		const int s = (int)sc->starRating;
		if (s >= 0 && s < 11)
			g_cs.dvdStarSaid[s] = 1;
	}
}

// HandleWorldChallengeUnlock (0x8018A374), beside AddWorldChallengeMessage:
// a showcase challenge (+0x14 3 or 4) unlocks its showcase's line.
static void careerSpeechWorldChallengeUnlock(const WorldChallengeRec* c) {
	if (c->type == WC_TYPE_3 || c->type == WC_TYPE_SHOWCASE)
		careerSpeechShowcaseUnlock(g_shopsOk ? eventdb_showcase_by_handle(&g_shops,
			c->goalHandle) : NULL);
}

// The shop the player walked into: PlayerCareerState +0x7DF0 (set) and
// +0x7DF8 (the ShopDataDesc), which NotifyEnterShopFromFreeRoam (0x80126DB0)
// writes for every shop, the car lot's included. HandleFESpeechEvent reads
// its +0x38 and +0x50. Set by careerEnterShop, cleared when the world is
// entered again.
static struct {
	bool valid;
	s8 kind;
	u32 handle;
	u32 doorShop;   // the shop walked into (the uniques' room is another): its exit NIS
} g_csShop;

// The SDA word at r13-0x6EF4: the crib is the frontend's way in. Event 0x11
// (the crib opened) sets it; a shop walk-in sets it to (shop type == 0). While
// set, events 1, 2 and 0x12 -- the categories the crib's own menu opens --
// become 0x11, which says nothing past its first time.
static int g_csFromCrib;

// HandleFESpeechEvent (0x80189940), from the frontend screens on their
// screen-open message (0x35F8620B) and from the two category handlers. The
// career only (GameMode, DAT_803CE800, 1). Each event speaks at most once in
// an hour of RealTimer (DAT_8032D374, 3600 s) and stamps fe[] with the clock;
// events 4 and 0x11 have a first time of their own, queued behind any line
// speaking (DoSpeechCall(cmd, 0)), that times events in the career clock
// (DAT_8032D36C 1 s, DAT_8032D370 30 s) and stamps nothing. Every other line
// cuts in (DoSpeechCall(cmd, 1)). True when the event was taken.
static bool careerSpeechFE(int ev) {
	if (!careerInProgress() || ev < 0 || ev >= CS_FE_EVENTS)
		return false;
	const int asked = ev;
	if (ev == 0x11)
		g_csFromCrib = 1;
	if (g_csShop.valid) {
		g_csFromCrib = g_csShop.kind == 0;
		// CC_MEGALOW, the one shop whose categories open on event 0.
		if (g_csShop.handle == PERFDB_CC_MEGALOW_HASH && ev == 1)
			ev = 0;
	}
	if (g_csFromCrib && (ev == 1 || ev == 2 || ev == 0x12))
		ev = 0x11;
	char b[192];
	if (ev == 4 && !g_cs.fes4Said) {
		g_cs.fes4Said = 1;
		speechPlayFEScreen(0x1000000, 0x20, false);
		careerSpeechAdd(1.0f, CS_EV_FES_4, 0);
		dlog("career: CareerSpeech FE event 4, the first -- FEScreen(0x1000000) asked for, "
			"event 4 in 1 s");
		return true;
	}
	if (ev == 0x11 && !g_cs.fes11Said) {
		g_cs.fes11Said = 1;
		speechPlayFEScreen(0x100000, 0x10, false);
		careerSpeechAdd(1.0f, CS_EV_FES_11, 0);
		careerSpeechAdd(30.0f, CS_EV_FES_11_LATER, 0);
		dlog("career: CareerSpeech FE event 0x11, the first -- FEScreen(0x100000) asked for, "
			"events 6 (1 s) and 10 (30 s)");
		return true;
	}
	if (ev == 2)
		g_cs.fes2Seen = 1;
	const int was = g_cs.fe[ev];
	const bool stamped = was != 0 && was != 0x7fffffff;
	if (stamped && g_cs.realClock - was <= 3600 * 4000) {
		snprintf(b, sizeof(b), "career: CareerSpeech FE event 0x%X%s -- raised %.0f s ago, "
			"quiet for the hour", ev, ev != asked ? " (asked as another)" : "",
			(double)(g_cs.realClock - was) / 4000.0);
		dlog(b);
		return false;
	}
	// The screens' Type_FE_Screen bits, events 0..0x10; 0x11 says nothing.
	static const u32 kScreen[0x11] = {
		0x400000, 0x800000, 0x8, 0x10, 0x20, 0x40, 0x80, 0x100, 0x400, 0x800,
		0x2000, 0x4000, 0x8000, 0x10000, 0x20000, 0x40000, 0x80000,
	};
	// The dyno's Type_Dynoshop bits, events 0x13..0x1B.
	static const u32 kDyno[9] = { 0x1, 0x2, 0x4, 0x8, 0x10, 0x20, 0x40, 0x80, 0x100 };
	const char* said = "nothing (the crib's own)";
	if (ev <= 0x10) {
		// Events 0 and 1 have a line of their own for a return past the hour.
		const u32 bits = (ev <= 1 && stamped) ? 1u : kScreen[ev];
		speechPlayFEScreen(bits, 0x20, true);
		snprintf(b, sizeof(b), "FEScreen(0x%lX, 0x20)", (unsigned long)bits);
		said = b;
	} else if (ev == 0x12) {
		speechPlayFEScreen(0x2000000, 0x20, true);
		said = "FEScreen(0x2000000, 0x20)";
	} else if (ev >= 0x13) {
		speechPlayFEDynoshop(kDyno[ev - 0x13], 0x10, true);
		snprintf(b, sizeof(b), "FEDynoshop(0x%lX, 0x10)", (unsigned long)kDyno[ev - 0x13]);
		said = b;
	}
	char line[256];
	snprintf(line, sizeof(line), "career: CareerSpeech FE event 0x%X%s -- %s", ev,
		ev != asked ? " (asked as another)" : "", said);
	dlog(line);
	g_cs.fe[ev] = g_cs.realClock;
	return true;
}

// HandlePerformanceCategory (0x80189E5C), from PerfCategoryThing::React's
// PAD_ACCEPT (0x8030E804): the category's ePerfPackageTypes to its event.
static void careerSpeechPerfCategory(int type) {
	static const int kEv[9] = { 0x10, 0xC, 0x9, 0x7, 0xD, 0xA, 0x3, 0x6, 0xB };
	if (type >= 0 && type < 9)
		careerSpeechFE(kEv[type]);
}

// HandleSponsorSelect (0x8018A3C0), from uiSponsorsMain's screen-open: once
// a time the list is up, the first sponsor line ever (queued, and timer event
// 11 in 1 s, DAT_8032D37C) or the one after it.
static void careerSpeechSponsorSelect(void) {
	if (g_cs.sponsorOpen)
		return;
	g_cs.sponsorOpen = 1;
	if (!g_cs.sponsorSaid) {
		g_cs.sponsorSaid = 1;
		speechPlayCareerID(0x8000000, 0x20, false);
		careerSpeechAdd(1.0f, CS_EV_SPONSOR, 0);
		dlog("career: CareerSpeech HandleSponsorSelect, the first -- Career(0x8000000) asked "
			"for, event 11 in 1 s");
	} else {
		speechPlayCareerID(0x10, 0x20, false);
		dlog("career: CareerSpeech HandleSponsorSelect -- Career(0x10) asked for");
	}
}

// HandleSponsorSelectDone (0x8018A470), from uiSponsorsMain's Yes
// (0xD05FC3A3), before ChooseSponsor.
static void careerSpeechSponsorSelectDone(void) {
	g_cs.sponsorOpen = 0;
}

// The screen-open message (0x35F8620B) of the screens that raise an FE event
// and that the port has (SpeedPS.elf, tools/re/wip268/fe_callers_ps.c):
// uiCareerCrib (0x800D2378) 0x11, UICareerCarLot (0x800D3AE8) 4,
// ChoosePerfCategory (0x80171938) 1, PartSelectionScreen (0x801615F8) 2 in
// CarCustomizeManager's mode 0 (DAT_803D84E4: the body shop, not the vinyls,
// decals or specialties on its package), ChooseDecalCategory (0x80166978) 5,
// IceSelectionScreen (0x801695C4) 0x12 in its mode 0 (DAT_803D84EC: the shop,
// not a trunk audio screen), ChoosePaintShopCategory (0x80175F28) 0xF,
// ChooseVinylLayerScreen (0x8017695C) 0xE and ChoosePaintScreen (0x80177658)
// 8 when the paint category (DAT_803D84F0) is 2, the plain paint shop -- the
// port's only UI_Paint mode. ChooseCustomizeCategory sends HandleEnterShop,
// which is empty. The frontend loop calls it when its
// screen changes; g_csScreenOpen is the last one it saw, emptied at each world
// entry so a screen opened from the world again counts.
static char g_csScreenOpen[64];
static void careerSpeechScreenOpened(const char* screen) {
	if (strcasecmp(screen, "UI_CareerCrib.fng") == 0)
		careerSpeechFE(0x11);
	else if (strcasecmp(screen, CARLOT_SCREEN) == 0)
		careerSpeechFE(4);
	else if (strcasecmp(screen, PERFCAT_SCREEN) == 0)
		careerSpeechFE(1);
	else if (strcasecmp(screen, BODYSHOP_SCREEN) == 0) {
		// The package's modes: set by bodyShopItems() as the screen loaded.
		if (g_bodyShop.decalMode)
			careerSpeechFE(5);
		else if (!g_bodyShop.vinylMode && !g_bodyShop.iceMode)
			careerSpeechFE(2);
	} else if (strcasecmp(screen, ICEMAIN_SCREEN) == 0) {
		if (g_iceMode == ICE_MODE_MAIN)
			careerSpeechFE(0x12);
	} else if (strcasecmp(screen, PAINTCAT_SCREEN) == 0)
		careerSpeechFE(0xF);
	else if (strcasecmp(screen, VINYL_LAYER_SCREEN) == 0)
		careerSpeechFE(0xE);
	else if (strcasecmp(screen, PAINT_SCREEN) == 0)
		careerSpeechFE(8);
}

// HandleDVDStars (0x8018A47C), RecalcDVDUnlocks' last call: the stars of
// the dearest cover still locked.
static void careerSpeechDVDStars(const ShowcaseRec* sc) {
	g_cs.dvdStar = sc ? (u8)(int)sc->starRating : 0;
}

// HandleEngageRequest (0x8018A05C), as an engage dialog's package comes up
// (message 0x35F8620B): the three stage 0 races have a line each, once; a
// showcase its magazine's or cover's. DoSpeechCall(cmd, 1).
static void careerSpeechEngageRequest(const EventRec* ev, const ShowcaseRec* sc) {
	g_cs.engagePlaying = 0;
	if (!ev) {
		if (sc && (sc->type == 1 || sc->type == 3))
			speechPlayCareerMag(csCsisMagName(sc->magHash), 2, true);
		else if (sc && (sc->type == 2 || sc->type == 4))
			speechPlayCareerDVD(csCsisDvdName(sc->magHash), 2, true);
		return;
	}
	static const struct { u32 id, crEvent, charId; } kEngage[3] = {
		{ 0xCA207583u, 0x80000, 1 },    // +0x5C
		{ 0xCA207584u, 0x100000, 8 },   // +0x60
		{ 0x1BCB7AB0u, 0x200000, 0x200 }, // +0x64
	};
	for (int i = 0; i < 3; i++)
		if (ev->eventId == kEngage[i].id) {
			if (g_cs.engageSaid[i])
				return;
			speechPlayCareerID(kEngage[i].crEvent, kEngage[i].charId, true);
			g_cs.engagePlaying = 1;
			g_cs.engageSaid[i] = 1;
			return;
		}
}

// HandleEngageDecline (0x8018A224), from DeclineRace and the challenge
// dialog's Cancel: an engage line still speaking is cut off.
static void careerSpeechEngageDecline(void) {
	if (g_cs.engagePlaying) {
		g_cs.engagePlaying = 0;
		speechPurge();
	}
}

// HandleShowcaseMode (0x8018A85C), as ShowcaseMagazineDialog's package comes
// up: Rachel's line on the photo shoot, once.
static void careerSpeechShowcaseMode(void) {
	if (g_cs.showcaseModeSaid == 0) {
		speechPlayCareerID(0x10000, 0x20, false);
		g_cs.showcaseModeSaid = 1;
	}
}

// ---- CareerSpeech's save block (#268 I step 3) ------------------------------
// The PC's CareerSpeech is PlayerCareerState +0x887C, 0x190 bytes, copied raw
// by SaveToBuffer (SPEED2.EXE 0x514530) and LoadFromBuffer (0x529230). It has
// the GameCube's fields in the same order, its flags bytes rather than ints,
// which is why it is 0x48 smaller. The offsets come from the PC's own methods
// on it: Default 0x531800, HandleTick 0x551070, the timer tick 0x54BD30,
// HandleSpeechEvent 0x53E0B0, HandleFESpeechEvent 0x5243D0, the engage request
// 0x5251A0 and decline 0x511280, HandleSponsorSelect 0x525510 / Done 0x5112A0,
// HandleShowcaseUnlock 0x5253F0, ShowcaseMode 0x525850, the Outrun start
// 0x511000 and end 0x5110C0, and the career event end 0x5242C0.
// +0x00 is a byte only Default writes (the GameCube's +0x00 int, which nothing
// reads either); it and the padding are left as the save has them.
enum {
	CSB_DDAY          = 0x01,  // u8, GC +0x04
	CSB_STAGE0_STEP   = 0x04,  // s32, GC +0x08
	CSB_STAGE1_SAID   = 0x08,  // u8, GC +0x0C
	CSB_FES4_SAID     = 0x09,  // u8, GC +0x10
	CSB_FES11_SAID    = 0x0A,  // u8, GC +0x14
	CSB_SPONSOR_OPEN  = 0x0B,  // u8, GC +0x18
	CSB_SPONSOR_SAID  = 0x0C,  // u8, GC +0x1C
	CSB_DVD_STAR_SAID = 0x0D,  // u8[11], GC +0x20 int[11]
	CSB_DVD_PENDING   = 0x18,  // u8, GC +0x4C
	CSB_DVD_STAR      = 0x19,  // u8, GC +0x50
	CSB_TAUNT         = 0x1A,  // u8, GC +0x51
	CSB_HOOD          = 0x1C,  // u32, GC +0x54
	CSB_HOOD_TIME     = 0x20,  // s32, GC +0x58
	CSB_ENGAGE_SAID   = 0x24,  // u8[3], GC +0x5C int[3]
	CSB_ENGAGE_PLAYING= 0x27,  // u8, GC +0x68
	CSB_FES2_SEEN     = 0x28,  // u8, GC +0x6C
	CSB_SHOWCASES     = 0x2C,  // u32[30], GC +0x70
	CSB_SHOWCASE_N    = 0xA4,  // u8, GC +0xE8
	CSB_STAGE_STARTED = 0xA5,  // u8, GC +0xE9
	CSB_SHOWCASE_MODE = 0xA6,  // u8, GC +0xEC
	CSB_TIMERS        = 0xA8,  // {s32 time, event, arg}[8], GC +0xF0
	CSB_CLOCKS        = 0x108, // s32[6], GC +0x150
	CSB_FE            = 0x120, // s32[0x1C], GC +0x168
};
_Static_assert(CSB_FE + CS_FE_EVENTS * 4 == PROFILE_SPEECH_BLOCK, "CareerSpeech block size");

static int csbGet32(const unsigned char* b, int o) {
	return (int)((u32)b[o] | (u32)b[o + 1] << 8 | (u32)b[o + 2] << 16 | (u32)b[o + 3] << 24);
}

static void csbPut32(unsigned char* b, int o, int v) {
	const u32 u = (u32)v;
	b[o] = (unsigned char)u;
	b[o + 1] = (unsigned char)(u >> 8);
	b[o + 2] = (unsigned char)(u >> 16);
	b[o + 3] = (unsigned char)(u >> 24);
}

// LoadFromBuffer's share: the block whole, then the four it zeroes (the
// neighbourhood, and the three clocks' last readings, so each picks up from
// the next tick).
static void careerSpeechLoadBlock(void) {
	careerSpeechDefault();
	if (!gProfile.isLoaded)
		return;
	const unsigned char* b = gProfile.speechBlock;
	g_cs.ddayDone = b[CSB_DDAY];
	g_cs.stage0Step = csbGet32(b, CSB_STAGE0_STEP);
	g_cs.stage1Said = b[CSB_STAGE1_SAID];
	g_cs.fes4Said = b[CSB_FES4_SAID];
	g_cs.fes11Said = b[CSB_FES11_SAID];
	g_cs.sponsorOpen = b[CSB_SPONSOR_OPEN];
	g_cs.sponsorSaid = b[CSB_SPONSOR_SAID];
	for (int i = 0; i < 11; i++)
		g_cs.dvdStarSaid[i] = b[CSB_DVD_STAR_SAID + i];
	g_cs.dvdPending = b[CSB_DVD_PENDING];
	g_cs.dvdStar = b[CSB_DVD_STAR];
	g_cs.taunt = b[CSB_TAUNT];
	g_cs.hood = 0;
	g_cs.hoodTime = csbGet32(b, CSB_HOOD_TIME);
	for (int i = 0; i < 3; i++)
		g_cs.engageSaid[i] = b[CSB_ENGAGE_SAID + i];
	g_cs.engagePlaying = b[CSB_ENGAGE_PLAYING];
	g_cs.fes2Seen = b[CSB_FES2_SEEN];
	for (int i = 0; i < CS_SHOWCASES; i++)
		g_cs.showcase[i] = (u32)csbGet32(b, CSB_SHOWCASES + i * 4);
	g_cs.showcaseCount = b[CSB_SHOWCASE_N];
	g_cs.stageStarted = b[CSB_STAGE_STARTED];
	g_cs.showcaseModeSaid = b[CSB_SHOWCASE_MODE];
	for (int i = 0; i < CS_TIMER_SLOTS; i++) {
		g_cs.timer[i].time = csbGet32(b, CSB_TIMERS + i * 12);
		g_cs.timer[i].event = csbGet32(b, CSB_TIMERS + i * 12 + 4);
		g_cs.timer[i].arg = csbGet32(b, CSB_TIMERS + i * 12 + 8);
	}
	g_cs.worldLast = 0;
	g_cs.worldClock = csbGet32(b, CSB_CLOCKS + 0x04);
	g_cs.lastTicks = 0;
	g_cs.timerTicks = csbGet32(b, CSB_CLOCKS + 0x0C);
	g_cs.realLast = 0;
	g_cs.realClock = csbGet32(b, CSB_CLOCKS + 0x14);
	for (int i = 0; i < CS_FE_EVENTS; i++)
		g_cs.fe[i] = csbGet32(b, CSB_FE + i * 4);
	// Out of range would index past the arrays that read them.
	if (g_cs.showcaseCount > CS_SHOWCASES)
		g_cs.showcaseCount = CS_SHOWCASES;
	if (g_cs.taunt >= 5)
		g_cs.taunt = 0;
	int queued = 0;
	for (int i = 0; i < CS_TIMER_SLOTS; i++)
		queued += g_cs.timer[i].event != 0;
	char m[256];
	snprintf(m, sizeof(m), "career: CareerSpeech from the save -- DDAY %s, stage 0 step %d, "
		"stage 1 line %s, engage lines %d%d%d, car lot / crib / sponsor first lines %d%d%d, "
		"%d showcases announced, shoot line %s, %d timer events queued, realClock %.0f s",
		g_cs.ddayDone ? "past" : "ahead", g_cs.stage0Step, g_cs.stage1Said ? "said" : "ahead",
		g_cs.engageSaid[0], g_cs.engageSaid[1], g_cs.engageSaid[2], g_cs.fes4Said,
		g_cs.fes11Said, g_cs.sponsorSaid, g_cs.showcaseCount,
		g_cs.showcaseModeSaid ? "said" : "ahead", queued, g_cs.realClock / 4000.0);
	dlog(m);
}

// SaveToBuffer's share: the struct back into the PC's layout, the bytes this
// struct does not hold left as they were.
static void careerSpeechStoreBlock(void) {
	unsigned char* b = gProfile.speechBlock;
	b[CSB_DDAY] = g_cs.ddayDone != 0;
	csbPut32(b, CSB_STAGE0_STEP, g_cs.stage0Step);
	b[CSB_STAGE1_SAID] = g_cs.stage1Said != 0;
	b[CSB_FES4_SAID] = g_cs.fes4Said != 0;
	b[CSB_FES11_SAID] = g_cs.fes11Said != 0;
	b[CSB_SPONSOR_OPEN] = g_cs.sponsorOpen != 0;
	b[CSB_SPONSOR_SAID] = g_cs.sponsorSaid != 0;
	for (int i = 0; i < 11; i++)
		b[CSB_DVD_STAR_SAID + i] = g_cs.dvdStarSaid[i] != 0;
	b[CSB_DVD_PENDING] = g_cs.dvdPending != 0;
	b[CSB_DVD_STAR] = g_cs.dvdStar;
	b[CSB_TAUNT] = g_cs.taunt;
	csbPut32(b, CSB_HOOD, (int)g_cs.hood);
	csbPut32(b, CSB_HOOD_TIME, g_cs.hoodTime);
	for (int i = 0; i < 3; i++)
		b[CSB_ENGAGE_SAID + i] = g_cs.engageSaid[i] != 0;
	b[CSB_ENGAGE_PLAYING] = g_cs.engagePlaying != 0;
	b[CSB_FES2_SEEN] = g_cs.fes2Seen != 0;
	for (int i = 0; i < CS_SHOWCASES; i++)
		csbPut32(b, CSB_SHOWCASES + i * 4, (int)g_cs.showcase[i]);
	b[CSB_SHOWCASE_N] = g_cs.showcaseCount;
	b[CSB_STAGE_STARTED] = g_cs.stageStarted;
	b[CSB_SHOWCASE_MODE] = g_cs.showcaseModeSaid != 0;
	for (int i = 0; i < CS_TIMER_SLOTS; i++) {
		csbPut32(b, CSB_TIMERS + i * 12, g_cs.timer[i].time);
		csbPut32(b, CSB_TIMERS + i * 12 + 4, g_cs.timer[i].event);
		csbPut32(b, CSB_TIMERS + i * 12 + 8, g_cs.timer[i].arg);
	}
	csbPut32(b, CSB_CLOCKS + 0x00, g_cs.worldLast);
	csbPut32(b, CSB_CLOCKS + 0x04, g_cs.worldClock);
	csbPut32(b, CSB_CLOCKS + 0x08, g_cs.lastTicks);
	csbPut32(b, CSB_CLOCKS + 0x0C, g_cs.timerTicks);
	csbPut32(b, CSB_CLOCKS + 0x10, g_cs.realLast);
	csbPut32(b, CSB_CLOCKS + 0x14, g_cs.realClock);
	for (int i = 0; i < CS_FE_EVENTS; i++)
		csbPut32(b, CSB_FE + i * 4, g_cs.fe[i]);
}

// Every career save goes through here, so CareerSpeech is on the card as of
// the save. A DbgPileProbe run's made-up CareerSpeech is never stored.
static bool careerSaveProfile(void) {
	if (!g_pileProbing)
		careerSpeechStoreBlock();
	return profile_save_career(&gProfile);
}

// A new career's start: Default's empty pile and CareerSpeech
// (PlayerCareerState::Default, SPEED2.EXE 0x532830, calls CareerSpeech's at
// 0x531800).
static void careerResetUnsaved(void) {
	careerPileReset();
	careerSpeechDefault();
}

// A profile load: the pile is not saved, so it starts empty; CareerSpeech
// comes from the save (PlayerCareerState::LoadFromBuffer).
static void careerLoadUnsaved(void) {
	careerPileReset();
	careerSpeechLoadBlock();
}

// ---- DbgPileProbe (TASKS.md #339): the rules a stage 4 save never reaches --
// BuildListOfEvents' stage 5 end, HasCompletedCareer and stage 0's CareerSpeech
// gate, run once on made-up career states -- completion records and flags set
// in RAM -- and each pile logged with what retail's rules give. CareerSpeech's
// queue is driven through DDAY_EVENT_A's 15 s and three stage 0 race ends on
// the same faked stage 0. Everything is put back after (the profile, the
// stage, the pile, bRandom, the queue and the edit count), so nothing reaches
// the card. Not a game feature.
static bool g_dbgPileProbe;  // Config's DbgPileProbe

// The state record's +6 on the loaded profile alone (careerSetEventState also
// writes g_prog and counts an edit).
static void pileProbeState(u32 id, u8 state) {
	u32 k = 0;
	while (k < gProfile.stateRecCount && gProfile.stateRec[k].eventId != id)
		k++;
	if (k == gProfile.stateRecCount) {
		if (k >= (u32)PROFILE_NUM_STATE_RECORDS)
			return;
		memset(&gProfile.stateRec[k], 0, sizeof(gProfile.stateRec[k]));
		gProfile.stateRec[k].eventId = id;
		gProfile.stateRecCount++;
	}
	gProfile.stateRec[k].state = state;
}

static const char* pileProbeName(u32 id) {
	const EventRec* e = g_shopsOk ? eventdb_event_by_id(&g_shops, id) : NULL;
	return e ? e->name : "?";
}

// One case: the pile built from an empty one and logged beside the answer.
static void pileProbeCase(const char* label, const char* expect) {
	char b[200];
	careerPileReset();
	careerBuildListOfEvents();
	snprintf(b, sizeof(b), "probe: %s -- expect %s", label, expect);
	dlog(b);
	careerPileLog(label);
}

static void careerPileProbe(void) {
	static Profile saved;
	saved = gProfile;
	const int savedStage = g_careerStage;
	const EventPile savedPile = g_pile;
	const u32 savedRandom = g_bRandom;
	const u32 savedEdits = g_profileEdits;
	const bool savedWorld = g_worldFromCareer;
	char b[200];
	g_pileProbing = true;
	g_worldFromCareer = true;

	const EventRec* fin = eventdb_event_by_id(&g_shops, CAREER_FINAL_RACE);
	const StageRec* sd5 = eventdb_stage(&g_shops, 5);
	snprintf(b, sizeof(b), "probe: DbgPileProbe -- final race %s (+0x10 %s), stage 5 clear event %s",
		fin ? fin->name : "none", fin ? pileProbeName(fin->field10) : "-",
		sd5 ? pileProbeName(sd5->clearEvent) : "none");
	dlog(b);

	// Stage 5, the save's records.
	g_careerStage = 5;
	pileProbeCase("stage 5", "a normal pile, no S5_CIRCUIT_36");
	if (fin) {
		pileProbeState(fin->field10, 1);
		pileProbeCase("stage 5, S5_URL_9 won", "S5_CIRCUIT_36 alone");
		pileProbeState(fin->eventId, 1);
		pileProbeCase("stage 5, both won", "nothing (career complete)");
		pileProbeState(fin->field10, 2);
		pileProbeCase("stage 5, S5_CIRCUIT_36 won only", "nothing (career complete)");
		gProfile = saved;
	}

	// Stage 0 as the prologue leaves it: DDAY_EVENT_A entered, B not, its
	// three races open.
	static const u32 kStage0Races[3] = { 0xCA207583u, 0xCA207584u, 0x1BCB7AB0u };
	g_careerStage = 0;
	pileProbeState(CAREER_PROLOGUE_FIRST_EVENT, 2);
	pileProbeState(CAREER_PROLOGUE_DONE_EVENT, 0);
	for (int i = 0; i < 3; i++)
		pileProbeState(kStage0Races[i], 0);
	gProfile.csCanSeeEvents = false;
	gProfile.stage0Timeout = false;
	pileProbeCase("stage 0, DDAY_EVENT_A on, events not seen", "nothing");
	gProfile.csCanSeeEvents = true;
	pileProbeCase("stage 0, events seen", "the stage 0 races");
	gProfile.stage0Timeout = true;
	pileProbeCase("stage 0, timed out", "nothing");
	gProfile.stage0Timeout = false;
	pileProbeState(CAREER_PROLOGUE_FIRST_EVENT, 1);
	pileProbeCase("stage 0, on DDAY_EVENT_B", "nothing");
	pileProbeState(CAREER_PROLOGUE_FIRST_EVENT, 2);

	// CareerSpeech: DDAY_EVENT_A's queue, then three stage 0 race ends.
	careerSpeechDefault();
	gProfile.csCanSeeEvents = false;
	careerPileReset();
	careerSpeechEventBegin(CAREER_PROLOGUE_FIRST_EVENT);
	careerSpeechUpdate(14 * 4000);
	snprintf(b, sizeof(b), "probe: speech 14 s in -- events seen %d (expect 0)", gProfile.csCanSeeEvents);
	dlog(b);
	careerSpeechUpdate(1 * 4000);
	snprintf(b, sizeof(b), "probe: speech 15 s in -- events seen %d (expect 1)", gProfile.csCanSeeEvents);
	dlog(b);
	careerBuildListOfEvents();
	careerPileLog("speech 15 s");
	careerSpeechUpdate(25 * 4000);
	careerSpeechUpdate(1);
	dlog("probe: speech 40 s in -- expect event 3's line above");
	for (int i = 0; i < 3; i++) {
		const EventRec* e = eventdb_event_by_id(&g_shops, kStage0Races[i]);
		if (!e)
			continue;
		pileProbeState(e->eventId, 1);
		careerSpeechEventEnd(e, true);
		careerSpeechUpdate(1 * 4000);
		snprintf(b, sizeof(b), "probe: %s won -- step %d, timed out %d (expect %d, %d)", e->name,
			g_cs.stage0Step, gProfile.stage0Timeout, i + 1, i == 2);
		dlog(b);
	}
	careerBuildListOfEvents();
	careerPileLog("speech after three");

	gProfile = saved;
	g_careerStage = savedStage;
	g_pile = savedPile;
	g_bRandom = savedRandom;
	g_profileEdits = savedEdits;
	g_worldFromCareer = savedWorld;
	careerSpeechLoadBlock();
	g_pileProbing = false;
	careerPileLog("probe restored");
}

// GetStateRecord (0x80123830) on the loaded profile: the record's index, -1
// for none.
static int careerStateRecordFind(u32 id) {
	for (u32 k = 0; k < gProfile.stateRecCount && k < (u32)PROFILE_NUM_STATE_RECORDS; k++)
		if (gProfile.stateRec[k].eventId == id)
			return (int)k;
	return -1;
}

// ShowcaseState::IsEnterable (0x8012B124), which IsShowcaseEnterable asks: the
// record of the showcase's +0x20 handle unlocked (type 2) and not completed.
static bool careerShowcaseEnterable(const ShowcaseRec* sc) {
	const int k = sc ? careerStateRecordFind(sc->handle) : -1;
	return k >= 0 && gProfile.stateRec[k].type == 2 && gProfile.stateRec[k].state != 1;
}

// IsGoalGetToShowcase / IsGoalGetToShop (0x8012CFF4 / 0x8012CF9C): a
// challenge is on and its goal (+0x0C) is this showcase's +0x20 / this
// shop's +0x38.
static bool careerWcGoalIsShowcase(const ShowcaseRec* sc) {
	return g_wc.active && sc && sc->handle == g_wc.active->goalHandle;
}
static bool careerWcGoalIsShop(const ShopRec* shop) {
	return g_wc.active && shop && shop->handle == g_wc.active->goalHandle;
}

// SummonTheRightEngageDialog's shop arm with a challenge on and not failed:
// EngageShopDialog::Setup's uniques arm. The port keeps it to the goal shop,
// where NotifyEnterShopTriggerArea (state 2) put the challenge.
static bool careerWcAtGoalShop(void) {
	return g_wc.active && !g_wc.failed && g_wc.state == WC_STATE_AT_GOAL_SHOP &&
		careerWcGoalIsShop(g_shopHere);
}

// GetGoalZone (0x8012D1B4): where the challenge on is won -- its goal shop's
// trigger (+0x3C) or else its goal showcase's (+0x2C) -- with which of the
// two it is; NULL with no challenge on.
static const TrackPathZone* trackZoneByDataHandle(u32 handle);
static const TrackPathZone* careerWcGoalZone(const ShopRec** shop, const ShowcaseRec** sc) {
	*shop = NULL;
	*sc = NULL;
	if (!g_wc.active || !g_shopsOk)
		return NULL;
	*shop = eventdb_shop_by_handle(&g_shops, g_wc.active->goalHandle);
	if (*shop)
		return trackZoneByDataHandle((*shop)->triggerHandle);
	*sc = eventdb_showcase_by_handle(&g_shops, g_wc.active->goalHandle);
	return *sc ? trackZoneByDataHandle((*sc)->triggerHandle) : NULL;
}

// SMSMessageQueue::AddWorldChallengeMessage (0x8012BD88): the challenge's SMS
// (+0x08) queued as a magazine message (sms.h) with a generic body and
// subject taken in turn -- SMS_MAG_GENERIC_* naming the magazine
// ("_TITLE" hashed on from the showcase's +0x28) for a showcase goal,
// SMS_PERF_GENERIC_* for a performance run, SMS_VISUAL_GENERIC_* naming the
// part (+0x15) for a visual one, and no frames for anything else. The turn
// counters are statics in retail too (r13-0x7118 / -0x7114).
static void careerAddWorldChallengeMessage(const WorldChallengeRec* c) {
	static int magTurn = 0, uniqueTurn = 0;
	if (!g_smsDb || eventdb_sms_find(g_smsDb, c->smsHash) < 0)
		return;
	char name[40];
	snprintf(name, sizeof(name), "SMS_MAG_GENERIC_BODY_%d", magTurn % 2 + 1);
	u32 body = eventdb_feng_hash(name);
	snprintf(name, sizeof(name), "SMS_MAG_GENERIC_SUBJ_%d", magTurn % 2 + 1);
	u32 subject = eventdb_feng_hash(name);
	u32 arg = 0;
	const ShowcaseRec* sc = eventdb_showcase_by_handle(g_smsDb, c->goalHandle);
	if (sc) {
		// bStringHash__FPCci: the string hashed on from a seed.
		arg = sc->magHash;
		for (const char* s = "_TITLE"; *s; s++)
			arg = arg * 33u + (u8)*s;
		magTurn++;
	} else if (c->type == WC_TYPE_PERF) {
		const int n = uniqueTurn++ % 3 + 1;
		snprintf(name, sizeof(name), "SMS_PERF_GENERIC_%d_BODY", n);
		body = eventdb_feng_hash(name);
		snprintf(name, sizeof(name), "SMS_PERF_GENERIC_%d_SUBJECT", n);
		subject = eventdb_feng_hash(name);
	} else if (c->type == WC_TYPE_VISUAL) {
		const int n = uniqueTurn++ % 5 + 1;
		snprintf(name, sizeof(name), "SMS_VISUAL_GENERIC_%d_BODY", n);
		body = eventdb_feng_hash(name);
		snprintf(name, sizeof(name), "SMS_VISUAL_GENERIC_%d_SUBJECT", n);
		subject = eventdb_feng_hash(name);
		switch (c->sub[0]) {
		case 11: arg = 0x028F7092u; break;
		case 12: arg = 0xBB034EA6u; break;
		case 13: arg = 0x0294D2A3u; break;
		case 22: arg = 0x945E9BC5u; break;
		case 62: arg = 0x78DEEA1Cu; break;
		default: break;
		}
	} else {
		body = subject = 0;
	}
	const int k = sms_add_magazine_message(&gProfile, g_smsDb, c->smsHash, body, subject, arg);
	if (k >= 0)
		g_profileEdits++;
	char b[192];
	snprintf(b, sizeof(b), "challenge: %s announced -- SMS %08X %s (body %08X subject %08X arg %08X)",
		c->name, (unsigned)c->smsHash, k >= 0 ? "queued" : "not queued",
		(unsigned)body, (unsigned)subject, (unsigned)arg);
	dlog(b);
}

// WorldChallengeState::NotifyCareerEventCompleted (0x8012CEEC), at the end of
// CommitWinEvent's tail: every challenge of the stage the career is on that
// world races unlock, whose count the stage's won races now equal, is
// announced by SMS -- once, as the count is equalled once -- and
// CareerSpeech::HandleWorldChallengeUnlock queues a showcase's line.
static void careerWcNotifyCareerEventCompleted(void) {
	if (!g_shopsOk)
		return;
	const int won = careerWorldRacesCompleted(careerStageInfo(g_careerStage));
	for (int i = 0; i < g_shops.challengeCount && i < EVENTDB_MAX_CHALLENGES; i++) {
		const WorldChallengeRec* c = &g_shops.challenges[i];
		if (c->unlockKind == WC_UNLOCK_WORLD_RACES && (int)c->stage == g_careerStage &&
				won == c->unlockCount) {
			careerAddWorldChallengeMessage(c);
			careerSpeechWorldChallengeUnlock(c);
		}
	}
}

// PlayerCareerState::NotifyBeginGetAway (0x80126F4C), from StartGetAway:
// SMSMessageQueue::NotifyBeginGetAway's trigger 4 messages and
// CareerSpeech::HandleOutrunStart's taunt.
// `encMs` is the encounter step that started the race, timed by the caller:
// the line carries what the start frame cost (the 2026-11-04 Outrun hitch).
static void careerNotifyBeginGetAway(double encMs) {
	if (!g_worldFromCareer)
		return;
	const u64 t0 = svcGetSystemTick();
	const int n = g_smsDb ? sms_notify_trigger(&gProfile, g_smsDb, 4) : 0;
	if (n > 0)
		g_profileEdits++;
	const u64 t1 = svcGetSystemTick();
	careerSpeechOutrunStart();
	const u64 t2 = svcGetSystemTick();
	char b[160];
	snprintf(b, sizeof(b), "outrun: NotifyBeginGetAway -- %d trigger 4 SMS queued (encounter step "
		"%.1f ms, SMS %.1f ms, the taunt %.1f ms)", n, encMs, TKMS(t0, t1), TKMS(t1, t2));
	dlog(b);
}

// PlayerCareerState::NotifyRandomEncounterFinished (0x80126F84), from
// EndGetAway, a career game only:
//   the stage's purse (GetRandomEncounterPurse 0x801275F4, StageData's
//     random-encounter record +0x02) deposited on a win, spent on a loss
//   RuntimeCareerStageInfo::NotifyRandomEncounterFinished (0x80124700): the
//     stage's outrun wins (+0xDC) up one on a win
//   SMSMessageQueue::NotifyFinishGetaway: trigger 5 on a win, 6 on a loss
//   WorldChallengeState::NotifyOutrunRaceFinished (0x8012CE38): on a win,
//     each challenge of this stage that outruns unlock (+0x06 == 2) whose
//     count (+0x07) the wins now equal is announced by SMS, and
//     CareerSpeech::HandleWorldChallengeUnlock beside it
//   CareerSpeech::HandleOutrunEnd, the voice's win or loss line
//   RecalcUnlockedZones and NotifyMinimapNewRace (nothing to reset here:
//     the port's minimap reads the career each frame).
static int careerNotifyRandomEncounterFinished(bool won) {
	if (!g_worldFromCareer)
		return 0;
	const StageRec* sd = g_shopsOk ? eventdb_stage(&g_shops, g_careerStage) : NULL;
	const int purse = sd ? (int)(s16)sd->encounterPurse : 0;
	const unsigned cashWas = gProfile.cash;
	if (won)
		gProfile.cash += (unsigned)(purse > 0 ? purse : 0);
	else
		careerSpend(purse > 0 ? (unsigned)purse : 0u);
	ProfileStageInfo* si = careerStageInfo(g_careerStage);
	if (si && won)
		si->outrunWins++;
	const int sms = g_smsDb ? sms_notify_trigger(&gProfile, g_smsDb, won ? 5 : 6) : 0;
	int wc = 0;
	if (won && si && g_shopsOk) {
		for (int i = 0; i < g_shops.challengeCount && i < EVENTDB_MAX_CHALLENGES; i++) {
			const WorldChallengeRec* c = &g_shops.challenges[i];
			if (c->unlockKind == WC_UNLOCK_OUTRUNS && (int)c->stage == g_careerStage &&
					si->outrunWins == c->unlockCount) {
				careerAddWorldChallengeMessage(c);
				careerSpeechWorldChallengeUnlock(c);
				wc++;
			}
		}
	}
	careerSpeechOutrunEnd(won);
	worldRecalcUnlockedZones();
	g_profileEdits++;
	char b[192];
	snprintf(b, sizeof(b), "outrun: NotifyRandomEncounterFinished(%s) -- purse %d, cash %u -> %u, "
		"stage %d outrun wins %d, %d trigger %d SMS, %d challenge(s) announced",
		won ? "won" : "lost", purse, cashWas, gProfile.cash, g_careerStage,
		si ? si->outrunWins : -1, sms, won ? 5 : 6, wc);
	dlog(b);
	return purse;
}

// The pause builder's (0x4C2900) gates, with the career for [0x850078]==1.
static bool menuWorldGateOpen(u8 gate) {
	// #321c: a LAN race's in-race list is its Quit alone.
	if (g_lanRaceOn && (gate == WORLD_GATE_RACE || gate == WORLD_GATE_RACE_CAREER ||
			gate == WORLD_GATE_RACE_WORLDMAP || gate == WORLD_GATE_FR_CAREER ||
			gate == WORLD_GATE_FR_NOT_CAREER || gate == WORLD_GATE_FR_GARAGE))
		return false;
	switch (gate) {
	case WORLD_GATE_LAN_RACE:   return g_lanRaceOn;
	case WORLD_GATE_NOT_LAN:    return !g_lanRaceOn;
	case WORLD_GATE_CAREER:     return g_worldFromCareer;
	case WORLD_GATE_NOT_CAREER: return !g_worldFromCareer;
	case WORLD_GATE_GARAGE:     return g_worldFromCareer && gProfile.isLoaded &&
	                                   gProfile.jumpToGarage;
	case WORLD_GATE_NETWORK:    return false;
	case WORLD_GATE_NEXTRACE:   return g_postRace.nextRace;
	case WORLD_GATE_WORLDMAP:   return g_worldFromCareer && g_postRace.worldMap;
	// ReplayMenu (#498): a race with a recording (replayRaceBegin()).
	case WORLD_GATE_REPLAY:     return !g_lanRaceOn && g_raceRun.on && !g_tune.on &&
	                                   replay_has_data();
	case WORLD_GATE_FR_CAREER:     return !g_raceRun.on && g_worldFromCareer;
	case WORLD_GATE_FR_NOT_CAREER: return !g_raceRun.on && !g_worldFromCareer;
	case WORLD_GATE_FR_GARAGE:     return !g_raceRun.on && g_worldFromCareer &&
	                                      gProfile.isLoaded && gProfile.jumpToGarage;
	case WORLD_GATE_RACE:          return g_raceRun.on;
	case WORLD_GATE_RACE_CAREER:   return g_raceRun.on && g_worldFromCareer;
	case WORLD_GATE_RACE_WORLDMAP: return g_raceRun.on && g_worldFromCareer &&
	                                      g_raceRun.fromWorldMap;
	case WORLD_GATE_TUNE_DYNO:     return g_tune.onDyno;
	case WORLD_GATE_TUNE_TEST:     return !g_tune.onDyno;
	case WORLD_GATE_TUNE_DIRTY:    return g_tune.onDyno && tuneAnyChanged();
	default:                    return true;
	}
}

// Which race barriers are solid (TASKS.md #232, topology.h) and which are
// drawn, with the start/finish lines and shop beams (#237, scenery.h).
// Outside a race it is what TrackLoader::InitTopologyAndSceneryGroups
// (0x80196cb8) enables with TheRaceParameters+0x14 == 0: the loaded track's
// two sets and, in career, FREE_ROAM and BARRIERS_CAREER<stage> -- in career
// free roam the only barriers there are, since no group is named for track
// 4000. Quick Race has loaded the picked track and no career. Free roam is
// TheRaceParameters+0x04 0, the forward direction.
static const char* worldQuitScreen(void) {
	if (g_lanRaceOn)
		return LAN_AFTER_RACE_SCREEN;   // #321c: back to the LAN lobby
	return g_worldFromCareer ? "UI_Main.fng" : QR_AFTER_RACE_SCREEN;
}

static int g_dbgBarrierStage = -1; // Config's DbgBarrierStage
static char g_worldPathsFile[560]; // PathsFreeRoam.bin, set when the world opens it

static u32 worldBarrierHash(const char* s) {
	u32 h = 0xFFFFFFFFu;
	for (; *s; s++)
		h = h * 33u + (u8)*s;
	return h;
}

// The road graph's half of InitTopologyAndSceneryGroups (TASKS.md #358): the
// TrackPathManager gates EnableBarriers closes -- BARRIERS_<track>,
// PLAYER_BARRIERS_<track> and in career BARRIERS_CAREER<stage> -- then
// InitTrackRoutes' barrier pass over RoutesFreeRoam.bin (gps_set_barriers),
// so the GPS and the racers keep off the roads the stage has closed.
static void worldSetFreeRoamBarriers(int track, int careerStage) {
	if (!gps_loaded() || !g_worldPathsFile[0])
		return;
	const char* paths = g_worldPathsFile;
	char name[32];
	u32 ids[3];
	int n = 0;
	snprintf(name, sizeof(name), "BARRIERS_%d", track);
	ids[n++] = worldBarrierHash(name);
	snprintf(name, sizeof(name), "PLAYER_BARRIERS_%d", track);
	ids[n++] = worldBarrierHash(name);
	if (careerStage >= 0 && g_dbgBarrierStage >= 0) {
		char b[96];
		snprintf(b, sizeof(b), "gps: DbgBarrierStage=%d -- the barriers of stage %d, not %d",
			g_dbgBarrierStage, g_dbgBarrierStage, careerStage);
		dlog(b);
		careerStage = g_dbgBarrierStage;
	}
	if (careerStage >= 0) {
		snprintf(name, sizeof(name), "BARRIERS_CAREER%d", careerStage);
		ids[n++] = worldBarrierHash(name);
	}
	gps_set_barriers(paths, ids, n, dlog);
}

static void worldSetFreeRoamGroups(void) {
	if (g_worldFromCareer) {
		world_set_groups(g_world, WORLD_FREE_ROAM_TRACK, g_careerStage,
			g_hasCareerCar, false);
		worldSetFreeRoamBarriers(WORLD_FREE_ROAM_TRACK, g_careerStage);
	} else {
		world_set_groups(g_world,
			g_qrTrackId >= 0 ? g_qrTrackId : WORLD_FREE_ROAM_TRACK, -1,
			false, false);
		worldSetFreeRoamBarriers(WORLD_FREE_ROAM_TRACK, -1);
	}
}

